const JSON_BODY_LIMIT = '25mb';
const app = express();
app.set('trust proxy', process.env.ATTICA_TRUST_PROXY || 'loopback, linklocal, uniquelocal');

process.on('unhandledRejection', (reason) => {
  console.error('[process] unhandledRejection:', reason?.stack || reason?.message || reason);
});

process.on('uncaughtException', (error) => {
  console.error('[process] uncaughtException:', error?.stack || error?.message || error);
});

app.use(cors());
app.use(express.json({ limit: JSON_BODY_LIMIT }));
app.use(express.urlencoded({ extended: true, limit: JSON_BODY_LIMIT }));
app.use('/api', (_req, res, next) => {
  res.set({
    'Cache-Control': 'no-store, no-cache, must-revalidate, proxy-revalidate, private',
    Pragma: 'no-cache',
    Expires: '0',
    'Surrogate-Control': 'no-store',
  });
  next();
});

