const AUTO_DIAL_CLOSED_CUSTOMER_REASON_SQL = `CASE
  WHEN LOWER(REPLACE(IFNULL(form_status,''), ' ', '')) IN ('soldout','sold','customersoldout','finalsale','billed')
    OR LOWER(REPLACE(IFNULL(callback_status,''), ' ', '')) IN ('soldout','sold','customersoldout','finalsale','billed')
    OR UPPER(TRIM(IFNULL(disposition,''))) IN ('SOLD','SE_SELL','SE_BUY','SE_RELEASE')
  THEN 'Sold Out'
  WHEN LOWER(TRIM(IFNULL(form_status,'')))='not interested'
    OR LOWER(TRIM(IFNULL(callback_status,'')))='not interested'
    OR UPPER(TRIM(IFNULL(disposition,'')))='NI'
  THEN 'Not Interested'
  ELSE ''
END`;
