const OPEN_AUTO_DIAL_LEAD_STATUSES = new Set(['pending', 'assigned', 'dialing']);
const FOLLOW_UP_RETENTION_DAYS = 7;
const MISSED_CALLBACK_AUTO_DIAL_PREDICATE_SQL = `(
  queue_bucket='missed-callback'
)`;
const FOLLOW_UP_AUTO_DIAL_PREDICATE_SQL = `((
  queue_work_mode='follow-up'
) AND NOT ${MISSED_CALLBACK_AUTO_DIAL_PREDICATE_SQL})`;
const ACTIVE_FOLLOW_UP_AUTO_DIAL_SQL = `(NOT ${FOLLOW_UP_AUTO_DIAL_PREDICATE_SQL} OR (
  IFNULL(is_active, 1) = 1
  AND (followup_expires_at IS NULL OR followup_expires_at >= ${MYSQL_QUEUE_NOW_SQL})
))`;
const OUTBOUND_AUTO_DIAL_PREDICATE_SQL = `(NOT ${FOLLOW_UP_AUTO_DIAL_PREDICATE_SQL})`;
const ACTIVE_OUTBOUND_AUTO_DIAL_SQL = `(NOT ${OUTBOUND_AUTO_DIAL_PREDICATE_SQL} OR created_at >= DATE_SUB(${MYSQL_QUEUE_NOW_SQL}, INTERVAL ${AUTO_DIAL_FRESH_MAX_AGE_DAYS} DAY))`;
function getAutoDialScheduleDueSql(alias = '') {
  const prefix = alias ? `${alias}.` : '';
  const followUpPredicate = `((${prefix}queue_work_mode='follow-up') AND NOT (${prefix}queue_bucket='missed-callback'))`;
  return `(${prefix}scheduled_for IS NULL OR ${prefix}scheduled_for <= CASE WHEN ${followUpPredicate} THEN ${MYSQL_DISPLAY_NOW_SQL} ELSE ${MYSQL_QUEUE_NOW_SQL} END)`;
}
const AUTO_DIAL_SCHEDULE_DUE_SQL = getAutoDialScheduleDueSql();
const AUTO_DIAL_SCHEDULE_DUE_SQL_L = getAutoDialScheduleDueSql('l');
const OPEN_AUTO_DIAL_LEAD_ORDER_SQL = `CASE
  WHEN status='dialing' THEN 0
  WHEN ${MISSED_CALLBACK_AUTO_DIAL_PREDICATE_SQL} THEN 1
  WHEN status='assigned' THEN 2
  WHEN queue_work_mode='outbound-auto' THEN 3
  WHEN queue_work_mode='follow-up' THEN 5
  WHEN scheduled_for IS NOT NULL THEN 6
  ELSE 7
END,
CASE WHEN ${OUTBOUND_AUTO_DIAL_PREDICATE_SQL} THEN created_at END ASC,
CASE WHEN ${MISSED_CALLBACK_AUTO_DIAL_PREDICATE_SQL} THEN COALESCE(scheduled_for, created_at) END ASC,
CASE WHEN ${FOLLOW_UP_AUTO_DIAL_PREDICATE_SQL} THEN COALESCE(scheduled_for, created_at) END DESC,
created_at ASC,
id ASC`;
const CALL_ROW_VISIBILITY_SQL = "(IFNULL(TRIM(id),'') <> '' AND (IFNULL(TRIM(caller_id),'') <> '' OR IFNULL(TRIM(caller_name),'') <> '' OR IFNULL(TRIM(customer_name),'') <> '' OR IFNULL(TRIM(agent_id),'') <> '' OR IFNULL(TRIM(agent_name),'') <> '' OR IFNULL(TRIM(direction),'') <> ''))";
const NON_DUPLICATE_REMOVED_CALL_SQL = "LOWER(TRIM(IFNULL(callback_status,''))) <> 'duplicate removed'";
const OPEN_MISSED_CALLBACK_STATUS_SQL = "LOWER(TRIM(IFNULL(callback_status,'')))='pending'";
const NON_REPORT_ARTIFACT_CALL_SQL = `(
  direction <> 'incoming'
  OR ${countableIncomingCallSql()}
)`;
const AUTO_DIAL_NOT_DUPLICATE_REMOVED_SQL = `(attica_auto_dial_leads.id NOT LIKE 'AUTO-%' OR NOT EXISTS (
  SELECT 1
  FROM attica_calls duplicate_removed_call
  WHERE duplicate_removed_call.id=SUBSTRING(attica_auto_dial_leads.id, 6)
    AND LOWER(TRIM(IFNULL(duplicate_removed_call.callback_status,'')))='duplicate removed'
))`;
const FOLLOWUP_NOT_DUPLICATE_REMOVED_SQL = `(attica_followups.id NOT LIKE 'AUTO-%' OR NOT EXISTS (
  SELECT 1
  FROM attica_calls duplicate_removed_call
  WHERE duplicate_removed_call.id=SUBSTRING(attica_followups.id, 6)
    AND LOWER(TRIM(IFNULL(duplicate_removed_call.callback_status,'')))='duplicate removed'
))`;
const REAL_AGENT_CALL_SQL = "NOT (UPPER(TRIM(COALESCE(agent_id,''))) IN ('', 'NONE', 'NO AGENT', 'UNKNOWN') AND UPPER(TRIM(COALESCE(agent_name,''))) IN ('', 'NONE', 'NO AGENT', 'UNKNOWN'))";
const CALL_ROW_SORT_SQL = 'created_at DESC, id DESC';
const CANONICAL_CALL_ID_SQL = "CASE WHEN LOCATE('|', IFNULL(id,'')) > 0 THEN SUBSTRING_INDEX(id, '|', 1) ELSE IFNULL(id,'') END";
const CANONICAL_CALL_UUID_SQL = "CASE WHEN LOCATE('|', IFNULL(call_uuid,'')) > 0 THEN SUBSTRING_INDEX(call_uuid, '|', 1) ELSE IFNULL(call_uuid,'') END";
const CALL_INTERACTION_DEDUPE_SQL = `CASE
  WHEN IFNULL(TRIM(caller_id),'') <> ''
   AND IFNULL(TRIM(direction),'') <> ''
   AND COALESCE(answered_at, ring_started_at, created_at, ended_at) IS NOT NULL
  THEN CONCAT(
    IFNULL(TRIM(agent_id), ''),
    '|',
    RIGHT(REPLACE(REPLACE(REPLACE(IFNULL(caller_id,''),'+',''),' ',''),'-',''), 10),
    '|',
    IFNULL(TRIM(direction), ''),
    '|',
    DATE_FORMAT(COALESCE(answered_at, ring_started_at, created_at, ended_at), '%Y-%m-%d %H:%i:%s')
  )
  ELSE ${CANONICAL_CALL_ID_SQL}
END`;

function parsePositiveInteger(value, fallback) {
  const parsed = Number.parseInt(String(value || ''), 10);
  return Number.isFinite(parsed) && parsed > 0 ? parsed : fallback;
}

function normalizeProcessRole(value) {
  const normalized = String(value || 'all').trim().toLowerCase();
  return ['all', 'api', 'scheduler'].includes(normalized) ? normalized : 'all';
}

function isDisabledFlag(value) {
  return ['0', 'false', 'no', 'off'].includes(String(value || '').trim().toLowerCase());
}

