const dbStorage = new AsyncLocalStorage();

const primaryPool = mysql.createPool({
  host: 'localhost', user: 'custom', password: (process.env.ATTICA_DB_PASSWORD || ""),
  database: 'asterisk', waitForConnections: true,
  connectionLimit: DB_POOL_CONNECTION_LIMIT,
  maxIdle: Math.max(1, Math.min(DB_POOL_CONNECTION_LIMIT, 2)),
  queueLimit: 0,
  idleTimeout: 15000
});

const heavyPool = mysql.createPool({
  host: 'localhost', user: 'custom', password: (process.env.ATTICA_DB_PASSWORD || ""),
  database: 'asterisk', waitForConnections: true,
  connectionLimit: HEAVY_DB_POOL_CONNECTION_LIMIT,
  maxIdle: Math.max(1, Math.min(HEAVY_DB_POOL_CONNECTION_LIMIT, 2)),
  queueLimit: 0,
  idleTimeout: 15000
});

const pool = new Proxy(primaryPool, {
  get(target, prop, receiver) {
    const store = dbStorage.getStore();
    const activePool = store || target;
    if (ENABLE_DB_ROUTE_LOGS && (prop === 'query' || prop === 'execute')) {
      const poolName = store ? 'heavyPool' : 'primaryPool';
      console.log(`[dbProxy] Routing query to ${poolName}`);
    }
    const value = Reflect.get(activePool, prop, receiver);
    if (typeof value === 'function') {
      return value.bind(activePool);
    }
    return value;
  }
});

const HEAVY_ENDPOINTS = new Set([
  '/api/calls/list',
  '/api/calls/date-details',
  '/api/calls/duplicate-audit',
  '/api/calls',
  '/api/stats',
  '/api/customerdata/list'
]);

app.use((req, res, next) => {
  const isHeavy = HEAVY_ENDPOINTS.has(req.path);
  if (ENABLE_DB_ROUTE_LOGS) {
    console.log(`[dbProxyMiddleware] pid=${process.pid} path=${req.path} isHeavy=${isHeavy}`);
  }
  if (isHeavy) {
    dbStorage.run(heavyPool, next);
  } else {
    next();
  }
});

