function formatDateInZone(value) {
  if (!value) return '';
  const date = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(date.getTime())) return '';
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: DISPLAY_TIME_ZONE,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).formatToParts(date);
  const year = parts.find((part) => part.type === 'year')?.value || '';
  const month = parts.find((part) => part.type === 'month')?.value || '';
  const day = parts.find((part) => part.type === 'day')?.value || '';
  return year && month && day ? `${year}-${month}-${day}` : '';
}

function resolveRecordingAbsolutePath(recordingName) {
  const safeName = basename(String(recordingName || ''));
  if (!safeName || safeName !== String(recordingName || '')) {
    return '';
  }

  for (const dir of RECORDING_SOURCE_DIRECTORIES) {
    try {
      const absolutePath = join(dir, safeName);
      const stats = statSync(absolutePath);
      if (stats.isFile()) return absolutePath;
    } catch (error) {
      // Try the next directory.
    }
  }

  return '';
}

function hasGooglePlacesApiKey() {
  return GOOGLE_PLACES_API_KEY.length > 0;
}

async function fetchJsonWithTimeout(url, options = {}, timeoutMs = 5000) {
  const controller = new AbortController();
  const timeoutHandle = setTimeout(() => controller.abort(), timeoutMs);

  try {
    const response = await fetch(url, {
      ...options,
      signal: controller.signal,
    });
    if (!response.ok) {
      throw new Error(`HTTP ${response.status}`);
    }
    return await response.json();
  } finally {
    clearTimeout(timeoutHandle);
  }
}

function base64UrlEncode(value) {
  const buffer = Buffer.isBuffer(value) ? value : Buffer.from(String(value));
  return buffer.toString('base64').replace(/=/g, '').replace(/\+/g, '-').replace(/\//g, '_');
}

function parseGoogleMarketingServiceAccount() {
  let raw = '';
  let source = '';

  if (GOOGLE_MARKETING_SERVICE_ACCOUNT_JSON) {
    raw = GOOGLE_MARKETING_SERVICE_ACCOUNT_JSON;
    source = 'env_json';
  } else if (GOOGLE_MARKETING_SERVICE_ACCOUNT_JSON_BASE64) {
    raw = Buffer.from(GOOGLE_MARKETING_SERVICE_ACCOUNT_JSON_BASE64, 'base64').toString('utf8');
    source = 'env_base64';
  } else if (GOOGLE_MARKETING_SERVICE_ACCOUNT_PATH) {
    try {
      raw = readFileSync(GOOGLE_MARKETING_SERVICE_ACCOUNT_PATH, 'utf8');
      source = 'file';
    } catch (error) {
      return {
        configured: false,
        source: 'missing',
        credentialPath: GOOGLE_MARKETING_SERVICE_ACCOUNT_PATH,
        error: `Credential file not readable: ${GOOGLE_MARKETING_SERVICE_ACCOUNT_PATH}`,
      };
    }
  }

  if (!raw) {
    return {
      configured: false,
      source: 'missing',
      credentialPath: GOOGLE_MARKETING_SERVICE_ACCOUNT_PATH,
      error: 'Google service account credential is not configured',
    };
  }

  try {
    const credential = JSON.parse(raw);
    const clientEmail = cleanJustDialString(credential.client_email, 240);
    const clientId = cleanJustDialString(credential.client_id, 80);
    const privateKey = String(credential.private_key || '').trim();
    if (credential.type !== 'service_account' || !clientEmail || !privateKey) {
      return {
        configured: false,
        source,
        credentialPath: source === 'file' ? GOOGLE_MARKETING_SERVICE_ACCOUNT_PATH : '',
        error: 'Google credential is not a valid service account JSON',
      };
    }

    return {
      configured: true,
      source,
      credentialPath: source === 'file' ? GOOGLE_MARKETING_SERVICE_ACCOUNT_PATH : '',
      credential,
      clientEmail,
      clientId,
      projectId: cleanJustDialString(credential.project_id, 120),
      tokenUri: cleanJustDialString(credential.token_uri || 'https://oauth2.googleapis.com/token', 240),
    };
  } catch (error) {
    return {
      configured: false,
      source,
      credentialPath: source === 'file' ? GOOGLE_MARKETING_SERVICE_ACCOUNT_PATH : '',
      error: 'Google service account JSON could not be parsed',
    };
  }
}

function createGoogleServiceAccountAssertion(credential, scopes = GOOGLE_MARKETING_SCOPES) {
  const now = Math.floor(Date.now() / 1000);
  const header = {
    alg: 'RS256',
    typ: 'JWT',
  };
  const payload = {
    iss: credential.client_email,
    scope: scopes.join(' '),
    aud: credential.token_uri || 'https://oauth2.googleapis.com/token',
    iat: now,
    exp: now + 3600,
  };
  const unsignedJwt = `${base64UrlEncode(JSON.stringify(header))}.${base64UrlEncode(JSON.stringify(payload))}`;
  const signer = createSign('RSA-SHA256');
  signer.update(unsignedJwt);
  signer.end();
  return `${unsignedJwt}.${base64UrlEncode(signer.sign(credential.private_key))}`;
}

let googleMarketingAccessTokenCache = null;

async function getGoogleMarketingAccessToken(scopes = GOOGLE_MARKETING_SCOPES) {
  const scopeKey = [...scopes].sort().join(' ');
  const now = Date.now();
  if (
    googleMarketingAccessTokenCache
    && googleMarketingAccessTokenCache.scopeKey === scopeKey
    && googleMarketingAccessTokenCache.expiresAt > now + 60000
  ) {
    return googleMarketingAccessTokenCache;
  }

  const parsed = parseGoogleMarketingServiceAccount();
  if (!parsed.configured) {
    throw new Error(parsed.error || 'Google service account credential is not configured');
  }

  const assertion = createGoogleServiceAccountAssertion(parsed.credential, scopes);
  const body = new URLSearchParams({
    grant_type: 'urn:ietf:params:oauth:grant-type:jwt-bearer',
    assertion,
  });
  const response = await fetch(parsed.tokenUri || 'https://oauth2.googleapis.com/token', {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body,
  });
  const payload = await response.json().catch(() => ({}));
  if (!response.ok || !payload?.access_token) {
    throw new Error(payload?.error_description || payload?.error || `Google OAuth token request failed: HTTP ${response.status}`);
  }

  googleMarketingAccessTokenCache = {
    accessToken: payload.access_token,
    tokenType: payload.token_type || 'Bearer',
    expiresIn: Number(payload.expires_in) || 3600,
    expiresAt: now + ((Number(payload.expires_in) || 3600) * 1000),
    scopeKey,
  };
  return googleMarketingAccessTokenCache;
}

function normalizeGoogleAdsCustomerId(value) {
  return String(value || '').replace(/[^0-9]/g, '');
}

async function verifyGoogleAdsServiceAccountAccess() {
  const customerId = normalizeGoogleAdsCustomerId(GOOGLE_MARKETING_ADS_CUSTOMER_ID);
  const managerCustomerId = normalizeGoogleAdsCustomerId(GOOGLE_MARKETING_ADS_MANAGER_CUSTOMER_ID);
  if (!customerId) throw new Error('ATTICA_GOOGLE_ADS_CUSTOMER_ID is not configured');
  if (!GOOGLE_MARKETING_ADS_DEVELOPER_TOKEN) throw new Error('ATTICA_GOOGLE_ADS_DEVELOPER_TOKEN is not configured');

  const token = await getGoogleMarketingAccessToken(GOOGLE_MARKETING_ADS_SCOPES);
  const runSearch = async (includeManagerHeader) => {
    const response = await fetch(
      `https://googleads.googleapis.com/${GOOGLE_MARKETING_ADS_API_VERSION}/customers/${customerId}/googleAds:searchStream`,
      {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${token.accessToken}`,
          'Content-Type': 'application/json',
          'developer-token': GOOGLE_MARKETING_ADS_DEVELOPER_TOKEN,
          ...(includeManagerHeader && managerCustomerId && managerCustomerId !== customerId ? { 'login-customer-id': managerCustomerId } : {}),
        },
        body: JSON.stringify({
          query: 'SELECT customer.id, customer.descriptive_name FROM customer LIMIT 1',
        }),
      }
    );
    return { response, payload: await response.json().catch(() => null), usedManagerHeader: includeManagerHeader };
  };

  let { response, payload, usedManagerHeader } = await runSearch(Boolean(managerCustomerId && managerCustomerId !== customerId));
  const googleAdsError = Array.isArray(payload) ? payload[0]?.error : payload?.error;
  const googleErrorCode = googleAdsError?.details?.[0]?.errors?.[0]?.errorCode?.authorizationError || '';
  if (!response.ok && usedManagerHeader && googleErrorCode === 'USER_PERMISSION_DENIED') {
    ({ response, payload, usedManagerHeader } = await runSearch(false));
  }
  if (!response.ok) {
    const googleError = payload?.error?.message
      || payload?.[0]?.error?.message
      || `Google Ads API verification failed: HTTP ${response.status}`;
    throw new Error(googleError);
  }
  return {
    status: 'valid',
    apiVersion: GOOGLE_MARKETING_ADS_API_VERSION,
    usedManagerHeader,
    checkedAt: new Date().toISOString(),
  };
}

const googleAdsMetricsCache = new Map();
const GOOGLE_ADS_METRICS_CACHE_MS = 10 * 60 * 1000;
const GOOGLE_ADS_METRICS_SHARED_CACHE_DIR = process.env.ATTICA_GOOGLE_ADS_METRICS_CACHE_DIR || '/tmp/attica-google-ads-metrics';

function getGoogleAdsMetricsCacheFile(cacheKey) {
  const digest = createHash('sha1').update(cacheKey).digest('hex');
  return join(GOOGLE_ADS_METRICS_SHARED_CACHE_DIR, `${digest}.json`);
}

function serializeGoogleAdsMetrics(value) {
  return {
    ...value,
    campaignMetrics: [...(value?.campaignMetrics || new Map()).entries()],
    keywordMetrics: [...(value?.keywordMetrics || new Map()).entries()],
  };
}

function hydrateGoogleAdsMetrics(value) {
  if (!value || typeof value !== 'object') return null;
  return {
    configured: Boolean(value.configured),
    campaignMetrics: new Map(Array.isArray(value.campaignMetrics) ? value.campaignMetrics : []),
    keywordMetrics: new Map(Array.isArray(value.keywordMetrics) ? value.keywordMetrics : []),
    totalSpend: Math.max(0, Number(value.totalSpend) || 0),
    totalClicks: Math.max(0, Number(value.totalClicks) || 0),
    totalImpressions: Math.max(0, Number(value.totalImpressions) || 0),
  };
}

function readSharedGoogleAdsMetricsCache(cacheKey) {
  try {
    const parsed = JSON.parse(readFileSync(getGoogleAdsMetricsCacheFile(cacheKey), 'utf8'));
    if (!parsed || Number(parsed.expiresAt) <= Date.now()) return null;
    return hydrateGoogleAdsMetrics(parsed.value);
  } catch {
    return null;
  }
}

function writeSharedGoogleAdsMetricsCache(cacheKey, value, expiresAt) {
  try {
    mkdirSync(GOOGLE_ADS_METRICS_SHARED_CACHE_DIR, { recursive: true, mode: 0o700 });
    writeFileSync(
      getGoogleAdsMetricsCacheFile(cacheKey),
      JSON.stringify({ expiresAt, value: serializeGoogleAdsMetrics(value) }),
      { mode: 0o600 }
    );
  } catch (error) {
    console.warn('[seo-marketing/google-ads] shared cache write failed:', error?.message || error);
  }
}

function flattenGoogleAdsSearchStreamPayload(payload) {
  if (!Array.isArray(payload)) return [];
  return payload.flatMap((chunk) => Array.isArray(chunk?.results) ? chunk.results : []);
}

async function fetchGoogleAdsSearchStream(query) {
  const customerId = normalizeGoogleAdsCustomerId(GOOGLE_MARKETING_ADS_CUSTOMER_ID);
  const managerCustomerId = normalizeGoogleAdsCustomerId(GOOGLE_MARKETING_ADS_MANAGER_CUSTOMER_ID);
  if (!customerId || !GOOGLE_MARKETING_ADS_DEVELOPER_TOKEN) return [];

  const token = await getGoogleMarketingAccessToken(GOOGLE_MARKETING_ADS_SCOPES);
  const runSearch = async (includeManagerHeader) => {
    const response = await fetch(
      `https://googleads.googleapis.com/${GOOGLE_MARKETING_ADS_API_VERSION}/customers/${customerId}/googleAds:searchStream`,
      {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${token.accessToken}`,
          'Content-Type': 'application/json',
          'developer-token': GOOGLE_MARKETING_ADS_DEVELOPER_TOKEN,
          ...(includeManagerHeader && managerCustomerId && managerCustomerId !== customerId ? { 'login-customer-id': managerCustomerId } : {}),
        },
        body: JSON.stringify({ query }),
      }
    );
    return { response, payload: await response.json().catch(() => null), usedManagerHeader: includeManagerHeader };
  };

  let { response, payload, usedManagerHeader } = await runSearch(Boolean(managerCustomerId && managerCustomerId !== customerId));
  const googleAdsError = Array.isArray(payload) ? payload[0]?.error : payload?.error;
  const googleErrorCode = googleAdsError?.details?.[0]?.errors?.[0]?.errorCode?.authorizationError || '';
  if (!response.ok && usedManagerHeader && googleErrorCode === 'USER_PERMISSION_DENIED') {
    ({ response, payload } = await runSearch(false));
  }
  if (!response.ok) {
    const googleError = payload?.error?.message
      || payload?.[0]?.error?.message
      || `Google Ads API request failed: HTTP ${response.status}`;
    throw new Error(googleError);
  }
  return flattenGoogleAdsSearchStreamPayload(payload);
}

function addGoogleAdsMetric(map, key, values = {}) {
  const displayKey = cleanJustDialString(key, 300);
  const normalizedKey = displayKey.toLowerCase();
  if (!normalizedKey) return;
  const existing = map.get(normalizedKey) || {
    key: displayKey,
    spend: 0,
    clicks: 0,
    impressions: 0,
    googleConversions: 0,
    googleConversionValue: 0,
  };
  existing.key ||= displayKey;
  existing.spend += Math.max(0, Number(values.spend) || 0);
  existing.clicks += Math.max(0, Number(values.clicks) || 0);
  existing.impressions += Math.max(0, Number(values.impressions) || 0);
  existing.googleConversions += Math.max(0, Number(values.googleConversions) || 0);
  existing.googleConversionValue += Math.max(0, Number(values.googleConversionValue) || 0);
  map.set(normalizedKey, existing);
}

async function fetchGoogleAdsMetricsForDateRange(range = {}) {
  const startDate = normalizeQueryDate(range.startDate);
  const endDate = normalizeQueryDate(range.endDate);
  if (!startDate || !endDate || !GOOGLE_MARKETING_ADS_CUSTOMER_ID || !GOOGLE_MARKETING_ADS_DEVELOPER_TOKEN) {
    return { configured: false, campaignMetrics: new Map(), keywordMetrics: new Map(), totalSpend: 0, totalClicks: 0, totalImpressions: 0 };
  }
  const cacheKey = `${startDate}:${endDate}:${GOOGLE_MARKETING_ADS_CUSTOMER_ID}:${GOOGLE_MARKETING_ADS_API_VERSION}`;
  const cached = googleAdsMetricsCache.get(cacheKey);
  if (cached && cached.expiresAt > Date.now()) return cached.value;
  const sharedCached = readSharedGoogleAdsMetricsCache(cacheKey);
  if (sharedCached) {
    googleAdsMetricsCache.set(cacheKey, { value: sharedCached, expiresAt: Date.now() + GOOGLE_ADS_METRICS_CACHE_MS });
    return sharedCached;
  }

  const campaignMetrics = new Map();
  const keywordMetrics = new Map();
  let totalSpend = 0;
  let totalClicks = 0;
  let totalImpressions = 0;

  const campaignRows = await fetchGoogleAdsSearchStream(`
    SELECT
      campaign.id,
      campaign.name,
      campaign.status,
      campaign.advertising_channel_type,
      metrics.impressions,
      metrics.clicks,
      metrics.cost_micros,
      metrics.conversions,
      metrics.conversions_value
    FROM campaign
    WHERE segments.date BETWEEN '${startDate}' AND '${endDate}'
    ORDER BY metrics.cost_micros DESC
    LIMIT 1000
  `);
  for (const row of campaignRows) {
    const campaignName = cleanJustDialString(row?.campaign?.name, 180);
    const metrics = row?.metrics || {};
    const values = {
      spend: (Number(metrics.costMicros) || 0) / 1000000,
      clicks: Number(metrics.clicks) || 0,
      impressions: Number(metrics.impressions) || 0,
      googleConversions: Number(metrics.conversions) || 0,
      googleConversionValue: Number(metrics.conversionsValue) || 0,
    };
    totalSpend += values.spend;
    totalClicks += values.clicks;
    totalImpressions += values.impressions;
    addGoogleAdsMetric(campaignMetrics, campaignName, values);
  }

  try {
    const keywordRows = await fetchGoogleAdsSearchStream(`
      SELECT
        campaign.name,
        ad_group.name,
        ad_group_criterion.keyword.text,
        metrics.impressions,
        metrics.clicks,
        metrics.cost_micros,
        metrics.conversions,
        metrics.conversions_value
      FROM keyword_view
      WHERE segments.date BETWEEN '${startDate}' AND '${endDate}'
      ORDER BY metrics.cost_micros DESC
      LIMIT 5000
    `);
    for (const row of keywordRows) {
      const campaignName = cleanJustDialString(row?.campaign?.name, 180);
      const keyword = cleanJustDialString(row?.adGroupCriterion?.keyword?.text, 180);
      const metrics = row?.metrics || {};
      const values = {
        spend: (Number(metrics.costMicros) || 0) / 1000000,
        clicks: Number(metrics.clicks) || 0,
        impressions: Number(metrics.impressions) || 0,
        googleConversions: Number(metrics.conversions) || 0,
        googleConversionValue: Number(metrics.conversionsValue) || 0,
      };
      addGoogleAdsMetric(keywordMetrics, `${campaignName}|${keyword}`, values);
      addGoogleAdsMetric(keywordMetrics, keyword, values);
    }
  } catch (error) {
    console.warn('[seo-marketing/google-ads] keyword metrics unavailable:', error?.message || error);
  }

  const value = { configured: true, campaignMetrics, keywordMetrics, totalSpend, totalClicks, totalImpressions };
  const expiresAt = Date.now() + GOOGLE_ADS_METRICS_CACHE_MS;
  googleAdsMetricsCache.set(cacheKey, { value, expiresAt });
  writeSharedGoogleAdsMetricsCache(cacheKey, value, expiresAt);
  return value;
}

async function getGoogleMarketingIntegrationStatus(options = {}) {
  const parsed = parseGoogleMarketingServiceAccount();
  const warnings = [];
  if (!parsed.configured && parsed.error) warnings.push(parsed.error);
  if (!GOOGLE_MARKETING_GA4_PROPERTY_ID) warnings.push('ATTICA_GA4_PROPERTY_ID is not configured');
  if (!GOOGLE_MARKETING_SEARCH_CONSOLE_SITE_URL) warnings.push('ATTICA_SEARCH_CONSOLE_SITE_URL is not configured');
  const googleAdsServiceAccountConfigured = Boolean(
    parsed.configured
    && GOOGLE_MARKETING_ADS_CUSTOMER_ID
    && GOOGLE_MARKETING_ADS_DEVELOPER_TOKEN
  );
  const googleAdsRefreshTokenConfigured = Boolean(
    GOOGLE_MARKETING_ADS_CUSTOMER_ID
    && GOOGLE_MARKETING_ADS_DEVELOPER_TOKEN
    && GOOGLE_MARKETING_ADS_REFRESH_TOKEN
  );
  const googleAdsConfigured = googleAdsServiceAccountConfigured || googleAdsRefreshTokenConfigured;
  if (!GOOGLE_MARKETING_ADS_CUSTOMER_ID || !GOOGLE_MARKETING_ADS_DEVELOPER_TOKEN) {
    warnings.push('Google Ads API needs customer ID and developer token');
  } else if (!googleAdsConfigured) {
    warnings.push('Google Ads API needs either a readable service account JSON or OAuth refresh token');
  }

  const emailMatchesExpected = !parsed.clientEmail
    || !GOOGLE_MARKETING_EXPECTED_SERVICE_ACCOUNT_EMAIL
    || parsed.clientEmail === GOOGLE_MARKETING_EXPECTED_SERVICE_ACCOUNT_EMAIL;
  const clientIdMatchesExpected = !parsed.clientId
    || !GOOGLE_MARKETING_EXPECTED_CLIENT_ID
    || parsed.clientId === GOOGLE_MARKETING_EXPECTED_CLIENT_ID;

  let tokenStatus = 'not_checked';
  let tokenError = '';
  let tokenExpiresAt = '';
  let googleAdsTokenStatus = 'not_checked';
  let googleAdsTokenError = '';
  let googleAdsVerifiedAt = '';
  if (options.verify && parsed.configured) {
    try {
      const token = await getGoogleMarketingAccessToken();
      tokenStatus = 'valid';
      tokenExpiresAt = new Date(token.expiresAt).toISOString();
    } catch (error) {
      tokenStatus = 'failed';
      tokenError = cleanJustDialString(error?.message || error, 300);
      warnings.push(tokenError);
    }
    if (GOOGLE_MARKETING_ADS_CUSTOMER_ID && GOOGLE_MARKETING_ADS_DEVELOPER_TOKEN) {
      try {
        const adsStatus = await verifyGoogleAdsServiceAccountAccess();
        googleAdsTokenStatus = adsStatus.status;
        googleAdsVerifiedAt = adsStatus.checkedAt;
      } catch (error) {
        googleAdsTokenStatus = 'failed';
        googleAdsTokenError = cleanJustDialString(error?.message || error, 300);
        warnings.push(googleAdsTokenError);
      }
    }
  }

  return {
    configured: Boolean(parsed.configured),
    source: parsed.source || 'missing',
    credentialPath: parsed.credentialPath || (GOOGLE_MARKETING_SERVICE_ACCOUNT_PATH || ''),
    projectId: parsed.projectId || 'attica-analytics',
    clientEmail: parsed.clientEmail || GOOGLE_MARKETING_EXPECTED_SERVICE_ACCOUNT_EMAIL,
    clientId: parsed.clientId || GOOGLE_MARKETING_EXPECTED_CLIENT_ID,
    emailMatchesExpected,
    clientIdMatchesExpected,
    scopes: GOOGLE_MARKETING_SCOPES,
    tokenStatus,
    tokenExpiresAt,
    tokenError,
    ga4: {
      configured: Boolean(GOOGLE_MARKETING_GA4_PROPERTY_ID),
      propertyId: GOOGLE_MARKETING_GA4_PROPERTY_ID,
    },
    searchConsole: {
      configured: Boolean(GOOGLE_MARKETING_SEARCH_CONSOLE_SITE_URL),
      siteUrl: GOOGLE_MARKETING_SEARCH_CONSOLE_SITE_URL,
    },
    googleAds: {
      configured: googleAdsConfigured,
      authMode: googleAdsServiceAccountConfigured ? 'service_account' : googleAdsRefreshTokenConfigured ? 'refresh_token' : 'missing',
      customerId: GOOGLE_MARKETING_ADS_CUSTOMER_ID,
      managerCustomerId: GOOGLE_MARKETING_ADS_MANAGER_CUSTOMER_ID,
      apiVersion: GOOGLE_MARKETING_ADS_API_VERSION,
      developerTokenConfigured: Boolean(GOOGLE_MARKETING_ADS_DEVELOPER_TOKEN),
      refreshTokenConfigured: Boolean(GOOGLE_MARKETING_ADS_REFRESH_TOKEN),
      serviceAccountUsable: googleAdsServiceAccountConfigured,
      serviceAccountConfigured: Boolean(parsed.configured),
      tokenStatus: googleAdsTokenStatus,
      tokenError: googleAdsTokenError,
      verifiedAt: googleAdsVerifiedAt,
    },
    warnings,
    updatedAt: new Date().toISOString(),
  };
}

async function fetchGooglePlaceAutocompleteSuggestions(query) {
  if (!hasGooglePlacesApiKey()) return [];

  const params = new URLSearchParams({
    input: String(query || '').trim(),
    key: GOOGLE_PLACES_API_KEY,
    components: 'country:in',
    language: 'en',
  });

  const payload = await fetchJsonWithTimeout(`https://maps.googleapis.com/maps/api/place/autocomplete/json?${params}`);
  const status = String(payload?.status || '');
  if (!['OK', 'ZERO_RESULTS'].includes(status)) {
    throw new Error(`Google autocomplete returned ${status || 'unknown status'}`);
  }

  const predictions = Array.isArray(payload?.predictions) ? payload.predictions : [];
  return predictions
    .map((prediction) => ({
      description: String(prediction?.description || '').trim(),
      placeId: String(prediction?.place_id || '').trim(),
    }))
    .filter((prediction) => prediction.description);
}

function pickGoogleAddressComponent(result, candidateTypes = []) {
  const components = Array.isArray(result?.address_components) ? result.address_components : [];
  for (const component of components) {
    const componentTypes = Array.isArray(component?.types) ? component.types : [];
    if (candidateTypes.some((candidate) => componentTypes.includes(candidate))) {
      return String(component?.long_name || component?.short_name || '').trim();
    }
  }
  return '';
}

function buildGoogleGeocodeResult(result) {
  const location = result?.geometry?.location;
  const lat = Number(location?.lat);
  const lng = Number(location?.lng);
  if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null;

  const district = pickGoogleAddressComponent(result, ['locality', 'administrative_area_level_2', 'administrative_area_level_1']);
  const state = pickGoogleAddressComponent(result, ['administrative_area_level_1']);
  const label = String(result?.formatted_address || result?.name || '').trim();

  return {
    lat,
    lng,
    district,
    state,
    label,
  };
}

async function geocodeGooglePlace({ address = '', placeId = '' }) {
  if (!hasGooglePlacesApiKey()) return null;

  const safePlaceId = String(placeId || '').trim();
  if (safePlaceId) {
    const params = new URLSearchParams({
      place_id: safePlaceId,
      fields: 'geometry/location,address_component,formatted_address,name,address_components',
      key: GOOGLE_PLACES_API_KEY,
    });
    const payload = await fetchJsonWithTimeout(`https://maps.googleapis.com/maps/api/place/details/json?${params}`);
    const status = String(payload?.status || '');
    if (status === 'OK' && payload?.result?.geometry?.location) {
      const result = buildGoogleGeocodeResult(payload.result);
      if (result) return result;
    }
    if (!['ZERO_RESULTS', 'NOT_FOUND'].includes(status)) {
      throw new Error(`Google place details returned ${status || 'unknown status'}`);
    }
  }

  const safeAddress = String(address || '').trim();
  if (!safeAddress) return null;

  const params = new URLSearchParams({
    address: safeAddress,
    key: GOOGLE_PLACES_API_KEY,
    components: 'country:IN',
    language: 'en',
  });
  const payload = await fetchJsonWithTimeout(`https://maps.googleapis.com/maps/api/geocode/json?${params}`);
  const status = String(payload?.status || '');
  if (status === 'OK' && Array.isArray(payload?.results) && payload.results[0]?.geometry?.location) {
    const result = buildGoogleGeocodeResult(payload.results[0]);
    if (result) return result;
  }
  if (!['ZERO_RESULTS', 'NOT_FOUND'].includes(status)) {
    throw new Error(`Google geocode returned ${status || 'unknown status'}`);
  }

  return null;
}

function extractPhotonFeatureResult(feature) {
  const coordinates = Array.isArray(feature?.geometry?.coordinates) ? feature.geometry.coordinates : [];
  const lng = Number(coordinates[0]);
  const lat = Number(coordinates[1]);
  if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null;

  const properties = feature?.properties && typeof feature.properties === 'object'
    ? feature.properties
    : {};
  const location = cleanJustDialString(
    properties.name
      || properties.street
      || properties.suburb
      || properties.locality
      || properties.city
      || properties.county,
    120,
  );
  const district = cleanJustDialString(
    properties.city
      || properties.county
      || properties.locality
      || properties.district
      || properties.state_district
      || properties.state,
    120,
  );
  const state = cleanJustDialString(properties.state, 120);
  const country = cleanJustDialString(properties.country, 120);
  const label = [location, district !== location ? district : '', state && state !== district ? state : '', country]
    .filter(Boolean)
    .join(', ');

  return {
    lat,
    lng,
    district,
    state,
    label: label || location,
    description: label || location,
    source: 'photon',
  };
}

async function fetchPhotonAutocompleteSuggestions(query) {
  const params = new URLSearchParams({
    q: String(query || '').trim(),
    limit: '10',
    lang: 'en',
  });
  const payload = await fetchJsonWithTimeout(`https://photon.komoot.io/api/?${params}`, {
    headers: {
      Accept: 'application/json',
      'User-Agent': 'AtticaGoldCallcenter/1.0',
    },
  });
  const features = Array.isArray(payload?.features) ? payload.features : [];

  return features
    .map((feature) => extractPhotonFeatureResult(feature))
    .filter(Boolean)
    .map((result) => ({
      description: result.description,
      lat: result.lat,
      lng: result.lng,
      district: result.district,
      state: result.state,
      source: result.source,
    }));
}

async function geocodePhotonPlace({ address = '' }) {
  const safeAddress = String(address || '').trim();
  if (!safeAddress) return null;

  const params = new URLSearchParams({
    q: safeAddress,
    limit: '1',
    lang: 'en',
  });
  const payload = await fetchJsonWithTimeout(`https://photon.komoot.io/api/?${params}`, {
    headers: {
      Accept: 'application/json',
      'User-Agent': 'AtticaGoldCallcenter/1.0',
    },
  });
  const features = Array.isArray(payload?.features) ? payload.features : [];
  return extractPhotonFeatureResult(features[0]);
}

function listRecordingCatalogEntries() {
  const filesByName = new Map();

  for (const dir of RECORDING_SOURCE_DIRECTORIES) {
    try {
      const filenames = readdirSync(dir).filter((filename) => filename.endsWith('.wav'));
      for (const filename of filenames) {
        try {
          const absolutePath = join(dir, filename);
          const stats = statSync(absolutePath);
          if (!stats.isFile()) continue;

          const nextEntry = {
            name: filename,
            url: '/api/recordings/' + encodeURIComponent(filename),
            playbackUrl: '/api/recordings/' + encodeURIComponent(filename),
            downloadUrl: '/api/recordings/' + encodeURIComponent(filename),
            size: stats.size,
            durationSeconds: estimateAsteriskWavDurationSeconds(stats.size),
            date: stats.mtime.toISOString(),
            sourceDir: dir,
          };
          const existingEntry = filesByName.get(filename);

          if (!existingEntry) {
            filesByName.set(filename, nextEntry);
            continue;
          }

          if (existingEntry.sourceDir !== PRIMARY_RECORDING_DIRECTORY && dir === PRIMARY_RECORDING_DIRECTORY) {
            filesByName.set(filename, nextEntry);
            continue;
          }

          if (existingEntry.sourceDir === dir && existingEntry.date < nextEntry.date) {
            filesByName.set(filename, nextEntry);
          }
        } catch (error) {
          // Skip unreadable files.
        }
      }
    } catch (error) {
      // Missing directories should not break the catalog.
    }
  }

  return Array.from(filesByName.values())
    .sort((left, right) => right.date.localeCompare(left.date))
    .map(({ sourceDir, ...entry }) => entry);
}

function buildRecordingDatePrefix(value) {
  const timestamp = new Date(String(value || '').trim()).getTime();
  if (!Number.isFinite(timestamp)) return '';
  const date = new Date(timestamp);
  return [
    date.getUTCFullYear(),
    String(date.getUTCMonth() + 1).padStart(2, '0'),
    String(date.getUTCDate()).padStart(2, '0'),
  ].join('');
}

function listRecordingCatalogEntriesForCallRows(rows) {
  const phoneSuffixes = new Set();
  const datePrefixes = new Set();

  rows.forEach((row) => {
    getCallRecordingPhoneCandidates(row)
      .map((digits) => String(digits || '').replace(/[^0-9]/g, '').slice(-10))
      .filter((digits) => digits.length >= 10)
      .forEach((digits) => phoneSuffixes.add(digits));

    getCallRecordingReferenceTimes(row)
      .map((timestamp) => buildRecordingDatePrefix(new Date(timestamp).toISOString()))
      .filter(Boolean)
      .forEach((prefix) => datePrefixes.add(prefix));
  });

  if (phoneSuffixes.size === 0) return [];

  const filesByName = new Map();
  const phoneSuffixList = Array.from(phoneSuffixes);
  const datePrefixList = Array.from(datePrefixes);
  for (const dir of RECORDING_SOURCE_DIRECTORIES) {
    try {
      const filenames = readdirSync(dir).filter((filename) => {
        if (!filename.endsWith('.wav')) return false;
        if (datePrefixList.length > 0 && !datePrefixList.some((prefix) => filename.startsWith(prefix))) return false;
        return phoneSuffixList.some((phone) => filename.includes(phone));
      });

      for (const filename of filenames) {
        try {
          const absolutePath = join(dir, filename);
          const stats = statSync(absolutePath);
          if (!stats.isFile()) continue;

          const nextEntry = {
            name: filename,
            url: '/api/recordings/' + encodeURIComponent(filename),
            playbackUrl: '/api/recordings/' + encodeURIComponent(filename),
            downloadUrl: '/api/recordings/' + encodeURIComponent(filename),
            size: stats.size,
            durationSeconds: estimateAsteriskWavDurationSeconds(stats.size),
            date: stats.mtime.toISOString(),
            sourceDir: dir,
          };
          const existingEntry = filesByName.get(filename);
          if (!existingEntry || (existingEntry.sourceDir !== PRIMARY_RECORDING_DIRECTORY && dir === PRIMARY_RECORDING_DIRECTORY)) {
            filesByName.set(filename, nextEntry);
          }
        } catch (error) {
          // Skip unreadable files.
        }
      }
    } catch (error) {
      // Missing directories should not break matching.
    }
  }

  return Array.from(filesByName.values())
    .sort((left, right) => right.date.localeCompare(left.date))
    .map(({ sourceDir, ...entry }) => entry);
}

function estimateAsteriskWavDurationSeconds(size) {
  const bytes = Math.max(0, Number(size) || 0);
  if (bytes <= DEFAULT_WAV_HEADER_BYTES) return 0;
  return Math.max(0, Math.round((bytes - DEFAULT_WAV_HEADER_BYTES) / DEFAULT_ASTERISK_PCM_BYTES_PER_SECOND));
}

function buildRecordingApiPath(recordingName) {
  const safeName = basename(String(recordingName || '').trim());
  return safeName ? `/api/recordings/${encodeURIComponent(safeName)}` : '';
}

function parseRecordingFilenameTimestamp(recordingName) {
  const match = String(recordingName || '').trim().match(RECORDING_FILENAME_TIMESTAMP_PATTERN);
  if (!match) return null;

  const datePart = match[1];
  const timePart = match[2];
  const timestamp = Date.UTC(
    Number(datePart.slice(0, 4)),
    Number(datePart.slice(4, 6)) - 1,
    Number(datePart.slice(6, 8)),
    Number(timePart.slice(0, 2)),
    Number(timePart.slice(2, 4)),
    Number(timePart.slice(4, 6)),
  );
  return Number.isFinite(timestamp) ? timestamp : null;
}

function normalizeRecordingCatalogEntry(entry) {
  const recordingName = basename(String(entry?.name || '').trim());
  if (!recordingName) return null;

  const directPaths = [
    entry?.playbackUrl,
    entry?.downloadUrl,
    entry?.url,
  ].map((value) => String(value || '').trim()).filter(Boolean);
  const recordedAt = parseRecordingFilenameTimestamp(recordingName)
    ?? (() => {
      const timestamp = new Date(String(entry?.date || '').trim()).getTime();
      return Number.isFinite(timestamp) ? timestamp : null;
    })();

  return {
    name: recordingName,
    haystack: `${recordingName} ${directPaths.join(' ')}`.toLowerCase(),
    recordedAt,
    size: Math.max(0, Number(entry?.size) || 0),
    durationSeconds: Math.max(
      0,
      Number(entry?.durationSeconds) || estimateAsteriskWavDurationSeconds(entry?.size)
    ),
  };
}

function getCallRecordingPhoneCandidates(callLike) {
  const candidates = new Set();
  const rawCandidates = [
    callLike?.normalized_customer_number,
    callLike?.normalizedCustomerNumber,
    callLike?.caller_id,
    callLike?.callerId,
  ];

  rawCandidates.forEach((value) => {
    const normalizedPhone = normalizeAutoDialPhone(value);
    if (normalizedPhone) {
      candidates.add(normalizedPhone);
    }

    const digitsOnly = String(value || '').replace(/[^0-9]/g, '');
    if (digitsOnly) {
      candidates.add(digitsOnly);
      if (digitsOnly.length >= 10) {
        candidates.add(digitsOnly.slice(-10));
      }
    }
  });

  return Array.from(candidates);
}

function getCallRecordingReferenceTimes(callLike) {
  return [
    toApiIsoString(callLike?.ring_started_at || callLike?.ringStartedAt),
    toApiIsoString(callLike?.answered_at || callLike?.answeredAt),
    toApiIsoString(callLike?.created_at || callLike?.createdAt),
    toApiIsoString(callLike?.ended_at || callLike?.endedAt),
  ].map((value) => {
    const timestamp = new Date(String(value || '').trim()).getTime();
    return Number.isFinite(timestamp) ? timestamp : null;
  }).filter((value) => Number.isFinite(value));
}

function getAgentRecordingExtension(callLike) {
  const directExtension = normalizeSipExtension(callLike?.extension || callLike?.agentExtension);
  if (directExtension) return directExtension;

  const agentId = normalizeAgentId(callLike?.agent_id || callLike?.agentId);
  const numericAgentId = Number(String(agentId || '').replace(/[^0-9]/g, ''));
  if (!Number.isFinite(numericAgentId) || numericAgentId <= 0) return '';

  return String(2000 + numericAgentId);
}

function getOutboundRecordingExtension(recordingName) {
  const match = basename(String(recordingName || '').trim()).match(/^\d{8}-\d{6}-(20\d{2})-/);
  return match ? match[1] : '';
}

function scoreRecordingCatalogEntry(entry, callLike, options = {}) {
  const allowSmallFiles = options.allowSmallFiles === true;
  const phoneCandidates = getCallRecordingPhoneCandidates(callLike);
  const phoneCandidatesLong = phoneCandidates.filter((digits) => digits.length > 10);
  const phoneCandidatesLastTen = phoneCandidates
    .map((digits) => digits.slice(-10))
    .filter((digits) => digits.length >= 10);
  const hasFullPhoneMatch = phoneCandidatesLong.some((digits) => entry.haystack.includes(digits));
  const hasLastTenPhoneMatch = phoneCandidatesLastTen.some((digits) => entry.haystack.includes(digits));
  const hasStrongPhoneMatch = phoneCandidates.length > 0 && (hasFullPhoneMatch || hasLastTenPhoneMatch);
  const isInboundRecording = INBOUND_RECORDING_PATTERN.test(entry.name);
  const agentExtension = normalizeCallDirection(callLike?.direction) === 'outgoing'
    ? getAgentRecordingExtension(callLike)
    : '';
  const hasAgentExtensionMatch = Boolean(
    agentExtension && new RegExp(`(^|[-_])${agentExtension}([-_]|\\.)`).test(entry.name)
  );
  const hasDifferentAgentExtension = Boolean(
    agentExtension && /(^|[-_])20\d{2}([-_]|[.])/.test(entry.name) && !hasAgentExtensionMatch
  );
  const referenceTimes = getCallRecordingReferenceTimes(callLike);
  const nearestTimeDistance = (
    entry.recordedAt && referenceTimes.length > 0
      ? Math.min(...referenceTimes.map((timestamp) => Math.abs(entry.recordedAt - timestamp)))
      : Number.POSITIVE_INFINITY
  );

  if (
    !hasStrongPhoneMatch
    || (!allowSmallFiles && entry.size < MIN_PLAYABLE_RECORDING_BYTES)
    || (
      normalizeCallDirection(callLike?.direction) === 'outgoing'
      && agentExtension
      && getOutboundRecordingExtension(entry.name)
      && !hasAgentExtensionMatch
    )
  ) {
    return {
      score: Number.NEGATIVE_INFINITY,
      nearestTimeDistance,
    };
  }

  let score = 0;

  if (hasFullPhoneMatch) score += 180;
  else if (hasLastTenPhoneMatch) score += 140;

  if (normalizeCallDirection(callLike?.direction) === 'incoming') {
    score += isInboundRecording ? 80 : -160;
  } else {
    score += isInboundRecording ? -120 : 40;
    if (hasAgentExtensionMatch) score += 100;
    else if (hasDifferentAgentExtension) score -= 140;
  }

  score += 10;

  if (nearestTimeDistance <= 60_000) score += 220;
  else if (nearestTimeDistance <= 2 * 60_000) score += 180;
  else if (nearestTimeDistance <= 5 * 60_000) score += 120;
  else if (nearestTimeDistance <= 10 * 60_000) score += 60;
  else if (nearestTimeDistance <= 15 * 60_000) score += 20;
  else if (nearestTimeDistance <= 30 * 60_000) score -= 40;
  else if (nearestTimeDistance <= 60 * 60_000) score -= 120;
  else if (nearestTimeDistance <= 2 * 60 * 60_000) score -= 200;
  else if (Number.isFinite(nearestTimeDistance)) score -= 260;

  return {
    score,
    nearestTimeDistance,
  };
}

function hasPersistedRecordingMetadata(row) {
  return Boolean(cleanJustDialString(row?.recording_name || row?.recordingName, 255));
}

function hasZeroCallDuration(row) {
  return Math.max(
    parseDurationSeconds(row?.duration),
    Number(row?.talk_duration_seconds ?? row?.talkDurationSeconds) || 0
  ) <= 0;
}

function canShareRecordingAcrossCallRows(entry, row) {
  return normalizeCallDirection(row?.direction) === 'incoming'
    && INBOUND_RECORDING_PATTERN.test(entry?.name || '');
}

function shouldAttemptRecordingBackfill(row) {
  if (!row) return false;
  const hasRecording = Boolean(row.has_recording || row.hasRecording || hasPersistedRecordingMetadata(row));
  const hasPersistedMetadata = hasPersistedRecordingMetadata(row);
  if (hasPersistedMetadata && !hasZeroCallDuration(row)) return false;
  if (!getCallRecordingPhoneCandidates(row).length) return false;

  const hasEndedAt = Boolean(toDatabaseDateTime(row?.ended_at || row?.endedAt));
  const hasAnsweredAt = Boolean(toDatabaseDateTime(row?.answered_at || row?.answeredAt));
  const hasConnectedTalk = !hasZeroCallDuration(row) || hasAnsweredAt;
  if (!hasRecording && !hasConnectedTalk) return false;
  if (isLiveCallStatus(row?.status)) return false;
  if (hasEndedAt) return true;

  return hasConnectedTalk;
}

function getCallRowRecordingLookupKey(row, index) {
  const canonicalId = cleanCanonicalCallId(row?.id, 120)
    || cleanCanonicalCallId(row?.call_uuid || row?.callUuid, 120)
    || '';
  if (canonicalId) return canonicalId;
  return `recording-row-${index}`;
}

async function backfillRecordingMetadataOnCallRows(rows, options = {}) {
  const shouldPersistMatches = options.persistMatches === true;
  if (!Array.isArray(rows) || rows.length === 0) {
    return rows;
  }

  const rowsNeedingBackfill = rows
    .map((row, index) => ({ row, index, key: getCallRowRecordingLookupKey(row, index) }))
    .filter(({ row }) => shouldAttemptRecordingBackfill(row));
  if (rowsNeedingBackfill.length === 0) {
    return rows;
  }

  const catalog = listRecordingCatalogEntriesForCallRows(rowsNeedingBackfill.map(({ row }) => row))
    .map((entry) => normalizeRecordingCatalogEntry(entry))
    .filter(Boolean);
  if (catalog.length === 0) {
    return rows;
  }

  const reservedRecordingNames = new Set(
    rows
      .map((row) => cleanJustDialString(row?.recording_name || row?.recordingName, 255))
      .filter(Boolean)
  );
  const candidatePairs = [];

  rowsNeedingBackfill.forEach(({ row, index, key }) => {
    const rowCreatedAt = new Date(
      toApiIsoString(row?.created_at || row?.createdAt)
      || toApiIsoString(row?.answered_at || row?.answeredAt)
      || toApiIsoString(row?.ring_started_at || row?.ringStartedAt)
      || toApiIsoString(row?.ended_at || row?.endedAt)
      || 0
    ).getTime();

    catalog.forEach((entry) => {
      if (reservedRecordingNames.has(entry.name) && !canShareRecordingAcrossCallRows(entry, row)) return;

      const { score, nearestTimeDistance } = scoreRecordingCatalogEntry(entry, row);
      if (score < MIN_RECORDING_MATCH_SCORE) return;

      candidatePairs.push({
        key,
        row,
        index,
        entry,
        score,
        nearestTimeDistance,
        rowCreatedAt: Number.isFinite(rowCreatedAt) ? rowCreatedAt : 0,
      });
    });
  });

  candidatePairs.sort((left, right) => {
    if (right.score !== left.score) return right.score - left.score;
    if (left.nearestTimeDistance !== right.nearestTimeDistance) {
      return left.nearestTimeDistance - right.nearestTimeDistance;
    }
    if (right.entry.size !== left.entry.size) return right.entry.size - left.entry.size;
    if (right.rowCreatedAt !== left.rowCreatedAt) return right.rowCreatedAt - left.rowCreatedAt;
    return left.index - right.index;
  });

  const usedRecordingNames = new Set(reservedRecordingNames);
  const matchedEntryByRowKey = new Map();

  candidatePairs.forEach((candidate) => {
    if (matchedEntryByRowKey.has(candidate.key)) return;
    if (usedRecordingNames.has(candidate.entry.name) && !canShareRecordingAcrossCallRows(candidate.entry, candidate.row)) return;
    matchedEntryByRowKey.set(candidate.key, candidate.entry);
    if (!canShareRecordingAcrossCallRows(candidate.entry, candidate.row)) {
      usedRecordingNames.add(candidate.entry.name);
    }
  });

  if (matchedEntryByRowKey.size === 0) {
    return rows;
  }

  for (const { row, key } of rowsNeedingBackfill) {
    const match = matchedEntryByRowKey.get(key);
    if (!match) continue;

    if (shouldPersistMatches && cleanCanonicalCallId(row?.id, 120)) {
      const [existingRecordingRows] = await pool.query(
        `SELECT id
         FROM attica_calls
         WHERE recording_name=?
           AND id<>?
         LIMIT 1`,
        [match.name, row.id]
      );
      if (existingRecordingRows[0]?.id) {
        if (!canShareRecordingAcrossCallRows(match, row)) {
          continue;
        }
      }
    }

    row.recording_name = match.name;
    row.recordingName = match.name;
    row.recording_size = match.size;
    row.recordingSize = match.size;
    row.recording_recorded_at = match.recordedAt
      ? toDatabaseDateTime(new Date(match.recordedAt).toISOString())
      : null;
    row.recordingRecordedAt = row.recording_recorded_at ? toApiIsoString(row.recording_recorded_at) : '';
    row.has_recording = 1;
    row.hasRecording = true;
    const matchedDurationSeconds = Math.max(0, Number(match.durationSeconds) || 0);
    const shouldBackfillDuration = matchedDurationSeconds > 0 && hasZeroCallDuration(row) && !isLiveCallStatus(row?.status);
    if (shouldBackfillDuration) {
      row.talk_duration_seconds = matchedDurationSeconds;
      row.talkDurationSeconds = matchedDurationSeconds;
      row.duration = normalizeDurationValue(formatDurationSeconds(matchedDurationSeconds));
    }

    if (!shouldPersistMatches || !cleanCanonicalCallId(row?.id, 120)) {
      continue;
    }

    await pool.query(
      `UPDATE attica_calls
       SET has_recording=1,
           recording_name=CASE
             WHEN COALESCE(TRIM(recording_name), '') = '' THEN ?
             ELSE recording_name
           END,
           recording_size=CASE
             WHEN recording_size IS NULL OR recording_size = 0 THEN ?
             ELSE recording_size
           END,
           recording_recorded_at=COALESCE(recording_recorded_at, ?),
           talk_duration_seconds=CASE
             WHEN COALESCE(talk_duration_seconds, 0) = 0 AND ? > 0 AND COALESCE(status, '') NOT IN ('active','on-hold')
             THEN ?
             ELSE talk_duration_seconds
           END,
           duration=CASE
             WHEN COALESCE(duration, '') IN ('', '0', '00', '00:00') AND ? <> '' AND COALESCE(status, '') NOT IN ('active','on-hold')
             THEN ?
             ELSE duration
           END
       WHERE id=?`,
      [
        match.name,
        match.size,
        row.recording_recorded_at,
        matchedDurationSeconds,
        matchedDurationSeconds,
        shouldBackfillDuration ? row.duration : '',
        shouldBackfillDuration ? row.duration : '',
        row.id,
      ]
    );
  }

  return rows;
}

function scheduleRecordingMetadataBackfill(callId, delaysMs = [0, 5000, 15000, 45000]) {
  const normalizedCallId = cleanCanonicalCallId(callId, 120);
  if (!normalizedCallId) return;

  delaysMs.forEach((delayMs) => {
    setTimeout(async () => {
      try {
        const [rows] = await pool.query(
          'SELECT * FROM attica_calls WHERE id=? LIMIT 1',
          [normalizedCallId]
        );
        const row = rows?.[0];
        if (!row) return;
        if (cleanJustDialString(row.recording_name, 255)) return;
        if (!row.has_recording && !row.recording_name) return;
        await backfillRecordingMetadataOnCallRows([row], { persistMatches: true });
      } catch (error) {
        console.warn('Recording metadata backfill failed:', {
          callId: normalizedCallId,
          message: error?.message || String(error),
        });
      }
    }, Math.max(0, Number(delayMs) || 0));
  });
}

function formatTimeInZone(value) {
  if (!value) return '';
  const date = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(date.getTime())) return '';
  const parts = new Intl.DateTimeFormat('en-IN', {
    timeZone: DISPLAY_TIME_ZONE,
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false,
  }).formatToParts(date);
  const readPart = type => parts.find(part => part.type === type)?.value || '';
  const rawHour = readPart('hour');
  const hour = rawHour === '24' ? '00' : rawHour;
  const minute = readPart('minute');
  const second = readPart('second');
  return hour && minute && second ? `${hour}:${minute}:${second}` : '';
}

function formatBreakTimeInZone(value = new Date()) {
  return new Intl.DateTimeFormat('en-IN', {
    timeZone: DISPLAY_TIME_ZONE,
    hour: '2-digit',
    minute: '2-digit',
    hour12: true,
  }).format(value);
}

function formatDurationSeconds(value) {
  const totalSeconds = Math.max(0, Math.floor(Number(value) || 0));
  const hours = Math.floor(totalSeconds / 3600);
  const minutes = Math.floor((totalSeconds % 3600) / 60);
  const seconds = totalSeconds % 60;

  if (hours > 0) {
    return `${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;
  }

  return `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;
}

function normalizeDurationValue(value, fallback = '00:00') {
  const totalSeconds = parseDurationSeconds(value);
  if (totalSeconds <= 0) {
    return fallback;
  }
  return formatDurationSeconds(totalSeconds);
}

function normalizeBreakLogId(value, fallback = '') {
  const normalized = String(value || '').trim();
  if (!normalized) return fallback;
  if (!/^BRK-/i.test(normalized)) return normalized;
  const compositeSeparatorIndex = normalized.indexOf('|');
  if (compositeSeparatorIndex > 0) {
    return normalized.slice(0, compositeSeparatorIndex);
  }
  return normalized;
}

function isCanonicalBreakLogId(value) {
  const normalized = String(value || '').trim();
  return Boolean(normalized) && normalizeBreakLogId(normalized) === normalized;
}

function getDateTimestamp(value) {
  if (!value) return Number.NaN;
  const parsed = value instanceof Date ? value : new Date(value);
  return Number.isNaN(parsed.getTime()) ? Number.NaN : parsed.getTime();
}

function parseLegacyBreakDateTime(dateValue, timeValue) {
  const normalizedDate = formatDateInZone(dateValue) || String(dateValue || '').trim();
  const normalizedTime = String(timeValue || '').trim().toLowerCase();
  if (!normalizedDate || !normalizedTime) return null;

  const timeMatch = normalizedTime.match(/^(\d{1,2}):(\d{2})(?::(\d{2}))?\s*([ap]m)$/i);
  if (!timeMatch) return null;

  let hours = Number(timeMatch[1] || 0) % 12;
  const minutes = Number(timeMatch[2] || 0);
  const seconds = Number(timeMatch[3] || 0);
  const meridiem = String(timeMatch[4] || '').toLowerCase();
  if ([hours, minutes, seconds].some((part) => Number.isNaN(part))) {
    return null;
  }
  if (meridiem === 'pm') {
    hours += 12;
  }

  const parsed = new Date(`${normalizedDate}T${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}+05:30`);
  return Number.isNaN(parsed.getTime()) ? null : parsed;
}

function resolveBreakStartedAtDate(row) {
  const explicitStartedAt = getDateTimestamp(row?.started_at);
  if (!Number.isNaN(explicitStartedAt)) {
    return new Date(explicitStartedAt);
  }

  const legacyStartedAt = parseLegacyBreakDateTime(row?.break_date, row?.start_time);
  if (legacyStartedAt) {
    return legacyStartedAt;
  }

  const createdAt = getDateTimestamp(row?.created_at);
  if (!Number.isNaN(createdAt)) {
    return new Date(createdAt);
  }

  return null;
}

function resolveBreakEndedAtDate(row) {
  const explicitEndedAt = getDateTimestamp(row?.ended_at);
  if (!Number.isNaN(explicitEndedAt)) {
    return new Date(explicitEndedAt);
  }

  if (!row?.end_time) return null;
  const legacyEndedAt = parseLegacyBreakDateTime(row?.break_date, row?.end_time);
  if (!legacyEndedAt) return null;

  const startedAt = resolveBreakStartedAtDate(row);
  if (startedAt && legacyEndedAt.getTime() < startedAt.getTime()) {
    legacyEndedAt.setDate(legacyEndedAt.getDate() + 1);
  }

  return legacyEndedAt;
}

function parseDurationSeconds(value) {
  const normalized = String(value || '').trim().toLowerCase();
  if (!normalized) return 0;

  const minuteMatch = normalized.match(/^(\d+)\s*min(?:ute)?s?$/);
  if (minuteMatch) {
    return Number(minuteMatch[1] || 0) * 60;
  }

  const timeParts = normalized.split(':').map((part) => Number(part));
  if (timeParts.some((part) => Number.isNaN(part))) {
    return 0;
  }

  if (timeParts.length === 2) {
    const [minutes = 0, seconds = 0] = timeParts;
    return (minutes * 60) + seconds;
  }

  if (timeParts.length === 3) {
    const [hours = 0, minutes = 0, seconds = 0] = timeParts;
    return (hours * 3600) + (minutes * 60) + seconds;
  }

  return 0;
}

function getBreakDurationSeconds(row) {
  const startedAt = resolveBreakStartedAtDate(row);
  if (!startedAt || Number.isNaN(startedAt.getTime())) {
    return parseDurationSeconds(row?.duration);
  }

  const endedAt = resolveBreakEndedAtDate(row);
  if (!endedAt || Number.isNaN(endedAt.getTime())) {
    if (!row?.end_time) {
      return Math.max(0, Math.floor((Date.now() - startedAt.getTime()) / 1000));
    }
    return parseDurationSeconds(row?.duration);
  }

  return Math.max(0, Math.floor((endedAt.getTime() - startedAt.getTime()) / 1000));
}

function buildBreakDedupKey(row) {
  const startedAt = resolveBreakStartedAtDate(row);
  const startedAtKey = startedAt ? startedAt.toISOString() : '';
  return [
    row?.agent_id || '',
    startedAtKey,
    String(row?.break_type || '').trim().toLowerCase(),
    String(row?.start_time || '').trim().toLowerCase(),
  ].join('|');
}

function shouldReplaceBreakRow(currentRow, candidateRow) {
  if (!currentRow) return true;

  const currentId = String(currentRow?.id || '').trim();
  const candidateId = String(candidateRow?.id || '').trim();
  const currentNormalizedId = normalizeBreakLogId(currentId);
  const candidateNormalizedId = normalizeBreakLogId(candidateId);
  if (
    currentNormalizedId
    && candidateNormalizedId
    && currentNormalizedId === candidateNormalizedId
    && isCanonicalBreakLogId(candidateId) !== isCanonicalBreakLogId(currentId)
  ) {
    return isCanonicalBreakLogId(candidateId);
  }

  const currentBreakType = String(currentRow?.break_type || '').trim();
  const candidateBreakType = String(candidateRow?.break_type || '').trim();
  if (candidateBreakType && !currentBreakType) {
    return true;
  }

  const currentDurationSeconds = getBreakDurationSeconds(currentRow);
  const candidateDurationSeconds = getBreakDurationSeconds(candidateRow);
  if (candidateDurationSeconds !== currentDurationSeconds) {
    return candidateDurationSeconds > currentDurationSeconds;
  }

  if (Boolean(candidateRow?.end_time) !== Boolean(currentRow?.end_time)) {
    return Boolean(candidateRow?.end_time);
  }

  const currentStartedAt = getDateTimestamp(currentRow?.started_at || currentRow?.created_at);
  const candidateStartedAt = getDateTimestamp(candidateRow?.started_at || candidateRow?.created_at);
  return candidateStartedAt > currentStartedAt;
}

async function closeOpenBreaksForAgent(agentId, options = {}) {
  if (!agentId) return 0;
  const normalizedOptions = typeof options === 'string'
    ? { endTime: options }
    : (options && typeof options === 'object' ? options : {});
  const endedAtSource = normalizedOptions.endedAt || new Date().toISOString();
  const endedAt = toDatabaseDateTime(endedAtSource) || toDatabaseDateTime(new Date().toISOString());
  const endedAtDate = endedAt ? new Date(`${endedAt.replace(' ', 'T')}Z`) : new Date();
  const endTime = String(normalizedOptions.endTime || '').trim() || formatBreakTimeInZone(endedAtDate);
  const breakId = normalizeBreakLogId(normalizedOptions.breakId);
  const normalizedProvidedDuration = String(normalizedOptions.duration || '').trim();
  const [openRows] = await pool.query(
    `SELECT id, break_date, start_time, end_time, duration, created_at, started_at, ended_at
       FROM attica_break_logs
      WHERE agent_id=?
        AND end_time IS NULL
      ORDER BY COALESCE(started_at, created_at) DESC`,
    [agentId],
  );

  if (!Array.isArray(openRows) || openRows.length === 0) {
    return 0;
  }

  const rowsToClose = openRows;
  let closedCount = 0;

  for (const row of rowsToClose) {
    const startedAtDate = resolveBreakStartedAtDate(row) || endedAtDate;
    const duration = normalizedProvidedDuration
      ? normalizeDurationValue(normalizedProvidedDuration, '00:00')
      : formatDurationSeconds(Math.max(0, Math.floor((endedAtDate.getTime() - startedAtDate.getTime()) / 1000)));
    const [updateResult] = await pool.query(
      `UPDATE attica_break_logs
          SET end_time=?,
              ended_at=?,
              duration=?
        WHERE id=?`,
      [endTime, endedAt, duration, row.id],
    );
    closedCount += updateResult?.affectedRows || 0;
  }

  return closedCount;
}

async function isAgentOnOpenBreak(agentId) {
  const normalizedAgentId = normalizeAgentId(agentId);
  if (!normalizedAgentId) return false;

  const [rows] = await pool.query(
    'SELECT id FROM attica_break_logs WHERE agent_id=? AND end_time IS NULL LIMIT 1',
    [normalizedAgentId],
  );
  return rows.length > 0;
}

async function releaseAssignedAutoDialLeadsForAgentBreak(agentId) {
  const normalizedAgentId = normalizeAgentId(agentId);
  if (!normalizedAgentId) return 0;

  const [result] = await pool.query(
    `UPDATE attica_auto_dial_leads
        SET status='pending',
            assigned_agent_id=NULL,
            assigned_agent_name=NULL,
            assigned_at=NULL,
            dial_started_at=NULL,
            retry_allowed=1,
            open_dedupe_number=normalized_number,
            last_error='Released because agent went on break',
            updated_at=NOW()
      WHERE assigned_agent_id=?
        AND status='assigned'
        AND dial_started_at IS NULL`,
    [normalizedAgentId],
  );

  return Number(result?.affectedRows || 0);
}

async function ensureOpenBreakForAgent(agentId, options = {}) {
  if (!agentId) return null;
  const [[agent]] = await pool.query('SELECT id, name FROM attica_agents WHERE id=? LIMIT 1', [agentId]);
  if (!agent?.id) return null;

  const id = normalizeBreakLogId(options.breakId) || `BRK-${Date.now()}-${agentId}`;
  const startedAtSource = options.startedAt || options.createdAt || new Date().toISOString();
  const startedAt = toDatabaseDateTime(startedAtSource) || toDatabaseDateTime(new Date().toISOString());
  const startedAtDate = startedAt ? new Date(`${startedAt.replace(' ', 'T')}Z`) : new Date();
  const breakDate = String(options.breakDate || '').trim() || formatDateInZone(startedAtDate);
  const startTime = String(options.startTime || '').trim() || formatBreakTimeInZone(startedAtDate);
  const agentName = String(options.agentName || '').trim() || agent.name || agent.id;
  const breakType = normalizeAgentBreakStatus(options.breakType, 'on-break');
  await pool.query(
    `UPDATE attica_agents
        SET status=?
      WHERE id=?
        AND status <> 'inactive'`,
    [breakType, agent.id],
  );
  const [existing] = await pool.query('SELECT id FROM attica_break_logs WHERE agent_id=? AND end_time IS NULL ORDER BY COALESCE(started_at, created_at) DESC LIMIT 1', [agentId]);
  if (existing.length) {
    await pool.query(
      `UPDATE attica_break_logs
          SET agent_name=COALESCE(NULLIF(?, ''), agent_name),
              break_type=COALESCE(NULLIF(?, ''), break_type),
              break_date=COALESCE(NULLIF(?, ''), break_date),
              start_time=COALESCE(NULLIF(?, ''), start_time),
              started_at=COALESCE(started_at, ?)
        WHERE id=?`,
      [agentName, breakType, breakDate, startTime, startedAt, existing[0].id],
    );
    return existing[0].id;
  }

  await pool.query(
    'INSERT INTO attica_break_logs (id,agent_id,agent_name,break_type,break_date,start_time,started_at,end_time,ended_at,duration) VALUES (?,?,?,?,?,?,?,?,?,?)',
    [id, agent.id, agentName, breakType, breakDate, startTime, startedAt, null, null, null],
  );
  return id;
}

const AGENT_BREAK_STATUSES = new Set(['on-break', 'lunch-break', 'restroom-break']);

function normalizeAgentBreakStatus(status, fallback = 'on-break') {
  const normalized = String(status || '').trim().toLowerCase();
  return AGENT_BREAK_STATUSES.has(normalized) ? normalized : fallback;
}

function isAgentBreakStatusValue(status) {
  const normalized = String(status || '').trim().toLowerCase();
  return AGENT_BREAK_STATUSES.has(normalized);
}

function buildOpenBreakStatusByAgentId(breaks = []) {
  const latestBreakByAgentId = new Map();

  for (const entry of breaks) {
    const agentId = String(entry?.agent_id || '').trim();
    if (!agentId) continue;

    const startedAtTimestamp = getDateTimestamp(entry?.started_at || entry?.created_at);
    const startedAt = Number.isNaN(startedAtTimestamp) ? 0 : startedAtTimestamp;
    const existing = latestBreakByAgentId.get(agentId);
    if (existing && existing.startedAt > startedAt) {
      continue;
    }

    latestBreakByAgentId.set(agentId, {
      startedAt,
      status: normalizeAgentBreakStatus(entry?.break_type, 'on-break'),
    });
  }

  return new Map(Array.from(latestBreakByAgentId.entries()).map(([agentId, value]) => [agentId, value.status]));
}

function isAgentRole(role) {
  return String(role || '').trim().toLowerCase() === 'agent';
}

function applyRuntimeAgentStatus(agents, breaks, options = {}) {
  const breakStatusByAgentId = buildOpenBreakStatusByAgentId(breaks);
  const liveChannels = Array.isArray(options.liveChannels) ? options.liveChannels : [];
  return agents.map((agent) => {
    const roleIsAgent = isAgentRole(agent.role);
    const savedActiveCallId = cleanCanonicalCallId(agent.active_call_id, 120);
    const activeCallLive = roleIsAgent && savedActiveCallId
      ? hasLiveAgentExtensionChannel(agent.extension, liveChannels)
      : false;
    const staleActiveCallId = roleIsAgent && savedActiveCallId && !activeCallLive ? savedActiveCallId : '';

    if (!roleIsAgent) {
      return {
        ...agent,
        status: Number(agent.is_logged_in || 0) === 1 ? 'online' : 'offline',
        incoming_access: 0,
        outgoing_access: 0,
        follow_up_access: 0,
        active_call_id: null,
        active_call_direction: null,
        active_call_started_at: null,
        active_call_live: 0,
        stale_active_call_id: '',
      };
    }

    if (Number(agent.is_logged_in || 0) !== 1) {
      return {
        ...agent,
        status: 'offline',
        active_call_id: null,
        active_call_direction: null,
        active_call_started_at: null,
        active_call_live: 0,
        stale_active_call_id: staleActiveCallId,
      };
    }

    return {
      ...agent,
      status: agent.status !== 'inactive' && breakStatusByAgentId.has(agent.id)
        ? breakStatusByAgentId.get(agent.id)
        : agent.status,
      active_call_id: activeCallLive ? savedActiveCallId : null,
      active_call_live: activeCallLive ? 1 : 0,
      stale_active_call_id: staleActiveCallId,
    };
  });
}

function toApiIsoString(value) {
  if (!value) return '';
  const date = value instanceof Date ? value : new Date(value);
  return Number.isNaN(date.getTime()) ? '' : date.toISOString();
}

function toDatabaseDateTime(value) {
  if (value === undefined || value === null) return null;
  const normalized = String(value).trim();
  if (!normalized) return null;
  const date = new Date(normalized);
  if (Number.isNaN(date.getTime())) {
    return null;
  }
  return date.toISOString().slice(0, 19).replace('T', ' ');
}

function getDateTimeDurationSeconds(startValue, endValue) {
  if (!startValue || !endValue) return 0;

  const startAt = new Date(startValue);
  const endAt = new Date(endValue);
  if (Number.isNaN(startAt.getTime()) || Number.isNaN(endAt.getTime())) {
    return 0;
  }

  return Math.max(0, Math.round((endAt.getTime() - startAt.getTime()) / 1000));
}

async function backfillBreakLogDateTimes() {
  const [rows] = await pool.query(`
    SELECT id, break_date, start_time, end_time, duration, created_at, started_at, ended_at
    FROM attica_break_logs
    WHERE started_at IS NULL
       OR (end_time IS NOT NULL AND ended_at IS NULL)
       OR (end_time IS NOT NULL AND IFNULL(duration, '') = '')
  `);

  for (const row of rows) {
    const startedAtDate = resolveBreakStartedAtDate(row);
    const endedAtDate = resolveBreakEndedAtDate(row);
    const nextStartedAt = row?.started_at || (startedAtDate ? toDatabaseDateTime(startedAtDate.toISOString()) : null);
    const nextEndedAt = row?.ended_at || (endedAtDate ? toDatabaseDateTime(endedAtDate.toISOString()) : null);
    const nextDuration = endedAtDate && startedAtDate
      ? formatDurationSeconds(Math.max(0, Math.floor((endedAtDate.getTime() - startedAtDate.getTime()) / 1000)))
      : normalizeDurationValue(row?.duration, '');

    await pool.query(
      `UPDATE attica_break_logs
          SET started_at=COALESCE(?, started_at),
              ended_at=COALESCE(?, ended_at),
              duration=CASE
                WHEN ? <> '' THEN ?
                ELSE duration
              END
        WHERE id=?`,
      [nextStartedAt, nextEndedAt, nextDuration, nextDuration, row.id],
    );
  }
}

async function dedupeBreakLogRows() {
  const [rows] = await pool.query(`
    SELECT id, agent_id, break_type, break_date, start_time, end_time, duration, created_at, started_at, ended_at
    FROM attica_break_logs
    ORDER BY COALESCE(started_at, created_at) DESC, created_at DESC, id DESC
  `);

  const survivorByKey = new Map();
  const duplicateIds = new Set();

  for (const row of rows) {
    const dedupeKey = buildBreakDedupKey(row);
    const currentSurvivor = survivorByKey.get(dedupeKey);
    if (!currentSurvivor) {
      survivorByKey.set(dedupeKey, row);
      continue;
    }

    if (shouldReplaceBreakRow(currentSurvivor, row)) {
      duplicateIds.add(currentSurvivor.id);
      survivorByKey.set(dedupeKey, row);
      continue;
    }

    duplicateIds.add(row.id);
  }

  const idsToDelete = Array.from(duplicateIds).filter((id) => {
    const candidateId = String(id || '').trim();
    if (!candidateId) return false;
    return Array.from(survivorByKey.values()).every((row) => String(row?.id || '').trim() !== candidateId);
  });

  for (let index = 0; index < idsToDelete.length; index += 100) {
    const chunk = idsToDelete.slice(index, index + 100);
    if (chunk.length === 0) continue;
    await pool.query(
      `DELETE FROM attica_break_logs
        WHERE id IN (${chunk.map(() => '?').join(',')})`,
      chunk,
    );
  }
}

function normalizeAgentUpdateValue(requestKey, value) {
  if (requestKey === 'isLoggedIn') {
    return value ? 1 : 0;
  }
  if (requestKey === 'status') {
    return normalizeAgentAvailabilityStatus(value, 'active');
  }
  if (requestKey === 'lastLoginAt' || requestKey === 'lastLogoutAt' || requestKey === 'followUpStartedAt') {
    return toDatabaseDateTime(value);
  }
  if (requestKey === 'incomingAccess' || requestKey === 'outgoingAccess' || requestKey === 'followUpAccess') {
    return (value === false || value === 0 || value === '0') ? 0 : 1;
  }
  if (requestKey === 'adminMessage') {
    return String(value || '').trim().slice(0, 500) || null;
  }
  return value || null;
}

function resolveAgentWorkStatusFromAccessValues({
  incomingAccess,
  outgoingAccess,
  followUpAccess,
} = {}) {
  const incoming = Number(incomingAccess) !== 0;
  const outgoing = Number(outgoingAccess) !== 0;
  const followUp = Number(followUpAccess) !== 0;
  if (outgoing && !incoming && !followUp) return 'outbound-auto';
  if (followUp && !incoming && !outgoing) return 'follow-up';
  return 'active';
}

function isStaleAgentLoginUpdate(payload = {}) {
  if (payload?.isLoggedIn !== true) return false;

  const loginDate = formatDateInZone(payload.lastLoginAt);
  if (!loginDate) return false;

  return loginDate < getBusinessDateString();
}

function isFreshWorkstationIpSeenAt(seenAt, loginAt, isLoggedIn) {
  if (!seenAt) return false;
  const seenTimestamp = new Date(seenAt).getTime();
  if (!Number.isFinite(seenTimestamp)) return false;

  if (isLoggedIn) {
    const loginTimestamp = new Date(loginAt || '').getTime();
    return !Number.isFinite(loginTimestamp) || seenTimestamp >= loginTimestamp - 60 * 1000;
  }

  return Date.now() - seenTimestamp <= 15 * 60 * 1000;
}

function serializeAgentRecord(agent) {
  const sipContactIp = agent.sip_contact_ip || agent.sipContactIp || '';
  const legacyWorkstationIp = !isGatewayPlaceholderIp(agent.last_login_ip) ? agent.last_login_ip : '';
  const rawWorkstationIp = agent.last_workstation_ip
    || agent.last_session_workstation_ip
    || legacyWorkstationIp
    || '';
  const workstationIpLastSeenAt = agent.last_workstation_ip_seen_at
    || agent.last_session_workstation_ip_seen_at
    || (legacyWorkstationIp ? agent.last_login_at : '')
    || '';
  const isLoggedIn = agent.is_logged_in === 1 || agent.is_logged_in === true;
  const storedWorkstationIp = isFreshWorkstationIpSeenAt(workstationIpLastSeenAt, agent.last_login_at, isLoggedIn)
    ? rawWorkstationIp
    : '';
  const workstationIp = sipContactIp || storedWorkstationIp;
  const publicLoginIp = agent.last_public_login_ip
    || agent.last_session_public_login_ip
    || (isGatewayPlaceholderIp(agent.last_login_ip) ? agent.last_login_ip : '')
    || '';
  const rawLastLoginIp = workstationIp || publicLoginIp || agent.last_login_ip || agent.last_session_login_ip || '';
  const lastLoginIpIsGateway = Boolean(rawLastLoginIp) && isGatewayPlaceholderIp(rawLastLoginIp);
  return {
    ...agent,
    shift: agent.shift || '',
    isLoggedIn,
    loginTime: agent.login_time || '',
    logoutTime: agent.logout_time || '',
    lastLoginAt: toApiIsoString(agent.last_login_at),
    lastLogoutAt: toApiIsoString(agent.last_logout_at),
    publicLoginIp,
    workstationIp,
    workstationIpLastSeenAt: toApiIsoString(workstationIpLastSeenAt),
    lastLoginIp: workstationIp || publicLoginIp || rawLastLoginIp || '',
    lastLoginIpIsGateway,
    lastLoginDeviceId: agent.last_login_device_id || agent.last_session_device_id || '',
    activeDuration: agent.active_duration || '',
    breakTime: agent.break_time || '',
    followUpStartedAt: toApiIsoString(agent.follow_up_started_at),
    followUpDuration: agent.follow_up_duration || '',
    incomingAccess: agent.incoming_access !== 0,
    outgoingAccess: agent.outgoing_access !== 0,
    followUpAccess: agent.follow_up_access !== 0,
    adminMessage: agent.admin_message || '',
    sipPassword: agent.sip_password || agent.sipPassword || '',
    activeCallId: agent.active_call_id || '',
    activeCallLive: agent.active_call_live === 1 || agent.active_call_live === true,
    staleActiveCallId: agent.stale_active_call_id || '',
    activeCallDirection: agent.active_call_direction || '',
    activeCallStartedAt: toApiIsoString(agent.active_call_started_at),
    callStateUpdatedAt: toApiIsoString(agent.call_state_updated_at),
    lastCallEndedAt: toApiIsoString(agent.last_call_ended_at),
    uiRefreshToken: uiRefreshState.token,
    uiRefreshScope: uiRefreshState.scope,
    uiRefreshTriggeredAt: uiRefreshState.triggeredAt,
  };
}

function attachCurrentUiRefreshStateToAgents(agents = []) {
  return agents.map((agent) => ({
    ...agent,
    uiRefreshToken: uiRefreshState.token,
    uiRefreshScope: uiRefreshState.scope,
    uiRefreshTriggeredAt: uiRefreshState.triggeredAt,
  }));
}

async function loadAgentRecordsForEndpoint() {
  const now = Date.now();
  if (agentsEndpointCache && agentsEndpointCacheExpiresAt > now) {
    return attachCurrentUiRefreshStateToAgents(agentsEndpointCache);
  }

  if (agentsEndpointCache) {
    if (!agentsEndpointPromise) {
      agentsEndpointPromise = refreshAgentRecordsEndpointCache()
        .catch((error) => {
          console.error('Agent records background refresh failed:', error);
          return agentsEndpointCache;
        })
        .finally(() => {
          agentsEndpointPromise = null;
        });
    }
    return attachCurrentUiRefreshStateToAgents(agentsEndpointCache);
  }

  if (agentsEndpointPromise) {
    const cached = await agentsEndpointPromise;
    return attachCurrentUiRefreshStateToAgents(cached);
  }

  agentsEndpointPromise = refreshAgentRecordsEndpointCache().finally(() => {
    agentsEndpointPromise = null;
  });

  const cached = await agentsEndpointPromise;
  return attachCurrentUiRefreshStateToAgents(cached);
}

async function refreshAgentRecordsEndpointCache() {
  const [agents] = await pool.query(`
    SELECT a.id, a.name, a.email, a.role, a.extension, a.shift, a.status, a.admin_message,
           a.is_logged_in, a.login_time, a.logout_time,
           a.last_login_at, a.last_logout_at, a.active_duration, a.break_time,
           a.follow_up_started_at, a.follow_up_duration,
           a.incoming_access, a.outgoing_access, a.follow_up_access,
           a.active_call_id, a.active_call_direction, a.active_call_started_at,
           a.call_state_updated_at, a.last_call_ended_at, a.last_login_ip,
           a.last_public_login_ip, a.last_workstation_ip, a.last_workstation_ip_seen_at,
           a.last_login_device_id,
           s.login_ip AS last_session_login_ip,
           s.public_login_ip AS last_session_public_login_ip,
           s.workstation_ip AS last_session_workstation_ip,
           s.workstation_ip_seen_at AS last_session_workstation_ip_seen_at,
           s.device_id AS last_session_device_id
    FROM attica_agents a
    LEFT JOIN (
      SELECT sess.agent_id, sess.login_ip, sess.public_login_ip, sess.workstation_ip,
             sess.workstation_ip_seen_at, sess.device_id
      FROM attica_agent_sessions sess
      INNER JOIN (
        SELECT agent_id, MAX(login_at) AS latest_login_at
        FROM attica_agent_sessions
        WHERE IFNULL(login_ip, '') <> ''
        GROUP BY agent_id
      ) latest
        ON latest.agent_id=sess.agent_id
       AND latest.latest_login_at=sess.login_at
    ) s ON s.agent_id=a.id
    ORDER BY a.id
  `);
  const [breaks] = await pool.query('SELECT agent_id, break_type, started_at, created_at FROM attica_break_logs WHERE end_time IS NULL');
  let liveChannels = [];
  try {
    liveChannels = readAsteriskConciseChannels();
  } catch (error) {
    console.warn('User management active-call channel snapshot skipped:', error?.message || error);
  }
  const pjsipContactIpByExtension = parsePjsipContactIpByExtension(readPjsipContactOutput());
  const records = applyRuntimeAgentStatus(agents, breaks, { liveChannels }).map((agent) => serializeAgentRecord({
    ...agent,
    sip_contact_ip: pjsipContactIpByExtension.get(normalizeSipExtension(agent.extension)) || '',
  }));
  agentsEndpointCache = records;
  agentsEndpointCacheExpiresAt = Date.now() + AGENTS_ENDPOINT_CACHE_TTL_MS;
  return records;
}

function serializeAgentSessionRecord(row) {
  const workstationIp = row.workstation_ip || (!isGatewayPlaceholderIp(row.login_ip) ? row.login_ip : '') || '';
  const publicLoginIp = row.public_login_ip || (isGatewayPlaceholderIp(row.login_ip) ? row.login_ip : '') || '';
  return {
    id: String(row.id || ''),
    agentId: row.agent_id || '',
    agentName: row.agent_name || row.agent_id || '',
    role: row.role || 'agent',
    extension: row.extension || '',
    sessionState: row.logout_at ? 'logged-out' : 'logged-in',
    loginAt: toApiIsoString(row.login_at),
    logoutAt: toApiIsoString(row.logout_at),
    loginTime: row.login_time || '',
    logoutTime: row.logout_time || '',
    publicLoginIp,
    workstationIp,
    workstationIpLastSeenAt: toApiIsoString(row.workstation_ip_seen_at),
    loginIp: workstationIp || publicLoginIp || row.login_ip || '',
    loginIpIsGateway: Boolean(!workstationIp && publicLoginIp) && isGatewayPlaceholderIp(publicLoginIp),
    deviceId: row.device_id || '',
    activeDuration: row.active_duration || '',
    breakTime: row.break_time || '',
    createdAt: toApiIsoString(row.created_at),
    updatedAt: toApiIsoString(row.updated_at),
  };
}

async function getAgentSessionSnapshot(agentId) {
  if (!agentId) return null;
  const [[agent]] = await pool.query(
    'SELECT id, name, role, extension FROM attica_agents WHERE id=? LIMIT 1',
    [agentId]
  );
  return agent?.id ? agent : null;
}

async function syncAgentSessionHistory(agentId, updates = {}) {
  if (!agentId) return;

  const agent = await getAgentSessionSnapshot(agentId);
  if (!agent?.id) return;

  const loginAt = toDatabaseDateTime(updates.lastLoginAt);
  const logoutAt = toDatabaseDateTime(updates.lastLogoutAt);
  const loginTime = String(updates.loginTime || '').trim() || null;
  const logoutTime = String(updates.logoutTime || '').trim() || null;
  const publicLoginIp = String(updates.publicLoginIp || updates.loginIp || '').trim().slice(0, 45);
  const workstationIp = getReportedComputerIp(
    updates.workstationIp || updates.computerIp || updates.browserIp || updates.clientIp
  );
  const loginIp = workstationIp || publicLoginIp;
  const deviceId = sanitizeLoginDeviceId(updates.deviceId);
  const activeDuration = String(updates.activeDuration || '').trim() || null;
  const breakTime = String(updates.breakTime || '').trim() || null;

  if (updates.isLoggedIn === true && loginAt) {
    await pool.query(
      `UPDATE attica_agent_sessions
          SET agent_name=?,
              role=?,
              extension=?,
              logout_at=COALESCE(logout_at, ?),
              logout_time=COALESCE(logout_time, ?),
              updated_at=CURRENT_TIMESTAMP
        WHERE agent_id=?
          AND logout_at IS NULL
          AND login_at<>?`,
      [
        agent.name || agent.id,
        agent.role || 'agent',
        agent.extension || '',
        loginAt,
        loginTime,
        agent.id,
        loginAt,
      ]
    );
    await pool.query(
      `INSERT INTO attica_agent_sessions (
         agent_id, agent_name, role, extension,
         login_at, login_time, logout_at, logout_time,
         login_ip, public_login_ip, workstation_ip, workstation_ip_seen_at,
         device_id, active_duration, break_time
       ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, IF(? <> '', NOW(), NULL), ?, ?, ?)
       ON DUPLICATE KEY UPDATE
         agent_name=VALUES(agent_name),
         role=VALUES(role),
         extension=VALUES(extension),
         login_time=VALUES(login_time),
         login_ip=COALESCE(NULLIF(VALUES(login_ip), ''), login_ip),
         public_login_ip=COALESCE(NULLIF(VALUES(public_login_ip), ''), public_login_ip),
         workstation_ip=COALESCE(NULLIF(VALUES(workstation_ip), ''), workstation_ip),
         workstation_ip_seen_at=COALESCE(VALUES(workstation_ip_seen_at), workstation_ip_seen_at),
         device_id=COALESCE(NULLIF(VALUES(device_id), ''), device_id),
         logout_at=NULL,
         logout_time=NULL,
         active_duration=VALUES(active_duration),
         break_time=VALUES(break_time),
         updated_at=CURRENT_TIMESTAMP`,
      [
        agent.id,
        agent.name || agent.id,
        agent.role || 'agent',
        agent.extension || '',
        loginAt,
        loginTime,
        null,
        null,
        loginIp || null,
        publicLoginIp || null,
        workstationIp || null,
        workstationIp,
        deviceId || null,
        activeDuration,
        breakTime,
      ]
    );
    return;
  }

  if (updates.isLoggedIn === false) {
    await pool.query(
      `UPDATE attica_agent_sessions
          SET agent_name=?,
              role=?,
              extension=?,
              logout_at=COALESCE(?, logout_at),
              logout_time=COALESCE(?, logout_time),
              active_duration=COALESCE(?, active_duration),
              break_time=COALESCE(?, break_time),
              updated_at=CURRENT_TIMESTAMP
        WHERE agent_id=?
          AND logout_at IS NULL`,
      [
        agent.name || agent.id,
        agent.role || 'agent',
        agent.extension || '',
        logoutAt,
        logoutTime,
        activeDuration,
        breakTime,
        agent.id,
      ]
    );
  }
}

async function backfillAgentSessionHistory() {
  const [rows] = await pool.query(
    `SELECT id, name, role, extension, is_logged_in, login_time, logout_time,
            last_login_at, last_logout_at, last_login_ip, last_login_device_id, active_duration, break_time
       FROM attica_agents
      WHERE last_login_at IS NOT NULL`
  );

  for (const row of rows) {
    const loginAt = toDatabaseDateTime(row.last_login_at);
    if (!loginAt) continue;

    const isLoggedIn = row.is_logged_in === 1 || row.is_logged_in === true;
    const legacyPublicIp = isGatewayPlaceholderIp(row.last_login_ip) ? (row.last_login_ip || null) : null;
    const legacyWorkstationIp = !isGatewayPlaceholderIp(row.last_login_ip) ? (row.last_login_ip || null) : null;
    await pool.query(
      `INSERT INTO attica_agent_sessions (
         agent_id, agent_name, role, extension,
         login_at, login_time, logout_at, logout_time,
         login_ip, public_login_ip, workstation_ip, workstation_ip_seen_at,
         device_id, active_duration, break_time
       ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, IF(? IS NOT NULL, ?, NULL), ?, ?, ?)
       ON DUPLICATE KEY UPDATE
         agent_name=VALUES(agent_name),
         role=VALUES(role),
         extension=VALUES(extension),
         login_time=VALUES(login_time),
         login_ip=COALESCE(NULLIF(VALUES(login_ip), ''), login_ip),
         public_login_ip=COALESCE(NULLIF(VALUES(public_login_ip), ''), public_login_ip),
         workstation_ip=COALESCE(NULLIF(VALUES(workstation_ip), ''), workstation_ip),
         workstation_ip_seen_at=COALESCE(VALUES(workstation_ip_seen_at), workstation_ip_seen_at),
         device_id=COALESCE(NULLIF(VALUES(device_id), ''), device_id),
         logout_at=VALUES(logout_at),
         logout_time=VALUES(logout_time),
         active_duration=VALUES(active_duration),
         break_time=VALUES(break_time),
         updated_at=CURRENT_TIMESTAMP`,
      [
        row.id,
        row.name || row.id,
        row.role || 'agent',
        row.extension || '',
        loginAt,
        row.login_time || null,
        isLoggedIn ? null : toDatabaseDateTime(row.last_logout_at),
        isLoggedIn ? null : (row.logout_time || null),
        legacyWorkstationIp || legacyPublicIp,
        legacyPublicIp,
        legacyWorkstationIp,
        legacyWorkstationIp,
        legacyWorkstationIp ? loginAt : null,
        row.last_login_device_id || null,
        row.active_duration || null,
        row.break_time || null,
      ]
    );
  }
}

function getCallDisplayDate(row) {
  if (row.call_date) {
    if (typeof row.call_date === 'string') {
      const matched = row.call_date.trim().match(/^(\d{4})-(\d{2})-(\d{2})/);
      if (matched) return `${matched[1]}-${matched[2]}-${matched[3]}`;
    }
    return formatDateInZone(row.call_date) || getBusinessDateString(row.call_date);
  }
  if (row.created_at) {
    return formatDateInZone(row.created_at);
  }
  return '';
}

function normalizeDisplayClockTime(value) {
  const normalized = String(value || '').trim();
  const matched = normalized.match(/^(\d{1,2}):(\d{2})(?::(\d{2}))?$/);
  if (!matched) return normalized;
  return [
    String(matched[1]).padStart(2, '0'),
    matched[2],
    matched[3] || '00',
  ].join(':');
}

function getCallDisplayTime(row) {
  const timestamp = row.answered_at || row.ring_started_at || row.created_at;
  if (timestamp) {
    return formatTimeInZone(timestamp);
  }
  return normalizeDisplayClockTime(row.call_time);
}

function normalizeQueryDate(value) {
  const normalized = String(value || '').trim().slice(0, 10);
  return /^\d{4}-\d{2}-\d{2}$/.test(normalized) ? normalized : '';
}

function getNextQueryDate(value) {
  const normalized = normalizeQueryDate(value);
  if (!normalized) return '';
  const date = new Date(`${normalized}T00:00:00.000Z`);
  if (Number.isNaN(date.getTime())) return '';
  date.setUTCDate(date.getUTCDate() + 1);
  return date.toISOString().slice(0, 10);
}

function getQueryDateTimeRange(value) {
  const normalized = normalizeQueryDate(value);
  if (!normalized) return null;
  const nextDate = getNextQueryDate(normalized);
  if (!nextDate) return null;
  return {
    start: `${normalized} 00:00:00`,
    end: `${nextDate} 00:00:00`,
  };
}

function getQueryDateDaysBefore(value, dayOffset = 0) {
  const normalized = normalizeQueryDate(value);
  if (!normalized) return '';
  const date = new Date(`${normalized}T00:00:00.000Z`);
  if (Number.isNaN(date.getTime())) return normalized;
  date.setUTCDate(date.getUTCDate() - Math.max(0, Math.trunc(Number(dayOffset) || 0)));
  return date.toISOString().slice(0, 10);
}

function getSourceLeadQueryWindow(query = {}) {
  const requestedDays = Number.parseInt(String(query.days || ''), 10);
  const days = Math.min(
    SOURCE_LEADS_MAX_DAYS,
    Math.max(
      SOURCE_LEADS_DEFAULT_DAYS,
      Number.isFinite(requestedDays) ? requestedDays : SOURCE_LEADS_DEFAULT_DAYS,
    ),
  );
  const endDate = normalizeQueryDate(query.endDate || query.to || query.dateTo) || getBusinessDateString();
  const startDate = normalizeQueryDate(query.startDate || query.from || query.dateFrom)
    || getQueryDateDaysBefore(endDate, days - 1);
  const requestedLimit = Number.parseInt(String(query.limit || ''), 10);
  const limit = Math.min(
    SOURCE_LEADS_MAX_LIMIT,
    Math.max(
      SOURCE_LEADS_DEFAULT_LIMIT,
      Number.isFinite(requestedLimit) ? requestedLimit : SOURCE_LEADS_DEFAULT_LIMIT,
    ),
  );

  return { startDate, endDate, days, limit };
}

function normalizeQueryText(value, maxLength = 160) {
  return String(value || '').trim().toLowerCase().slice(0, maxLength);
}

function normalizeAgentIdentifier(value, maxLength = 20) {
  return String(value || '').trim().toUpperCase().slice(0, maxLength);
}

function normalizeSipExtension(value) {
  const normalized = String(value || '').replace(/[^0-9]/g, '').slice(0, 10);
  return /^\d{3,6}$/.test(normalized) ? normalized : '';
}

function normalizeIpAddress(value) {
  let normalized = String(value || '').trim();
  if (!normalized) return '';

  normalized = normalized.replace(/^"|"$/g, '');
  if (normalized.startsWith('::ffff:')) {
    normalized = normalized.slice(7);
  }
  if (normalized.startsWith('[')) {
    const closingBracketIndex = normalized.indexOf(']');
    normalized = closingBracketIndex > 0 ? normalized.slice(1, closingBracketIndex) : normalized;
  } else {
    const portMatch = normalized.match(/^(\d{1,3}(?:\.\d{1,3}){3}):\d+$/);
    if (portMatch) normalized = portMatch[1];
  }

  const ipv4Parts = normalized.split('.');
  if (ipv4Parts.length === 4 && ipv4Parts.every((part) => /^\d{1,3}$/.test(part) && Number(part) >= 0 && Number(part) <= 255)) {
    return ipv4Parts.map((part) => String(Number(part))).join('.');
  }
  if (/^[0-9a-f:]+$/i.test(normalized) && normalized.includes(':')) {
    return normalized.toLowerCase();
  }
  return '';
}

function isGatewayPlaceholderIp(ipAddress) {
  const ip = normalizeIpAddress(ipAddress);
  if (!ip) return false;
  return /^(10|172\.(1[6-9]|2\d|3[0-1])|192\.168)\.\d+\.(1|254)$/.test(ip)
    || ip === '127.0.0.1'
    || ip === '::1';
}

const TRUSTED_PROXY_IPS = new Set(
  String(process.env.ATTICA_TRUSTED_PROXY_IPS || '127.0.0.1,::1')
    .split(',')
    .map((entry) => normalizeIpAddress(entry))
    .filter(Boolean)
);

function splitIpHeader(value) {
  return String(value || '')
    .split(',')
    .map((entry) => normalizeIpAddress(entry))
    .filter(Boolean);
}

function getRequestClientIp(req) {
  const headerCandidates = [
    ...splitIpHeader(req.headers['cf-connecting-ip']),
    ...splitIpHeader(req.headers['true-client-ip']),
    ...splitIpHeader(req.headers['x-client-ip']),
    ...splitIpHeader(req.headers['x-forwarded-for']),
    ...splitIpHeader(req.headers['x-real-ip']),
  ].filter(Boolean);
  const fallbackCandidates = [
    ...(Array.isArray(req.ips) ? req.ips.map((ip) => normalizeIpAddress(ip)).filter(Boolean) : []),
    normalizeIpAddress(req.socket?.remoteAddress),
    normalizeIpAddress(req.ip),
  ].filter(Boolean);
  const candidates = [...headerCandidates, ...fallbackCandidates];

  const headerClientIp = headerCandidates.find((candidate) => (
    !TRUSTED_PROXY_IPS.has(candidate) && !isGatewayPlaceholderIp(candidate)
  ));
  const nonProxyCandidate = candidates.find((candidate) => (
    !TRUSTED_PROXY_IPS.has(candidate) && !isGatewayPlaceholderIp(candidate)
  ));
  const gatewayCandidate = candidates.find((candidate) => (
    !TRUSTED_PROXY_IPS.has(candidate) && isGatewayPlaceholderIp(candidate)
  ));
  return (headerClientIp || nonProxyCandidate || gatewayCandidate || '').slice(0, 45);
}

function getReportedComputerIp(value) {
  const candidates = splitIpHeader(value);
  const usableCandidate = candidates.find((candidate) => (
    !TRUSTED_PROXY_IPS.has(candidate) && !isGatewayPlaceholderIp(candidate)
  ));
  return (usableCandidate || '').slice(0, 45);
}

function sanitizeLoginDeviceId(value) {
  return String(value || '')
    .trim()
    .replace(/[^a-zA-Z0-9_-]/g, '')
    .slice(0, 80);
}

const DISPOSITION_CATEGORY_VALUES = {
  Lost: [
    'ABUSE_CALL', 'Abuse Call',
    'NI', 'Not Interested',
    'WN', 'Wrong Number',
    'JRC', 'Job Related Call',
    'ARC', 'Advertisement Related Call',
    'GL_OTHER', 'General Enquiry - Other',
    'DIS_LB', 'Disconnected - Language Barrier',
    'SPAM', 'Spam Call',
  ],
  Enquiry: [
    'GRE_OLD', 'Gold Rate Enquiry - Old Gold',
    'GRE_NEW', 'Gold Rate Enquiry - New Gold Purchase',
    'PCE', 'Payment Channel Enquiry',
    'DOC_REQ', 'Documents Required Information',
    'CTR', 'Call Transfer',
    'TRANSFERRED', 'Transferred',
    'ENQ', 'Enquiry',
    'LB', 'Line Busy',
    'PND', 'Pending',
    'REPLEDGE_ENQ', 'Repledge Enquiry',
    'SILVER_ENQ', 'Silver Enquiry',
  ],
  'Follow Up / Call Back': [
    'CB', 'Call Back',
    'LM', 'Left Message',
    'DEC', 'Declined',
    'MISSED', 'Missed',
    'PENDING_CALLS', 'Pending Calls',
    'Pending (They will discuss and come)',
    'CUSTOMER_DISCONNECTED', 'Customer Disconnected',
  ],
  'L2 Lost & Complaints': [
    'CSE', "Can't Send Executive", 'Cant Send Executive',
    'QM', 'Quotation Mismatch',
    'BMI', 'BM Behaviour Issue',
    'BCV', 'Branch Closed but Customer Visited',
    'WCPQ', 'Quotation Given Without Purity Check',
    'SDC', 'Service Delay Complaint',
    'SBC', 'Staff Behaviour Complaint',
    'NOT_SERVICEABLE', 'Not Serviceable',
    'SOLD_OUTSIDE', 'Sold Outside',
  ],
  RNR: [
    'RNR', 'Ring No Reply',
    'NA', 'No Answer',
    'DIS', 'Disconnected',
    'DIS_NC', 'Disconnected - Not Connected',
  ],
  QL: [
    'CTO', 'Coming to Office', 'Coming To Branch',
    'VNS', 'Visited Not-Sold', 'Visited Not Sold Out',
    'INT', 'Interested',
    'NBL', 'Nearest Branch Location',
    'BT', 'Branch Timings',
    'MRR', 'Margin Reduce Request',
    'IQA', 'Increase Quotation Amount Request',
    'SUV', 'Speed Up Validation Request',
    'DOOR_STEP_ENQUIRY', 'Door-Step Enquiry',
    'PLANNING_TO_VISIT', 'Planning to Visit (Date and Time)',
  ],
  Billed: [
    'SE_SELL', 'Service Enquiry - Sell Gold',
    'SE_BUY', 'Service Enquiry - Buy Gold',
    'SE_RELEASE', 'Service Enquiry - Release Gold',
    'SOLD', 'Sale Done',
    'Sold Out', 'Visited Sold Out', 'Billed', 'Final Sale',
  ],
  Others: [
    'NONE', 'None',
    'OOS', 'Out of State',
  ],
  'Active / Scheduled Call': [
    'SCHEDULED', 'Scheduled',
  ],
  Walkin: [
    'VISITED_BRANCH', 'Visited Branch',
  ],
};

const DISPOSITION_CATEGORY_BY_KEY = new Map();
for (const [category, values] of Object.entries(DISPOSITION_CATEGORY_VALUES)) {
  values.forEach((value) => {
    DISPOSITION_CATEGORY_BY_KEY.set(normalizeDispositionCategoryKey(value), category);
  });
}

function normalizeDispositionCategoryKey(value) {
  return cleanJustDialString(value, 120)
    .toLowerCase()
    .replace(/&/g, 'and')
    .replace(/[^a-z0-9]+/g, '');
}

function normalizeDispositionCategoryName(value) {
  const key = normalizeDispositionCategoryKey(value);
  if (!key) return '';
  const aliases = {
    lost: 'Lost',
    enquiry: 'Enquiry',
    followupcallback: 'Follow Up / Call Back',
    followupcallbackback: 'Follow Up / Call Back',
    callback: 'Follow Up / Call Back',
    l2lostandcomplaints: 'L2 Lost & Complaints',
    l2lostcomplaints: 'L2 Lost & Complaints',
    rnr: 'RNR',
    ql: 'QL',
    billed: 'Billed',
    others: 'Others',
    other: 'Others',
    activescheduledcall: 'Active / Scheduled Call',
    scheduledcall: 'Active / Scheduled Call',
    scheduled: 'Active / Scheduled Call',
    walkin: 'Walkin',
    walkins: 'Walkin',
    walkinbranch: 'Walkin',
  };
  return aliases[key] || '';
}

function getDispositionCategory(value) {
  const key = normalizeDispositionCategoryKey(value);
  if (!key) return '';
  if (SOLD_OUT_STATUS_KEYS.has(key)) return 'Billed';
  return DISPOSITION_CATEGORY_BY_KEY.get(key) || '';
}

function getCallCategory(row = {}) {
  const status = cleanJustDialString(row.status || row.sourceStatus || row.source_status, 40).toLowerCase();
  const direction = normalizeCallDirection(row.direction || row.callDirection || row.call_direction);
  const disposition = cleanJustDialString(
    row.disposition
    || row.callbackStatus
    || row.callback_status
    || row.formStatus
    || row.form_status,
    120
  );
  const dispositionKey = normalizeDispositionCategoryKey(disposition);
  const durationSeconds = Math.max(
    parseDurationSeconds(row.duration),
    Number(row.durationSeconds || row.duration_seconds || row.talkDurationSeconds || row.talk_duration_seconds) || 0
  );
  const isZeroDuration = durationSeconds === 0 || ['00:00', '00:00:00', '0', '00'].includes(String(row.duration || '').trim());

  if (isZeroDuration && status === 'failed' && ['ringnoreply', 'rnr'].includes(dispositionKey)) {
    return 'RNR';
  }

  if (
    direction === 'incoming'
    && durationSeconds > 0
    && ['completed', 'answered', 'transferred'].includes(status)
    && ['ringnoreply', 'rnr', 'noanswer', 'na'].includes(dispositionKey)
  ) {
    return 'Follow Up / Call Back';
  }

  if (
    status === 'completed'
    && ['planningtovisit', 'planningtovisitdatetime', 'comingtooffice', 'comingtobranch'].includes(dispositionKey)
  ) {
    return 'QL';
  }

  if (
    status === 'completed'
    && ['customerdisconnected', 'calldisconnected', 'disconnected'].includes(dispositionKey)
  ) {
    return 'Follow Up / Call Back';
  }

  if (status === 'completed' && ['pendingcalls', 'pending', 'pnd'].includes(dispositionKey)) {
    return 'Follow Up / Call Back';
  }

  if (status === 'active' && (!dispositionKey || ['none', 'null'].includes(dispositionKey))) {
    return 'Others';
  }

  if (status === 'active' && dispositionKey === 'scheduled') {
    return 'Active / Scheduled Call';
  }

  return getDispositionCategory(disposition) || 'Others';
}

function isRnrDispositionValue(value) {
  return ['ringnoreply', 'rnr', 'noanswer', 'na', 'ringingnoresponse'].includes(
    normalizeDispositionCategoryKey(value)
  );
}

function resolveConnectedIncomingCallbackStatus({
  direction = '',
  status = '',
  callbackStatus = '',
  duration = '',
  talkDurationSeconds = 0,
  answeredAt = '',
  hasRecording = false,
} = {}) {
  const normalizedDirection = normalizeCallDirection(direction);
  const normalizedStatus = normalizeCallStatus(status);
  const durationSeconds = Math.max(
    parseDurationSeconds(duration),
    Number(talkDurationSeconds) || 0
  );
  const hasConnectedIncomingTalk = normalizedDirection === 'incoming'
    && ['completed', 'answered', 'transferred'].includes(normalizedStatus)
    && (
      durationSeconds > 0
      || Boolean(answeredAt)
      || Boolean(hasRecording)
    );

  if (hasConnectedIncomingTalk && isRnrDispositionValue(callbackStatus)) {
    return 'Customer Disconnected';
  }

  return callbackStatus;
}

function isGenericCompletedDisposition(value) {
  const key = normalizeDispositionCategoryKey(value);
  return key === 'completed';
}

function isSystemDisconnectCallbackStatus(value) {
  const normalized = cleanJustDialString(value, 100).toLowerCase();
  return Boolean(normalized) && SYSTEM_DISCONNECT_CALLBACK_STATUSES.has(normalized);
}

function isCallbackQueuePlaceholderStatus(value) {
  const normalized = cleanJustDialString(value, 100).toLowerCase();
  return Boolean(normalized) && CALLBACK_QUEUE_PLACEHOLDER_STATUSES.has(normalized);
}

function isMeaningfulAgentDisposition(value) {
  const cleaned = cleanJustDialString(value, 100);
  const key = normalizeDispositionCategoryKey(cleaned);
  return Boolean(cleaned)
    && !LEAD_PURPOSE_STATUS_KEYS.has(key)
    && !isGenericCompletedDisposition(cleaned)
    && !isSystemDisconnectCallbackStatus(cleaned)
    && !isCallbackQueuePlaceholderStatus(cleaned);
}

function isDisplayableSystemDisposition(value) {
  const cleaned = cleanJustDialString(value, 100);
  if (!cleaned || isGenericCompletedDisposition(cleaned)) return false;
  const normalized = cleaned.toLowerCase();
  return SYSTEM_DISCONNECT_CALLBACK_STATUSES.has(normalized)
    && !['none', 'completed', 'auto dial'].includes(normalized);
}

function resolveVisibleDisposition(primaryDisposition, ...fallbackDispositionValues) {
  const primary = cleanJustDialString(primaryDisposition, 100);
  const primaryKey = normalizeDispositionCategoryKey(primary);
  const fallback = fallbackDispositionValues
    .map((value) => cleanJustDialString(value, 100))
    .find(isMeaningfulAgentDisposition);
  const systemFallback = fallbackDispositionValues
    .map((value) => cleanJustDialString(value, 100))
    .find(isDisplayableSystemDisposition);

  if ([primary, ...fallbackDispositionValues].some(isSoldOutCustomerDataStatus)) {
    return 'Sold Out';
  }

  if (
    isGenericCompletedDisposition(primary)
    || isSystemDisconnectCallbackStatus(primary)
    || isCallbackQueuePlaceholderStatus(primary)
  ) {
    return fallback || systemFallback || primary;
  }

  if (LEAD_PURPOSE_STATUS_KEYS.has(primaryKey)) {
    return fallback || systemFallback || '';
  }

  return primary;
}

function addDispositionCategoryFilter(where, params, category, soldOutSql = CUSTOMER_DATA_SOLD_OUT_SQL) {
  const normalizedCategory = normalizeDispositionCategoryName(category);
  if (!normalizedCategory) return where;

  if (normalizedCategory === 'Active / Scheduled Call') {
    return `${where} AND LOWER(status)='active' AND LOWER(callback_status)='scheduled'`;
  }

  const values = DISPOSITION_CATEGORY_VALUES[normalizedCategory] || [];
  const normalizedValues = Array.from(new Set(values.map((value) => cleanJustDialString(value, 120).toLowerCase()).filter(Boolean)));
  if (normalizedValues.length === 0) return where;

  const placeholders = normalizedValues.map(() => '?').join(',');
  let categorySql = `(
    LOWER(IFNULL(callback_status,'')) IN (${placeholders})
    OR LOWER(IFNULL(form_status,'')) IN (${placeholders})
    OR LOWER(IFNULL(disposition,'')) IN (${placeholders})
  )`;
  const categoryParams = [...normalizedValues, ...normalizedValues, ...normalizedValues];

  if (normalizedCategory === 'Follow Up / Call Back') {
    categorySql = `(${categorySql} OR (LOWER(status)='completed' AND LOWER(callback_status) IN ('pending','pnd','pending calls','customer disconnected','call disconnected','disconnected')))`;
  }

  if (normalizedCategory === 'QL') {
    categorySql = `(${categorySql} OR (LOWER(status)='completed' AND LOWER(callback_status) IN ('planning to visit','planning to visit (date and time)','coming to office','coming to branch')))`;
  }

  let nextWhere = `${where} AND ${categorySql}`;
  params.push(...categoryParams);

  if (normalizedCategory === 'Billed') {
    nextWhere = `${where} AND (${categorySql} OR ${soldOutSql})`;
  }

  return nextWhere;
}

function buildCallFilters({
  date = '',
  fromDate = '',
  toDate = '',
  agentId = '',
  direction = '',
  status = '',
  disposition = '',
  dispositionCategory = '',
  language = '',
  branch = '',
  search = '',
} = {}) {
  let where = '1=1';
  const params = [];

  if (date) {
    const dateRange = getQueryDateTimeRange(date);
    if (dateRange) {
      where += ' AND (call_date=? OR (call_date IS NULL AND created_at>=? AND created_at<?))';
      params.push(date, dateRange.start, dateRange.end);
    } else {
      where += ' AND call_date=?';
      params.push(date);
    }
  } else {
    if (fromDate) {
      const fromRange = getQueryDateTimeRange(fromDate);
      if (fromRange) {
        where += ' AND (call_date>=? OR (call_date IS NULL AND created_at>=?))';
        params.push(fromDate, fromRange.start);
      } else {
        where += ' AND call_date>=?';
        params.push(fromDate);
      }
    }
    if (toDate) {
      const toRange = getQueryDateTimeRange(toDate);
      if (toRange) {
        where += ' AND (call_date<=? OR (call_date IS NULL AND created_at<?))';
        params.push(toDate, toRange.end);
      } else {
        where += ' AND call_date<=?';
        params.push(toDate);
      }
    }
  }

  if (agentId) {
    where += ' AND agent_id=?';
    params.push(agentId);
  }

  if (direction) {
    where += ' AND direction=?';
    params.push(direction);
    if (direction === 'incoming') {
      where += ` AND ${countableIncomingCallSql()}`;
    }
  }

  if (status === 'live' || status === 'open') {
    where += " AND status IN ('ringing','connecting','answered','active','on-hold')";
  } else if (status) {
    where += ' AND status=?';
    params.push(status);
  }

  if (disposition) {
    const normalizedDisposition = cleanJustDialString(disposition, 100).toLowerCase();
    if (isSoldOutCustomerDataStatus(disposition)) {
      where += ` AND (
        LOWER(IFNULL(callback_status,''))=?
        OR LOWER(IFNULL(form_status,''))=?
        OR LOWER(IFNULL(disposition,''))=?
        OR ${CUSTOMER_DATA_SOLD_OUT_SQL}
      )`;
      params.push(normalizedDisposition, normalizedDisposition, normalizedDisposition);
    } else {
      where += ` AND (
        LOWER(IFNULL(callback_status,''))=?
        OR LOWER(IFNULL(form_status,''))=?
        OR LOWER(IFNULL(disposition,''))=?
      )`;
      params.push(normalizedDisposition, normalizedDisposition, normalizedDisposition);
    }
  }

  if (dispositionCategory) {
    where = addDispositionCategoryFilter(where, params, dispositionCategory);
  }

  if (language) {
    where += ' AND LOWER(language)=?';
    params.push(language);
  }

  if (branch) {
    where += ' AND LOWER(branch)=?';
    params.push(branch);
  }

  if (search) {
    const searchPattern = `%${search}%`;
    where += ' AND (LOWER(caller_id) LIKE ? OR LOWER(normalized_customer_number) LIKE ? OR LOWER(caller_name) LIKE ? OR LOWER(customer_name) LIKE ? OR LOWER(agent_name) LIKE ? OR LOWER(branch) LIKE ?)';
    params.push(searchPattern, searchPattern, searchPattern, searchPattern, searchPattern, searchPattern);
  }

  return { where, params };
}

function getDisplayCustomerNameFromValues(...values) {
  for (const value of values) {
    const normalized = cleanJustDialString(value, 255);
    if (isMeaningfulCustomerName(normalized)) {
      return normalized;
    }
  }
  return '';
}

function normalizeDemographicTextValue(value, maxLength = 20) {
  const normalized = cleanJustDialString(value, maxLength);
  if (!normalized) return '';
  return /^n\/?a$/i.test(normalized) ? 'NA' : normalized;
}

function normalizeAgeFieldValue(value) {
  return normalizeDemographicTextValue(value, 20);
}

function normalizeGenderFieldValue(value) {
  const normalized = normalizeDemographicTextValue(value, 20);
  if (!normalized || normalized === 'NA') return normalized;
  if (/^male$/i.test(normalized)) return 'Male';
  if (/^female$/i.test(normalized)) return 'Female';
  if (/^other$/i.test(normalized)) return 'Other';
  return '';
}

function hasMeaningfulDemographicValue(value) {
  const normalized = normalizeDemographicTextValue(value, 20);
  return Boolean(normalized) && normalized !== 'NA';
}

function pickPreferredDemographicValue(primary, fallback, type = 'age') {
  const normalizeValue = type === 'gender' ? normalizeGenderFieldValue : normalizeAgeFieldValue;
  const primaryValue = normalizeValue(primary);
  if (hasMeaningfulDemographicValue(primaryValue)) return primaryValue;
  return normalizeValue(fallback) || '';
}

function normalizeLeadSourceLabel(value) {
  const raw = cleanJustDialString(value, 255);
  if (!raw) return '';
  const normalized = raw.toLowerCase();

  if (normalized.includes('incoming') || normalized.includes('inbound')) {
    return 'Incoming';
  }
  if (
    normalized.includes('justdial')
    || normalized.includes('just dial')
    || normalized.includes('jd_lead')
    || normalized.includes('jd-lead')
    || normalized.includes('jd lead')
  ) {
    return 'JustDial';
  }
  if (normalized.includes('website') || normalized.includes('web site')) {
    return 'Website';
  }
  if (normalized.includes('meta') || normalized.includes('facebook') || normalized.includes('instagram')) {
    return 'Meta Lead';
  }
  if (normalized.includes('status follow')) {
    return 'Status Follow-Up';
  }
  if (normalized.includes('missed call')) {
    return 'Missed Call';
  }
  if (normalized.includes('auto follow') || normalized.includes('rnr')) {
    return 'Auto Follow-Up';
  }
  if (normalized === 'manual') {
    return 'Manual';
  }

  return raw;
}

function getCallLeadSourceLabel(row = {}) {
  if (normalizeCallDirection(row?.direction) === 'incoming') {
    return 'Incoming';
  }

  return normalizeLeadSourceLabel(
    row?.lead_source
    || row?.source_file
    || row?.source
    || row?.lead_from
    || row?.leadSource
    || row?.sourceFile
    || ''
  );
}

function normalizeReportSourceFilterValue(value) {
  return normalizeLeadSourceLabel(value || 'Manual').trim().toLowerCase();
}

const SOLD_OUT_STATUS_KEYS = new Set([
  'soldout',
  'sold',
  'customersoldout',
  'finalsale',
  'billed',
]);

const CUSTOMER_DATA_SOLD_OUT_SQL = `(
  LOWER(REPLACE(IFNULL(form_status,''), ' ', '')) IN ('soldout','sold','customersoldout','finalsale','billed')
  OR LOWER(REPLACE(IFNULL(callback_status,''), ' ', '')) IN ('soldout','sold','customersoldout','finalsale','billed')
  OR LOWER(REPLACE(IFNULL(purpose,''), ' ', '')) IN ('soldout','customersoldout','finalsale')
  OR LOWER(REPLACE(IFNULL(business_type,''), ' ', '')) IN ('soldout','customersoldout','finalsale')
)`;
const CUSTOMER_DATA_BILL_ATTRIBUTION_METHOD = 'HIGHEST_TOTAL_TALK_TIME_ANY_DAY_FOR_BILLED_NUMBER';
const CUSTOMER_DATA_BILL_ATTRIBUTION_NO_AGENT_REASON = 'No eligible connected agent call found for billed number';

function isSoldOutCustomerDataStatus(value) {
  const normalized = cleanJustDialString(value, 100)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '');
  return SOLD_OUT_STATUS_KEYS.has(normalized);
}

function resolveCustomerDataDisposition(primaryDisposition, ...customerDataValues) {
  return resolveVisibleDisposition(primaryDisposition, ...customerDataValues);
}

function getRecordingBackedDurationSeconds(row) {
  const explicitDurationSeconds = Math.max(
    parseDurationSeconds(row?.duration),
    Number(row?.talk_duration_seconds || row?.talkDurationSeconds) || 0
  );
  const timestampBackedDurationSeconds = getDateTimeDurationSeconds(
    row?.answered_at || row?.answeredAt,
    row?.ended_at || row?.endedAt,
  );

  // Answered/ended timestamps are the authoritative connected-call duration.
  // Older clients could persist a stale browser timer (sometimes hours long),
  // so never let that value win when both telephony timestamps are present.
  if (timestampBackedDurationSeconds > 0) {
    return timestampBackedDurationSeconds;
  }
  if (explicitDurationSeconds > 0) {
    return explicitDurationSeconds;
  }

  const hasRecording = Boolean(cleanJustDialString(row?.recording_name || row?.recordingName, 255));
  if (!hasRecording || isLiveCallStatus(row?.status)) {
    return 0;
  }

  const endValue = row?.ended_at || row?.endedAt;
  const startValue = row?.answered_at
    || row?.answeredAt
    || row?.ring_started_at
    || row?.ringStartedAt
    || row?.created_at
    || row?.createdAt;

  return getDateTimeDurationSeconds(startValue, endValue);
}

function getSerializedCallerId(row = {}) {
  const rawCallerId = cleanJustDialString(row?.caller_id || row?.callerId, 40);
  const normalizedPhone = normalizeAutoDialPhone(row?.normalized_customer_number || row?.normalizedCustomerNumber);
  const rawCallerDigits = rawCallerId.replace(/[^0-9]/g, '');
  const rawCallerPhone = normalizeAutoDialPhone(rawCallerId);

  if (rawCallerPhone && rawCallerDigits.length >= 10) {
    return rawCallerPhone;
  }
  if (normalizedPhone) {
    return normalizedPhone;
  }
  return rawCallerId;
}

function serializeCallRow(r) {
  const serializedDirection = r.direction;
  const serializedEndedAt = toApiIsoString(r.ended_at);
  const serializedAnsweredAt = toApiIsoString(r.answered_at);
  const rawTalkDurationSeconds = Math.max(0, Number(r.talk_duration_seconds) || 0);
  const rawDuration = normalizeDurationValue(r.duration);
  const timestampBackedDurationSeconds = getDateTimeDurationSeconds(
    r.answered_at,
    r.ended_at,
  );
  const recordingBackedDurationSeconds = getRecordingBackedDurationSeconds(r);
  const serializedTalkDurationSeconds = timestampBackedDurationSeconds > 0
    ? timestampBackedDurationSeconds
    : Math.max(rawTalkDurationSeconds, recordingBackedDurationSeconds);
  const serializedDuration = serializedTalkDurationSeconds > 0
    ? normalizeDurationValue(formatDurationSeconds(serializedTalkDurationSeconds))
    : rawDuration;
  const rawDisplayCustomerName = getDisplayCustomerNameFromValues(r.customer_name, r.caller_name);
  const rawCallbackStatus = resolveCustomerDataDisposition(r.callback_status, r.form_status, r.purpose, r.business_type);
  const recordingName = cleanJustDialString(r.recording_name, 255);
  const serializedStatus = coerceSerializedEndedCallStatus({
    direction: serializedDirection,
    status: r.status,
    endedAt: serializedEndedAt,
    answeredAt: serializedAnsweredAt,
    talkDurationSeconds: rawTalkDurationSeconds,
    duration: rawDuration,
  });
  const callbackStatus = resolveConnectedIncomingCallbackStatus({
    direction: serializedDirection,
    status: serializedStatus,
    callbackStatus: rawCallbackStatus,
    duration: serializedDuration,
    talkDurationSeconds: serializedTalkDurationSeconds,
    answeredAt: serializedAnsweredAt,
    hasRecording: Boolean(recordingName),
  });
  return {
    id: cleanCanonicalCallId(r.id, 120) || cleanCanonicalCallId(r.call_uuid, 120) || cleanJustDialString(r.id, 120) || '',
    customerId: cleanJustDialString(r.customer_uid, 40) || getCustomerUidForPhone(r.normalized_customer_number || r.caller_id),
    customerUid: cleanJustDialString(r.customer_uid, 40) || getCustomerUidForPhone(r.normalized_customer_number || r.caller_id),
    callerId: getSerializedCallerId(r),
    callerName: r.caller_name,
    customerName: getDisplayCustomerNameFromValues(r.customer_name, r.caller_name) || '',
    displayCustomerName: rawDisplayCustomerName || 'N/A',
    intakeToken: cleanCanonicalIntakeToken(r.intake_token) || '',
    mob2: r.mob2 || '',
    age: normalizeAgeFieldValue(r.age),
    gender: normalizeGenderFieldValue(r.gender),
    district: r.district || '',
    businessType: r.business_type || '',
    metalType: r.metal_type || '',
    grams: r.grams || '',
    releaseGrossAmount: r.release_gross_amount || '',
    releasingAmount: r.releasing_amount || '',
    pledgePlace: r.pledge_place || '',
    otherPledgePlace: r.other_pledge_place || '',
    differenceAmount: r.difference_amount || '',
    bankName: r.bank_name || '',
    onlinePrice: r.online_price || '',
    pricePerGram: r.price_per_gram || '',
    advertisement: r.advertisement || '',
    lead: r.lead || '',
    leadSource: getCallLeadSourceLabel(r),
    formStatus: r.form_status || '',
    agentId: r.agent_id,
    agentName: r.agent_name,
    direction: serializedDirection,
    status: serializedStatus,
    duration: serializedDuration,
    ringStartedAt: toApiIsoString(r.ring_started_at),
    answeredAt: serializedAnsweredAt,
    endedAt: serializedEndedAt,
    talkDurationSeconds: serializedTalkDurationSeconds,
    time: getCallDisplayTime(r),
    date: getCallDisplayDate(r),
    language: r.language,
    hasRecording: Boolean(recordingName),
    recordingName,
    recordingSize: Math.max(0, Number(r.recording_size) || 0),
    recordingRecordedAt: toApiIsoString(r.recording_recorded_at),
    branch: r.branch,
    place: r.place,
    purpose: r.purpose,
    callbackStatus,
    dispositionCategory: getCallCategory({
      direction: serializedDirection,
      status: serializedStatus,
      duration: serializedDuration,
      talkDurationSeconds: serializedTalkDurationSeconds,
      callbackStatus,
    }),
    followUpFlag: !!r.follow_up_flag,
    statusFollowUpAt: toApiIsoString(r.status_follow_up_at),
    quickNote: cleanJustDialString(r.quick_note, 500),
    notes: r.notes || '',
    smsSent: !!r.sms_sent,
    createdAt: toApiIsoString(r.created_at),
  };
}

function serializeIntakeFormRow(row) {
  const callbackStatus = resolveCustomerDataDisposition(row.callback_status, row.form_status, row.purpose, row.business_type);
  const sourceStatus = cleanJustDialString(row.source_status, 20);
  const callDirection = normalizeCallDirection(row.call_direction);
  const callStatus = normalizeCallStatus(row.call_status);
  const callTalkDurationSeconds = Math.max(0, Number(row.call_talk_duration_seconds) || 0);
  const callDuration = normalizeDurationValue(
    row.call_duration || (callTalkDurationSeconds > 0 ? formatDurationSeconds(callTalkDurationSeconds) : ''),
    ''
  );
  const leadSource = normalizeLeadSourceLabel(
    row.lead_source
      || row.source_file
      || row.source
      || row.lead_from
      || (callDirection === 'incoming' ? 'Incoming' : '')
      || (callDirection === 'outgoing' ? 'Manual Dial' : '')
  );
  return {
    callId: cleanCanonicalCallId(row.call_id, 120) || '',
    customerId: cleanJustDialString(row.customer_uid, 40) || getCustomerUidForPhone(row.normalized_phone),
    customerUid: cleanJustDialString(row.customer_uid, 40) || getCustomerUidForPhone(row.normalized_phone),
    intakeToken: cleanCanonicalIntakeToken(row.intake_token) || '',
    callUuid: cleanCanonicalCallId(row.call_uuid, 120) || '',
    normalizedPhone: normalizeAutoDialPhone(row.normalized_phone) || '',
    callerName: cleanJustDialString(row.caller_name, 255),
    customerName: cleanJustDialString(row.customer_name, 255),
    agentId: normalizeAgentId(row.agent_id),
    agentName: cleanJustDialString(row.agent_name, 100),
    mob2: cleanJustDialString(row.mob2, 50),
    age: normalizeAgeFieldValue(row.age),
    gender: normalizeGenderFieldValue(row.gender),
    district: cleanJustDialString(row.district, 100),
    language: cleanJustDialString(row.language, 30),
    businessType: cleanJustDialString(row.business_type, 100),
    metalType: cleanJustDialString(row.metal_type, 100),
    grams: cleanJustDialString(row.grams, 50),
    releaseGrossAmount: cleanJustDialString(row.release_gross_amount, 50),
    releasingAmount: cleanJustDialString(row.releasing_amount, 50),
    pledgePlace: cleanJustDialString(row.pledge_place, 150),
    otherPledgePlace: cleanJustDialString(row.other_pledge_place, 150),
    differenceAmount: cleanJustDialString(row.difference_amount, 50),
    bankName: cleanJustDialString(row.bank_name, 150),
    onlinePrice: cleanJustDialString(row.online_price, 50),
    pricePerGram: cleanJustDialString(row.price_per_gram, 50),
    advertisement: cleanJustDialString(row.advertisement, 100),
    lead: cleanJustDialString(row.lead, 100),
    leadSource,
    formStatus: cleanJustDialString(row.form_status, 100),
    statusFollowUpAt: toApiIsoString(row.status_follow_up_at),
    branch: cleanJustDialString(row.branch, 150),
    place: cleanJustDialString(row.place, 255),
    purpose: cleanJustDialString(row.purpose, 150),
    callbackStatus,
    dispositionCategory: getCallCategory({
      status: sourceStatus,
      callbackStatus,
    }),
    quickNote: cleanJustDialString(row.quick_note, 500),
    notes: cleanJustDialString(row.notes, 5000),
    smsSent: Number(row.sms_sent) > 0,
    sourceStatus,
    direction: callDirection === 'incoming' || callDirection === 'outgoing' ? callDirection : '',
    status: callStatus || sourceStatus,
    duration: callDuration,
    date: row.call_date ? String(row.call_date).slice(0, 10) : '',
    time: cleanJustDialString(row.call_time, 20),
    hasRecording: Number(row.call_has_recording) > 0,
    ringStartedAt: toApiIsoString(row.call_ring_started_at),
    answeredAt: toApiIsoString(row.call_answered_at),
    endedAt: toApiIsoString(row.call_ended_at),
    talkDurationSeconds: callTalkDurationSeconds,
    lastSavedAt: toApiIsoString(row.last_saved_at),
    createdAt: toApiIsoString(row.created_at),
    updatedAt: toApiIsoString(row.updated_at),
  };
}

function serializeCustomerDataRow(row) {
  const recordedAt = row.created_at || row.last_saved_at || row.updated_at;
  const status = resolveCustomerDataDisposition(row.callback_status, row.form_status, row.purpose, row.business_type)
    || cleanJustDialString(row.form_status || row.callback_status, 100);
  return {
    customerName: cleanJustDialString(row.customer_name || row.caller_name, 255),
    contact: normalizeAutoDialPhone(row.normalized_phone) || '',
    type: cleanJustDialString(row.business_type || row.purpose, 100),
    branch: cleanJustDialString(row.branch, 150),
    date: recordedAt ? (formatDateInZone(recordedAt) || '') : '',
    time: recordedAt ? formatTimeInZone(recordedAt) : '',
    status,
    dispositionCategory: getCallCategory({ disposition: status }),
    grossW: cleanJustDialString(row.grams, 50),
    walkinType: cleanJustDialString(row.purpose, 150),
    firstAgentName: cleanJustDialString(row.agent_name, 100),
  };
}

let remoteCustomerDataListCache = null;
let remoteCustomerDataListCacheKey = '';
let remoteCustomerDataListCacheExpiresAt = 0;
let remoteCustomerDataSyncInFlight = null;
let remoteCustomerDataLastSyncedAt = 0;

function clearRemoteCustomerDataListCache() {
  remoteCustomerDataListCache = null;
  remoteCustomerDataListCacheKey = '';
  remoteCustomerDataListCacheExpiresAt = 0;
}

async function syncRemoteCustomerDataCacheIfStale(maxAgeMs = CUSTOMER_DATA_REMOTE_CACHE_MS) {
  const safeMaxAgeMs = Math.max(1000, Number(maxAgeMs) || CUSTOMER_DATA_REMOTE_CACHE_MS);
  if (remoteCustomerDataLastSyncedAt > 0 && Date.now() - remoteCustomerDataLastSyncedAt < safeMaxAgeMs) {
    return 0;
  }

  try {
    return await syncRemoteCustomerDataCache();
  } catch (error) {
    console.warn('[customerdata] stale refresh failed, using cached remote rows:', error?.message || error);
    return 0;
  }
}

function readRemoteCustomerDataExtra(row) {
  if (!row || typeof row !== 'object' || typeof row.extra !== 'string' || !row.extra.trim()) {
    return {};
  }

  try {
    const parsed = JSON.parse(row.extra);
    return parsed && typeof parsed === 'object' ? parsed : {};
  } catch (_error) {
    return {};
  }
}

function isVisibleRemoteCustomerDataRow(row) {
  const statusKey = cleanJustDialString(row?.status, 60).toLowerCase();
  return CUSTOMER_DATA_REMOTE_VISIBLE_STATUSES.has(statusKey);
}

function deriveRemoteCustomerOrnamentType(row) {
  const idNumber = cleanJustDialString(row?.idnumber ?? row?.idNumber ?? row?.ornamentType ?? row?.ornament_type, 150);
  const idSignal = idNumber.toLowerCase();
  if (idSignal.includes('silver')) return 'Silver';
  if (idSignal.includes('gold')) return 'Gold';

  const quotation = parseJsonObject(row?.quotation);
  const rate = Number(String(quotation.rate ?? quotation.Rate ?? '').replace(/[^0-9.]/g, ''));
  if (Number.isFinite(rate) && rate > 0) {
    return rate < 1000 ? 'Silver' : 'Gold';
  }

  const type = cleanJustDialString(row?.type, 100);
  const typeSignal = type.toLowerCase();
  if (
    idSignal.includes('phys')
    || idSignal.includes('phy')
    || typeSignal === 'physical'
    || typeSignal === 'release'
  ) {
    return 'Gold';
  }

  return type;
}

function parseRemoteMoneyNumber(value) {
  if (value === undefined || value === null) return 0;
  const parsed = Number(String(value).replace(/[^0-9.-]/g, ''));
  return Number.isFinite(parsed) ? parsed : 0;
}

function roundMoneyAmount(value) {
  const amount = Number(value);
  if (!Number.isFinite(amount) || amount <= 0) return 0;
  return Math.round(amount * 100) / 100;
}

function deriveRemoteCustomerBillingAmount(row, grossWeightValue = '') {
  const extra = readRemoteCustomerDataExtra(row);
  const quotation = parseJsonObject(row?.quotation);
  const issueCallMeta = parseJsonObject(row?.issuecallmeta);
  const explicitAmount = [
    row?.billing_amount,
    row?.billingAmount,
    row?.billAmount,
    row?.bill_amount,
    row?.totalAmount,
    row?.total_amount,
    row?.netAmount,
    row?.net_amount,
    row?.releaseAmount,
    row?.release_amount,
    row?.issue_call_amount,
    row?.issuecallprice,
    issueCallMeta.issueCallAmount,
    issueCallMeta.issue_call_amount,
    issueCallMeta.amount,
    extra.BillAmount,
    extra.billAmount,
    extra.bill_amount,
    extra.TotalAmount,
    extra.totalAmount,
    extra.amount,
    extra.NetA,
    extra.netAmount,
    extra.RelAmount,
    extra.releaseAmount,
    extra.release_amount,
  ].map(parseRemoteMoneyNumber).find((amount) => amount > 0);
  if (explicitAmount) return roundMoneyAmount(explicitAmount);

  const grossWeight = parseRemoteMoneyNumber(
    grossWeightValue
    || extra.GrossW
    || extra.grossW
    || extra.gross_weight
    || extra.gross
  );
  const rate = parseRemoteMoneyNumber(
    quotation.rate
    || quotation.Rate
    || row?.rate
    || row?.price
    || extra.rate
    || extra.Rate
  );
  return roundMoneyAmount(grossWeight * rate);
}

function normalizeRemoteCustomerBillStatus(value) {
  const status = cleanJustDialString(value, 100);
  const key = status.toLowerCase().replace(/[\s_-]+/g, '');
  if (['approved', 'billed', 'bill', 'completed', 'complete', 'paid', 'success', 'successful'].includes(key)) {
    return 'Billed';
  }
  return status;
}

function getRemoteCustomerBillId(row) {
  return cleanJustDialString(
    row?.billId
    ?? row?.bill_id
    ?? row?.billid
    ?? row?.invoiceId
    ?? row?.invoice_id
    ?? '',
    80
  );
}

function hasConfirmedCustomerBillingTransaction(transaction) {
  const billId = getRemoteCustomerBillId(transaction);
  return Boolean(billId);
}

function getTransactionGrossWeight(transaction) {
  return cleanJustDialString(
    transaction?.grossW
    ?? transaction?.gross_w
    ?? transaction?.grossWeight
    ?? transaction?.gross_weight
    ?? transaction?.hold_grossW
    ?? '',
    50
  );
}

function getTransactionNetWeight(transaction) {
  return cleanJustDialString(
    transaction?.netW
    ?? transaction?.NetW
    ?? transaction?.net_w
    ?? transaction?.netWeight
    ?? transaction?.NetWeight
    ?? transaction?.net_weight
    ?? transaction?.netweight
    ?? transaction?.netWt
    ?? transaction?.NetWt
    ?? transaction?.net_wt
    ?? transaction?.hold_netW
    ?? transaction?.hold_net_w
    ?? transaction?.['Net W']
    ?? transaction?.['Net Weight']
    ?? transaction?.['net weight']
    ?? '',
    50
  );
}

function getTransactionBillingAmount(transaction) {
  return [
    transaction?.netA,
    transaction?.net_amount,
    transaction?.amountPaid,
    transaction?.amount_paid,
    transaction?.grossA,
    transaction?.gross_amount,
  ].map(parseRemoteMoneyNumber).find((amount) => amount > 0) || 0;
}

function serializeRemoteCustomerDataRow(row) {
  const extra = readRemoteCustomerDataExtra(row);
  const status = cleanJustDialString(row?.status, 100);
  const type = deriveRemoteCustomerOrnamentType(row);
  const category = status.toLowerCase() === 'billed'
    ? 'Billed'
    : status.toLowerCase() === 'release'
      ? 'Billed'
      : getCallCategory({ disposition: status });
  const grossW = cleanJustDialString(extra.GrossW ?? extra.grossW ?? extra.gross_weight ?? extra.gross, 50);
  const netW = cleanJustDialString(
    extra.NetW
    ?? extra.netW
    ?? extra.NetWeight
    ?? extra.netweight
    ?? extra.net_weight
    ?? extra.netWeight
    ?? extra.netWt
    ?? extra.net_wt
    ?? extra['Net W']
    ?? extra['Net Weight']
    ?? extra['net weight']
    ?? row?.netW
    ?? row?.NetW
    ?? row?.net_w
    ?? row?.netWeight
    ?? row?.NetWeight
    ?? row?.net_weight
    ?? row?.netweight
    ?? row?.netWt
    ?? row?.net_wt
    ?? row?.['Net W']
    ?? row?.['Net Weight']
    ?? row?.['net weight'],
    50
  );

  return {
    customerName: cleanJustDialString(row?.customer, 255),
    contact: normalizeAutoDialPhone(row?.contact) || cleanJustDialString(row?.contact, 30),
    type,
    branch: cleanJustDialString(row?.branch, 150),
    date: normalizeQueryDate(row?.date) || cleanJustDialString(row?.date, 30),
    time: cleanJustDialString(row?.time, 30),
    status,
    dispositionCategory: category,
    grossW,
    netW,
    billId: getRemoteCustomerBillId(row),
    transactionStatus: '',
    billAmount: deriveRemoteCustomerBillingAmount(row, grossW),
    walkinType: cleanJustDialString(row?.walkinType || row?.serviceType || type, 150),
    firstAgentName: cleanJustDialString(row?.agent || row?.updated_by || '', 100),
  };
}

function buildRemoteCustomerDataId(row) {
  const explicitId = cleanJustDialString(row?.Id ?? row?.id, 80);
  if (explicitId) return explicitId;

  return createHash('sha1')
    .update(JSON.stringify({
      contact: normalizeAutoDialPhone(row?.contact) || cleanJustDialString(row?.contact, 30),
      date: normalizeQueryDate(row?.date),
      time: cleanJustDialString(row?.time, 30),
      customer: cleanJustDialString(row?.customer, 255),
      status: cleanJustDialString(row?.status, 100),
    }))
    .digest('hex');
}

async function upsertRemoteCustomerDataRows(rawRows) {
  const rows = Array.isArray(rawRows) ? rawRows : [];
  if (rows.length === 0) return 0;

  let upserted = 0;
  for (const row of rows) {
    if (!row || typeof row !== 'object') continue;

    const serialized = serializeRemoteCustomerDataRow(row);
    const remoteId = buildRemoteCustomerDataId(row);
    const contact = normalizeAutoDialPhone(serialized.contact);
    const recordDate = normalizeQueryDate(serialized.date);
    if (!remoteId || !contact || !recordDate) continue;

    await pool.query(
      `INSERT INTO attica_remote_customer_data (
         remote_id,
         contact,
         customer_name,
         customer_type,
         branch,
         record_date,
         record_time,
         status,
         gross_w,
         net_w,
         bill_id,
         billing_amount,
         transaction_status,
         walkin_type,
         remote_agent,
         source_attribution,
         raw_payload,
         synced_at
       ) VALUES (?, ?, ?, ?, ?, ?, NULLIF(?, ''), ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NOW())
       ON DUPLICATE KEY UPDATE
         contact=VALUES(contact),
         customer_name=VALUES(customer_name),
         customer_type=VALUES(customer_type),
         branch=VALUES(branch),
         record_date=VALUES(record_date),
         record_time=VALUES(record_time),
         status=VALUES(status),
         gross_w=VALUES(gross_w),
         net_w=CASE
           WHEN COALESCE(TRIM(VALUES(net_w)), '')=''
           THEN attica_remote_customer_data.net_w
           ELSE VALUES(net_w)
         END,
         bill_id=CASE
           WHEN COALESCE(TRIM(VALUES(bill_id)), '')=''
           THEN attica_remote_customer_data.bill_id
           ELSE VALUES(bill_id)
         END,
         billing_amount=CASE
           WHEN COALESCE(TRIM(attica_remote_customer_data.bill_id), '') <> ''
             AND COALESCE(TRIM(VALUES(transaction_status)), '')=''
           THEN attica_remote_customer_data.billing_amount
           ELSE VALUES(billing_amount)
         END,
         transaction_status=CASE
           WHEN COALESCE(TRIM(VALUES(transaction_status)), '')=''
           THEN attica_remote_customer_data.transaction_status
           ELSE VALUES(transaction_status)
         END,
         walkin_type=VALUES(walkin_type),
         remote_agent=VALUES(remote_agent),
         source_attribution=CASE
           WHEN COALESCE(TRIM(attica_remote_customer_data.source_attribution), '') <> ''
           THEN attica_remote_customer_data.source_attribution
           ELSE COALESCE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(VALUES(raw_payload), '$.howToKnowAttica')), ''), '')
         END,
         raw_payload=VALUES(raw_payload),
         synced_at=NOW()`,
      [
        remoteId,
        contact,
        serialized.customerName,
        serialized.type,
        serialized.branch,
        recordDate,
        cleanJustDialString(serialized.time, 30),
        serialized.status,
        serialized.grossW,
        serialized.netW,
        serialized.billId,
        serialized.billAmount,
        serialized.transactionStatus,
        serialized.walkinType,
        serialized.firstAgentName,
        cleanJustDialString(row?.howToKnowAttica || row?.source || row?.sourceStatus || '', 120),
        JSON.stringify(row),
      ]
    );
    upserted += 1;
  }

  return upserted;
}

async function pruneStaleRemoteCustomerDataRows(rawRows) {
  const rows = Array.isArray(rawRows) ? rawRows : [];
  if (rows.length === 0) return 0;

  const remoteIdsByDate = new Map();
  for (const row of rows) {
    if (!row || typeof row !== 'object') continue;
    const remoteId = buildRemoteCustomerDataId(row);
    const recordDate = normalizeQueryDate(row?.date);
    if (!remoteId || !recordDate) continue;

    const dateRemoteIds = remoteIdsByDate.get(recordDate) || new Set();
    dateRemoteIds.add(remoteId);
    remoteIdsByDate.set(recordDate, dateRemoteIds);
  }

  let pruned = 0;
  for (const [recordDate, remoteIds] of remoteIdsByDate.entries()) {
    const ids = [...remoteIds].filter(Boolean);
    if (ids.length === 0) continue;

    const placeholders = ids.map(() => '?').join(',');
    const [result] = await pool.query(
      `DELETE FROM attica_remote_customer_data
        WHERE record_date=?
          AND remote_id NOT IN (${placeholders})`,
      [recordDate, ...ids]
    );
    pruned += Number(result?.affectedRows) || 0;
  }

  return pruned;
}

let remoteCustomerTransactionCache = new Map();

function normalizeCustomerTransactionRows(payload) {
  if (Array.isArray(payload)) return payload.filter((row) => row && typeof row === 'object');
  if (payload && typeof payload === 'object' && Array.isArray(payload.data)) {
    return payload.data.filter((row) => row && typeof row === 'object');
  }
  if (payload && typeof payload === 'object' && !payload.error) return [payload];
  return [];
}

async function fetchRemoteCustomerTransactionsByPhone(phone) {
  const normalizedPhone = normalizeAutoDialPhone(phone);
  if (!normalizedPhone) return [];

  const cached = remoteCustomerTransactionCache.get(normalizedPhone);
  if (cached && cached.expiresAt > Date.now()) {
    return cached.rows;
  }

  const url = `${CUSTOMER_DATA_TRANSACTION_URL}?phone=${encodeURIComponent(normalizedPhone)}`;
  // Failed requests are not cached as successful empty lookups.
  const payload = await fetchJsonWithTimeout(
    url,
    { headers: { Accept: 'application/json' } },
    CUSTOMER_DATA_REMOTE_TIMEOUT_MS
  );
  const rows = normalizeCustomerTransactionRows(payload);

  remoteCustomerTransactionCache.set(normalizedPhone, {
    rows,
    expiresAt: Date.now() + CUSTOMER_DATA_TRANSACTION_CACHE_MS,
  });
  if (remoteCustomerTransactionCache.size > 5000) {
    remoteCustomerTransactionCache = new Map([...remoteCustomerTransactionCache.entries()].slice(-2500));
  }
  return rows;
}

function scoreRemoteCustomerTransactionMatch(customerRow, transaction) {
  if (!hasConfirmedCustomerBillingTransaction(transaction)) return -1;

  let score = 0;
  const customerDate = normalizeQueryDate(customerRow?.record_date || customerRow?.date);
  const transactionDate = normalizeQueryDate(transaction?.date);
  if (customerDate && transactionDate && customerDate === transactionDate) score += 40;

  const rowBranch = cleanJustDialString(customerRow?.branch, 80).toLowerCase();
  const transactionBranch = cleanJustDialString(transaction?.branchId || transaction?.CurrentBranch || transaction?.branch, 80).toLowerCase();
  if (rowBranch && transactionBranch && rowBranch === transactionBranch) score += 25;

  const rowGross = parseRemoteMoneyNumber(customerRow?.gross_w || customerRow?.grossW);
  const transactionGross = parseRemoteMoneyNumber(getTransactionGrossWeight(transaction));
  if (rowGross > 0 && transactionGross > 0 && Math.abs(rowGross - transactionGross) <= 0.05) score += 25;

  const rowCustomer = cleanJustDialString(customerRow?.customer_name || customerRow?.customerName, 255).toLowerCase();
  const transactionCustomer = cleanJustDialString(transaction?.name || transaction?.customer, 255).toLowerCase();
  if (rowCustomer && transactionCustomer && (rowCustomer === transactionCustomer || transactionCustomer.includes(rowCustomer) || rowCustomer.includes(transactionCustomer))) {
    score += 10;
  }

  const rowTime = normalizeClockTimeForSql(customerRow?.record_time || customerRow?.time, '');
  const transactionTime = normalizeClockTimeForSql(transaction?.time, '');
  if (rowTime && transactionTime && rowTime.slice(0, 5) === transactionTime.slice(0, 5)) score += 10;

  return score;
}

function pickRemoteCustomerTransaction(customerRow, transactions) {
  let best = null;
  let bestScore = -1;
  for (const transaction of Array.isArray(transactions) ? transactions : []) {
    const score = scoreRemoteCustomerTransactionMatch(customerRow, transaction);
    if (score > bestScore) {
      best = transaction;
      bestScore = score;
    }
  }
  return bestScore >= 40 ? best : null;
}

async function syncRemoteCustomerTransactionsForDate(date, options = {}) {
  const normalizedDate = normalizeQueryDate(date);
  if (!normalizedDate) return 0;

  const force = Boolean(options?.force);
  const [rows] = await pool.query(
    `SELECT remote_id,
            contact,
            customer_name,
            customer_type,
            branch,
            DATE_FORMAT(record_date, '%Y-%m-%d') AS record_date,
            TIME_FORMAT(record_time, '%H:%i:%s') AS record_time,
            status,
            gross_w,
            net_w,
            bill_id,
            transaction_synced_at
       FROM attica_remote_customer_data
      WHERE record_date=?
        AND LOWER(TRIM(status)) IN ('billed', 'release')
        AND (
          ?=1
          OR IFNULL(TRIM(bill_id), '')=''
          OR LOWER(TRIM(status))='release'
          OR transaction_synced_at IS NULL
          OR transaction_synced_at < DATE_SUB(UTC_TIMESTAMP(), INTERVAL 12 HOUR)
        )
      ORDER BY record_time DESC, remote_id DESC
      LIMIT ?`,
    [normalizedDate, force ? 1 : 0, CUSTOMER_DATA_TRANSACTION_SYNC_LIMIT]
  );

  const transactionsByPhone = new Map();
  let consecutiveFailures = 0;
  for (const row of rows) {
    const phone = normalizeAutoDialPhone(row.contact);
    if (!phone || transactionsByPhone.has(phone)) continue;
    try {
      transactionsByPhone.set(phone, await fetchRemoteCustomerTransactionsByPhone(phone));
      consecutiveFailures = 0;
    } catch (error) {
      transactionsByPhone.set(phone, null);
      consecutiveFailures += 1;
      console.warn('[customerdata/transactions] lookup deferred:', error?.message || error);
      if (consecutiveFailures >= 3) break;
    }
  }

  let updated = 0;
  for (const row of rows) {
    const phone = normalizeAutoDialPhone(row.contact);
    if (!phone) continue;
    if (!Array.isArray(transactionsByPhone.get(phone))) continue;
    const transaction = pickRemoteCustomerTransaction(row, transactionsByPhone.get(phone) || []);
    if (!transaction) {
      await pool.query(
        `UPDATE attica_remote_customer_data
            SET transaction_synced_at=UTC_TIMESTAMP()
          WHERE remote_id=?`,
        [row.remote_id]
      );
      continue;
    }

    const billId = getRemoteCustomerBillId(transaction);
    const transactionStatus = cleanJustDialString(transaction.status, 100);
    const grossW = getTransactionGrossWeight(transaction) || cleanJustDialString(row.gross_w, 50);
    const netW = getTransactionNetWeight(transaction) || cleanJustDialString(row.net_w, 50);
    const billingAmount = roundMoneyAmount(getTransactionBillingAmount(transaction))
      || deriveRemoteCustomerBillingAmount(transaction, grossW);
    const customerType = deriveRemoteCustomerOrnamentType(transaction) || cleanJustDialString(row.customer_type, 100);

    await pool.query(
      `UPDATE attica_remote_customer_data
          SET bill_id=?,
              transaction_status=?,
              gross_w=?,
              net_w=?,
              billing_amount=?,
              customer_type=CASE WHEN COALESCE(TRIM(?), '')='' THEN customer_type ELSE ? END,
              transaction_payload=?,
              transaction_synced_at=UTC_TIMESTAMP()
        WHERE remote_id=?`,
      [
        billId,
        transactionStatus,
        grossW,
        netW,
        billingAmount,
        customerType,
        customerType,
        JSON.stringify(transaction),
        row.remote_id,
      ]
    );
    updated += 1;
  }

  if (updated > 0) clearRemoteCustomerDataListCache();
  return updated;
}

function normalizeClockTimeForSql(value, fallback = '23:59:59') {
  const raw = cleanJustDialString(value, 30);
  if (!raw) return fallback;

  const match = raw.match(/^(\d{1,2}):(\d{2})(?::(\d{2}))?\s*([ap]m)?$/i);
  if (!match) return fallback;

  let hour = Number(match[1]);
  const minute = Number(match[2]);
  const second = match[3] === undefined ? 0 : Number(match[3]);
  const meridian = String(match[4] || '').toLowerCase();
  if (!Number.isInteger(hour) || !Number.isInteger(minute) || !Number.isInteger(second)) return fallback;
  if (minute < 0 || minute > 59 || second < 0 || second > 59) return fallback;

  if (meridian) {
    if (hour < 1 || hour > 12) return fallback;
    if (meridian === 'pm' && hour !== 12) hour += 12;
    if (meridian === 'am' && hour === 12) hour = 0;
  } else if (hour < 0 || hour > 23) {
    return fallback;
  }

  return `${String(hour).padStart(2, '0')}:${String(minute).padStart(2, '0')}:${String(second).padStart(2, '0')}`;
}

function getRemoteCustomerBillDateTime(row) {
  const recordDate = normalizeQueryDate(row?.date || row?.record_date);
  if (!recordDate) return null;

  const recordTime = normalizeClockTimeForSql(row?.time || row?.record_time, '23:59:59');
  return `${recordDate} ${recordTime}`;
}

function shiftSqlDateTimeDays(sqlDateTime, dayDelta) {
  const match = String(sqlDateTime || '').match(/^(\d{4})-(\d{2})-(\d{2}) (\d{2}):(\d{2}):(\d{2})$/);
  if (!match) return null;

  const date = new Date(Date.UTC(
    Number(match[1]),
    Number(match[2]) - 1,
    Number(match[3]),
    Number(match[4]),
    Number(match[5]),
    Number(match[6])
  ));
  if (Number.isNaN(date.getTime())) return null;
  date.setUTCDate(date.getUTCDate() + Number(dayDelta || 0));
  return date.toISOString().slice(0, 19).replace('T', ' ');
}

async function fetchBillAttributionForCustomer(contact, billDateTime) {
  const phone = normalizeAutoDialPhone(contact);
  const normalizedBillDateTime = cleanJustDialString(billDateTime, 30);
  if (!phone || !/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/.test(normalizedBillDateTime)) {
    return null;
  }

  const [rows] = await pool.query(
    `SELECT
        agent_id,
        MAX(agent_name) AS agent_name,
        SUM(talk_seconds) AS total_talk_seconds,
        COUNT(DISTINCT call_key) AS connected_call_count,
        MAX(connected_at) AS latest_connected_at
       FROM (
         SELECT
           agent_id,
           agent_name,
           direction,
           COALESCE(NULLIF(call_uuid, ''), id) AS call_key,
           COALESCE(
             STR_TO_DATE(
               CONCAT(
                 call_date,
                 ' ',
                 CASE
                   WHEN call_time REGEXP '^[0-9]{1,2}:[0-9]{2}$' THEN CONCAT(call_time, ':00')
                   WHEN call_time REGEXP '^[0-9]{1,2}:[0-9]{2}:[0-9]{2}$' THEN call_time
                   ELSE '00:00:00'
                 END
               ),
               '%Y-%m-%d %H:%i:%s'
             ),
             DATE_ADD(created_at, INTERVAL 330 MINUTE)
           ) AS connected_at,
           GREATEST(
             IFNULL(talk_duration_seconds, 0),
             CASE
               WHEN answered_at IS NOT NULL
                 AND ended_at IS NOT NULL
                 AND TIMESTAMPDIFF(SECOND, answered_at, ended_at) > 0
               THEN TIMESTAMPDIFF(SECOND, answered_at, ended_at)
               ELSE 0
             END
          ) AS talk_seconds
          FROM attica_calls FORCE INDEX (idx_attica_calls_norm_date_agent)
         WHERE normalized_customer_number=?
           AND call_date <= DATE(?)
           AND direction IN ('incoming', 'outgoing')
           AND UPPER(TRIM(IFNULL(agent_id, ''))) LIKE 'AG%'
           AND LOWER(TRIM(IFNULL(agent_name, ''))) NOT IN ('', 'no agent', 'system', 'unknown', 'ivr abandoned', 'ivr no selection')
           AND LOWER(TRIM(IFNULL(status, ''))) NOT IN ('missed', 'failed', 'ringing', 'busy')
           AND LOWER(TRIM(IFNULL(callback_status, ''))) NOT IN (
             'duplicate removed',
             'rnr',
             'ring no reply',
             'no answer',
             'busy',
             'call failed',
             'failed',
             'wrong number',
             'switched off'
           )
       ) eligible_calls
      WHERE (
          connected_at <= ?
          OR connected_at < DATE_ADD(DATE(?), INTERVAL 1 DAY)
        )
        AND talk_seconds > 0
      GROUP BY agent_id
      ORDER BY
        total_talk_seconds DESC,
        connected_call_count DESC,
        latest_connected_at DESC,
        agent_id ASC
      LIMIT 1`,
    [phone, normalizedBillDateTime, normalizedBillDateTime, normalizedBillDateTime]
  );

  const best = rows?.[0];
  const windowStart = null;

  if (!best || !normalizeAgentId(best.agent_id)) {
    const [manualSoldOutRows] = await pool.query(
      `SELECT
          agent_id,
          MAX(agent_name) AS agent_name,
          GREATEST(SUM(talk_seconds), COUNT(DISTINCT call_key)) AS total_talk_seconds,
          COUNT(DISTINCT call_key) AS connected_call_count,
          MAX(connected_at) AS latest_connected_at
         FROM (
           SELECT
             agent_id,
             agent_name,
             direction,
             COALESCE(NULLIF(call_uuid, ''), id) AS call_key,
             COALESCE(
               STR_TO_DATE(
                 CONCAT(
                   call_date,
                   ' ',
                   CASE
                     WHEN call_time REGEXP '^[0-9]{1,2}:[0-9]{2}$' THEN CONCAT(call_time, ':00')
                     WHEN call_time REGEXP '^[0-9]{1,2}:[0-9]{2}:[0-9]{2}$' THEN call_time
                     ELSE '00:00:00'
                   END
                 ),
                 '%Y-%m-%d %H:%i:%s'
               ),
               DATE_ADD(created_at, INTERVAL 330 MINUTE)
             ) AS connected_at,
             GREATEST(
               IFNULL(talk_duration_seconds, 0),
               CASE
                 WHEN answered_at IS NOT NULL
                   AND ended_at IS NOT NULL
                   AND TIMESTAMPDIFF(SECOND, answered_at, ended_at) > 0
                 THEN TIMESTAMPDIFF(SECOND, answered_at, ended_at)
                 ELSE 0
               END
             ) AS talk_seconds
            FROM attica_calls FORCE INDEX (idx_attica_calls_norm_date_agent)
           WHERE normalized_customer_number=?
             AND call_date <= DATE(?)
             AND direction IN ('incoming', 'outgoing')
             AND UPPER(TRIM(IFNULL(agent_id, ''))) LIKE 'AG%'
             AND LOWER(TRIM(IFNULL(agent_name, ''))) NOT IN ('', 'no agent', 'system', 'unknown', 'ivr abandoned', 'ivr no selection')
             AND LOWER(TRIM(IFNULL(callback_status, ''))) NOT IN (
               'duplicate removed',
               'rnr',
               'ring no reply',
               'no answer',
               'busy',
               'call failed',
               'wrong number',
               'wrong call',
               'spam call',
               'not interested',
               'switched off'
             )
             AND (
               LOWER(REPLACE(IFNULL(callback_status, ''), ' ', '')) IN ('soldout','sold','customersoldout','finalsale','billed')
               OR LOWER(REPLACE(IFNULL(form_status, ''), ' ', '')) IN ('soldout','sold','customersoldout','finalsale','billed')
               OR LOWER(REPLACE(IFNULL(notes, ''), ' ', '')) LIKE '%soldout%'
               OR LOWER(REPLACE(IFNULL(notes, ''), ' ', '')) LIKE '%salemade%'
             )
         ) manual_sold_out_calls
        WHERE (
            connected_at <= ?
            OR connected_at < DATE_ADD(DATE(?), INTERVAL 1 DAY)
          )
        GROUP BY agent_id
        ORDER BY
          total_talk_seconds DESC,
          connected_call_count DESC,
          latest_connected_at DESC,
          agent_id ASC
        LIMIT 1`,
      [phone, normalizedBillDateTime, normalizedBillDateTime, normalizedBillDateTime]
    );
    const fallback = manualSoldOutRows?.[0];
    if (fallback && normalizeAgentId(fallback.agent_id)) {
      return {
        agentId: normalizeAgentId(fallback.agent_id),
        agentName: cleanJustDialString(fallback.agent_name, 100),
        totalTalkSeconds: Math.max(1, Number(fallback.total_talk_seconds) || 0),
        connectedCallCount: Number(fallback.connected_call_count) || 1,
        windowStart,
        windowEnd: normalizedBillDateTime,
        method: CUSTOMER_DATA_BILL_ATTRIBUTION_METHOD,
        reason: '',
      };
    }

    const [postBillSoldOutRows] = await pool.query(
      `SELECT
          agent_id,
          MAX(agent_name) AS agent_name,
          SUM(talk_seconds) AS total_talk_seconds,
          COUNT(DISTINCT call_key) AS connected_call_count,
          MAX(connected_at) AS latest_connected_at
         FROM (
           SELECT
             agent_id,
             agent_name,
             COALESCE(NULLIF(call_uuid, ''), id) AS call_key,
             COALESCE(
               STR_TO_DATE(
                 CONCAT(
                   call_date,
                   ' ',
                   CASE
                     WHEN call_time REGEXP '^[0-9]{1,2}:[0-9]{2}$' THEN CONCAT(call_time, ':00')
                     WHEN call_time REGEXP '^[0-9]{1,2}:[0-9]{2}:[0-9]{2}$' THEN call_time
                     ELSE '00:00:00'
                   END
                 ),
                 '%Y-%m-%d %H:%i:%s'
               ),
               DATE_ADD(created_at, INTERVAL 330 MINUTE)
             ) AS connected_at,
             GREATEST(
               IFNULL(talk_duration_seconds, 0),
               CASE
                 WHEN answered_at IS NOT NULL
                   AND ended_at IS NOT NULL
                   AND TIMESTAMPDIFF(SECOND, answered_at, ended_at) > 0
                 THEN TIMESTAMPDIFF(SECOND, answered_at, ended_at)
                 ELSE 0
               END
             ) AS talk_seconds
            FROM attica_calls FORCE INDEX (idx_attica_calls_norm_date_agent)
           WHERE normalized_customer_number=?
             AND call_date >= DATE(?)
             AND direction IN ('incoming', 'outgoing')
             AND UPPER(TRIM(IFNULL(agent_id, ''))) LIKE 'AG%'
             AND LOWER(TRIM(IFNULL(agent_name, ''))) NOT IN ('', 'no agent', 'system', 'unknown', 'ivr abandoned', 'ivr no selection')
             AND LOWER(TRIM(IFNULL(status, ''))) NOT IN ('missed', 'failed', 'ringing', 'busy')
             AND LOWER(TRIM(IFNULL(callback_status, ''))) NOT IN (
               'duplicate removed',
               'rnr',
               'ring no reply',
               'no answer',
               'busy',
               'call failed',
               'wrong number',
               'wrong call',
               'spam call',
               'not interested',
               'switched off'
             )
             AND (
               LOWER(REPLACE(IFNULL(callback_status, ''), ' ', '')) IN ('soldout','sold','customersoldout','finalsale','billed')
               OR LOWER(REPLACE(IFNULL(form_status, ''), ' ', '')) IN ('soldout','sold','customersoldout','finalsale','billed')
               OR LOWER(REPLACE(IFNULL(notes, ''), ' ', '')) LIKE '%soldout%'
               OR LOWER(REPLACE(IFNULL(notes, ''), ' ', '')) LIKE '%salemade%'
             )
         ) post_bill_sold_out_calls
        WHERE connected_at > ?
          AND connected_at <= DATE_ADD(UTC_TIMESTAMP(), INTERVAL 330 MINUTE)
          AND talk_seconds > 0
        GROUP BY agent_id
        ORDER BY
          total_talk_seconds DESC,
          connected_call_count DESC,
          latest_connected_at DESC,
          agent_id ASC
        LIMIT 1`,
      [phone, normalizedBillDateTime, normalizedBillDateTime]
    );
    const postBillFallback = postBillSoldOutRows?.[0];
    if (postBillFallback && normalizeAgentId(postBillFallback.agent_id)) {
      return {
        agentId: normalizeAgentId(postBillFallback.agent_id),
        agentName: cleanJustDialString(postBillFallback.agent_name, 100),
        totalTalkSeconds: Math.max(1, Number(postBillFallback.total_talk_seconds) || 0),
        connectedCallCount: Number(postBillFallback.connected_call_count) || 1,
        windowStart: normalizedBillDateTime,
        windowEnd: toDatabaseDateTime(postBillFallback.latest_connected_at) || normalizedBillDateTime,
        method: CUSTOMER_DATA_BILL_ATTRIBUTION_METHOD,
        reason: '',
      };
    }

    return {
      agentId: '',
      agentName: 'Unattributed / No Agent',
      totalTalkSeconds: 0,
      connectedCallCount: 0,
      windowStart,
      windowEnd: normalizedBillDateTime,
      method: CUSTOMER_DATA_BILL_ATTRIBUTION_METHOD,
      reason: CUSTOMER_DATA_BILL_ATTRIBUTION_NO_AGENT_REASON,
    };
  }

  return {
    agentId: normalizeAgentId(best.agent_id),
    agentName: cleanJustDialString(best.agent_name, 100),
    totalTalkSeconds: Number(best.total_talk_seconds) || 0,
    connectedCallCount: Number(best.connected_call_count) || 0,
    windowStart,
    windowEnd: normalizedBillDateTime,
    method: CUSTOMER_DATA_BILL_ATTRIBUTION_METHOD,
    reason: '',
  };
}

async function persistRemoteCustomerDataAttributions(attributionsByRemoteId) {
  if (!(attributionsByRemoteId instanceof Map) || attributionsByRemoteId.size === 0) return;

  for (const [remoteId, attribution] of attributionsByRemoteId.entries()) {
    if (!remoteId || !attribution) continue;
    await pool.query(
      `UPDATE attica_remote_customer_data
          SET attributed_agent_id=NULLIF(?, ''),
              attributed_agent_name=?,
              total_talk_seconds=?,
              connected_call_count=?,
              attribution_window_start=?,
              attribution_window_end=?,
              attribution_method=?,
              attribution_reason=?,
              attributed_at=NOW()
        WHERE remote_id=?
          AND (
            IFNULL(attributed_agent_id, '') <> IFNULL(?, '')
            OR IFNULL(attributed_agent_name, '') <> IFNULL(?, '')
            OR IFNULL(total_talk_seconds, 0) <> ?
            OR IFNULL(connected_call_count, 0) <> ?
            OR IFNULL(attribution_window_start, '1000-01-01 00:00:00') <> IFNULL(?, '1000-01-01 00:00:00')
            OR IFNULL(attribution_window_end, '1000-01-01 00:00:00') <> IFNULL(?, '1000-01-01 00:00:00')
            OR IFNULL(attribution_method, '') <> IFNULL(?, '')
            OR IFNULL(attribution_reason, '') <> IFNULL(?, '')
          )`,
      [
        attribution.agentId,
        attribution.agentName,
        attribution.totalTalkSeconds,
        attribution.connectedCallCount,
        attribution.windowStart,
        attribution.windowEnd,
        attribution.method,
        attribution.reason,
        remoteId,
        attribution.agentId,
        attribution.agentName,
        attribution.totalTalkSeconds,
        attribution.connectedCallCount,
        attribution.windowStart,
        attribution.windowEnd,
        attribution.method,
        attribution.reason,
      ]
    );
  }
}

async function fetchBillAttributionsForRemoteRows(rows) {
  const attributionsByRemoteId = new Map();
  const lookupCache = new Map();

  for (const row of Array.isArray(rows) ? rows : []) {
    const remoteId = cleanJustDialString(row?.remoteId || row?.remote_id, 80);
    const phone = normalizeAutoDialPhone(row?.contact);
    const billDateTime = getRemoteCustomerBillDateTime(row);
    if (!remoteId || !phone || !billDateTime) continue;

    const lookupKey = `${phone}|${billDateTime}`;
    if (!lookupCache.has(lookupKey)) {
      lookupCache.set(lookupKey, await fetchBillAttributionForCustomer(phone, billDateTime));
    }

    const attribution = lookupCache.get(lookupKey);
    if (attribution) {
      attributionsByRemoteId.set(remoteId, attribution);
    }
  }

  await persistRemoteCustomerDataAttributions(attributionsByRemoteId);
  return attributionsByRemoteId;
}

async function fetchFirstCallCenterAgentByPhoneForDate(date) {
  const normalizedDate = normalizeQueryDate(date);
  if (!normalizedDate) return new Map();

  const [rows] = await pool.query(
    `SELECT COALESCE(NULLIF(normalized_customer_number, ''), caller_id) AS phone,
            agent_id,
            agent_name,
            call_date,
            call_time,
            created_at
       FROM attica_calls FORCE INDEX (idx_attica_calls_call_date_agent_id)
      WHERE call_date=?
        AND agent_id LIKE 'AG%'
        AND IFNULL(TRIM(agent_name), '') <> ''
        AND LOWER(TRIM(agent_name)) NOT IN ('no agent', 'system', 'unknown')
      ORDER BY call_date ASC, call_time ASC, created_at ASC`,
    [normalizedDate]
  );

  const firstAgentByPhone = new Map();
  for (const row of rows) {
    const phone = normalizeAutoDialPhone(row.phone);
    if (!phone || firstAgentByPhone.has(phone)) continue;

    firstAgentByPhone.set(phone, {
      agentId: normalizeAgentId(row.agent_id),
      agentName: cleanJustDialString(row.agent_name, 100),
    });
  }

  return firstAgentByPhone;
}

async function fetchCallCenterAgentByPhoneForRemoteRows(rows) {
  const phones = [...new Set((Array.isArray(rows) ? rows : [])
    .map((row) => normalizeAutoDialPhone(row?.contact))
    .filter(Boolean))];
  const agentByPhone = new Map();
  if (phones.length === 0) return agentByPhone;

  const normalizeCallerSql = "RIGHT(REGEXP_REPLACE(COALESCE(caller_id,''), '[^0-9]', ''), 10)";
  const chunkSize = 500;
  for (let start = 0; start < phones.length; start += chunkSize) {
    const chunk = phones.slice(start, start + chunkSize);
    const [rowsForChunk] = await pool.query(
      `SELECT phone, agent_id, agent_name
         FROM (
           SELECT normalized_customer_number AS phone,
                  agent_id,
                  agent_name,
                  created_at
             FROM attica_calls FORCE INDEX (idx_attica_calls_norm_created)
            WHERE normalized_customer_number IN (?)
           UNION ALL
           SELECT ${normalizeCallerSql} AS phone, agent_id, agent_name, created_at
             FROM attica_calls FORCE INDEX (idx_attica_calls_norm_created)
            WHERE (normalized_customer_number IS NULL OR normalized_customer_number='')
              AND ${normalizeCallerSql} IN (?)
         ) contacted
        WHERE phone IN (?)
          AND agent_id LIKE 'AG%'
          AND IFNULL(TRIM(agent_name), '') <> ''
          AND LOWER(TRIM(agent_name)) NOT IN ('no agent', 'system', 'unknown')
        ORDER BY created_at DESC`,
      [chunk, chunk, chunk]
    );

    for (const row of rowsForChunk) {
      const phone = normalizeAutoDialPhone(row.phone);
      if (!phone || agentByPhone.has(phone)) continue;
      agentByPhone.set(phone, {
        agentId: normalizeAgentId(row.agent_id),
        agentName: cleanJustDialString(row.agent_name, 100),
      });
    }
  }

  return agentByPhone;
}

