async function syncFailedMetaLeadsToFollowUps(limit = 1000) {
  const normalizedLimit = Math.max(1, Math.min(2000, Number(limit) || 1000));
  const [rows] = await pool.query(
    `SELECT m.*,
            a.status AS auto_dial_status_current,
            a.queue_exit_reason AS auto_dial_queue_exit_reason_current,
            a.last_error AS auto_dial_last_error_current
     FROM attica_meta_leads m
     LEFT JOIN attica_auto_dial_leads a ON a.id=m.auto_dial_lead_id
     WHERE LOWER(IFNULL(m.auto_dial_status, '')) <> 'blocked'
       AND (
         LOWER(IFNULL(m.auto_dial_status, '')) = 'failed'
         OR LOWER(IFNULL(a.status, '')) = 'failed'
         OR LOWER(IFNULL(a.last_error, '')) REGEXP 'rnr|no answer|disconnect|disconnection|failed'
         OR LOWER(IFNULL(a.queue_exit_reason, '')) REGEXP 'not reachable|disconnect|disconnection|failed'
       )
     ORDER BY COALESCE(m.lead_created_at, m.received_at) DESC, m.received_at DESC
     LIMIT ?`,
    [normalizedLimit]
  );

  return createFollowUpsFromMetaLeadRows(rows);
}

async function createFollowUpsFromJustDialLeadRows(rows) {
  let processed = 0;
  let skipped = 0;

  for (const lead of rows) {
    const phone = normalizeAutoDialPhone(lead.mobile || lead.phone);
    const followUpId = buildSourceFollowUpId('JD', lead.leadid);
    if (!phone || !followUpId) {
      skipped += 1;
      continue;
    }

    const notes = compactNoteParts([
      'JustDial export follow-up',
      `Lead ID: ${lead.leadid || ''}`,
      lead.leadtype ? `Lead Type: ${lead.leadtype}` : '',
      lead.category ? `Category: ${lead.category}` : '',
      lead.company ? `Company: ${lead.company}` : '',
      lead.city ? `City: ${lead.city}` : '',
      lead.area ? `Area: ${lead.area}` : '',
      lead.brancharea ? `Branch Area: ${lead.brancharea}` : '',
      lead.state ? `State: ${lead.state}` : '',
      lead.lead_date ? `Lead Date: ${lead.lead_date.toISOString().slice(0, 10)}` : '',
      lead.lead_time ? `Lead Time: ${lead.lead_time}` : '',
      `Auto Dial: ${lead.auto_dial_status_current || lead.auto_dial_status || 'idle'}`,
    ]);
    const followUpExpiry = getFollowUpExpiryValues('JustDial Lead Export');

    await pool.query(
      `INSERT INTO attica_followups
        (id, customer_name, phone, branch, follow_up_at, status, agent_id, agent_name, notes, outcome, followup_created_at, followup_expires_at, followup_reason, is_active, updated_at)
       VALUES (?, ?, ?, ?, ?, 'Pending', '', '', ?, 'JustDial Lead Export', ?, ?, ?, 1, NOW())
       ON DUPLICATE KEY UPDATE
         customer_name=VALUES(customer_name),
         phone=VALUES(phone),
         branch=VALUES(branch),
         follow_up_at=CASE
           WHEN status='Called' THEN follow_up_at
           ELSE VALUES(follow_up_at)
         END,
         status=CASE
           WHEN status='Called' THEN status
           ELSE 'Pending'
         END,
         is_active=CASE
           WHEN status='Called' THEN is_active
           ELSE 1
         END,
         notes=VALUES(notes),
         outcome=CASE
           WHEN status='Called' THEN outcome
           ELSE VALUES(outcome)
         END,
         followup_created_at=COALESCE(attica_followups.followup_created_at, VALUES(followup_created_at)),
         followup_expires_at=COALESCE(attica_followups.followup_expires_at, VALUES(followup_expires_at)),
         followup_reason=COALESCE(NULLIF(attica_followups.followup_reason, ''), VALUES(followup_reason)),
         updated_at=NOW()`,
      [
        followUpId,
        lead.name || 'JustDial Lead',
        phone,
        lead.brancharea || lead.area || lead.city || lead.state || '',
        resolveLeadFollowUpAt({
          dateValue: lead.lead_date,
          timeValue: lead.lead_time,
          fallbackValue: lead.received_at,
        }),
        notes,
        followUpExpiry.createdAt,
        followUpExpiry.expiresAt,
        followUpExpiry.reason,
      ]
    );
    processed += 1;
  }

  return { processed, skipped };
}

function normalizeLeadIdList(value) {
  return Array.from(
    new Set(
      (Array.isArray(value) ? value : [])
        .map((entry) => cleanJustDialString(entry, 255))
        .filter(Boolean)
    )
  ).slice(0, 500);
}

function parseCsvText(csvText) {
  const rows = [];
  let row = [];
  let field = '';
  let inQuotes = false;

  for (let index = 0; index < csvText.length; index += 1) {
    const char = csvText[index];
    const nextChar = csvText[index + 1];

    if (inQuotes) {
      if (char === '"' && nextChar === '"') {
        field += '"';
        index += 1;
      } else if (char === '"') {
        inQuotes = false;
      } else {
        field += char;
      }
      continue;
    }

    if (char === '"') {
      inQuotes = true;
    } else if (char === ',') {
      row.push(field);
      field = '';
    } else if (char === '\n') {
      row.push(field);
      rows.push(row);
      row = [];
      field = '';
    } else if (char !== '\r') {
      field += char;
    }
  }

  if (field || row.length > 0) {
    row.push(field);
    rows.push(row);
  }

  return rows.filter((entries) => entries.some((entry) => String(entry || '').trim() !== ''));
}

function normalizeSheetHeader(value) {
  return String(value || '').trim().toLowerCase().replace(/[^a-z0-9]+/g, '');
}

function parseMetaLeadCsv(csvText) {
  const rows = parseCsvText(csvText);
  if (rows.length < 2) return [];

  const headers = rows[0];
  return rows.slice(1).map((values) => {
    const row = {};
    headers.forEach((header, index) => {
      const rawHeader = String(header || '').trim();
      const normalizedHeader = normalizeSheetHeader(rawHeader) || `column${index + 1}`;
      const value = String(values[index] || '').trim();
      row[normalizedHeader] = value;
      row[`column${index + 1}`] = value;
    });
    return row;
  });
}

function parseMetaNameNumberStateFormCsv(csvText) {
  const rows = parseCsvText(csvText);
  return rows
    .filter((values) => /^l:/i.test(String(values[0] || '').trim()) && values.length >= 16)
    .map((values, index) => {
      const row = {
        id: String(values[0] || '').trim(),
        date: String(values[1] || '').trim(),
        formid: String(values[8] || '').trim(),
        formname: String(values[9] || '').trim(),
        platform: String(values[11] || '').trim(),
        selectyourstate: String(values[12] || '').trim(),
        fullname: String(values[13] || '').trim(),
        phonenumber: String(values[14] || '').trim(),
        leadstatus: String(values[15] || '').trim(),
      };
      values.forEach((value, valueIndex) => {
        row[`column${valueIndex + 1}`] = String(value || '').trim();
      });
      row.source_sheet = META_LEADS_NAME_NUMBER_STATE_SHEET_NAME;
      row.source_row_index = index + 1;
      return row;
    });
}

function pickMetaLeadCsvValue(row, aliases) {
  for (const alias of aliases) {
    const key = normalizeSheetHeader(alias);
    if (row[key] !== undefined && row[key] !== null && String(row[key]).trim() !== '') {
      return row[key];
    }
  }
  return '';
}

function pickWebsiteSheetCsvValue(row, aliases) {
  return pickMetaLeadCsvValue(row, aliases);
}

function buildStableWebsiteSheetLeadId(row, index, contactNumber, leadDate, leadTime) {
  const explicitLeadId = cleanJustDialString(pickWebsiteSheetCsvValue(row, ['leadid', 'lead_id', 'id']), 255);
  const sourceSheet = cleanJustDialString(pickWebsiteSheetCsvValue(row, ['source_sheet']), 120);
  if (explicitLeadId) {
    if (!sourceSheet || sourceSheet === 'default') return explicitLeadId;
    const sheetHash = createHash('sha1').update(sourceSheet).digest('hex').slice(0, 8);
    return cleanJustDialString(`${explicitLeadId}-${sheetHash}`, 255);
  }

  const stableParts = [
    sourceSheet,
    contactNumber,
    leadDate,
    leadTime,
    pickWebsiteSheetCsvValue(row, ['customer_name', 'customer name', 'name']),
    pickWebsiteSheetCsvValue(row, ['lead_from', 'lead from', 'source']),
    pickWebsiteSheetCsvValue(row, ['gold_weight', 'gold weight', 'grams']),
    String(index + 1),
  ].join('|');
  const hash = createHash('sha1').update(stableParts).digest('hex').slice(0, 14);
  return `WSL-${hash}`;
}

