async function persistWebsiteFormLead(lead, options = {}) {
  if (!lead?.leadid || !lead?.contactNumber) {
    return { success: false, skipped: true, error: 'MISSING_CONTACT_NUMBER' };
  }

  const blockedContentReason = getBlockedLeadContentReason({
    customer_name: lead.customerName,
    name: lead.customerName,
    type: lead.type,
    state: lead.state,
    city: lead.city,
    area: lead.area,
    lead_from: lead.leadFrom,
    utm_source: lead.utmSource,
    keyword: lead.keyword,
    remarks: lead.remarks,
    comments: lead.comments,
  });
  if (blockedContentReason) {
    return { success: false, skipped: true, error: 'BLOCKED_SPAM_CONTENT', reason: blockedContentReason };
  }

  const duplicateLead = await findExistingWebsiteLeadDuplicate({
    leadid: lead.leadid,
    phone10: lead.contactNumber,
    leadDate: lead.leadDate,
    allowSameDayPhoneDuplicate: false,
  });
  if (duplicateLead) {
    await updateWebsiteLeadMarketingFields(duplicateLead.leadid, lead);
    const queueResult = options.immediateQueue
      ? await queueSourceLeadForAutoDialNow('website', duplicateLead.leadid)
      : (queueSourceLeadForAutoDial('website', duplicateLead.leadid), { ok: true });
    enqueueAisensyLeadCampaign('website', duplicateLead);
    return {
      success: true,
      duplicate: true,
      leadid: duplicateLead.leadid,
      queued: queueResult?.ok !== false,
      autoDialLeadId: queueResult?.autoDialLeadId || '',
      alreadyQueued: Boolean(queueResult?.alreadyQueued),
    };
  }

  await pool.query(
    `INSERT INTO attica_website_leads
      (leadid,customer_name,contact_number,gold_weight,language,lead_type,state,city,area,lead_from,lead_date,lead_time,device,utm_source,utm_campaign_name,keyword,adgroupid,gclid,remarks,comments,followup_date,raw_payload)
     VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
     ON DUPLICATE KEY UPDATE
       customer_name=VALUES(customer_name),
       contact_number=VALUES(contact_number),
       gold_weight=VALUES(gold_weight),
       language=VALUES(language),
       lead_type=VALUES(lead_type),
       state=VALUES(state),
       city=VALUES(city),
       area=VALUES(area),
       lead_from=VALUES(lead_from),
       lead_date=VALUES(lead_date),
       lead_time=VALUES(lead_time),
       device=VALUES(device),
       utm_source=VALUES(utm_source),
       utm_campaign_name=VALUES(utm_campaign_name),
       keyword=VALUES(keyword),
       adgroupid=VALUES(adgroupid),
       gclid=VALUES(gclid),
       remarks=VALUES(remarks),
       comments=VALUES(comments),
       followup_date=VALUES(followup_date),
       raw_payload=VALUES(raw_payload),
       received_at=NOW()`,
    [
      lead.leadid,
      lead.customerName,
      lead.contactNumber,
      lead.goldWeight,
      lead.language,
      lead.type,
      lead.state,
      lead.city,
      lead.area,
      lead.leadFrom,
      lead.leadDate,
      lead.leadTime,
      lead.device,
      lead.utmSource,
      lead.utmCampaignName,
      lead.keyword,
      lead.adgroupid,
      lead.gclid,
      lead.remarks,
      lead.comments,
      lead.followupDate,
      lead.rawPayload,
    ]
  );

  const queueResult = options.immediateQueue
    ? await queueSourceLeadForAutoDialNow('website', lead.leadid)
    : (queueSourceLeadForAutoDial('website', lead.leadid), { ok: true });
  enqueueAisensyLeadCampaign('website', lead);

  return {
    success: true,
    duplicate: false,
    leadid: lead.leadid,
    queued: queueResult?.ok !== false,
    autoDialLeadId: queueResult?.autoDialLeadId || '',
    alreadyQueued: Boolean(queueResult?.alreadyQueued),
  };
}

