function buildMetaLeadFromCsvRow(row, index) {
  const platform = cleanJustDialString(pickMetaLeadCsvValue(row, ['platform']), 120);
  const selectedState = cleanJustDialString(pickMetaLeadCsvValue(row, ['select_your_state', 'select your state', 'state']), 120);
  const fullName = cleanJustDialString(
    pickMetaLeadCsvValue(row, ['full_name', 'full name'])
      || pickMetaLeadCsvValue(row, ['column15']),
    255
  );
  const city = cleanJustDialString(pickMetaLeadCsvValue(row, ['city']), 120);
  const phoneNumber = normalizeAutoDialPhone(pickMetaLeadCsvValue(row, ['phone_number', 'phone number']));
  const leadid = cleanJustDialString(pickMetaLeadCsvValue(row, ['id', 'leadid', 'lead_id']), 255)
    || (phoneNumber ? `META-${phoneNumber}` : `META-${Date.now()}-${index}`);
  const createdTime = pickMetaLeadCsvValue(row, ['time_of_creation', 'time of creation', 'timeof creation', 'created_time', 'created time', 'created_at', 'date']);
  const formName = cleanJustDialString(pickMetaLeadCsvValue(row, ['form_name', 'form name']), 120);
  const sourceSheet = cleanJustDialString(pickMetaLeadCsvValue(row, ['source_sheet']), 120);
  const questionColumnAliases = META_LEADS_CUSTOM_QUESTION_SHEET_NAMES.has(sourceSheet);
  const tamilJulyQuestionSheet = sourceSheet === 'CT-FB-LG-Tamil-CustomQuestion-July26';
  const serviceLookingFor = cleanJustDialString(
    pickMetaLeadCsvValue(row, [
      'what_service_are_you_looking_for?',
      'what service are you looking for',
      'service',
      ...(questionColumnAliases ? ['column13'] : []),
      ...(tamilJulyQuestionSheet ? ['column1'] : []),
    ]),
    255
  );
  const goldAmount = cleanJustDialString(
    pickMetaLeadCsvValue(row, [
      'approximately_how_much_gold_do_you_have?',
      'approximately how much gold do you have',
      'gold amount',
      'grams',
      ...(questionColumnAliases ? ['column14'] : []),
      ...(tamilJulyQuestionSheet ? ['column2'] : []),
    ]),
    120
  );
  const plannedVisit = cleanJustDialString(
    pickMetaLeadCsvValue(row, [
      'when_are_you_planning_to_visit_an_attica_gold_company_branch?',
      'when are you planning to visit an attica gold company branch',
      'planned visit',
      'visit plan',
      ...(questionColumnAliases ? ['column15'] : []),
      ...(tamilJulyQuestionSheet ? ['column3'] : []),
    ]),
    255
  );
  const selectedPayload = {
    source_sheet: sourceSheet,
    form_name: formName,
    platform,
    service_looking_for: serviceLookingFor,
    gold_amount: goldAmount,
    planned_visit: plannedVisit,
    select_your_state: selectedState,
    full_name: fullName,
    phone_number: phoneNumber,
    city,
    state: selectedState,
    created_time: createdTime,
  };

  return {
    leadid,
    fullName,
    phoneNumber,
    city,
    state: selectedState,
    grams: goldAmount,
    type: formName || platform,
    leadCreatedAt: toDatabaseDateTime(createdTime),
    rawPayload: JSON.stringify(selectedPayload),
  };
}

let lastMetaLeadsSheetSyncAt = 0;
let lastMetaLeadsSheetSyncError = '';
let metaLeadsBackgroundSyncPromise = null;

async function queueUnqueuedMetaLeadsForAutoDial(limit = 200) {
  const normalizedLimit = Math.max(1, Math.min(500, Number(limit) || 200));
  const result = await queueUnqueuedFreshSourceLeadsForAutoDial(normalizedLimit);
  return result.meta;
}

async function syncMetaLeadsFromSheet(options = {}) {
  const force = options.force === true;
  if (!force && Date.now() - lastMetaLeadsSheetSyncAt < META_LEADS_SYNC_CACHE_MS) {
    return { synced: 0, cached: true, error: lastMetaLeadsSheetSyncError };
  }

  let csvRows = [];
  const sheetErrors = [];
  const fetchedSheetNames = [];
  for (const sheetName of META_LEADS_SHEET_NAMES) {
    let csvText = '';
    for (const sheetUrl of getMetaSheetCsvUrlCandidates(sheetName)) {
      let response;
      try {
        response = await fetch(sheetUrl, {
          headers: { Accept: 'text/csv,*/*' },
          cache: 'no-store',
        });
      } catch (error) {
        sheetErrors.push(`${sheetName || 'default'}: ${error?.message || String(error)}`);
        continue;
      }
      if (!response.ok) {
        sheetErrors.push(`${sheetName || 'default'}: Google Sheet returned ${response.status}`);
        continue;
      }

      const responseText = await response.text();
      if (/^\s*</.test(responseText) || /Too Many Requests|unavailable/i.test(responseText.slice(0, 1000))) {
        sheetErrors.push(`${sheetName || 'default'}: Google Sheet returned HTML instead of CSV`);
        continue;
      }

      csvText = responseText;
      break;
    }

    if (!csvText) continue;
    fetchedSheetNames.push(sheetName || 'default');
    csvRows = csvRows.concat(parseMetaLeadCsv(csvText).map((csvRow) => ({
      ...csvRow,
      sourcesheet: sheetName || 'default',
      source_sheet: sheetName || 'default',
    })));
  }

  if (csvRows.length === 0 && sheetErrors.length > 0) {
    lastMetaLeadsSheetSyncError = sheetErrors.join('; ');
    return { synced: 0, cached: false, error: lastMetaLeadsSheetSyncError };
  }

  let namedTabRows = [];
  let namedTabError = '';
  try {
    const namedTabResponse = await fetch(META_LEADS_NAME_NUMBER_STATE_CSV_URL, {
      headers: { Accept: 'text/csv,*/*' },
      cache: 'no-store',
    });
    if (namedTabResponse.ok) {
      namedTabRows = parseMetaNameNumberStateFormCsv(await namedTabResponse.text());
    } else {
      namedTabError = `${META_LEADS_NAME_NUMBER_STATE_SHEET_NAME} returned ${namedTabResponse.status}`;
    }
  } catch (error) {
    namedTabError = error?.message || String(error);
  }
  if (namedTabError) {
    console.warn('[meta-leads] named tab sync failed:', namedTabError);
  }
  let synced = 0;
  for (const [index, csvRow] of [...csvRows, ...namedTabRows].entries()) {
    const lead = buildMetaLeadFromCsvRow(csvRow, index);
    if (!lead.leadid || !lead.phoneNumber) continue;
    const blockedContentReason = getBlockedLeadContentReason({
      full_name: lead.fullName,
      name: lead.fullName,
      city: lead.city,
      state: lead.state,
      type: lead.type,
    });
    if (blockedContentReason) {
      console.warn('[meta-leads] skipped sheet spam lead:', {
        leadid: lead.leadid,
        phone: lead.phoneNumber,
        reason: blockedContentReason,
      });
      continue;
    }
    await pool.query(
      `INSERT INTO attica_meta_leads
        (leadid, full_name, phone_number, city, state, grams, lead_type, lead_created_at, raw_payload)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
       ON DUPLICATE KEY UPDATE
         full_name=VALUES(full_name),
         phone_number=VALUES(phone_number),
         city=VALUES(city),
         state=VALUES(state),
         grams=VALUES(grams),
         lead_type=VALUES(lead_type),
         lead_created_at=VALUES(lead_created_at),
         raw_payload=VALUES(raw_payload),
         updated_at=NOW()`,
      [
        lead.leadid,
        lead.fullName,
        lead.phoneNumber,
        lead.city,
        lead.state,
        lead.grams,
        lead.type,
        lead.leadCreatedAt,
        lead.rawPayload,
      ]
    );
    enqueueAisensyLeadCampaign('meta', lead);
    synced += 1;
  }
  lastMetaLeadsSheetSyncAt = Date.now();
  lastMetaLeadsSheetSyncError = '';
  const autoQueued = await queueUnqueuedMetaLeadsForAutoDial();
  const failedFollowUps = await syncFailedMetaLeadsToFollowUps();
  return {
    synced,
    cached: false,
    error: namedTabError || sheetErrors.join('; '),
    autoQueued,
    failedFollowUps: failedFollowUps.processed,
    fetchedSheets: fetchedSheetNames,
    namedTabRows: namedTabRows.length,
  };
}

function serializeAutoDialLeadRow(row) {
  const isFollowUpLead = getAutoDialWorkModeForLead(row) === 'follow-up';
  const normalizedStatus = String(row.status || '').trim().toLowerCase();
  const hideAssignedFollowUpSchedule = isFollowUpLead && (normalizedStatus === 'assigned' || normalizedStatus === 'dialing');
  return {
    id: row.id,
    customerName: row.customer_name || '',
    mobileNumber: row.mobile_number || '',
    area: row.area || '',
    sourceState: row.source_state || '',
    preferredLanguage: row.preferred_language || '',
    goldWeight: row.gold_weight || '',
    type: row.lead_type || '',
    status: row.status,
    assignedAgentId: row.assigned_agent_id || '',
    assignedAgentName: row.assigned_agent_name || '',
    scheduledAgentId: isFollowUpLead ? '' : (row.scheduled_agent_id || ''),
    scheduledAgentName: isFollowUpLead ? '' : (row.scheduled_agent_name || ''),
    sourceFile: row.source_file || '',
    callId: row.call_id || '',
    assignedAt: row.assigned_at ? row.assigned_at.toISOString() : '',
    dialStartedAt: row.dial_started_at ? row.dial_started_at.toISOString() : '',
    completedAt: row.completed_at ? row.completed_at.toISOString() : '',
    scheduledFor: !hideAssignedFollowUpSchedule && row.scheduled_for ? row.scheduled_for.toISOString() : '',
    lastError: cleanJustDialString(row.last_error, 255),
    queueExitReason: row.queue_exit_reason || '',
    retryAllowed: Number(row.retry_allowed ?? 1) > 0,
    metaState: row.__meta_state || '',
    metaCity: row.__meta_city || '',
    metaFullName: row.__meta_full_name || '',
    metaPhoneNumber: row.__meta_phone_number || '',
    metaServiceLookingFor: row.__meta_service_looking_for || '',
    metaGoldAmount: row.__meta_gold_amount || '',
    metaPlannedVisit: row.__meta_planned_visit || '',
    metaDate: row.__meta_lead_created_at ? formatDateInZone(row.__meta_lead_created_at) : '',
    createdAt: row.created_at ? row.created_at.toISOString() : '',
    updatedAt: row.updated_at ? row.updated_at.toISOString() : '',
  };
}

async function enrichAutoDialLeadRowsWithMetaDetails(rows) {
  const normalizedRows = Array.isArray(rows) ? rows.filter(Boolean) : [];
  const metaCandidateRows = normalizedRows.filter((row) => (
    String(row?.source_file || '').trim().toLowerCase() === 'meta lead'
    || String(row?.id || '').trim().toUpperCase().startsWith('MTL-')
  ));
  if (metaCandidateRows.length === 0) return normalizedRows;

  const autoDialLeadIds = Array.from(new Set(
    metaCandidateRows.map((row) => cleanJustDialString(row.id, 80)).filter(Boolean)
  ));
  const phoneNumbers = Array.from(new Set(
    metaCandidateRows.map((row) => normalizeAutoDialPhone(row.normalized_number || row.mobile_number)).filter(Boolean)
  ));
  const whereParts = [];
  const params = [];
  if (autoDialLeadIds.length > 0) {
    whereParts.push('auto_dial_lead_id IN (?)');
    params.push(autoDialLeadIds);
  }
  if (phoneNumbers.length > 0) {
    whereParts.push('phone_number IN (?)');
    params.push(phoneNumbers);
  }
  if (whereParts.length === 0) return normalizedRows;

  const [metaRows] = await pool.query(
    `SELECT leadid, full_name, phone_number, city, state, lead_created_at, raw_payload, auto_dial_lead_id, received_at, updated_at
     FROM attica_meta_leads
     WHERE ${whereParts.join(' OR ')}
     ORDER BY updated_at DESC, received_at DESC`,
    params
  );
  const metaByAutoDialLeadId = new Map();
  const metaByPhone = new Map();
  for (const metaRow of metaRows) {
    const autoDialLeadId = cleanJustDialString(metaRow.auto_dial_lead_id, 80);
    const phone = normalizeAutoDialPhone(metaRow.phone_number);
    if (autoDialLeadId && !metaByAutoDialLeadId.has(autoDialLeadId)) {
      metaByAutoDialLeadId.set(autoDialLeadId, metaRow);
    }
    if (phone && !metaByPhone.has(phone)) {
      metaByPhone.set(phone, metaRow);
    }
  }

  return normalizedRows.map((row) => {
    const leadId = cleanJustDialString(row.id, 80);
    const phone = normalizeAutoDialPhone(row.normalized_number || row.mobile_number);
    const metaRow = metaByAutoDialLeadId.get(leadId) || metaByPhone.get(phone);
    if (!metaRow) return row;
    const rawPayload = parseJsonObject(metaRow.raw_payload);
    return {
      ...row,
      __meta_state: cleanJustDialString(metaRow.state, 120),
      __meta_city: cleanJustDialString(metaRow.city, 120),
      __meta_full_name: cleanJustDialString(metaRow.full_name, 255),
      __meta_phone_number: normalizeAutoDialPhone(metaRow.phone_number) || cleanJustDialString(metaRow.phone_number, 30),
      __meta_service_looking_for: cleanJustDialString(rawPayload.service_looking_for, 255),
      __meta_gold_amount: cleanJustDialString(rawPayload.gold_amount, 120),
      __meta_planned_visit: cleanJustDialString(rawPayload.planned_visit, 255),
      __meta_lead_created_at: metaRow.lead_created_at,
    };
  });
}

async function serializeEnrichedAutoDialLeadRows(rows) {
  const enrichedRows = await enrichAutoDialLeadRowsWithMetaDetails(rows);
  return enrichedRows.map(serializeAutoDialLeadRow);
}

async function serializeEnrichedAutoDialLeadRow(row) {
  const [serializedRow] = await serializeEnrichedAutoDialLeadRows(row ? [row] : []);
  return serializedRow || null;
}

function parseSystemSettingBoolean(value, fallback = false) {
  if (value === undefined || value === null || value === '') return fallback;
  const normalizedValue = String(value).trim().toLowerCase();
  if (['1', 'true', 'on', 'yes', 'enabled', 'connect', 'connected'].includes(normalizedValue)) return true;
  if (['0', 'false', 'off', 'no', 'disabled', 'disconnect', 'disconnected'].includes(normalizedValue)) return false;
  return fallback;
}

function normalizePledgePlaces(value) {
  let values = value;
  if (typeof value === 'string') {
    try { values = JSON.parse(value); } catch { values = value.split(','); }
  }
  const normalized = Array.isArray(values)
    ? values.map((item) => String(item || '').trim().slice(0, 150)).filter(Boolean)
    : [];
  return Array.from(new Set([...normalized.filter((item) => item.toLowerCase() !== 'bank'), 'Other']));
}

async function readPledgePlaces() {
  const [rows] = await pool.query(
    'SELECT setting_value FROM attica_system_settings WHERE setting_key=? LIMIT 1',
    [PLEDGE_PLACES_SETTING_KEY],
  );
  return normalizePledgePlaces(rows?.[0]?.setting_value || DEFAULT_PLEDGE_PLACES);
}

async function updatePledgePlaces(value, updatedById = '', updatedByName = '') {
  const places = normalizePledgePlaces(value);
  await pool.query(
    `INSERT INTO attica_system_settings (setting_key, setting_value, updated_by_id, updated_by_name)
     VALUES (?, ?, ?, ?)
     ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value), updated_by_id=VALUES(updated_by_id), updated_by_name=VALUES(updated_by_name), updated_at=CURRENT_TIMESTAMP`,
    [PLEDGE_PLACES_SETTING_KEY, JSON.stringify(places), String(updatedById || '').slice(0, 20), String(updatedByName || '').slice(0, 100)],
  );
  return places;
}

function normalizeFreshLeadAutoConnectIntervalSeconds(value) {
  const seconds = Number(value);
  if (!Number.isFinite(seconds)) return 3;
  return Math.max(1, Math.min(120, Math.round(seconds)));
}

function serializeAutoDialControlState(rows) {
  const normalizedRows = Array.isArray(rows) ? rows : (rows ? [rows] : []);
  const settingsByKey = new Map(normalizedRows.map((row) => [String(row?.setting_key || ''), row]));
  const controlRow = settingsByKey.get(AUTO_DIAL_CONTROL_SETTING_KEY) || normalizedRows[0] || null;
  const freshAutoConnectRow = settingsByKey.get(AUTO_DIAL_FRESH_AUTO_CONNECT_SETTING_KEY) || null;
  const freshIntervalRow = settingsByKey.get(AUTO_DIAL_FRESH_AUTO_CONNECT_INTERVAL_SETTING_KEY) || null;

  return {
    enabled: parseSystemSettingBoolean(controlRow?.setting_value, false),
    freshLeadAutoConnectEnabled: parseSystemSettingBoolean(freshAutoConnectRow?.setting_value, true),
    freshLeadAutoConnectIntervalSeconds: normalizeFreshLeadAutoConnectIntervalSeconds(freshIntervalRow?.setting_value),
    updatedAt: toApiIsoString(controlRow?.updated_at),
    updatedById: controlRow?.updated_by_id || '',
    updatedByName: controlRow?.updated_by_name || '',
  };
}

async function readAutoDialControlState() {
  if (autoDialControlStateCache && autoDialControlStateCacheExpiresAt > Date.now()) {
    return autoDialControlStateCache;
  }

  const [rows] = await pool.query(
    `SELECT setting_key, setting_value, updated_by_id, updated_by_name, updated_at
     FROM attica_system_settings
     WHERE setting_key IN (?, ?, ?)`,
    [
      AUTO_DIAL_CONTROL_SETTING_KEY,
      AUTO_DIAL_FRESH_AUTO_CONNECT_SETTING_KEY,
      AUTO_DIAL_FRESH_AUTO_CONNECT_INTERVAL_SETTING_KEY,
    ]
  );

  const state = serializeAutoDialControlState(rows);
  autoDialControlStateCache = state;
  autoDialControlStateCacheExpiresAt = Date.now() + AUTO_DIAL_CONTROL_CACHE_MS;
  return state;
}

async function updateAutoDialControlState({
  enabled,
  freshLeadAutoConnectEnabled,
  freshLeadAutoConnectIntervalSeconds,
  updatedById = '',
  updatedByName = '',
}) {
  const updates = [
    [AUTO_DIAL_CONTROL_SETTING_KEY, enabled ? '1' : '0'],
  ];

  if (freshLeadAutoConnectEnabled !== undefined) {
    updates.push([AUTO_DIAL_FRESH_AUTO_CONNECT_SETTING_KEY, freshLeadAutoConnectEnabled ? '1' : '0']);
  }

  if (freshLeadAutoConnectIntervalSeconds !== undefined) {
    updates.push([
      AUTO_DIAL_FRESH_AUTO_CONNECT_INTERVAL_SETTING_KEY,
      String(normalizeFreshLeadAutoConnectIntervalSeconds(freshLeadAutoConnectIntervalSeconds)),
    ]);
  }

  for (const [settingKey, settingValue] of updates) {
    await pool.query(
      `INSERT INTO attica_system_settings (setting_key, setting_value, updated_by_id, updated_by_name)
       VALUES (?, ?, ?, ?)
       ON DUPLICATE KEY UPDATE
         setting_value=VALUES(setting_value),
         updated_by_id=VALUES(updated_by_id),
         updated_by_name=VALUES(updated_by_name),
         updated_at=CURRENT_TIMESTAMP`,
      [
        settingKey,
        settingValue,
        updatedById || null,
        updatedByName || null,
      ]
    );
  }

  invalidateLiveAgentSnapshotCache();
  autoDialControlStateCache = null;
  autoDialControlStateCacheExpiresAt = 0;
  autoDialLeadsResponseCache.clear();
  return readAutoDialControlState();
}

async function disconnectAllAutoDialAssignments(reason = AUTO_DIAL_DISABLED_REASON) {
  const [leadRows] = await pool.query(
    `SELECT id
     FROM attica_auto_dial_leads
     WHERE status IN ('assigned','dialing')`
  );
  const leadIds = leadRows
    .map((row) => canonicalizeAutoDialLeadId(row.id))
    .filter(Boolean);
  const [result] = await pool.query(
    `UPDATE attica_auto_dial_leads
     SET status='pending',
         assigned_agent_id=NULL,
         assigned_agent_name=NULL,
         assigned_at=NULL,
         dial_started_at=NULL,
         completed_at=NULL,
         queue_exit_reason=NULL,
         retry_allowed=1,
         call_id=NULL,
         last_error=?,
         open_dedupe_number=normalized_number,
         updated_at=NOW()
     WHERE status IN ('assigned','dialing')`,
    [reason]
  );

  if (Number(result?.affectedRows || 0) > 0 && leadIds.length > 0) {
    await syncAutoDialLeadStatusToSources(leadIds, 'pending');
  }

  return Number(result?.affectedRows || 0);
}

let autoDialAssignmentInProgress = false;
let autoDialAssignmentStartedAt = 0;
let lastAutoDialTerminalCleanupAt = 0;
let autoDialLastOnDemandKickAt = 0;
const autoDialLastAgentPollKickAtByAgentId = new Map();
const autoDialLeadsResponseCache = new Map();
const AUTO_DIAL_LEADS_RESPONSE_CACHE_MS = 15000;
let autoDialControlStateCache = null;
let autoDialControlStateCacheExpiresAt = 0;
const AUTO_DIAL_CONTROL_CACHE_MS = 15000;

async function triggerAutoDialAssignment(trigger = 'background', context = {}) {
  const normalizedTrigger = cleanJustDialString(trigger, 50) || 'background';
  const requestedAgentId = normalizeAgentId(context.requestedAgentId);
  if (normalizedTrigger === 'agent-poll') {
    if (!requestedAgentId) {
      return { checked: 0, assigned: 0, skipped: true, trigger: normalizedTrigger, reason: 'missing-agent' };
    }
    const now = Date.now();
    const lastPollKickAt = autoDialLastAgentPollKickAtByAgentId.get(requestedAgentId) || 0;
    if (now - lastPollKickAt < AUTO_DIAL_AGENT_POLL_MIN_INTERVAL_MS) {
      return { checked: 0, assigned: 0, skipped: true, throttled: true, trigger: normalizedTrigger };
    }
    autoDialLastAgentPollKickAtByAgentId.set(requestedAgentId, now);
    return assignPendingAutoDialLeads(normalizedTrigger, { ...context, requestedAgentId });
  }
  if (PROCESS_ROLE === 'api' && normalizedTrigger !== 'background') {
    return { checked: 0, assigned: 0, skipped: true, deferredToScheduler: true, trigger: normalizedTrigger };
  }
  if (normalizedTrigger !== 'background') {
    const now = Date.now();
    if (now - autoDialLastOnDemandKickAt < AUTO_DIAL_EVENT_KICK_THROTTLE_MS) {
      return { checked: 0, assigned: 0, skipped: true, throttled: true, trigger: normalizedTrigger };
    }
    autoDialLastOnDemandKickAt = now;
  }
  return assignPendingAutoDialLeads(normalizedTrigger, context);
}

async function getAssignableAutoDialLeads(limit = 25, options = {}) {
  await expireOldFollowUps();
  const today = getBusinessDateString();
  const requestedAgentId = normalizeAgentId(options.requestedAgentId);
  let candidateFetchLimit = requestedAgentId
    ? Math.min(Math.max(limit * 8, 120), 240)
    : Math.min(Math.max(limit * 8, 160), 320);
  const availableAgentIds = Array.from(
    new Set(
      (Array.isArray(options.availableAgentIds) ? options.availableAgentIds : [])
        .map((agentId) => normalizeAgentId(agentId))
        .filter((agentId) => agentId && agentId !== requestedAgentId)
    )
  );
  const eligibleScheduledAgentIds = new Set([requestedAgentId, ...availableAgentIds].filter(Boolean));
  const allowedWorkModes = new Set(
    (Array.isArray(options.workModes) ? options.workModes : [])
      .map((value) => String(value || '').trim().toLowerCase())
      .filter((value) => value === 'outbound-auto' || value === 'follow-up')
  );
  const restrictOutboundOnly = allowedWorkModes.has('outbound-auto') && !allowedWorkModes.has('follow-up');
  const restrictFollowUpOnly = allowedWorkModes.has('follow-up') && !allowedWorkModes.has('outbound-auto');
  if (restrictFollowUpOnly) {
    candidateFetchLimit = Math.max(
      candidateFetchLimit,
      Math.min(AUTO_DIAL_FOLLOW_UP_CANDIDATE_SCAN_LIMIT, requestedAgentId ? 800 : AUTO_DIAL_FOLLOW_UP_CANDIDATE_SCAN_LIMIT)
    );
  }
  const eligibleScheduledAgentIdList = Array.from(eligibleScheduledAgentIds);
  const fetchQueueRows = async ({
    workMode,
    limit: fetchLimit,
    scheduledOnly = false,
    missedOnly = false,
    statusType = 'pending',
  }) => {
    const params = [];
    let workModeSql = '';
    let activeQueueSql = '';
    let queueIndexHint = '';
    let failedRetrySql = `(${FOLLOW_UP_AUTO_DIAL_PREDICATE_SQL} OR ${MISSED_CALLBACK_AUTO_DIAL_PREDICATE_SQL})`;
    let orderSql = 'created_at ASC, id ASC';

    if (missedOnly) {
      workModeSql = `AND queue_bucket='missed-callback'`;
      // Missed calls are priority callback work, not fresh leads. Keep every
      // active missed callback eligible and let FIFO order pick the oldest one.
      activeQueueSql = `AND IFNULL(is_active, 1) = 1`;
      failedRetrySql = `queue_bucket='missed-callback'`;
      orderSql = `FIELD(status, 'pending', 'assigned', 'failed', 'dialing'),
                  created_at ASC,
                  id ASC`;
    } else if (workMode === 'outbound-auto') {
      workModeSql = `AND queue_work_mode='outbound-auto'
                     AND queue_bucket='outbound'`;
      activeQueueSql = `AND created_at >= DATE_SUB(${MYSQL_QUEUE_NOW_SQL}, INTERVAL ${AUTO_DIAL_FRESH_MAX_AGE_DAYS} DAY)`;
      failedRetrySql = '0';
      orderSql = `CASE
                    WHEN LOWER(IFNULL(source_file, '')) LIKE '%website%' THEN 0
                    WHEN LOWER(IFNULL(source_file, '')) LIKE '%meta%' THEN 1
                    WHEN LOWER(IFNULL(source_file, '')) LIKE '%justdial%'
                      OR LOWER(IFNULL(source_file, '')) LIKE '%just dial%' THEN 2
                    ELSE 3
                  END,
                  CASE WHEN scheduled_for IS NOT NULL THEN 0 ELSE 1 END,
                  COALESCE(scheduled_for, created_at) ASC,
                  created_at ASC,
                  id ASC`;
    } else if (workMode === 'follow-up') {
      queueIndexHint = scheduledOnly
        ? 'FORCE INDEX (idx_attica_auto_dial_scheduled_agent_due)'
        : 'FORCE INDEX (idx_attica_auto_dial_status_work_created)';
      workModeSql = `AND queue_work_mode='follow-up'
                     AND queue_bucket='follow-up'`;
      activeQueueSql = `AND is_active = 1
                        AND (followup_expires_at IS NULL OR followup_expires_at >= ${MYSQL_QUEUE_NOW_SQL})`;
      failedRetrySql = `queue_work_mode='follow-up' AND queue_bucket='follow-up'`;
      orderSql = `COALESCE(scheduled_for, created_at) ASC,
                  created_at ASC,
                  id ASC`;
    }

    let statusSql = "status='pending'";
    if (statusType === 'failed') {
      if (failedRetrySql === '0') {
        return [];
      }
      statusSql = `status='failed' AND ${failedRetrySql}`;
    } else if (statusType === 'stale-assigned') {
      statusSql = `status='assigned'
                   AND dial_started_at IS NULL
                   AND (
                     IFNULL(assigned_agent_id, '') = ''
                     OR assigned_at IS NULL
                     OR assigned_at < DATE_SUB(NOW(), INTERVAL ? SECOND)
                   )`;
      params.push(AUTO_DIAL_STALE_ASSIGNMENT_SECONDS);
    } else if (statusType !== 'pending') {
      return [];
    }

    let scheduleSql = `AND ${AUTO_DIAL_SCHEDULE_DUE_SQL}`;
    if (scheduledOnly) {
      if (eligibleScheduledAgentIdList.length === 0) {
        return [];
      }
      scheduleSql = `AND scheduled_for IS NOT NULL
                     AND ${AUTO_DIAL_SCHEDULE_DUE_SQL}
                     AND scheduled_agent_id IN (?)`;
      params.push(eligibleScheduledAgentIdList);
    }

    params.push(Math.max(1, fetchLimit));

	    const [rows] = await pool.query(
	      `SELECT id,
	              customer_name,
	              mobile_number,
	              normalized_number,
	              area,
	              source_state,
	              preferred_language,
	              gold_weight,
	              lead_type,
	              source_file,
	              status,
	              scheduled_agent_id,
	              scheduled_agent_name,
	              scheduled_for,
	              assigned_agent_id,
	              assigned_at,
	              dial_started_at,
	              completed_at,
	              retry_allowed,
	              followup_expires_at,
	              followup_reason,
	              is_active,
	              queue_work_mode,
	              queue_bucket,
	              created_at,
	              updated_at
	       FROM attica_auto_dial_leads ${queueIndexHint}
	       WHERE ${statusSql}
	         AND retry_allowed = 1
         ${activeQueueSql}
         AND ${AUTO_DIAL_NOT_DUPLICATE_REMOVED_SQL}
         ${workModeSql}
         ${scheduleSql}
       ORDER BY ${orderSql}
       LIMIT ?`,
      params
    );
    return rows;
  };
  const fetchQueueStatusBatches = async (queueOptions) => {
    const statusOrder = ['pending', 'stale-assigned', 'failed'];
    const rows = [];
    const requestedLimit = Math.max(1, Number(queueOptions.limit || candidateFetchLimit));
    for (const statusType of statusOrder) {
      if (rows.length >= requestedLimit) {
        break;
      }
      const batchRows = await fetchQueueRows({
        ...queueOptions,
        statusType,
        limit: requestedLimit - rows.length,
      });
      rows.push(...batchRows);
    }
    return rows;
  };
  const shouldLoadOutboundRetryBlocks = !restrictFollowUpOnly;
  const shouldLoadFollowUpRetryBlocks = !restrictOutboundOnly;
  const [
    priorityRowsResult,
    candidateRowsResult,
    blockedRowsResult,
    calledRowsResult,
    recentCallRowsResult,
    recentLeadRowsResult,
    recentFollowUpLeadRowsResult,
    recentFollowUpCallRowsResult,
  ] = await Promise.all([
    (async () => {
      const batches = [];
      if (!restrictFollowUpOnly) {
        batches.push(await fetchQueueStatusBatches({ missedOnly: true, scheduledOnly: true, limit: Math.ceil(candidateFetchLimit / 2) }));
        batches.push(await fetchQueueStatusBatches({ workMode: 'outbound-auto', scheduledOnly: true, limit: candidateFetchLimit }));
      }
      if (!restrictOutboundOnly) {
        batches.push(await fetchQueueStatusBatches({ workMode: 'follow-up', scheduledOnly: true, limit: candidateFetchLimit }));
      }
      return [batches.flat()];
    })(),
    (async () => {
      const batches = [];
      if (!restrictFollowUpOnly) {
        batches.push(await fetchQueueStatusBatches({ missedOnly: true, limit: Math.ceil(candidateFetchLimit / 2) }));
        batches.push(await fetchQueueStatusBatches({ workMode: 'outbound-auto', limit: candidateFetchLimit }));
      }
      if (!restrictOutboundOnly) {
        batches.push(await fetchQueueStatusBatches({ workMode: 'follow-up', limit: candidateFetchLimit }));
      }
      return [batches.flat()];
    })(),
    pool.query('SELECT phone FROM attica_blocked_numbers'),
    shouldLoadOutboundRetryBlocks ? pool.query(
      `SELECT phone
       FROM attica_followups
       WHERE status='Called'
         AND ${FOLLOWUP_NOT_DUPLICATE_REMOVED_SQL}
         AND updated_at >= CURDATE()
         AND updated_at < DATE_ADD(CURDATE(), INTERVAL 1 DAY)`
    ) : Promise.resolve([[]]),
    Promise.resolve([[]]),
    Promise.resolve([[]]),
    Promise.resolve([[]]),
    Promise.resolve([[]]),
  ]);
  const [priorityRows] = priorityRowsResult;
  const [rows] = candidateRowsResult;
  const [blockedRows] = blockedRowsResult;
  const [calledRows] = calledRowsResult;
  let [recentCallRows] = recentCallRowsResult;
  let [recentLeadRows] = recentLeadRowsResult;
  let [recentFollowUpLeadRows] = recentFollowUpLeadRowsResult;
  let [recentFollowUpCallRows] = recentFollowUpCallRowsResult;
  const mergedRows = [];
  const seenLeadIds = new Set();

  for (const row of [...priorityRows, ...rows]) {
    const leadId = String(row.id || '');
    if (leadId && seenLeadIds.has(leadId)) continue;
    if (leadId) seenLeadIds.add(leadId);
    mergedRows.push(row);
  }

  const candidatePhones = Array.from(
    new Set(mergedRows.map((row) => normalizeAutoDialPhone(row.normalized_number || row.mobile_number)).filter(Boolean))
  );
  if (candidatePhones.length > 0) {
    const [
      targetedRecentCallRowsResult,
      targetedRecentLeadRowsResult,
      targetedRecentFollowUpLeadRowsResult,
      targetedRecentFollowUpCallRowsResult,
    ] = await Promise.all([
      shouldLoadOutboundRetryBlocks ? pool.query(
        `SELECT caller_id, normalized_customer_number, status, callback_status, created_at, call_date
         FROM attica_calls FORCE INDEX (idx_attica_calls_norm_created)
         WHERE normalized_customer_number IN (?)
           AND direction='outgoing'
           AND created_at >= DATE_SUB(NOW(), INTERVAL ? MINUTE)
         UNION ALL
         SELECT caller_id, normalized_customer_number, status, callback_status, created_at, call_date
         FROM attica_calls FORCE INDEX (idx_attica_calls_caller_created)
         WHERE caller_id IN (?)
           AND direction='outgoing'
           AND created_at >= DATE_SUB(NOW(), INTERVAL ? MINUTE)`,
        [
          candidatePhones,
          AUTO_DIAL_PHONE_RETRY_COOLDOWN_MINUTES,
          candidatePhones,
          AUTO_DIAL_PHONE_RETRY_COOLDOWN_MINUTES,
        ]
      ) : Promise.resolve([[]]),
      pool.query(
        `SELECT id, mobile_number, status, updated_at
         FROM attica_auto_dial_leads FORCE INDEX (idx_attica_auto_dial_mobile_status)
         WHERE mobile_number IN (?)
           AND (
             status IN ('assigned','dialing')
             OR (
               status IN ('completed','failed')
               AND updated_at >= DATE_SUB(NOW(), INTERVAL ? MINUTE)
             )
           )
         UNION ALL
         SELECT id, mobile_number, status, updated_at
         FROM attica_auto_dial_leads FORCE INDEX (idx_attica_auto_dial_normalized_number)
         WHERE normalized_number IN (?)
           AND (
             status IN ('assigned','dialing')
             OR (
               status IN ('completed','failed')
               AND updated_at >= DATE_SUB(NOW(), INTERVAL ? MINUTE)
             )
           )`,
        [
          candidatePhones,
          AUTO_DIAL_PHONE_RETRY_COOLDOWN_MINUTES,
          candidatePhones,
          AUTO_DIAL_PHONE_RETRY_COOLDOWN_MINUTES,
        ]
      ),
      shouldLoadFollowUpRetryBlocks ? pool.query(
        `SELECT id,
                mobile_number,
                normalized_number,
                status,
                GREATEST(
                  COALESCE(dial_started_at, '1970-01-01 00:00:00'),
                  COALESCE(completed_at, '1970-01-01 00:00:00'),
                  COALESCE(updated_at, '1970-01-01 00:00:00')
                ) AS last_attempt_at
         FROM attica_auto_dial_leads FORCE INDEX (idx_attica_auto_dial_mobile_status)
         WHERE mobile_number IN (?)
           AND ${FOLLOW_UP_AUTO_DIAL_PREDICATE_SQL}
           AND (
             status IN ('assigned','dialing')
             OR (
               status IN ('completed','failed')
               AND updated_at >= DATE_SUB(NOW(), INTERVAL ? MINUTE)
               AND GREATEST(
                 COALESCE(dial_started_at, '1970-01-01 00:00:00'),
                 COALESCE(completed_at, '1970-01-01 00:00:00'),
                 COALESCE(updated_at, '1970-01-01 00:00:00')
               ) >= DATE_SUB(NOW(), INTERVAL ? MINUTE)
             )
           )
         UNION ALL
         SELECT id,
                mobile_number,
                normalized_number,
                status,
                GREATEST(
                  COALESCE(dial_started_at, '1970-01-01 00:00:00'),
                  COALESCE(completed_at, '1970-01-01 00:00:00'),
                  COALESCE(updated_at, '1970-01-01 00:00:00')
                ) AS last_attempt_at
         FROM attica_auto_dial_leads FORCE INDEX (idx_attica_auto_dial_normalized_number)
         WHERE normalized_number IN (?)
           AND ${FOLLOW_UP_AUTO_DIAL_PREDICATE_SQL}
           AND (
             status IN ('assigned','dialing')
             OR (
               status IN ('completed','failed')
               AND updated_at >= DATE_SUB(NOW(), INTERVAL ? MINUTE)
               AND GREATEST(
                 COALESCE(dial_started_at, '1970-01-01 00:00:00'),
                 COALESCE(completed_at, '1970-01-01 00:00:00'),
                 COALESCE(updated_at, '1970-01-01 00:00:00')
               ) >= DATE_SUB(NOW(), INTERVAL ? MINUTE)
             )
           )`,
        [
          candidatePhones,
          FOLLOW_UP_PHONE_RETRY_COOLDOWN_MINUTES,
          FOLLOW_UP_PHONE_RETRY_COOLDOWN_MINUTES,
          candidatePhones,
          FOLLOW_UP_PHONE_RETRY_COOLDOWN_MINUTES,
          FOLLOW_UP_PHONE_RETRY_COOLDOWN_MINUTES,
        ]
      ) : Promise.resolve([[]]),
      shouldLoadFollowUpRetryBlocks ? pool.query(
        `SELECT caller_id,
                normalized_customer_number,
                COALESCE(ended_at, answered_at, ring_started_at, created_at) AS last_attempt_at
         FROM attica_calls FORCE INDEX (idx_attica_calls_norm_created)
         WHERE normalized_customer_number IN (?)
           AND direction='outgoing'
           AND created_at >= DATE_SUB(NOW(), INTERVAL ? MINUTE)
           AND COALESCE(ended_at, answered_at, ring_started_at, created_at) >= DATE_SUB(NOW(), INTERVAL ? MINUTE)
         UNION ALL
         SELECT caller_id,
                normalized_customer_number,
                COALESCE(ended_at, answered_at, ring_started_at, created_at) AS last_attempt_at
         FROM attica_calls FORCE INDEX (idx_attica_calls_caller_created)
         WHERE caller_id IN (?)
           AND direction='outgoing'
           AND created_at >= DATE_SUB(NOW(), INTERVAL ? MINUTE)
           AND COALESCE(ended_at, answered_at, ring_started_at, created_at) >= DATE_SUB(NOW(), INTERVAL ? MINUTE)`,
        [
          candidatePhones,
          FOLLOW_UP_PHONE_RETRY_COOLDOWN_MINUTES,
          FOLLOW_UP_PHONE_RETRY_COOLDOWN_MINUTES,
          candidatePhones,
          FOLLOW_UP_PHONE_RETRY_COOLDOWN_MINUTES,
          FOLLOW_UP_PHONE_RETRY_COOLDOWN_MINUTES,
        ]
      ) : Promise.resolve([[]]),
    ]);
    [recentCallRows] = targetedRecentCallRowsResult;
    [recentLeadRows] = targetedRecentLeadRowsResult;
    [recentFollowUpLeadRows] = targetedRecentFollowUpLeadRowsResult;
    [recentFollowUpCallRows] = targetedRecentFollowUpCallRowsResult;
  }
  const retryStateByPhone = await fetchAutoDialRetryStateByPhones(
    pool,
    [
      ...mergedRows.map((row) => row.mobile_number),
      ...recentLeadRows.map((row) => row.mobile_number),
      ...recentCallRows.map((row) => row.normalized_customer_number || row.caller_id),
    ],
    `${today}:`
  );
  const [openDedupeRows] = candidatePhones.length > 0
    ? await pool.query(
      `SELECT id, open_dedupe_number
       FROM attica_auto_dial_leads
       WHERE status IN (?)
         AND open_dedupe_number IN (?)`,
      [Array.from(OPEN_AUTO_DIAL_LEAD_STATUSES), candidatePhones]
    )
    : [[]];
  const openDedupeLeadIdsByPhone = new Map();

  for (const row of openDedupeRows) {
    const phone10 = normalizeAutoDialPhone(row.open_dedupe_number);
    if (!phone10) continue;
    if (!openDedupeLeadIdsByPhone.has(phone10)) {
      openDedupeLeadIdsByPhone.set(phone10, new Set());
    }
    openDedupeLeadIdsByPhone.get(phone10).add(String(row.id || ''));
  }
  const blockedPhones = new Set(blockedRows.map((row) => normalizeAutoDialPhone(row.phone)).filter(Boolean));
  const calledTodayPhones = new Set(calledRows.map((row) => normalizeAutoDialPhone(row.phone)).filter(Boolean));
  const recentOutgoingPhones = new Set();
  const recentOutgoingPhoneBlockReasons = new Map();
  const samePhoneRecentLeadIds = new Map();
  const recentFollowUpAttemptByPhone = new Map();

  const trackRecentFollowUpAttempt = (phoneValue, attemptedAtValue) => {
    const phone10 = normalizeAutoDialPhone(phoneValue);
    if (!phone10 || !attemptedAtValue) return;
    const attemptedAt = new Date(attemptedAtValue).getTime();
    if (!Number.isFinite(attemptedAt)) return;
    const previous = recentFollowUpAttemptByPhone.get(phone10) || 0;
    if (attemptedAt > previous) {
      recentFollowUpAttemptByPhone.set(phone10, attemptedAt);
    }
  };

  for (const row of recentCallRows) {
    const phone10 = normalizeAutoDialPhone(row.normalized_customer_number || row.caller_id);
    if (!phone10) continue;
    const callbackStatus = String(row.callback_status || '').trim().toUpperCase();
    const callStatus = normalizeCallStatus(row.status);
    const callDate = row.call_date instanceof Date
      ? row.call_date.toISOString().slice(0, 10)
      : String(row.call_date || '').slice(0, 10);
    const createdAt = row.created_at ? new Date(row.created_at).getTime() : Number.NaN;
    const isRecent = Number.isFinite(createdAt)
      && createdAt >= Date.now() - (AUTO_DIAL_PHONE_RETRY_COOLDOWN_MINUTES * 60 * 1000);
    const isRecentRetryBlock = ['RNR', 'NA', 'LB', 'NETWORK FAILURE', 'WN', 'DEC'].includes(callbackStatus) && isRecent;
    const isCompletedTodayBlock = (
      callStatus === 'completed'
      || ['COMPLETED', 'CUSTOMER DISCONNECTED', 'TRANSFERRED'].includes(callbackStatus)
    ) && callDate === today;
    if (isRecentRetryBlock || isCompletedTodayBlock) {
      recentOutgoingPhones.add(phone10);
      if (isCompletedTodayBlock) {
        recentOutgoingPhoneBlockReasons.set(phone10, 'called-today');
      } else if (!recentOutgoingPhoneBlockReasons.has(phone10)) {
        recentOutgoingPhoneBlockReasons.set(phone10, 'recent-retry');
      }
    }
  }

  for (const row of recentLeadRows) {
    const phone10 = normalizeAutoDialPhone(row.mobile_number);
    if (!phone10) continue;
    if (!samePhoneRecentLeadIds.has(phone10)) {
      samePhoneRecentLeadIds.set(phone10, new Set());
    }
    samePhoneRecentLeadIds.get(phone10).add(String(row.id || ''));
  }

  for (const row of recentFollowUpLeadRows) {
    trackRecentFollowUpAttempt(row.normalized_number || row.mobile_number, row.last_attempt_at || row.updated_at);
  }

  for (const row of recentFollowUpCallRows) {
    trackRecentFollowUpAttempt(row.normalized_customer_number || row.caller_id, row.last_attempt_at);
  }

  const eligibleRows = [];
  const seenPhones = new Set();

  for (const row of mergedRows) {
    const rowWorkMode = getAutoDialWorkModeForLead(row);
    if (allowedWorkModes.size > 0 && !allowedWorkModes.has(rowWorkMode)) {
      continue;
    }
    const scheduledAgentId = normalizeAgentId(row.scheduled_agent_id);
    // Do not hard-filter fresh leads by scheduled agent here. The assignment
    // loop checks whether the scheduled agent is currently usable and falls
    // back when that old lock would otherwise leave FIFO leads idle.
    const phone10 = normalizeAutoDialPhone(row.mobile_number);
    const rowIsMissedCallback = isImmediateMissedCallbackLead(row);
    if (rowWorkMode === 'outbound-auto' && !rowIsMissedCallback && isLikelyFakeAutoDialMobileNumber(phone10)) {
      await finalizeAutoDialLeadAsTerminalFailure(row.id, {
        queueExitReason: 'Invalid Lead',
        lastError: 'Invalid outbound mobile number removed from auto-dial queue',
      });
      continue;
    }
    if (phone10) {
      const openDedupeLeadIds = openDedupeLeadIdsByPhone.get(phone10);
      const conflictingRecentIds = samePhoneRecentLeadIds.get(phone10);
      const retryState = retryStateByPhone.get(phone10);
      if (blockedPhones.has(phone10)) continue;
      if (openDedupeLeadIds && Array.from(openDedupeLeadIds).some((id) => id && id !== String(row.id || ''))) {
        continue;
      }
      if (rowWorkMode !== 'follow-up' && !rowIsMissedCallback && calledTodayPhones.has(phone10)) {
        await closeFreshAutoDialLeadAlreadyCalledToday(pool, row.id);
        continue;
      }
      if (rowWorkMode !== 'follow-up' && !rowIsMissedCallback && retryState?.connectedOnce) continue;
      if (rowWorkMode !== 'follow-up' && !rowIsMissedCallback && (retryState?.attemptCount || 0) >= AUTO_DIAL_MAX_ATTEMPTS_PER_NUMBER) continue;
      if (rowWorkMode !== 'follow-up' && !rowIsMissedCallback && recentOutgoingPhones.has(phone10)) {
        if (recentOutgoingPhoneBlockReasons.get(phone10) === 'called-today') {
          await closeFreshAutoDialLeadAlreadyCalledToday(pool, row.id);
        }
        continue;
      }
      if (rowWorkMode === 'follow-up') {
        const lastAttemptAt = recentFollowUpAttemptByPhone.get(phone10) || 0;
        const nextAllowedAt = lastAttemptAt + (FOLLOW_UP_PHONE_RETRY_COOLDOWN_MINUTES * 60 * 1000);
        if (lastAttemptAt > 0 && nextAllowedAt > Date.now()) {
          await deferFollowUpLeadForPhoneCooldown(
            row.id,
            new Date(nextAllowedAt),
            `Waiting ${FOLLOW_UP_PHONE_RETRY_COOLDOWN_MINUTES / 60} hours before retrying this follow-up number`
          );
          continue;
        }
      }
      if (
        rowWorkMode !== 'follow-up'
        && !rowIsMissedCallback
        && conflictingRecentIds
        && Array.from(conflictingRecentIds).some((id) => id && id !== String(row.id || ''))
      ) {
        continue;
      }
      if (seenPhones.has(phone10)) continue;
      seenPhones.add(phone10);
    }

    eligibleRows.push(row);
  }

  return orderAssignableAutoDialRows(eligibleRows, limit, {
    balanceMissedCallbacks: restrictOutboundOnly,
  });
}

async function assignPendingAutoDialLeads(trigger = 'background', context = {}) {
  let assignmentLockConnection = null;
  if (autoDialAssignmentInProgress) {
    let heldMs = autoDialAssignmentStartedAt ? Date.now() - autoDialAssignmentStartedAt : 0;
    if (trigger === 'agent-poll' && heldMs <= 60000) {
      const waitStartedAt = Date.now();
      while (autoDialAssignmentInProgress && Date.now() - waitStartedAt < 2200) {
        await sleepMs(150);
      }
      heldMs = autoDialAssignmentStartedAt ? Date.now() - autoDialAssignmentStartedAt : 0;
    }
    if (!autoDialAssignmentInProgress) {
      // The prior assignment pass completed while this agent poll waited.
    } else if (heldMs > 60000) {
      logAutoDialEvent('assignment-lock-reset', {
        trigger,
        requestedAgentId: context.requestedAgentId || '',
        heldMs,
      });
      autoDialAssignmentInProgress = false;
      autoDialAssignmentStartedAt = 0;
    } else {
      if (trigger !== 'background') {
        logAutoDialEvent('assignment-skipped', {
          trigger,
          requestedAgentId: context.requestedAgentId || '',
          reason: 'in-progress',
          heldMs,
        });
      }
      return { checked: 0, assigned: 0, skipped: true };
    }
  }
  autoDialAssignmentInProgress = true;
  autoDialAssignmentStartedAt = Date.now();

  try {
    assignmentLockConnection = await pool.getConnection();
    const [[assignmentLockRow]] = await assignmentLockConnection.query(
      "SELECT GET_LOCK('attica_auto_dial_assignment', ?) AS got_lock",
      [trigger === 'agent-poll' ? 2 : 0]
    );
    if (Number(assignmentLockRow?.got_lock || 0) !== 1) {
      if (trigger !== 'background' && trigger !== 'agent-poll') {
        logAutoDialEvent('assignment-skipped', {
          trigger,
          requestedAgentId: context.requestedAgentId || '',
          reason: 'cluster-lock-in-progress',
        });
      }
      return { checked: 0, assigned: 0, skipped: true, locked: true };
    }

    const autoDialControl = await readAutoDialControlState();
    if (autoDialControl.enabled === false) {
      return { checked: 0, assigned: 0, skipped: false, disabled: true };
    }
    const outboundAutoConnectGapSeconds = autoDialControl.freshLeadAutoConnectEnabled === false
      ? OUTBOUND_AUTO_DIAL_CONNECT_GAP_SECONDS
      : normalizeFreshLeadAutoConnectIntervalSeconds(
        autoDialControl.freshLeadAutoConnectIntervalSeconds || OUTBOUND_AUTO_DIAL_CONNECT_GAP_SECONDS
      );

    await runWithDbLockRetry('assignPendingAutoDialLeads.requeueStaleAssigned', async () => {
      const [staleAssignmentRows] = await assignmentLockConnection.query(
        `SELECT id
         FROM attica_auto_dial_leads FORCE INDEX (idx_attica_auto_dial_stale_assigned)
         WHERE status='assigned'
           AND dial_started_at IS NULL
           AND assigned_at < DATE_SUB(NOW(), INTERVAL ? SECOND)
         ORDER BY assigned_at ASC, id ASC
         LIMIT 250`,
        [AUTO_DIAL_STALE_ASSIGNMENT_SECONDS]
      );
      const staleAssignmentIds = Array.isArray(staleAssignmentRows)
        ? staleAssignmentRows.map((row) => String(row?.id || '').trim()).filter(Boolean)
        : [];
      if (staleAssignmentIds.length === 0) return;
      const placeholders = staleAssignmentIds.map(() => '?').join(',');
      await assignmentLockConnection.query(
        `UPDATE attica_auto_dial_leads
         SET status='pending',
             assigned_agent_id=NULL,
             assigned_agent_name=NULL,
             assigned_at=NULL,
             dial_started_at=NULL,
             call_id=NULL,
             queue_exit_reason=NULL,
             retry_allowed=1,
             open_dedupe_number=NULL,
             last_error=CASE
               WHEN IFNULL(last_error,'')='' THEN 'Requeued stale assigned auto-dial lead before assignment pass'
               ELSE last_error
             END,
             updated_at=NOW()
         WHERE id IN (${placeholders})`,
        staleAssignmentIds
      );
    }, 2);

    const shouldRunTerminalCleanup = Date.now() - lastAutoDialTerminalCleanupAt > AUTO_DIAL_TERMINAL_CLEANUP_THROTTLE_MS;
    if (shouldRunTerminalCleanup) {
      lastAutoDialTerminalCleanupAt = Date.now();
      setImmediate(() => {
        runWithDbLockRetry(
          'cleanupOpenAutoDialLeadsBlockedByTerminalPhoneState',
          () => cleanupOpenAutoDialLeadsBlockedByTerminalPhoneState()
        ).catch((error) => {
          lastAutoDialTerminalCleanupAt = 0;
          console.warn('Auto dial terminal cleanup skipped:', error?.message || error);
        });
      });
    }

    const liveAgents = await getLiveAgentSnapshot({ useCache: true });
    const [busyAssignments, recentOutboundAutoCompletions, transferReservations] = await Promise.all([
      pool.query(
        `SELECT assigned_agent_id, mobile_number
       FROM attica_auto_dial_leads
       WHERE assigned_agent_id IS NOT NULL
         AND (
           status='dialing'
           OR (
             status='assigned'
             AND assigned_at >= DATE_SUB(NOW(), INTERVAL ? SECOND)
           )
         )`,
        [AUTO_DIAL_STALE_ASSIGNMENT_SECONDS]
      ),
      pool.query(
        `SELECT assigned_agent_id
         FROM attica_auto_dial_leads
         WHERE assigned_agent_id IS NOT NULL
           AND queue_work_mode='outbound-auto'
           AND completed_at IS NOT NULL
           AND completed_at >= DATE_SUB(NOW(), INTERVAL ? SECOND)`,
        [outboundAutoConnectGapSeconds]
      ),
      pool.query(
        `SELECT id
         FROM attica_agents
         WHERE wrap_up_call_id LIKE 'TRANSFER-%'
           AND wrap_up_until > NOW()`
      ),
    ]);
    const [busyAssignmentRows] = busyAssignments;
    const [recentOutboundAutoRows] = recentOutboundAutoCompletions;
    const [transferReservationRows] = transferReservations;
    const busyAgentIds = new Set([
      ...busyAssignmentRows.map((row) => row.assigned_agent_id).filter(Boolean),
      ...transferReservationRows.map((row) => row.id).filter(Boolean),
    ]);
    const outboundAutoCooldownAgentIds = new Set([
      ...recentOutboundAutoRows.map((row) => normalizeAgentId(row.assigned_agent_id)).filter(Boolean),
    ]);
    const busyPhoneNumbers = new Set(
      busyAssignmentRows
        .map((row) => normalizeAutoDialPhone(row.mobile_number))
        .filter(Boolean)
    );

    const requestedAgentId = normalizeAgentId(context.requestedAgentId);
    const availableAgents = liveAgents
      .filter((agent) => {
        if (requestedAgentId && agent.agentId !== requestedAgentId) return false;
        return agent.canReceiveAutoDialAssignments && !busyAgentIds.has(agent.agentId);
      })
      .sort((left, right) => {
        if (left.followUpsPending !== right.followUpsPending) return left.followUpsPending - right.followUpsPending;
        if (left.callsToday !== right.callsToday) return left.callsToday - right.callsToday;
        return left.agentId.localeCompare(right.agentId);
      });
    const initialAvailableAgentCount = availableAgents.length;

    if (availableAgents.length === 0) {
      if (trigger !== 'background') {
        logAutoDialEvent('assignment-idle', {
          trigger,
          reason: 'no-available-agents',
          requestedAgentId: context.requestedAgentId || '',
          liveAgentCount: liveAgents.length,
          busyAgentCount: busyAgentIds.size,
          outboundAutoCooldownAgentCount: outboundAutoCooldownAgentIds.size,
          outboundAutoConnectGapSeconds,
        });
      }
      return { checked: 0, assigned: 0, skipped: false };
    }

    const availableWorkModes = Array.from(new Set(availableAgents.map((agent) => agent.workMode).filter(Boolean)));
    const availableAgentIds = availableAgents.map((agent) => agent.agentId);
    let leads = [];

    const modeSpecificLeadBatches = [];
    const modeSpecificLeadIds = new Set();
    const appendLeadBatch = (batchRows) => {
      for (const row of Array.isArray(batchRows) ? batchRows : []) {
        const rowId = String(row?.id || '');
        if (rowId && modeSpecificLeadIds.has(rowId)) continue;
        if (rowId) modeSpecificLeadIds.add(rowId);
        modeSpecificLeadBatches.push(row);
      }
    };
    const outboundAgentCount = availableAgents.filter((agent) => agent.workMode === 'outbound-auto').length;
    const followUpAgentCount = availableAgents.filter((agent) => agent.workMode === 'follow-up').length;

    if (outboundAgentCount > 0) {
      appendLeadBatch(await getAssignableAutoDialLeads(
        Math.min(Math.max(outboundAgentCount * 2, 10), 30),
        {
          requestedAgentId: context.requestedAgentId,
          availableAgentIds,
          workModes: ['outbound-auto'],
        }
      ));
    }

    if (followUpAgentCount > 0) {
      appendLeadBatch(await getAssignableAutoDialLeads(
        Math.min(Math.max(followUpAgentCount * 2, 10), 40),
        {
          requestedAgentId: context.requestedAgentId,
          availableAgentIds,
          workModes: ['follow-up'],
        }
      ));
    }

    if (modeSpecificLeadBatches.length > 0) {
      // Keep mode batches in fetch order so outbound-auto agents are not starved
      // by a large follow-up queue when both modes have idle agents.
      leads = modeSpecificLeadBatches;
    } else {
      leads = await getAssignableAutoDialLeads(
        Math.min(Math.max(availableAgents.length, 10), 25),
        {
          requestedAgentId: context.requestedAgentId,
          availableAgentIds,
          workModes: availableWorkModes,
        }
      );
    }
    if (leads.length === 0) {
      if (trigger !== 'background') {
        logAutoDialEvent('assignment-idle', {
          trigger,
          reason: 'no-eligible-leads',
          requestedAgentId: context.requestedAgentId || '',
          availableAgentCount: initialAvailableAgentCount,
        });
      }
      return { checked: 0, assigned: 0, skipped: false };
    }
    let assigned = 0;
    let checked = 0;
    const stickyAgentByPhone = new Map();
    const postReservationSyncs = [];

    for (const lead of leads) {
      if (assigned >= AUTO_DIAL_MAX_ASSIGNMENTS_PER_RUN) {
        break;
      }
      const phone10 = normalizeAutoDialPhone(lead.mobile_number);
      if (phone10 && busyPhoneNumbers.has(phone10)) {
        checked += 1;
        continue;
      }

      checked += 1;
      if (!availableAgents.length) break;

      const routing = getResolvedAutoDialLeadRouting(lead);
      const requiredWorkMode = getAutoDialWorkModeForLead(lead);
      const bypassesAgentCooldown = requiredWorkMode === 'follow-up'
        || isImmediateMissedCallbackLead(lead);
      const ignoresScheduledAgent = requiredWorkMode === 'follow-up';
      const requiresLanguageMatch = false;
      const agentMatchesAutoDialLanguage = (agent) => (
        !requiresLanguageMatch || agentSupportsAutoDialLanguage(agent, routing.preferredLanguage)
      );
      const agentPassesCooldown = (agent) => (
        bypassesAgentCooldown
        || requiredWorkMode !== 'outbound-auto'
        || !outboundAutoCooldownAgentIds.has(agent.agentId)
      );
      const hasExplicitScheduledAgent = !ignoresScheduledAgent && Boolean(routing.scheduledAgentId);
      let scheduledAgentId = ignoresScheduledAgent ? '' : routing.scheduledAgentId;
      let scheduledAgentName = ignoresScheduledAgent ? '' : routing.scheduledAgentName;

      if (!ignoresScheduledAgent && !scheduledAgentId && phone10) {
        let stickyOwner = stickyAgentByPhone.get(phone10);
        if (stickyOwner === undefined) {
          stickyOwner = await findStickyAutoDialAgentByPhone(phone10);
          stickyAgentByPhone.set(phone10, stickyOwner || null);
        }
        if (stickyOwner?.agentId) {
          scheduledAgentId = stickyOwner.agentId;
          scheduledAgentName = stickyOwner.agentName;
        }
      }

      const scheduledAgentIsUsableNow = hasExplicitScheduledAgent
        ? liveAgents.some((agent) =>
            agent.agentId === scheduledAgentId &&
            agent.canReceiveAutoDialAssignments &&
            agent.workMode === requiredWorkMode &&
            !busyAgentIds.has(agent.agentId) &&
            agentPassesCooldown(agent) &&
            agentMatchesAutoDialLanguage(agent)
          )
        : false;
      const lockToScheduledAgent = hasExplicitScheduledAgent && scheduledAgentIsUsableNow;
      const preferredAgentIndex = scheduledAgentId
        ? availableAgents.findIndex((agent) =>
            agent.agentId === scheduledAgentId &&
            agent.workMode === requiredWorkMode &&
            agentPassesCooldown(agent) &&
            (hasExplicitScheduledAgent || agentMatchesAutoDialLanguage(agent))
          )
        : -1;
      const fallbackAgentIndex = availableAgents.findIndex((agent) =>
        agent.workMode === requiredWorkMode &&
        agentPassesCooldown(agent) &&
        agentMatchesAutoDialLanguage(agent)
      );
      const agentIndex = lockToScheduledAgent
        ? preferredAgentIndex
        : (preferredAgentIndex !== -1 ? preferredAgentIndex : fallbackAgentIndex);
      if (agentIndex === -1) {
      const pendingReason = hasExplicitScheduledAgent
          ? `Scheduled agent ${scheduledAgentId} is not currently available for ${requiredWorkMode === 'follow-up' ? 'follow-up' : 'outbound auto call'} mode`
          : requiresLanguageMatch && routing.preferredLanguage
            ? `No idle outbound auto call agent supports ${routing.preferredLanguage} right now`
            : `No idle ${requiredWorkMode === 'follow-up' ? 'follow-up' : 'outbound auto call'} agent is available right now`;
        await updateAutoDialPendingReason(lead.id, pendingReason);
        continue;
      }

      const [agent] = availableAgents.splice(agentIndex, 1);
      if (!agent) continue;
      if (hasExplicitScheduledAgent && agent.agentId !== scheduledAgentId) {
        scheduledAgentId = agent.agentId;
        scheduledAgentName = agent.agentName;
      }

      const [[agentActiveAssignmentRow]] = await assignmentLockConnection.query(
        `SELECT COUNT(*) AS active_count
         FROM attica_auto_dial_leads
         WHERE assigned_agent_id=?
           AND status IN ('assigned','dialing')`,
        [agent.agentId]
      );
      if (Number(agentActiveAssignmentRow?.active_count || 0) > 0) {
        logAutoDialEvent('lead-pick-skipped', {
          trigger,
          leadId: lead.id,
          phone: phone10,
          agentId: agent.agentId,
          reason: 'agent-already-has-active-auto-dial-lead',
        });
        continue;
      }

      if (autoDialControl.enabled === false) {
        logAutoDialEvent('assignment-stopped', {
          trigger,
          requestedAgentId: context.requestedAgentId || '',
          reason: 'disabled-before-reservation',
          checked,
          assigned,
        });
        return { checked, assigned, skipped: false, disabled: true };
      }

      const [reservationResult] = await assignmentLockConnection.query(
        `UPDATE attica_auto_dial_leads
         SET status='assigned',
             assigned_agent_id=?,
             assigned_agent_name=?,
             scheduled_agent_id=?,
             scheduled_agent_name=?,
             assigned_at=NOW(),
             dial_started_at=NULL,
             completed_at=NULL,
             retry_allowed=0,
             source_state=?,
             preferred_language=?,
             open_dedupe_number=normalized_number,
             last_error=NULL
         WHERE id=?
           AND (
             status='pending'
             OR (
               status='failed'
               AND (${FOLLOW_UP_AUTO_DIAL_PREDICATE_SQL} OR ${MISSED_CALLBACK_AUTO_DIAL_PREDICATE_SQL})
             )
             OR (
               status='assigned'
               AND dial_started_at IS NULL
               AND (
                 assigned_at IS NULL
                 OR assigned_at < DATE_SUB(NOW(), INTERVAL ? SECOND)
               )
             )
	           )`,
        [
          agent.agentId,
          agent.agentName,
          scheduledAgentId || null,
          scheduledAgentName || null,
          routing.sourceState || null,
          routing.preferredLanguage || null,
          lead.id,
	          AUTO_DIAL_STALE_ASSIGNMENT_SECONDS,
	        ]
	      );
      if (reservationResult.affectedRows === 0) {
        logAutoDialEvent('lead-pick-skipped', {
          trigger,
          leadId: lead.id,
          phone: phone10,
          agentId: agent.agentId,
          reason: 'agent-reserved-or-lead-no-longer-pending',
        });
        availableAgents.push(agent);
        continue;
      }
      postReservationSyncs.push({
        leadId: lead.id,
        agentId: agent.agentId,
        agentName: agent.agentName,
      });
      logAutoDialEvent('lead-picked', {
        trigger,
        leadId: lead.id,
        phone: phone10,
        agentId: agent.agentId,
        agentName: agent.agentName,
        preferredLanguage: routing.preferredLanguage,
        sourceState: routing.sourceState,
        requestedAgentId: context.requestedAgentId || '',
      });
      if (phone10) {
        busyPhoneNumbers.add(phone10);
      }
      assigned += 1;
    }

    if (assigned > 0 || trigger !== 'background') {
      logAutoDialEvent('assignment-run', {
        trigger,
        requestedAgentId: context.requestedAgentId || '',
        checked,
        assigned,
        availableAgentCount: initialAvailableAgentCount,
        candidateLeadCount: leads.length,
        busyAgentCount: busyAgentIds.size,
        outboundAutoCooldownAgentCount: outboundAutoCooldownAgentIds.size,
        outboundAutoConnectGapSeconds,
      });
    }

    if (postReservationSyncs.length > 0) {
      setImmediate(() => {
        for (const reservation of postReservationSyncs) {
          Promise.allSettled([
            suppressAutoDialPhoneAfterReservation(reservation.leadId, {
              agentId: reservation.agentId,
              agentName: reservation.agentName,
            }),
            syncAutoDialLeadStatusToSources(reservation.leadId, 'assigned'),
          ]).then((results) => {
            const failed = results.filter((result) => result.status === 'rejected');
            if (failed.length > 0) {
              console.warn('[auto-dial] post-reservation sync failed', {
                leadId: reservation.leadId,
                errors: failed.map((result) => result.reason?.message || String(result.reason)),
              });
            }
          });
        }
      });
    }

    return { checked, assigned, skipped: false };
  } catch (error) {
    const errorCode = String(error?.code || '').trim();
    const shouldRetryDeadlock = ['ER_LOCK_DEADLOCK', 'ER_LOCK_WAIT_TIMEOUT'].includes(errorCode)
      && !String(trigger || '').includes('retry');
    logAutoDialEvent('assignment-error', {
      trigger,
      requestedAgentId: context.requestedAgentId || '',
      message: error?.message || String(error),
      code: errorCode,
      retryScheduled: shouldRetryDeadlock,
    });
    console.error('Auto dial assignment failed:', error);
    if (shouldRetryDeadlock) {
      setTimeout(() => {
        void assignPendingAutoDialLeads(`${trigger}-retry`, context);
      }, 2500);
    }
    return { checked: 0, assigned: 0, skipped: false, error: true, code: errorCode, retryScheduled: shouldRetryDeadlock };
  } finally {
    if (assignmentLockConnection) {
      try {
        await assignmentLockConnection.query("SELECT RELEASE_LOCK('attica_auto_dial_assignment')");
      } catch (releaseError) {
        console.warn('Failed to release auto dial assignment lock:', releaseError?.message || releaseError);
      } finally {
        assignmentLockConnection.release();
      }
    }
    autoDialAssignmentInProgress = false;
    autoDialAssignmentStartedAt = 0;
  }
}

function buildAutoDialImportRows(fileName, leads) {
  const dedupeKeys = new Set();
  const rows = [];

  for (const [index, lead] of leads.entries()) {
    const mobileNumber = normalizeAutoDialPhone(lead.mobileNumber);
    if (!mobileNumber) continue;

    const key = `${getBusinessDateString()}:${mobileNumber}`;
    if (dedupeKeys.has(key)) continue;
    dedupeKeys.add(key);

    const area = String(lead.area || '').trim();
    const rawState = String(lead.state || '').trim();
    const rawLanguage = String(lead.language || '').trim();
    const sourceState = cleanJustDialString(
      extractAutoDialSourceState({ state: rawState, area }),
      120
    );
    const preferredLanguage = cleanJustDialString(
      resolveAutoDialPreferredLanguage({
        state: rawState || sourceState,
        language: rawLanguage,
        area,
      }),
      30
    );

    rows.push({
      id: `ADL-${Date.now()}-${index}-${Math.random().toString(36).slice(2, 8)}`,
      customerName: String(lead.customerName || '').trim(),
      mobileNumber,
      area,
      sourceState,
      preferredLanguage,
      goldWeight: String(lead.goldWeight || '').trim(),
      type: String(lead.type || '').trim(),
      sourceFile: fileName,
    });
  }

  return {
    rows,
    invalidCount: Math.max(0, leads.length - rows.length),
  };
}

async function importAutoDialLeadRows(fileName, leads) {
  const { rows, invalidCount } = buildAutoDialImportRows(fileName, leads);
  if (rows.length === 0) {
    return { error: 'No valid leads found in upload', inserted: 0, invalid: invalidCount, duplicatesIgnored: 0 };
  }

  let inserted = 0;
  let duplicatesIgnored = 0;
  let blockedIgnored = 0;

  for (let start = 0; start < rows.length; start += AUTO_DIAL_IMPORT_BATCH_SIZE) {
    const chunk = rows.slice(start, start + AUTO_DIAL_IMPORT_BATCH_SIZE);
    const [existingRows, openRows, blockedRows] = await Promise.all([
      pool.query(
        `SELECT normalized_number
         FROM attica_auto_dial_leads
         WHERE DATE(created_at) = CURDATE()
           AND normalized_number IN (?)`,
        [chunk.map((lead) => lead.mobileNumber)]
      ),
      pool.query(
        `SELECT open_dedupe_number
         FROM attica_auto_dial_leads
         WHERE open_dedupe_number IN (?)`,
        [chunk.map((lead) => lead.mobileNumber)]
      ),
      pool.query(
        `SELECT phone
         FROM attica_blocked_numbers
         WHERE phone IN (?)`,
        [chunk.map((lead) => lead.mobileNumber)]
      ),
    ]);
    const existingNumbers = new Set([
      ...existingRows[0].map((row) => row.normalized_number),
      ...openRows[0].map((row) => row.open_dedupe_number),
    ]);
    const blockedNumbers = new Set(blockedRows[0].map((row) => normalizeAutoDialPhone(row.phone)).filter(Boolean));
    const insertableRows = chunk.filter((lead) => (
      !existingNumbers.has(lead.mobileNumber)
      && !blockedNumbers.has(lead.mobileNumber)
    ));

    const chunkBlockedIgnored = chunk.filter((lead) => blockedNumbers.has(lead.mobileNumber)).length;
    blockedIgnored += chunkBlockedIgnored;
    duplicatesIgnored += chunk.length - insertableRows.length - chunkBlockedIgnored;
    if (insertableRows.length === 0) continue;

    await pool.query(
      'INSERT INTO attica_auto_dial_leads (id,customer_name,mobile_number,normalized_number,open_dedupe_number,area,source_state,preferred_language,gold_weight,lead_type,source_file,status,shuffle_no) VALUES ?',
      [insertableRows.map((lead) => [
        lead.id,
        lead.customerName,
        lead.mobileNumber,
        lead.mobileNumber,
        getOpenAutoDialDedupeNumber(lead.mobileNumber, 'pending', 1),
        lead.area,
        lead.sourceState || null,
        lead.preferredLanguage || null,
        lead.goldWeight,
        lead.type,
        lead.sourceFile,
        'pending',
        generateAutoDialShuffleNo(),
      ])]
    );
    inserted += insertableRows.length;
  }

  if (inserted > 0) {
    void triggerAutoDialAssignment('event');
  }

  return {
    success: true,
    inserted,
    invalid: invalidCount,
    duplicatesIgnored,
    blockedIgnored,
  };
}

async function markMissedCallPending(callId, callerId = '') {
  const phone10 = normalizeAutoDialPhone(callerId);
  if (!phone10) {
    return { duplicate: false, canonicalCallId: callId };
  }

  let lockAcquired = false;
  const lockName = `attica_missed_phone_${phone10}_${getBusinessDateString()}`;
  try {
    const [[lockRow]] = await pool.query('SELECT GET_LOCK(?, 2) AS lock_acquired', [lockName]);
    lockAcquired = Number(lockRow?.lock_acquired || 0) === 1;

    const [[currentMissedRow]] = await pool.query(
      `SELECT agent_name
       FROM attica_calls
       WHERE id=?
       LIMIT 1`,
      [callId]
    );
    const currentMissedAgentName = String(currentMissedRow?.agent_name || '').trim().toLowerCase();
    let missedTypeSql = '';
    if (currentMissedAgentName === 'ivr abandoned') {
      missedTypeSql = "AND LOWER(TRIM(IFNULL(agent_name,'')))='ivr abandoned'";
    } else if (currentMissedAgentName === 'ivr no selection') {
      missedTypeSql = "AND LOWER(TRIM(IFNULL(agent_name,'')))='ivr no selection'";
    } else {
      missedTypeSql = "AND LOWER(TRIM(IFNULL(agent_name,''))) NOT IN ('ivr abandoned','ivr no selection')";
    }

    const [existingRows] = await pool.query(
      `SELECT id
       FROM attica_calls
       WHERE id<>?
         AND direction='incoming'
         AND status='missed'
         AND call_date=CURDATE()
         AND LOWER(TRIM(IFNULL(callback_status,''))) NOT IN ('completed','duplicate removed')
         AND RIGHT(REPLACE(REPLACE(REPLACE(COALESCE(NULLIF(normalized_customer_number,''),caller_id),'+',''),' ',''),'-',''),10)=?
         ${missedTypeSql}
       ORDER BY
         CASE
           WHEN LOWER(TRIM(IFNULL(callback_status,''))) IN ('pending','callback assigned','dialing','callback dialed') THEN 0
           ELSE 1
         END,
         created_at ASC,
         id ASC
       LIMIT 1`,
      [callId, phone10]
    );

    const canonicalCallId = cleanCanonicalCallId(existingRows[0]?.id || '', 120);
    if (canonicalCallId) {
      await pool.query(
        `UPDATE attica_calls
         SET callback_status='Duplicate Removed',
             follow_up_flag=0,
             notes=CASE
               WHEN IFNULL(notes,'') LIKE '%Duplicate missed call removed; canonical missed callback is %' THEN notes
               ELSE CONCAT_WS(' | ', NULLIF(notes,''), ?)
             END
         WHERE id=?`,
        [`Duplicate missed call removed; canonical missed callback is ${canonicalCallId}`, callId]
      );
      return { duplicate: true, canonicalCallId };
    }
  } finally {
    if (lockAcquired) {
      await pool.query('SELECT RELEASE_LOCK(?)', [lockName]).catch(() => null);
    }
  }

  await pool.query(
    "UPDATE attica_calls SET callback_status='Pending', follow_up_flag=1 WHERE id=?",
    [callId]
  );
  return { duplicate: false, canonicalCallId: callId };
}

async function autoScheduleMissedCallFollowUp(call) {
  if (normalizeCallDirection(call.direction) !== 'incoming' || normalizeCallStatus(call.status) !== 'missed') {
    return null;
  }

  if (isIvrNoSelectionMissedCall(call)) {
    return null;
  }

  if (isNoAgentMissedCall(call)) {
    return null;
  }

  if (String(call.callbackStatus || '').trim().toLowerCase() === 'completed') {
    return null;
  }

  if (String(call.callbackStatus || '').trim().toLowerCase() === 'duplicate removed') {
    return null;
  }

  if (await isPhoneBlocked(call.callerId)) {
    return null;
  }

  const missedPendingResult = await markMissedCallPending(call.id, call.callerId);
  if (missedPendingResult.duplicate) {
    return null;
  }

  const chosenAgent = await pickAutoFollowUpAgent({
    preferredLanguage: call.language,
    excludedAgentId: normalizeAgentId(call.agentId),
    includeAvailableAgents: true,
  });
  const chosenAgentId = chosenAgent?.agentId || '';
  const chosenAgentName = chosenAgent?.agentName || '';

  const phone = String(call.callerId || '').replace(/[^0-9]/g, '');
  const followUpId = `AUTO-${call.id}`;
  const followUpAt = new Date();
  const followUpExpiry = getFollowUpExpiryValues('Missed');
  const followUpCustomerName = getDisplayCustomerNameFromValues(
    call.displayCustomerName,
    call.customerName,
    call.callerName
  ) || phone || 'Unknown Customer';
  const notes = [
    `Auto-scheduled from missed call ${call.id}`,
    call.language ? `IVR language: ${call.language}` : '',
  ].filter(Boolean).join(' | ');

  await pool.query(
    `INSERT INTO attica_followups (id,customer_name,phone,branch,follow_up_at,status,agent_id,agent_name,notes,followup_created_at,followup_expires_at,followup_reason,is_active)
     VALUES (?,?,?,?,?,?,?,?,?,?,?,?,1)
     ON DUPLICATE KEY UPDATE
       customer_name=VALUES(customer_name),
       phone=VALUES(phone),
       branch=VALUES(branch),
       is_active=1,
       status=attica_followups.status,
       followup_created_at=COALESCE(attica_followups.followup_created_at, VALUES(followup_created_at)),
       followup_expires_at=COALESCE(attica_followups.followup_expires_at, VALUES(followup_expires_at)),
       followup_reason=COALESCE(NULLIF(attica_followups.followup_reason, ''), VALUES(followup_reason)),
       follow_up_at=CASE
         WHEN attica_followups.follow_up_at IS NULL THEN VALUES(follow_up_at)
         WHEN attica_followups.agent_id IS NULL OR attica_followups.agent_id='' THEN VALUES(follow_up_at)
         ELSE attica_followups.follow_up_at
       END,
       agent_id=IF(attica_followups.agent_id IS NULL OR attica_followups.agent_id='', VALUES(agent_id), attica_followups.agent_id),
       agent_name=IF(attica_followups.agent_name IS NULL OR attica_followups.agent_name='', VALUES(agent_name), attica_followups.agent_name),
       notes=IF(attica_followups.notes IS NULL OR attica_followups.notes='', VALUES(notes), attica_followups.notes)`,
    [
      followUpId,
      followUpCustomerName,
      phone,
      call.branch || '',
      followUpAt,
      'Pending',
      chosenAgentId,
      chosenAgentName,
      notes,
      followUpExpiry.createdAt,
      followUpExpiry.expiresAt,
      followUpExpiry.reason,
    ]
  );

  await collapseOpenAutoDialLeadsByPhone(pool, phone, {
    preferredLeadId: followUpId,
    cleanupNote: 'Closed because missed-call callback created the canonical queue lead for this customer',
  });

  await pool.query(
    `INSERT INTO attica_auto_dial_leads
      (id,customer_name,mobile_number,normalized_number,open_dedupe_number,area,source_state,preferred_language,gold_weight,lead_type,source_file,status,shuffle_no,assigned_agent_id,assigned_agent_name,scheduled_agent_id,scheduled_agent_name,assigned_at,dial_started_at,completed_at,call_id,last_error,scheduled_for,followup_created_at,followup_expires_at,followup_reason,is_active)
     VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,1)
     ON DUPLICATE KEY UPDATE
       customer_name=VALUES(customer_name),
       mobile_number=VALUES(mobile_number),
       normalized_number=VALUES(normalized_number),
       open_dedupe_number=VALUES(open_dedupe_number),
       area=VALUES(area),
       source_state=VALUES(source_state),
       preferred_language=VALUES(preferred_language),
       lead_type=VALUES(lead_type),
       source_file=VALUES(source_file),
       is_active=1,
       followup_created_at=COALESCE(attica_auto_dial_leads.followup_created_at, VALUES(followup_created_at)),
       followup_expires_at=COALESCE(attica_auto_dial_leads.followup_expires_at, VALUES(followup_expires_at)),
       followup_reason=COALESCE(NULLIF(attica_auto_dial_leads.followup_reason, ''), VALUES(followup_reason)),
       status=CASE
         WHEN attica_auto_dial_leads.status IN ('completed','dialing') THEN attica_auto_dial_leads.status
         ELSE 'pending'
       END,
       assigned_agent_id=CASE
         WHEN attica_auto_dial_leads.status IN ('assigned','dialing') THEN attica_auto_dial_leads.assigned_agent_id
         ELSE NULL
       END,
       assigned_agent_name=CASE
         WHEN attica_auto_dial_leads.status IN ('assigned','dialing') THEN attica_auto_dial_leads.assigned_agent_name
         ELSE NULL
       END,
       scheduled_agent_id=NULL,
       scheduled_agent_name=NULL,
       assigned_at=CASE
         WHEN attica_auto_dial_leads.status IN ('assigned','dialing') THEN attica_auto_dial_leads.assigned_at
         ELSE NULL
       END,
       dial_started_at=CASE
         WHEN attica_auto_dial_leads.status='dialing' THEN attica_auto_dial_leads.dial_started_at
         ELSE NULL
       END,
       completed_at=CASE
         WHEN attica_auto_dial_leads.status='completed' THEN attica_auto_dial_leads.completed_at
         ELSE NULL
       END,
       queue_exit_reason=NULL,
       retry_allowed=1,
       shuffle_no=COALESCE(attica_auto_dial_leads.shuffle_no, VALUES(shuffle_no)),
       call_id=VALUES(call_id),
       last_error='',
       scheduled_for=VALUES(scheduled_for)`,
    [
      followUpId,
      followUpCustomerName,
      phone,
      phone,
      getOpenAutoDialDedupeNumber(phone, 'pending', 1),
      call.place || call.branch || '',
      '',
      call.language || '',
      String(call.grams || ''),
      'Missed Call',
      'Missed Callback',
      'pending',
      generateAutoDialShuffleNo(),
      null,
      null,
      null,
      null,
      null,
      null,
      null,
      call.id || '',
      '',
      followUpAt,
      followUpExpiry.createdAt,
      followUpExpiry.expiresAt,
      followUpExpiry.reason,
    ]
  );

  return {
    followUpId,
    agentId: chosenAgentId,
    agentName: chosenAgentName,
    followUpAt: followUpAt.toISOString(),
  };
}

function isShortIncomingDisconnectedForMissedCallback(call) {
  const direction = normalizeCallDirection(call?.direction);
  const status = normalizeCallStatus(call?.status);
  if (direction !== 'incoming' || !['completed', 'answered', 'transferred'].includes(status)) {
    return false;
  }

  const phone = normalizeAutoDialPhone(call?.normalizedCustomerNumber || call?.callerId);
  if (!phone) {
    return false;
  }

  const talkDurationSeconds = Math.max(
    parseDurationSeconds(call?.duration),
    Number(call?.talkDurationSeconds || call?.talk_duration_seconds) || 0
  );
  if (talkDurationSeconds <= 0 || talkDurationSeconds > 5) {
    return false;
  }

  const dispositionText = [
    call?.callbackStatus,
    call?.callback_status,
    call?.formStatus,
    call?.form_status,
    call?.notes,
  ].filter(Boolean).join(' ').toLowerCase();

  return /\b(rnr|na)\b|ring no reply|no answer|not reachable|missed|discon|disconnect|disc|call dis/.test(dispositionText);
}

async function autoScheduleShortIncomingDisconnectedFollowUp(call) {
  if (!isShortIncomingDisconnectedForMissedCallback(call)) {
    return null;
  }

  const callId = cleanCanonicalCallId(call?.id, 120);
  const shortDisconnectNote = 'Auto-corrected to missed callback because incoming call disconnected within 5 seconds';
  const missedCall = {
    ...call,
    status: 'missed',
    callbackStatus: 'Pending',
    followUpFlag: true,
    notes: [call?.notes, shortDisconnectNote].filter(Boolean).join(' | '),
  };

  if (callId) {
    await pool.query(
      `UPDATE attica_calls
       SET status='missed',
           callback_status='Pending',
           follow_up_flag=1,
           notes=CONCAT_WS(' | ', NULLIF(notes,''), ?)
       WHERE id=?`,
      [shortDisconnectNote, callId]
    );
  }

  return autoScheduleMissedCallFollowUp(missedCall);
}

async function autoScheduleOutboundRnrFollowUp(call) {
  if (normalizeCallDirection(call.direction) !== 'outgoing') {
    return null;
  }

  const callbackStatus = normalizeFormStatusLabel(call.callbackStatus).toLowerCase();
  const talkDurationSeconds = Math.max(
    parseDurationSeconds(call.duration),
    Number(call.talkDurationSeconds || call.talk_duration_seconds) || 0
  );
  const retryableCallbackStatuses = new Set([
    'rnr',
    'na',
    'lb',
    'callback',
    'pending',
    'dis',
    'dec',
    'customer disconnected',
    'call disconnected',
    'disconnected',
    'disconnected - not connected',
  ]);
  const shouldAutoScheduleFollowUp = retryableCallbackStatuses.has(callbackStatus)
    || (!callbackStatus && normalizeCallStatus(call.status) === 'missed')
    || (talkDurationSeconds > 0 && talkDurationSeconds < 30);
  if (!shouldAutoScheduleFollowUp) {
    return null;
  }

  const agentId = normalizeAgentId(call.agentId);
  const agentName = cleanJustDialString(call.agentName, 100);
  const phone10 = normalizeAutoDialPhone(call.callerId);
  if (!agentId || !phone10) {
    return null;
  }

  if (await isPhoneBlocked(phone10)) {
    return null;
  }

  const queueBlock = await getAutoDialQueueBlockByPhone(pool, phone10);
  if (queueBlock.error) {
    if (queueBlock.queueExitReason) {
      await clearPhoneFromAutoFollowUpSources(phone10, queueBlock.queueExitReason, queueBlock.error);
    }
    return null;
  }

  if (call.id) {
    await pool.query(
      `UPDATE attica_calls
       SET callback_status=?,
           follow_up_flag=1
       WHERE id=?`,
      [callbackStatus ? callbackStatus.toUpperCase() : 'RNR', String(call.id)]
    );
  }

  const customerName = getDisplayCustomerNameFromValues(
    call.displayCustomerName,
    call.customerName,
    call.callerName
  ) || phone10 || 'Unknown Customer';
  const branch = cleanJustDialString(call.branch, 150);
  const followUpAt = new Date();
  const followUpReason = talkDurationSeconds > 0 && talkDurationSeconds < 30
    ? 'Call duration less than 30 seconds'
    : (callbackStatus || 'RNR').toUpperCase();
  const followUpExpiry = getFollowUpExpiryValues(followUpReason);
  const followUpNotes = [
    `Auto-created from ${(callbackStatus || 'rnr').toUpperCase()} outbound call ${call.id || ''}`.trim(),
    cleanJustDialString(call.purpose, 150) || 'Outbound',
    cleanJustDialString(call.notes, 1000),
  ].filter(Boolean).join(' | ');

  const upsertOutboundRnrAutoDialLead = async (followUpId, scheduledFor) => {
    await collapseOpenAutoDialLeadsByPhone(pool, phone10, {
      preferredLeadId: followUpId,
      cleanupNote: 'Closed because outbound RNR/disconnected follow-up created the canonical queue lead for this customer',
    });

    await pool.query(
      `INSERT INTO attica_auto_dial_leads
        (id,customer_name,mobile_number,normalized_number,open_dedupe_number,area,source_state,preferred_language,gold_weight,lead_type,source_file,status,shuffle_no,assigned_agent_id,assigned_agent_name,scheduled_agent_id,scheduled_agent_name,assigned_at,dial_started_at,completed_at,call_id,last_error,scheduled_for,followup_created_at,followup_expires_at,followup_reason,is_active)
       VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,1)
       ON DUPLICATE KEY UPDATE
         customer_name=VALUES(customer_name),
         mobile_number=VALUES(mobile_number),
         normalized_number=VALUES(normalized_number),
         open_dedupe_number=VALUES(open_dedupe_number),
         area=VALUES(area),
         preferred_language=VALUES(preferred_language),
         lead_type=VALUES(lead_type),
         source_file=VALUES(source_file),
         is_active=1,
         followup_created_at=COALESCE(attica_auto_dial_leads.followup_created_at, VALUES(followup_created_at)),
         followup_expires_at=COALESCE(attica_auto_dial_leads.followup_expires_at, VALUES(followup_expires_at)),
         followup_reason=COALESCE(NULLIF(attica_auto_dial_leads.followup_reason, ''), VALUES(followup_reason)),
         status=CASE
           WHEN attica_auto_dial_leads.status='dialing' THEN attica_auto_dial_leads.status
           ELSE 'pending'
         END,
         assigned_agent_id=CASE
           WHEN attica_auto_dial_leads.status='dialing' THEN attica_auto_dial_leads.assigned_agent_id
           ELSE NULL
         END,
         assigned_agent_name=CASE
           WHEN attica_auto_dial_leads.status='dialing' THEN attica_auto_dial_leads.assigned_agent_name
           ELSE NULL
         END,
         scheduled_agent_id=NULL,
         scheduled_agent_name=NULL,
         assigned_at=CASE
           WHEN attica_auto_dial_leads.status='dialing' THEN attica_auto_dial_leads.assigned_at
           ELSE NULL
         END,
         dial_started_at=CASE
           WHEN attica_auto_dial_leads.status='dialing' THEN attica_auto_dial_leads.dial_started_at
           ELSE NULL
         END,
         completed_at=NULL,
         queue_exit_reason=NULL,
         retry_allowed=1,
         shuffle_no=COALESCE(attica_auto_dial_leads.shuffle_no, VALUES(shuffle_no)),
         call_id=VALUES(call_id),
         last_error='',
         scheduled_for=VALUES(scheduled_for),
         updated_at=NOW()`,
      [
        followUpId,
        customerName,
        phone10,
        phone10,
        getOpenAutoDialDedupeNumber(phone10, 'pending', 1),
        branch || cleanJustDialString(call.place, 150) || '',
        '',
        cleanJustDialString(call.language, 30) || '',
        String(call.grams || ''),
        followUpReason,
        'Auto Follow-Up',
        'pending',
        generateAutoDialShuffleNo(),
        null,
        null,
        null,
        null,
        null,
        null,
        null,
        String(call.id || ''),
        '',
        scheduledFor,
        followUpExpiry.createdAt,
        followUpExpiry.expiresAt,
        followUpExpiry.reason,
      ]
    );
  };

  const [existingRows] = await pool.query(
    `SELECT id, notes, follow_up_at
     FROM attica_followups
     WHERE status IN ('Pending','Rescheduled')
       AND IFNULL(is_active, 1)=1
       AND (followup_expires_at IS NULL OR followup_expires_at >= ${MYSQL_QUEUE_NOW_SQL})
       AND RIGHT(REPLACE(REPLACE(REPLACE(IFNULL(phone,''),'+',''),' ',''),'-',''), 10)=?
     ORDER BY COALESCE(follow_up_at, created_at) DESC, created_at DESC
     LIMIT 1`,
    [phone10]
  );

  const existing = existingRows[0];
  if (existing?.id) {
    const existingFollowUpAt = getScheduledFollowUpDate(existing.follow_up_at);
    const scheduledFor = existingFollowUpAt && existingFollowUpAt.getTime() > followUpAt.getTime()
      ? existingFollowUpAt
      : followUpAt;
    const mergedNotes = [cleanJustDialString(existing.notes, 1000), followUpNotes].filter(Boolean).join(' | ');

    await pool.query(
      `UPDATE attica_followups
       SET customer_name=?,
           phone=?,
           branch=?,
           follow_up_at=?,
           status='Pending',
           agent_id=?,
           agent_name=?,
           notes=?,
           outcome=?,
           is_active=1,
           followup_created_at=COALESCE(followup_created_at, created_at, NOW()),
           followup_expires_at=COALESCE(followup_expires_at, DATE_ADD(COALESCE(followup_created_at, created_at, NOW()), INTERVAL ? DAY)),
           followup_reason=COALESCE(NULLIF(followup_reason, ''), ?),
           updated_at=NOW()
       WHERE id=?`,
      [customerName, phone10, branch, scheduledFor, agentId, agentName, mergedNotes, followUpReason, FOLLOW_UP_RETENTION_DAYS, followUpReason, existing.id]
    );
    await upsertOutboundRnrAutoDialLead(existing.id, scheduledFor);
    void triggerAutoDialAssignment('event');

    return {
      followUpId: existing.id,
      agentId,
      agentName,
      followUpAt: scheduledFor.toISOString(),
      reused: true,
    };
  }

  const followUpId = `RNR-${call.id || `${Date.now()}-${phone10}`}`;
  await pool.query(
    `INSERT INTO attica_followups (id,customer_name,phone,branch,follow_up_at,status,agent_id,agent_name,notes,outcome,followup_created_at,followup_expires_at,followup_reason,is_active,updated_at)
     VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,1,?)
     ON DUPLICATE KEY UPDATE
       customer_name=VALUES(customer_name),
       phone=VALUES(phone),
       branch=VALUES(branch),
       follow_up_at=VALUES(follow_up_at),
       status='Pending',
       is_active=1,
       agent_id=VALUES(agent_id),
       agent_name=VALUES(agent_name),
       notes=VALUES(notes),
       outcome=VALUES(outcome),
       followup_created_at=COALESCE(attica_followups.followup_created_at, VALUES(followup_created_at)),
       followup_expires_at=COALESCE(attica_followups.followup_expires_at, VALUES(followup_expires_at)),
       followup_reason=COALESCE(NULLIF(attica_followups.followup_reason, ''), VALUES(followup_reason)),
       updated_at=VALUES(updated_at)`,
    [
      followUpId,
      customerName,
      phone10,
      branch,
      followUpAt,
      'Pending',
      agentId,
      agentName,
      followUpNotes,
      followUpReason,
      followUpExpiry.createdAt,
      followUpExpiry.expiresAt,
      followUpExpiry.reason,
      new Date(),
    ]
  );
  await upsertOutboundRnrAutoDialLead(followUpId, followUpAt);
  void triggerAutoDialAssignment('event');

  return {
    followUpId,
    agentId,
    agentName,
    followUpAt: followUpAt.toISOString(),
    reused: false,
  };
}

async function closeStatusFollowUp(phone10, resolvedStatus = '') {
  if (!phone10) return null;

  const queueId = getStatusFollowUpQueueId(phone10);
  const followUpId = getStatusFollowUpId(phone10);
  const outcome = resolvedStatus ? `Resolved by status: ${resolvedStatus}` : 'Resolved from updated intake form status';

  await pool.query(
    `UPDATE attica_status_followup_queue
     SET is_active=0,
         form_status=IF(? = '', form_status, ?),
         updated_at=NOW()
     WHERE id=?`,
    [resolvedStatus, resolvedStatus, queueId]
  );

  await pool.query(
    `UPDATE attica_calls c
     JOIN attica_status_followup_queue s ON s.source_call_id=c.id
     SET c.follow_up_flag=0
     WHERE s.id=?`,
    [queueId]
  );

  await pool.query(
    `INSERT INTO attica_followups
      (id,customer_name,phone,branch,follow_up_at,status,agent_id,agent_name,notes,outcome,is_active,updated_at)
     SELECT s.follow_up_id,s.customer_name,s.phone,s.branch,NULL,'Called',s.agent_id,s.agent_name,s.notes,?,0,NOW()
     FROM attica_status_followup_queue s
     WHERE s.id=?
     ON DUPLICATE KEY UPDATE
       status='Called',
       is_active=0,
       outcome=VALUES(outcome),
       updated_at=VALUES(updated_at)`,
    [outcome, queueId]
  );

  await pool.query(
    `UPDATE attica_auto_dial_leads
     SET status='completed',
         assigned_agent_id=NULL,
         assigned_agent_name=NULL,
         assigned_at=NULL,
         dial_started_at=NULL,
         completed_at=NOW(),
         queue_exit_reason=NULL,
         open_dedupe_number=NULL,
         updated_at=NOW(),
         last_error=?
     WHERE id=?
       AND status IN ('pending','assigned','dialing')`,
    [outcome, queueId]
  );
  await syncAutoDialLeadStatusToSources(queueId, 'completed');

  return { queueId, followUpId, closed: true };
}

async function syncStatusFollowUpQueue(call) {
  const phone10 = normalizeAutoDialPhone(call.callerId);
  if (!phone10) return null;

  if (await isPhoneBlocked(phone10)) {
    return null;
  }

  const queueBlock = await getAutoDialQueueBlockByPhone(pool, phone10);
  if (queueBlock.error) {
    if (queueBlock.queueExitReason) {
      await clearPhoneFromAutoFollowUpSources(phone10, queueBlock.queueExitReason, queueBlock.error);
    }
    return null;
  }

  const formStatus = normalizeFormStatusLabel(call.formStatus);
  const followUpAt = getScheduledFollowUpDate(call.statusFollowUpAt);
  const shouldScheduleStatusFollowUp = shouldQueueFormStatus(formStatus) && Boolean(followUpAt);

  if (!shouldScheduleStatusFollowUp) {
    if (call.id) {
      await pool.query(
        `UPDATE attica_calls
         SET follow_up_flag=0
         WHERE id=?`,
        [String(call.id)]
      );
    }
    return closeStatusFollowUp(phone10, formStatus);
  }

  const queueId = getStatusFollowUpQueueId(phone10);
  const followUpId = getStatusFollowUpId(phone10);
  await collapseOpenAutoDialLeadsByPhone(pool, phone10, {
    preferredLeadId: queueId,
    cleanupNote: 'Closed because status follow-up created the canonical queue lead for this customer',
  });
  const customerName = getDisplayCustomerNameFromValues(
    call.displayCustomerName,
    call.customerName,
    call.callerName
  ) || phone10 || 'Unknown Customer';
  const branch = cleanJustDialString(call.branch, 150);
  const place = cleanJustDialString(call.place, 255);
  const purpose = cleanJustDialString(call.purpose, 150);
  const language = cleanJustDialString(call.language, 30);
  const agentId = normalizeAgentId(call.agentId);
  const agentName = cleanJustDialString(call.agentName, 100);
  const followUpExpiry = getFollowUpExpiryValues('Status Follow-Up');
  const notes = [
    `Intake status: ${formStatus}`,
    call.statusFollowUpAt ? `Planned follow-up call: ${followUpAt.toISOString()}` : '',
    call.notes ? cleanJustDialString(call.notes, 1000) : '',
  ].filter(Boolean).join(' | ');

  await pool.query(
    `INSERT INTO attica_auto_dial_leads
      (id,customer_name,mobile_number,normalized_number,open_dedupe_number,area,source_state,preferred_language,gold_weight,lead_type,source_file,status,shuffle_no,assigned_agent_id,assigned_agent_name,scheduled_agent_id,scheduled_agent_name,assigned_at,dial_started_at,completed_at,call_id,last_error,scheduled_for,followup_created_at,followup_expires_at,followup_reason,is_active)
     VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,1)
     ON DUPLICATE KEY UPDATE
       customer_name=VALUES(customer_name),
       mobile_number=VALUES(mobile_number),
       normalized_number=VALUES(normalized_number),
       open_dedupe_number=VALUES(open_dedupe_number),
       area=VALUES(area),
       source_state=VALUES(source_state),
       preferred_language=VALUES(preferred_language),
       gold_weight=VALUES(gold_weight),
       lead_type=VALUES(lead_type),
       source_file=VALUES(source_file),
       is_active=1,
       scheduled_agent_id=NULL,
       scheduled_agent_name=NULL,
       followup_created_at=COALESCE(attica_auto_dial_leads.followup_created_at, VALUES(followup_created_at)),
       followup_expires_at=COALESCE(attica_auto_dial_leads.followup_expires_at, VALUES(followup_expires_at)),
       followup_reason=COALESCE(NULLIF(attica_auto_dial_leads.followup_reason, ''), VALUES(followup_reason)),
       status='pending',
       assigned_agent_id=NULL,
       assigned_agent_name=NULL,
       assigned_at=NULL,
       dial_started_at=NULL,
       completed_at=NULL,
      queue_exit_reason=NULL,
      retry_allowed=1,
       shuffle_no=COALESCE(shuffle_no, VALUES(shuffle_no)),
       call_id=VALUES(call_id),
       last_error='',
       scheduled_for=VALUES(scheduled_for)`,
    [
      queueId,
      customerName,
      phone10,
      phone10,
      getOpenAutoDialDedupeNumber(phone10, 'pending', 1),
      place,
      '',
      language,
      String(call.grams || ''),
      formStatus,
      'Status Follow-Up',
      'pending',
      generateAutoDialShuffleNo(),
      null,
      null,
      null,
      null,
      null,
      null,
      null,
      String(call.id || ''),
      '',
      followUpAt,
      followUpExpiry.createdAt,
      followUpExpiry.expiresAt,
      followUpExpiry.reason,
    ]
  );

  await pool.query(
    `INSERT INTO attica_followups (id,customer_name,phone,branch,follow_up_at,status,agent_id,agent_name,notes,outcome,followup_created_at,followup_expires_at,followup_reason,is_active,updated_at)
     VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,1,?)
     ON DUPLICATE KEY UPDATE
       customer_name=VALUES(customer_name),
       phone=VALUES(phone),
       branch=VALUES(branch),
       follow_up_at=VALUES(follow_up_at),
       status='Pending',
       is_active=1,
       agent_id=VALUES(agent_id),
       agent_name=VALUES(agent_name),
       notes=VALUES(notes),
       outcome=VALUES(outcome),
       followup_created_at=COALESCE(attica_followups.followup_created_at, VALUES(followup_created_at)),
       followup_expires_at=COALESCE(attica_followups.followup_expires_at, VALUES(followup_expires_at)),
       followup_reason=COALESCE(NULLIF(attica_followups.followup_reason, ''), VALUES(followup_reason)),
       updated_at=VALUES(updated_at)`,
    [
      followUpId,
      customerName,
      phone10,
      branch,
      followUpAt,
      'Pending',
      agentId,
      agentName,
      notes,
      `Status follow-up: ${formStatus}`,
      followUpExpiry.createdAt,
      followUpExpiry.expiresAt,
      followUpExpiry.reason,
      followUpAt,
    ]
  );

  await pool.query(
    `INSERT INTO attica_status_followup_queue
      (id,source_call_id,customer_name,phone,branch,form_status,agent_id,agent_name,direction,language,place,purpose,auto_dial_lead_id,follow_up_id,notes,is_active,followup_created_at,followup_expires_at,followup_reason)
     VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
     ON DUPLICATE KEY UPDATE
       source_call_id=VALUES(source_call_id),
       customer_name=VALUES(customer_name),
       phone=VALUES(phone),
       branch=VALUES(branch),
       form_status=VALUES(form_status),
       agent_id=VALUES(agent_id),
       agent_name=VALUES(agent_name),
       direction=VALUES(direction),
       language=VALUES(language),
       place=VALUES(place),
       purpose=VALUES(purpose),
       auto_dial_lead_id=VALUES(auto_dial_lead_id),
       follow_up_id=VALUES(follow_up_id),
       notes=VALUES(notes),
       is_active=1,
       followup_created_at=COALESCE(attica_status_followup_queue.followup_created_at, VALUES(followup_created_at)),
       followup_expires_at=COALESCE(attica_status_followup_queue.followup_expires_at, VALUES(followup_expires_at)),
       followup_reason=COALESCE(NULLIF(attica_status_followup_queue.followup_reason, ''), VALUES(followup_reason)),
       updated_at=NOW()`,
    [
      queueId,
      String(call.id || ''),
      customerName,
      phone10,
      branch,
      formStatus,
      agentId,
      agentName,
      cleanJustDialString(call.direction, 20),
      language,
      place,
      purpose,
      queueId,
      followUpId,
      notes,
      1,
      followUpExpiry.createdAt,
      followUpExpiry.expiresAt,
      followUpExpiry.reason,
    ]
  );

  if (call.id) {
    await pool.query(
      `UPDATE attica_calls
       SET callback_status='Pending',
           follow_up_flag=1
       WHERE id=?`,
      [String(call.id)]
    );
  }

  void triggerAutoDialAssignment('event');

  return {
    queueId,
    followUpId,
    phone: phone10,
    formStatus,
    active: true,
  };
}

let missedCallRetryInProgress = false;
let lastMissedCallRetryStartedAt = Date.now();
let missedCallbackStatusSyncPromise = null;
let lastMissedCallbackStatusSyncAt = 0;

async function cleanupTerminalActiveAutoDialLeads() {
  const [result] = await pool.query(
    `UPDATE attica_auto_dial_leads
     SET is_active=0,
         assigned_agent_id=NULL,
         assigned_agent_name=NULL,
         scheduled_agent_id=NULL,
         scheduled_agent_name=NULL,
         assigned_at=NULL,
         dial_started_at=NULL,
         open_dedupe_number=NULL,
         updated_at=updated_at
     WHERE status IN ('completed','failed')
       AND is_active=1`
  );
  return Number(result?.affectedRows || 0);
}

async function syncMissedCallbackStatusToSourceCalls() {
  const connection = await pool.getConnection();
  let lockAcquired = false;

  try {
    const [[lockRow]] = await connection.query("SELECT GET_LOCK('attica_missed_callback_status_sync', 0) AS lock_acquired");
    lockAcquired = Number(lockRow?.lock_acquired || 0) === 1;
    if (!lockAcquired) {
      return 0;
    }

    const updateBySourceSql = (sourceSql) => (
      `UPDATE attica_calls c
       JOIN (
         ${sourceSql}
       ) src ON src.id = c.id
       SET c.callback_status=CASE LOWER(src.auto_status)
             WHEN 'completed' THEN 'Callback Dialed'
             WHEN 'failed' THEN 'Failed'
             WHEN 'dialing' THEN 'Dialing'
             WHEN 'assigned' THEN 'Callback Assigned'
             WHEN 'pending' THEN 'Callback Assigned'
             ELSE c.callback_status
           END,
           c.follow_up_flag=0,
           c.notes=CASE
             WHEN IFNULL(c.notes,'') LIKE '%Auto-synced missed callback status from auto-dial lead%' THEN c.notes
             ELSE CONCAT_WS(' | ', NULLIF(c.notes,''), 'Auto-synced missed callback status from auto-dial lead')
           END
       WHERE c.direction='incoming'
         AND c.status='missed'`
    );

    const [exactLeadResult] = await connection.query(updateBySourceSql(
      `SELECT c2.id, a.status AS auto_status
       FROM attica_calls c2
       JOIN attica_auto_dial_leads a ON a.id = CONCAT('AUTO-', c2.id)
       WHERE c2.direction='incoming'
         AND c2.status='missed'
         AND ${OPEN_MISSED_CALLBACK_STATUS_SQL.replaceAll('callback_status', 'c2.callback_status')}
         AND a.status IN ('completed','failed','dialing','assigned','pending')
         AND c2.created_at >= DATE_SUB(NOW(), INTERVAL 10 DAY)
       ORDER BY c2.created_at ASC
       LIMIT 2000`
    ));

    const [callIdResult] = await connection.query(updateBySourceSql(
      `SELECT c2.id, a.status AS auto_status
       FROM attica_calls c2
       JOIN attica_auto_dial_leads a FORCE INDEX (idx_attica_auto_dial_call_id) ON a.call_id = c2.id
       WHERE c2.direction='incoming'
         AND c2.status='missed'
         AND ${OPEN_MISSED_CALLBACK_STATUS_SQL.replaceAll('callback_status', 'c2.callback_status')}
         AND a.status IN ('completed','failed','dialing','assigned','pending')
         AND c2.created_at >= DATE_SUB(NOW(), INTERVAL 10 DAY)
       ORDER BY c2.created_at ASC
       LIMIT 2000`
    ));

    return (
      Number(exactLeadResult?.affectedRows || 0)
      + Number(callIdResult?.affectedRows || 0)
    );
  } finally {
    if (lockAcquired) {
      await connection.query("SELECT RELEASE_LOCK('attica_missed_callback_status_sync')");
    }
    connection.release();
  }
}

async function maybeSyncMissedCallbackStatusToSourceCalls({ force = false } = {}) {
  if (!ENABLE_MISSED_CALLBACK_SOURCE_SYNC) {
    return { synced: 0, skipped: true, reason: 'disabled' };
  }
  const now = Date.now();
  if (!force && now - lastMissedCallbackStatusSyncAt < 60000) {
    return { synced: 0, skipped: true, reason: 'throttled' };
  }
  if (missedCallbackStatusSyncPromise) {
    return missedCallbackStatusSyncPromise;
  }

  lastMissedCallbackStatusSyncAt = now;
  missedCallbackStatusSyncPromise = syncMissedCallbackStatusToSourceCalls()
    .then((synced) => ({ synced, skipped: false }))
    .catch((error) => {
      console.error('Missed callback status sync failed:', error);
      return { synced: 0, skipped: false, error: error?.message || String(error) };
    })
    .finally(() => {
      missedCallbackStatusSyncPromise = null;
    });

  return missedCallbackStatusSyncPromise;
}

async function getRetryableMissedCalls(limit = 250) {
  const [rows] = await pool.query(
    `SELECT c.*
     FROM attica_calls c
     LEFT JOIN attica_followups f ON f.id = CONCAT('AUTO-', c.id)
     LEFT JOIN attica_auto_dial_leads a ON a.id = CONCAT('AUTO-', c.id)
     WHERE c.direction='incoming'
       AND c.status='missed'
       AND c.created_at >= DATE_SUB(NOW(), INTERVAL 7 DAY)
       AND c.id NOT LIKE 'IN-IVR-NOSEL-%'
       AND LOWER(TRIM(IFNULL(c.agent_name,''))) <> 'ivr no selection'
       AND ${REAL_AGENT_CALL_SQL.replaceAll('agent_id', 'c.agent_id').replaceAll('agent_name', 'c.agent_name')}
       AND ${OPEN_MISSED_CALLBACK_STATUS_SQL.replaceAll('callback_status', 'c.callback_status')}
       AND (
         a.id IS NULL
         OR (
           a.status IN ('pending','failed')
           AND IFNULL(a.retry_allowed, 1) <> 0
         )
         OR
         f.id IS NULL
         OR (
           f.status='Pending'
           AND (f.agent_id IS NULL OR f.agent_id='')
         )
       )
       AND NOT EXISTS (
         SELECT 1
         FROM attica_blocked_numbers b
         WHERE b.phone = RIGHT(REPLACE(REPLACE(REPLACE(IFNULL(c.caller_id,''),'+',''),' ',''),'-',''), 10)
       )
       AND NOT EXISTS (
         SELECT 1
         FROM attica_calls answered
         WHERE c.agent_id='IVR'
           AND answered.direction='incoming'
           AND answered.agent_id<>'IVR'
           AND answered.answered_at IS NOT NULL
           AND RIGHT(REPLACE(REPLACE(REPLACE(COALESCE(NULLIF(answered.normalized_customer_number,''),answered.caller_id),'+',''),' ',''),'-',''),10)
             = RIGHT(REPLACE(REPLACE(REPLACE(COALESCE(NULLIF(c.normalized_customer_number,''),c.caller_id),'+',''),' ',''),'-',''),10)
           AND answered.created_at BETWEEN c.created_at AND DATE_ADD(c.created_at, INTERVAL 5 MINUTE)
       )
     ORDER BY c.created_at ASC
     LIMIT ?`,
    [limit]
  );

  return serializeCallRowsWithDisplayNames(rows);
}

async function retryPendingMissedCallAssignments() {
  if (missedCallRetryInProgress) return { checked: 0, assigned: 0, skipped: true };
  const now = Date.now();
  if (now - lastMissedCallRetryStartedAt < MISSED_CALL_RETRY_INTERVAL_MS) {
    return { checked: 0, assigned: 0, skipped: true, throttled: true };
  }
  lastMissedCallRetryStartedAt = now;
  missedCallRetryInProgress = true;
  let dbLockAcquired = false;

  try {
    const autoDialControl = await readAutoDialControlState();
    if (autoDialControl.enabled === false) {
      return { checked: 0, assigned: 0, skipped: true, reason: 'auto-dial-disabled' };
    }

    const [[lockRow]] = await pool.query("SELECT GET_LOCK('attica_missed_call_retry', 0) AS lock_acquired");
    dbLockAcquired = Number(lockRow?.lock_acquired || 0) === 1;
    if (!dbLockAcquired) {
      return { checked: 0, assigned: 0, skipped: true };
    }

    const missedCalls = await getRetryableMissedCalls();
    let assigned = 0;

    for (const call of missedCalls) {
      const result = await autoScheduleMissedCallFollowUp(call);
      if (result) assigned += 1;
    }

    return { checked: missedCalls.length, assigned, skipped: false };
  } catch (error) {
    console.error('Missed-call fallback assignment failed:', error);
    return { checked: 0, assigned: 0, skipped: false };
  } finally {
    if (dbLockAcquired) {
      await pool.query("SELECT RELEASE_LOCK('attica_missed_call_retry')");
    }
    missedCallRetryInProgress = false;
  }
}

async function cleanupStaleAgentCallState(limit = 100) {
  const [agentRows] = await pool.query(
    `SELECT id, extension, active_call_id, active_call_direction,
            active_call_started_at, call_state_updated_at
     FROM attica_agents
     WHERE active_call_id IS NOT NULL
     ORDER BY COALESCE(call_state_updated_at, active_call_started_at, last_call_ended_at) ASC
     LIMIT ?`,
    [Math.max(1, limit)]
  );
  const callLookupKeys = Array.from(new Set(
    agentRows
      .flatMap((row) => {
        const activeCallId = String(row.active_call_id || '').trim();
        const canonicalCallId = activeCallId.includes('|') ? activeCallId.split('|')[0] : activeCallId;
        return [activeCallId, canonicalCallId].filter(Boolean);
      })
  ));
  const [callRows] = callLookupKeys.length > 0
    ? await pool.query(
      `SELECT id, call_uuid, status, ended_at, answered_at,
              talk_duration_seconds, duration, has_recording, recording_name
       FROM attica_calls
       WHERE id IN (?) OR call_uuid IN (?)`,
      [callLookupKeys, callLookupKeys]
    )
    : [[]];
  const callsByLookupKey = new Map();
  for (const callRow of callRows) {
    const id = String(callRow.id || '').trim();
    const uuid = String(callRow.call_uuid || '').trim();
    const canonicalId = id.includes('|') ? id.split('|')[0] : id;
    const canonicalUuid = uuid.includes('|') ? uuid.split('|')[0] : uuid;
    for (const key of [id, uuid, canonicalId, canonicalUuid]) {
      if (key && !callsByLookupKey.has(key)) {
        callsByLookupKey.set(key, callRow);
      }
    }
  }
  const rows = agentRows.map((agentRow) => {
    const activeCallId = String(agentRow.active_call_id || '').trim();
    const canonicalCallId = activeCallId.includes('|') ? activeCallId.split('|')[0] : activeCallId;
    const callRow = callsByLookupKey.get(activeCallId) || callsByLookupKey.get(canonicalCallId) || {};
    return {
      ...agentRow,
      call_status: callRow.status,
      call_ended_at: callRow.ended_at,
      call_answered_at: callRow.answered_at,
      call_talk_duration_seconds: callRow.talk_duration_seconds,
      call_duration: callRow.duration,
      call_has_recording: callRow.has_recording,
      call_recording_name: callRow.recording_name,
    };
  });
  const pjsipOutput = readSipEndpointOutput();
  let liveChannels = [];
  try {
    liveChannels = readAsteriskConciseChannels();
  } catch (error) {
    console.warn('Unable to read live Asterisk channels for stale cleanup:', error?.message || error);
  }
  const staleRows = rows.filter((row) => {
    if (hasLiveAgentExtensionChannel(row.extension, liveChannels)) {
      return false;
    }

    const endpointState = getAgentLiveEndpointState(row.extension, pjsipOutput);
    const existingCall = row.call_status || row.call_ended_at || row.call_answered_at || row.call_talk_duration_seconds || row.call_duration || row.call_has_recording || row.call_recording_name
      ? {
        status: row.call_status,
        ended_at: row.call_ended_at,
        answered_at: row.call_answered_at,
        talk_duration_seconds: row.call_talk_duration_seconds,
        duration: row.call_duration,
        has_recording: row.call_has_recording,
        recording_name: row.call_recording_name,
      }
      : null;
    return shouldTreatAgentCallSlotAsStale({
      existingCall,
      callStateUpdatedAt: row.call_state_updated_at,
      endpointState,
    });
  });

  let cleared = 0;
  for (const row of staleRows) {
    try {
      const result = await runTransactionWithRetries(async (connection) => resetAgentCallState(connection, {
        agentId: row.id,
        nextStatus: 'active',
        finalCallStatus: normalizeCallDirection(row.active_call_direction) === 'incoming' ? 'missed' : 'failed',
        reason: 'Closed by stale-call watchdog',
      }), {
        attempts: 3,
        baseDelayMs: 75,
        label: `cleanup stale agent call state for ${row.id}`,
      });
      if (result.success) {
        cleared += 1;
      }
    } catch (error) {
      console.error('Stale agent call cleanup failed:', error);
    }
  }

  return cleared;
}

