app.get('/api/blocked-numbers', async (req, res) => {
  try {
    const requestedPhone = normalizeAutoDialPhone(req.query.phone);
    if (requestedPhone) {
      const [[row]] = await pool.query(
        'SELECT * FROM attica_blocked_numbers WHERE phone=? LIMIT 1',
        [requestedPhone]
      );
      res.json(row ? serializeBlockedNumberRow(row) : { phone: requestedPhone, blocked: false });
      return;
    }

    const [rows] = await pool.query(
      'SELECT * FROM attica_blocked_numbers ORDER BY updated_at DESC, created_at DESC'
    );
    res.json(rows.map(serializeBlockedNumberRow));
  } catch (e) {
    res.status(500).json({ error: e.message, blocked: false });
  }
});

app.put('/api/blocked-numbers/:phone', async (req, res) => {
  try {
    const phone = normalizeAutoDialPhone(req.params.phone);
    if (!phone) {
      res.status(400).json({ error: 'Invalid phone number' });
      return;
    }

    const blocked = Boolean(req.body?.blocked);
    const blockedById = cleanJustDialString(req.body?.blockedById, 40);
    const blockedByName = cleanJustDialString(req.body?.blockedByName, 100);
    const sourceCallId = cleanJustDialString(req.body?.sourceCallId, 80);
    const note = cleanJustDialString(req.body?.note, 500);

    if (blocked) {
      await pool.query(
        `INSERT INTO attica_blocked_numbers
          (phone, blocked_by_id, blocked_by_name, source_call_id, note, created_at, updated_at)
         VALUES (?, ?, ?, ?, ?, NOW(), NOW())
         ON DUPLICATE KEY UPDATE
           blocked_by_id=VALUES(blocked_by_id),
           blocked_by_name=VALUES(blocked_by_name),
           source_call_id=VALUES(source_call_id),
           note=VALUES(note),
           updated_at=NOW()`,
        [phone, blockedById || null, blockedByName || null, sourceCallId || null, note || null]
      );
      syncAsteriskBlockedNumber(phone, true);
      await disableBlockedPhoneWork(phone, blockedByName);
      void triggerAutoDialAssignment('event');
      const [[row]] = await pool.query(
        'SELECT * FROM attica_blocked_numbers WHERE phone=? LIMIT 1',
        [phone]
      );
      res.json(row ? { success: true, ...serializeBlockedNumberRow(row) } : { success: true, phone, blocked: true });
      return;
    }

    await pool.query('DELETE FROM attica_blocked_numbers WHERE phone=?', [phone]);
    syncAsteriskBlockedNumber(phone, false);
    res.json({ phone, blocked: false, success: true });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

app.get('/api/calls', async (req, res) => {
  try {
    const requestedStatus = normalizeCallStatus(req.query.status);
    const requestedLimit = parseInt(req.query.limit, 10);
    const limit = Number.isFinite(requestedLimit)
      ? Math.min(MAX_CALLS_FETCH_LIMIT, Math.max(1, requestedLimit))
      : DEFAULT_LIST_API_LIMIT;

    if (requestedStatus === 'live') {
      const liveStatuses = Array.from(LIVE_CALL_STATUSES);
      const [rows] = await pool.query(
        `SELECT ${CALL_LIST_SELECT_SQL}
         FROM attica_calls FORCE INDEX (idx_attica_calls_status_created)
         WHERE status IN (?)
           AND ${CALL_ROW_VISIBILITY_SQL}
           AND ${NON_DUPLICATE_REMOVED_CALL_SQL}
           AND ${NON_REPORT_ARTIFACT_CALL_SQL}
         ORDER BY COALESCE(ring_started_at, answered_at, created_at) DESC, created_at DESC
         LIMIT ?`,
        [liveStatuses, Math.min(200, limit)]
      );
      res.json(await serializeCallRowsBasic(rows, { dedupe: false }));
      return;
    }

    const [rows] = await pool.query(
      `SELECT ${CALL_LIST_SELECT_SQL}
       FROM attica_calls
       WHERE ${CALL_ROW_VISIBILITY_SQL}
         AND ${NON_DUPLICATE_REMOVED_CALL_SQL}
         AND ${NON_REPORT_ARTIFACT_CALL_SQL}
       ORDER BY ${CALL_ROW_SORT_SQL}
       LIMIT ?`,
      [limit]
    );
    res.json(await serializeCallRowsBasic(rows));
  } catch (e) { res.status(500).json({ error: e.message }); }
});

app.get('/api/calls/duplicate-audit', async (req, res) => {
  try {
    const requestedLimit = parseInt(req.query.limit, 10);
    const limit = Number.isFinite(requestedLimit)
      ? Math.min(500, Math.max(10, requestedLimit))
      : 100;
    const date = normalizeQueryDate(req.query.date) || getBusinessDateString();

    const [rows] = await pool.query(
      `SELECT
         call_date AS callDate,
         RIGHT(REPLACE(REPLACE(REPLACE(IFNULL(caller_id,''),'+',''),' ',''),'-',''), 10) AS phone,
         MAX(customer_name) AS customerName,
         MAX(agent_id) AS agentId,
         MAX(agent_name) AS agentName,
         MAX(direction) AS direction,
         MAX(callback_status) AS callbackStatus,
         MAX(form_status) AS formStatus,
         MAX(branch) AS branch,
         MAX(purpose) AS purpose,
         COUNT(*) AS duplicateCount,
         MIN(created_at) AS firstCreatedAt,
         MAX(created_at) AS lastCreatedAt,
         GROUP_CONCAT(id ORDER BY created_at DESC SEPARATOR ',') AS callIds
       FROM attica_calls
       WHERE call_date=?
         AND COALESCE(status, '') NOT IN ('active', 'on-hold')
         AND RIGHT(REPLACE(REPLACE(REPLACE(IFNULL(caller_id,''),'+',''),' ',''),'-',''), 10) <> ''
       GROUP BY
         call_date,
         RIGHT(REPLACE(REPLACE(REPLACE(IFNULL(caller_id,''),'+',''),' ',''),'-',''), 10),
         COALESCE(agent_id, ''),
         COALESCE(direction, ''),
         COALESCE(TRIM(customer_name), ''),
         COALESCE(TRIM(callback_status), ''),
         COALESCE(TRIM(form_status), ''),
         COALESCE(TRIM(branch), ''),
         COALESCE(TRIM(purpose), ''),
         COALESCE(TRIM(mob2), ''),
         COALESCE(TRIM(district), ''),
         COALESCE(TRIM(notes), '')
       HAVING COUNT(*) > 1
       ORDER BY duplicateCount DESC, lastCreatedAt DESC
       LIMIT ?`,
      [date, limit]
    );

    res.json({
      date,
      total: rows.length,
      results: rows.map((row) => ({
        callDate: row.callDate || '',
        phone: row.phone || '',
        customerName: row.customerName || '',
        agentId: row.agentId || '',
        agentName: row.agentName || '',
        direction: row.direction || '',
        callbackStatus: row.callbackStatus || '',
        formStatus: row.formStatus || '',
        branch: row.branch || '',
        purpose: row.purpose || '',
        duplicateCount: Number(row.duplicateCount || 0),
        firstCreatedAt: row.firstCreatedAt ? new Date(row.firstCreatedAt).toISOString() : '',
        lastCreatedAt: row.lastCreatedAt ? new Date(row.lastCreatedAt).toISOString() : '',
        callIds: String(row.callIds || '').split(',').filter(Boolean),
      })),
    });
  } catch (e) { res.status(500).json({ error: e.message, results: [] }); }
});

app.post('/api/calls', async (req, res) => {
  try {
    const c = req.body || {};
    const submittedAgentId = cleanJustDialString(c.agentId || c.agent_id, 20);
    if (normalizeCallDirection(c.direction) === 'incoming' && submittedAgentId) {
      const [[submittedOwner]] = await pool.query(
        'SELECT role FROM attica_agents WHERE id=? LIMIT 1',
        [submittedAgentId],
      );
      if (submittedOwner && String(submittedOwner.role || '').trim().toLowerCase() !== 'agent') {
        console.warn('[calls] Ignored incoming SIP artifact submitted for a non-agent account', {
          callId: cleanCanonicalCallId(c.id, 50),
          agentId: submittedAgentId,
          role: submittedOwner.role,
        });
        res.json({
          success: true,
          ignored: true,
          reason: 'Incoming SIP artifacts are not stored for non-agent accounts',
        });
        return;
      }
    }
    const isDraftSave = Boolean(c.draftSave);
    const shouldSkipCallSlotSync = Boolean(c.skipCallSlotSync || c.clientSlotManaged);
    let saveStage = 'prepare';
    const requestedCallId = cleanCanonicalCallId(c.id, 50);
    let normalizedCallId = requestedCallId;
    let existingDuration = '';
    let existingStatus = '';
    let existingAnsweredAt = '';
    let existingEndedAt = '';
    let existingTalkDurationSeconds = 0;
    let existingHasRecording = false;
    let existingRecordingName = '';
    let normalizedIntakeToken = cleanCanonicalIntakeToken(c.intakeToken);
    const intakeTokenCallId = getCallIdFromGeneratedIntakeToken(normalizedIntakeToken);
    if (requestedCallId && intakeTokenCallId !== requestedCallId) {
      normalizedIntakeToken = buildGeneratedIntakeTokenForCallId(requestedCallId);
    }
    if (normalizedIntakeToken) {
      const existingByIntakeToken = await findExistingCallByIntakeToken(normalizedIntakeToken);
      if (existingByIntakeToken?.id) {
        normalizedCallId = existingByIntakeToken.id;
        existingStatus = existingByIntakeToken.status || '';
        existingDuration = existingByIntakeToken.duration;
        existingAnsweredAt = existingByIntakeToken.answeredAt || '';
        existingEndedAt = existingByIntakeToken.endedAt || '';
        existingTalkDurationSeconds = Math.max(0, Number(existingByIntakeToken.talkDurationSeconds) || 0);
        existingHasRecording = Boolean(existingByIntakeToken.hasRecording);
        existingRecordingName = cleanJustDialString(existingByIntakeToken.recordingName, 255);
      }
    }
    if (normalizedCallId) {
      const [existingRows] = await pool.query(
        'SELECT status, duration, answered_at, ended_at, talk_duration_seconds, has_recording, recording_name FROM attica_calls WHERE id=? LIMIT 1',
        [normalizedCallId],
      );
      existingStatus = String(existingRows?.[0]?.status || '').trim();
      existingDuration = String(existingRows?.[0]?.duration || '').trim();
      existingAnsweredAt = toDatabaseDateTime(existingRows?.[0]?.answered_at);
      existingEndedAt = toDatabaseDateTime(existingRows?.[0]?.ended_at);
      existingTalkDurationSeconds = Math.max(0, Number(existingRows?.[0]?.talk_duration_seconds) || 0);
      existingHasRecording = Boolean(existingRows?.[0]?.has_recording);
      existingRecordingName = cleanJustDialString(existingRows?.[0]?.recording_name, 255);
    }
    // A verified dialog identity must not be merged with a different recent call.
    if (!existingDuration && !c.pbxSipCallId) {
      const duplicateCallId = await findRecentDuplicateCallId({ ...c, id: normalizedCallId });
      if (duplicateCallId) {
        normalizedCallId = duplicateCallId;
        const [duplicateRows] = await pool.query(
          'SELECT status, duration, answered_at, ended_at, talk_duration_seconds, has_recording, recording_name FROM attica_calls WHERE id=? LIMIT 1',
          [normalizedCallId],
        );
        existingStatus = String(duplicateRows?.[0]?.status || '').trim();
        existingDuration = String(duplicateRows?.[0]?.duration || '').trim();
        existingAnsweredAt = toDatabaseDateTime(duplicateRows?.[0]?.answered_at);
        existingEndedAt = toDatabaseDateTime(duplicateRows?.[0]?.ended_at);
        existingTalkDurationSeconds = Math.max(0, Number(duplicateRows?.[0]?.talk_duration_seconds) || 0);
        existingHasRecording = Boolean(duplicateRows?.[0]?.has_recording);
        existingRecordingName = cleanJustDialString(duplicateRows?.[0]?.recording_name, 255);
      }
    }
    const incomingStatus = cleanJustDialString(c.status, 20);
    const incomingAnsweredAt = toDatabaseDateTime(c.answeredAt);
    const incomingEndedAt = toDatabaseDateTime(c.endedAt);
    const incomingDuration = cleanJustDialString(c.duration, 10);
    const incomingTalkDurationSeconds = Math.max(0, Number(c.talkDurationSeconds) || 0);
    const incomingHasCustomerConnection = hasCustomerInteractionSignal({
      status: incomingStatus,
      answeredAt: incomingAnsweredAt,
      talkDurationSeconds: incomingTalkDurationSeconds,
      duration: incomingDuration,
      hasRecording: c.hasRecording,
      recordingName: c.recordingName,
    });
    const existingHasCustomerConnection = hasCustomerInteractionSignal({
      status: existingStatus,
      answeredAt: existingAnsweredAt,
      talkDurationSeconds: existingTalkDurationSeconds,
      duration: existingDuration,
      hasRecording: existingHasRecording,
      recordingName: existingRecordingName,
    });
    const incomingTimestampDurationSeconds = getDateTimeDurationSeconds(
      incomingAnsweredAt,
      incomingEndedAt,
    );
    const existingTimestampDurationSeconds = getDateTimeDurationSeconds(
      existingAnsweredAt,
      existingEndedAt,
    );
    const persistedTalkDurationSeconds = Math.max(
      incomingHasCustomerConnection
        ? (incomingTimestampDurationSeconds > 0
          ? incomingTimestampDurationSeconds
          : Math.max(incomingTalkDurationSeconds, parseDurationSeconds(incomingDuration)))
        : 0,
      existingHasCustomerConnection
        ? (existingTimestampDurationSeconds > 0
          ? existingTimestampDurationSeconds
          : Math.max(existingTalkDurationSeconds, parseDurationSeconds(existingDuration)))
        : 0,
    );
    const persistedDuration = normalizeDurationValue(
      formatDurationSeconds(persistedTalkDurationSeconds),
    );
    const shouldLookupProfile = Boolean(c.callerId) && (
      !isMeaningfulCustomerName(c.customerName) ||
      !isMeaningfulCustomerName(c.callerName) ||
      !cleanJustDialString(c.place, 255) ||
      !cleanJustDialString(c.mob2, 50) ||
      !cleanJustDialString(c.district, 100) ||
      !normalizeAgeFieldValue(c.age) ||
      !normalizeGenderFieldValue(c.gender)
    );
    const profile = shouldLookupProfile ? await buildCustomerProfile(c.callerId) : null;
    const persistedProfileCustomerName = isMeaningfulCustomerName(profile?.customerName) ? profile.customerName : '';
    const persistedCustomerName = getDisplayCustomerNameFromValues(c.customerName, c.callerName, persistedProfileCustomerName);
    const persistedCallerName = getDisplayCustomerNameFromValues(c.callerName, c.customerName, persistedProfileCustomerName);
    const persistedCall = {
      ...c,
      id: normalizedCallId,
      callUuid: cleanCanonicalCallId(c.callUuid || normalizedCallId || normalizedIntakeToken, 120) || normalizedCallId,
      intakeToken: normalizedIntakeToken,
      callerId: cleanJustDialString(c.callerId, 50),
      normalizedCustomerNumber: normalizeAutoDialPhone(c.callerId),
      customerName: cleanJustDialString(persistedCustomerName || persistedProfileCustomerName, 100),
      callerName: cleanJustDialString(persistedCallerName || persistedProfileCustomerName, 100),
      mob2: cleanJustDialString(c.mob2, 50) || cleanJustDialString(profile?.mob2, 50),
      age: normalizeAgeFieldValue(c.age) || normalizeAgeFieldValue(profile?.age),
      gender: normalizeGenderFieldValue(c.gender) || normalizeGenderFieldValue(profile?.gender),
      district: cleanJustDialString(c.district, 100) || cleanJustDialString(profile?.district, 100),
      businessType: cleanJustDialString(c.businessType, 100),
      metalType: cleanJustDialString(c.metalType, 100),
      grams: cleanJustDialString(c.grams, 50),
      releaseGrossAmount: cleanJustDialString(c.releaseGrossAmount, 50),
      releasingAmount: cleanJustDialString(c.releasingAmount, 50),
      pledgePlace: cleanJustDialString(c.pledgePlace || c.pledge_place, 150),
      otherPledgePlace: cleanJustDialString(c.otherPledgePlace || c.other_pledge_place, 150),
      differenceAmount: cleanJustDialString(c.differenceAmount || c.difference_amount, 50),
      bankName: cleanJustDialString(c.bankName, 150),
      onlinePrice: cleanJustDialString(c.onlinePrice, 50),
      pricePerGram: cleanJustDialString(c.pricePerGram, 50),
      advertisement: cleanJustDialString(c.advertisement, 100),
      lead: cleanJustDialString(c.lead, 100),
      formStatus: cleanJustDialString(c.formStatus, 100),
      statusFollowUpAt: toDatabaseDateTime(c.statusFollowUpAt),
      ringStartedAt: toDatabaseDateTime(c.ringStartedAt),
      answeredAt: toDatabaseDateTime(c.answeredAt),
      endedAt: toDatabaseDateTime(c.endedAt),
      talkDurationSeconds: persistedTalkDurationSeconds,
      agentId: cleanJustDialString(c.agentId, 20),
      agentName: cleanJustDialString(c.agentName, 100),
      direction: cleanJustDialString(c.direction, 20),
      status: incomingStatus,
      duration: persistedDuration,
      time: cleanJustDialString(c.time, 10),
      date: cleanJustDialString(c.date, 10),
      language: cleanJustDialString(c.language, 30),
      hasRecording: Boolean(c.hasRecording || existingHasRecording),
      recordingName: cleanJustDialString(c.recordingName, 255) || existingRecordingName,
      branch: cleanJustDialString(c.branch, 100),
      place: cleanJustDialString(c.place, 100) || cleanJustDialString(profile?.location, 100),
      purpose: cleanJustDialString(c.purpose, 100),
      callbackStatus: cleanJustDialString(c.callbackStatus, 100),
      quickNote: cleanJustDialString(c.quickNote, 500),
      notes: cleanJustDialString(c.notes, 5000),
    };
    const persistedCallHasCustomerConnection = hasCustomerConnection(persistedCall);
    const persistedCallHasCustomerInteraction = hasCustomerInteractionSignal(persistedCall);
    const derivedTalkDurationSeconds = persistedCallHasCustomerInteraction
      ? getDateTimeDurationSeconds(
          persistedCall.answeredAt || persistedCall.ringStartedAt || persistedCall.createdAt,
          persistedCall.endedAt
        )
      : 0;
    persistedCall.talkDurationSeconds = persistedCallHasCustomerInteraction
      ? (derivedTalkDurationSeconds > 0
        ? derivedTalkDurationSeconds
        : persistedCall.talkDurationSeconds)
      : 0;
    persistedCall.duration = normalizeDurationValue(
      formatDurationSeconds(persistedCall.talkDurationSeconds),
    );
    const persistedDirection = normalizeCallDirection(persistedCall.direction);
    const persistedStatus = normalizeCallStatus(persistedCall.status);
    const persistedCallbackStatus = String(persistedCall.callbackStatus || '').trim().toLowerCase();
    const persistedHasAgentSelectedCallbackStatus = hasAgentSelectedCallbackStatus(persistedCall.callbackStatus);
    const hasConnectedTalk = persistedCallHasCustomerInteraction;
    const connectedMarkedAsFailedOrMissed = (
      ['incoming', 'outgoing'].includes(persistedDirection)
      && ['failed', 'missed'].includes(persistedStatus)
      && hasConnectedTalk
    );
    const completedWithoutConnection = (
      persistedDirection === 'outgoing'
      && ['completed', 'answered'].includes(persistedStatus)
      && !persistedCall.answeredAt
    );
    const incomingCompletedWithoutConnection = (
      persistedDirection === 'incoming'
      && ['completed', 'answered'].includes(persistedStatus)
      && !persistedCallHasCustomerInteraction
    );
    const noConnectionWithConversationDisposition = (
      persistedDirection === 'outgoing'
      && ['failed', 'missed'].includes(persistedStatus)
      && !hasConnectedTalk
      && persistedCallbackStatus
      && !persistedHasAgentSelectedCallbackStatus
      && !['disconnected - not connected', 'rnr', 'ring no reply', 'ringing no response'].includes(persistedCallbackStatus)
    );
    if (connectedMarkedAsFailedOrMissed) {
      persistedCall.status = 'completed';
      persistedCall.notes = [persistedCall.notes, 'Auto-corrected to completed because customer interaction was recorded']
        .filter(Boolean)
        .join(' | ');
    }
    if (
      persistedDirection === 'outgoing'
      && ['disconnected - not connected', 'rnr', 'ring no reply', 'ringing no response'].includes(persistedCallbackStatus)
      && hasConnectedTalk
    ) {
      persistedCall.callbackStatus = hasAgentSelectedCallbackStatus(persistedCall.formStatus)
        ? persistedCall.formStatus
        : (persistedStatus === 'transferred'
        ? 'Call Transfer'
        : 'Customer Disconnected');
      persistedCall.notes = [persistedCall.notes, 'Auto-corrected disposition because customer interaction was recorded']
        .filter(Boolean)
        .join(' | ');
    }
    if (noConnectionWithConversationDisposition) {
      persistedCall.callbackStatus = 'Disconnected - Not Connected';
      persistedCall.notes = [persistedCall.notes, 'Auto-corrected disposition because no customer connection was recorded']
        .filter(Boolean)
        .join(' | ');
    }
    if (completedWithoutConnection) {
      persistedCall.status = 'failed';
      if (!persistedHasAgentSelectedCallbackStatus) {
        persistedCall.callbackStatus = 'Disconnected - Not Connected';
      }
      persistedCall.answeredAt = '';
      persistedCall.talkDurationSeconds = 0;
      persistedCall.duration = '00:00';
      persistedCall.notes = [persistedCall.notes, 'Auto-corrected to failed because outgoing calls without customer connection are not missed calls']
        .filter(Boolean)
        .join(' | ');
    }
    if (incomingCompletedWithoutConnection) {
      persistedCall.status = 'missed';
      if (!persistedHasAgentSelectedCallbackStatus) {
        persistedCall.callbackStatus = 'Caller Disconnected';
      }
      persistedCall.answeredAt = '';
      persistedCall.talkDurationSeconds = 0;
      persistedCall.duration = '00:00';
      persistedCall.notes = [persistedCall.notes, 'Auto-corrected to missed because incoming call had no answer or talk time']
        .filter(Boolean)
        .join(' | ');
    }
    if (persistedDirection === 'outgoing' && persistedStatus === 'missed') {
      persistedCall.status = 'failed';
      persistedCall.notes = [persistedCall.notes, 'Auto-corrected from missed to failed because missed is inbound-only']
        .filter(Boolean)
        .join(' | ');
    }
    const finalDirection = normalizeCallDirection(persistedCall.direction);
    const finalStatus = normalizeCallStatus(persistedCall.status);
    const finalCallbackStatus = String(persistedCall.callbackStatus || '').trim().toLowerCase();
    const finalHasAgentSelectedCallbackStatus = hasAgentSelectedCallbackStatus(persistedCall.callbackStatus);
    const finalHasCustomerInteraction = hasCustomerInteractionSignal(persistedCall);
    if (finalDirection === 'outgoing') {
      if (finalHasCustomerInteraction) {
        if (['failed', 'missed'].includes(finalStatus)) {
          persistedCall.status = 'completed';
          persistedCall.notes = [persistedCall.notes, 'Auto-corrected to completed because talk time exists']
            .filter(Boolean)
            .join(' | ');
        }
        if (['disconnected - not connected', 'rnr', 'ring no reply', 'ringing no response'].includes(finalCallbackStatus)) {
          persistedCall.callbackStatus = hasAgentSelectedCallbackStatus(persistedCall.formStatus)
            ? persistedCall.formStatus
            : 'Customer Disconnected';
          persistedCall.notes = [persistedCall.notes, 'Auto-corrected disposition because talk time exists']
            .filter(Boolean)
            .join(' | ');
        }
      } else {
        if (['completed', 'answered'].includes(finalStatus)) {
          persistedCall.status = 'failed';
          if (!finalHasAgentSelectedCallbackStatus) {
            persistedCall.callbackStatus = 'Disconnected - Not Connected';
          }
          persistedCall.answeredAt = '';
          persistedCall.talkDurationSeconds = 0;
          persistedCall.duration = '00:00';
          persistedCall.notes = [persistedCall.notes, 'Auto-corrected to failed because no talk time exists']
            .filter(Boolean)
            .join(' | ');
        } else if (finalStatus === 'missed') {
          persistedCall.status = 'failed';
          persistedCall.notes = [persistedCall.notes, 'Auto-corrected from missed to failed because missed is inbound-only']
            .filter(Boolean)
            .join(' | ');
        }
      }
    }
    if (finalDirection === 'incoming' && finalHasCustomerInteraction && ['failed', 'missed'].includes(finalStatus)) {
      persistedCall.status = 'completed';
      persistedCall.notes = [persistedCall.notes, 'Auto-corrected incoming call to completed because customer interaction was recorded']
        .filter(Boolean)
        .join(' | ');
    }
    if (
      finalDirection === 'incoming'
      && finalHasCustomerInteraction
      && ['rnr', 'ring no reply', 'ringing no response'].includes(finalCallbackStatus)
    ) {
      persistedCall.callbackStatus = hasAgentSelectedCallbackStatus(persistedCall.formStatus)
        ? persistedCall.formStatus
        : 'Customer Disconnected';
      persistedCall.notes = [persistedCall.notes, 'Auto-corrected incoming disposition because talk time exists']
        .filter(Boolean)
        .join(' | ');
    }
    if (!isDraftSave && isNoAgentMissedCall(persistedCall)) {
      res.json({
        success: true,
        skipped: true,
        reason: 'no-agent-missed-call',
      });
      return;
    }
    if (
      normalizeCallDirection(persistedCall.direction) === 'incoming'
      && persistedCall.callerId
      && (!persistedCall.language || !persistedCall.businessType || !persistedCall.purpose)
    ) {
      const ivrMetadata = await lookupCallIvr(
        persistedCall.normalizedCustomerNumber || persistedCall.callerId
      ).catch(() => null);
      if (ivrMetadata) {
        persistedCall.language = persistedCall.language || cleanJustDialString(ivrMetadata.language, 30);
        persistedCall.businessType = persistedCall.businessType || cleanJustDialString(ivrMetadata.businessType, 100);
        persistedCall.purpose = persistedCall.purpose || cleanJustDialString(ivrMetadata.purpose, 100);
      }
    }
    let clearedAgentWrapUp = false;
    let releasedAgentCallSlot = false;
    let intakeWorkflow = null;
    const shouldClearAgentWrapUp = !isDraftSave
      && persistedCall.agentId
      && hasAgentSelectedCallbackStatus(persistedCall.callbackStatus);
    await withCallSaveLock(persistedCall, (lockConnection) => runTransactionWithRetries(async (connection) => {
      if (!shouldSkipCallSlotSync && persistedCall.agentId && isLiveCallStatus(persistedCall.status)) {
        saveStage = 'call-slot-claim';
        const claimResult = await claimAgentCallSlot(connection, {
          agentId: persistedCall.agentId,
          callId: persistedCall.callUuid || persistedCall.id,
          direction: persistedCall.direction,
        });
        if (!claimResult.success) {
          const error = new Error(claimResult.error || 'Another live call is already active for this agent');
          error.statusCode = claimResult.statusCode || 409;
          error.skipTransactionRetry = true;
          error.errorStage = saveStage;
          error.errorCode = 'CALL_SLOT_CLAIM_FAILED';
          throw error;
        }
      }

      if (await hasNearbyAnsweredIncomingFork(connection, persistedCall)) {
        persistedCall.callbackStatus = 'Duplicate Removed';
        persistedCall.followUpFlag = false;
        const answeredForkNote = 'Suppressed queue fork miss because this customer was answered by another agent';
        if (!String(persistedCall.notes || '').includes(answeredForkNote)) {
          persistedCall.notes = [persistedCall.notes, answeredForkNote]
            .filter(Boolean)
            .join(' | ');
        }
      }
      if (await hasNearbyLongerIncomingFork(connection, persistedCall)) {
        persistedCall.status = 'missed';
        persistedCall.callbackStatus = 'Duplicate Removed';
        persistedCall.followUpFlag = false;
        persistedCall.answeredAt = '';
        persistedCall.endedAt = persistedCall.endedAt || toDatabaseDateTime(new Date());
        persistedCall.talkDurationSeconds = 0;
        persistedCall.duration = '00:00:00';
        const longerForkNote = 'Suppressed short ring-all fork because this customer was answered longer by another agent';
        if (!String(persistedCall.notes || '').includes(longerForkNote)) {
          persistedCall.notes = [persistedCall.notes, longerForkNote]
            .filter(Boolean)
            .join(' | ');
        }
      }

      saveStage = 'calls-upsert';
      const persistedCustomerUid = await getOrCreateCustomerUidForPhone(
        connection,
        persistedCall.normalizedCustomerNumber || persistedCall.callerId,
        persistedCall.createdAt || persistedCall.ringStartedAt || persistedCall.answeredAt || persistedCall.endedAt || new Date()
      );
      await connection.query(
        `INSERT INTO attica_calls (id,call_uuid,intake_token,normalized_customer_number,customer_uid,caller_id,caller_name,customer_name,mob2,age,gender,district,business_type,metal_type,grams,release_gross_amount,releasing_amount,pledge_place,other_pledge_place,difference_amount,bank_name,online_price,price_per_gram,advertisement,lead,form_status,status_follow_up_at,ring_started_at,answered_at,ended_at,talk_duration_seconds,agent_id,agent_name,direction,status,duration,call_time,call_date,language,has_recording,branch,place,purpose,callback_status,follow_up_flag,quick_note,notes,sms_sent)
         VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
         ON DUPLICATE KEY UPDATE
           status=CASE
             WHEN VALUES(status) IS NULL OR TRIM(VALUES(status))='' THEN attica_calls.status
             WHEN COALESCE(VALUES(direction), attica_calls.direction)='outgoing'
               AND COALESCE(VALUES(status), '') IN ('completed','answered')
               AND VALUES(answered_at) IS NULL
               AND COALESCE(VALUES(talk_duration_seconds), 0)=0
               THEN 'failed'
             WHEN COALESCE(attica_calls.status, '') IN ('answered','completed','transferred','missed','failed')
               AND COALESCE(VALUES(status), '') IN ('active','on-hold')
               THEN attica_calls.status
             ELSE VALUES(status)
           END,
           duration=CASE
             WHEN COALESCE(VALUES(answered_at), attica_calls.answered_at) IS NOT NULL
               AND COALESCE(VALUES(ended_at), attica_calls.ended_at) IS NOT NULL
               THEN TIME_FORMAT(SEC_TO_TIME(GREATEST(0, TIMESTAMPDIFF(
                 SECOND,
                 COALESCE(VALUES(answered_at), attica_calls.answered_at),
                 COALESCE(VALUES(ended_at), attica_calls.ended_at)
               ))), '%H:%i:%s')
             WHEN COALESCE(attica_calls.duration, '') NOT IN ('', '00:00', '0', '00')
               AND COALESCE(VALUES(duration), '') IN ('', '00:00', '0', '00')
               THEN attica_calls.duration
             WHEN COALESCE(attica_calls.status, '') IN ('answered','completed','transferred','missed','failed')
               AND COALESCE(VALUES(status), '') IN ('active','on-hold')
               THEN attica_calls.duration
             ELSE COALESCE(VALUES(duration), attica_calls.duration)
           END,
           call_uuid=CASE
             WHEN COALESCE(attica_calls.call_uuid, '') <> '' THEN attica_calls.call_uuid
             ELSE VALUES(call_uuid)
           END,
           normalized_customer_number=CASE
             WHEN COALESCE(VALUES(normalized_customer_number), '') = '' THEN attica_calls.normalized_customer_number
             ELSE VALUES(normalized_customer_number)
           END,
           customer_uid=CASE
             WHEN COALESCE(VALUES(customer_uid), '') = '' THEN attica_calls.customer_uid
             ELSE VALUES(customer_uid)
           END,
           ring_started_at=COALESCE(VALUES(ring_started_at), attica_calls.ring_started_at),
           answered_at=COALESCE(VALUES(answered_at), attica_calls.answered_at),
           ended_at=COALESCE(VALUES(ended_at), attica_calls.ended_at),
           talk_duration_seconds=CASE
             WHEN COALESCE(VALUES(answered_at), attica_calls.answered_at) IS NOT NULL
               AND COALESCE(VALUES(ended_at), attica_calls.ended_at) IS NOT NULL
               THEN GREATEST(0, TIMESTAMPDIFF(
                 SECOND,
                 COALESCE(VALUES(answered_at), attica_calls.answered_at),
                 COALESCE(VALUES(ended_at), attica_calls.ended_at)
               ))
             ELSE GREATEST(
               COALESCE(attica_calls.talk_duration_seconds, 0),
               COALESCE(VALUES(talk_duration_seconds), 0)
             )
           END,
           caller_name=COALESCE(VALUES(caller_name), attica_calls.caller_name),
           customer_name=COALESCE(VALUES(customer_name), attica_calls.customer_name),
           mob2=COALESCE(VALUES(mob2), attica_calls.mob2),
           age=COALESCE(VALUES(age), attica_calls.age),
           gender=COALESCE(VALUES(gender), attica_calls.gender),
           district=COALESCE(VALUES(district), attica_calls.district),
           business_type=COALESCE(VALUES(business_type), attica_calls.business_type),
           metal_type=COALESCE(VALUES(metal_type), attica_calls.metal_type),
           grams=COALESCE(VALUES(grams), attica_calls.grams),
           release_gross_amount=VALUES(release_gross_amount),
           releasing_amount=COALESCE(VALUES(releasing_amount), attica_calls.releasing_amount),
           pledge_place=COALESCE(NULLIF(VALUES(pledge_place), ''), attica_calls.pledge_place),
           other_pledge_place=COALESCE(NULLIF(VALUES(other_pledge_place), ''), attica_calls.other_pledge_place),
           difference_amount=COALESCE(NULLIF(VALUES(difference_amount), ''), attica_calls.difference_amount),
           bank_name=COALESCE(VALUES(bank_name), attica_calls.bank_name),
           online_price=COALESCE(VALUES(online_price), attica_calls.online_price),
           price_per_gram=COALESCE(VALUES(price_per_gram), attica_calls.price_per_gram),
           advertisement=COALESCE(VALUES(advertisement), attica_calls.advertisement),
           lead=COALESCE(VALUES(lead), attica_calls.lead),
           form_status=COALESCE(VALUES(form_status), attica_calls.form_status),
           status_follow_up_at=COALESCE(VALUES(status_follow_up_at), attica_calls.status_follow_up_at),
           callback_status=CASE
             WHEN COALESCE(TRIM(VALUES(callback_status)), '') = '' THEN attica_calls.callback_status
             WHEN LOWER(TRIM(VALUES(callback_status))) IN ('scheduled','none','completed','customer disconnected','caller disconnected','disconnected - not connected')
               AND COALESCE(TRIM(VALUES(form_status)), '') <> ''
               AND LOWER(TRIM(VALUES(form_status))) NOT IN ('scheduled','none','completed','customer disconnected','caller disconnected','disconnected - not connected')
               THEN VALUES(form_status)
             WHEN LOWER(TRIM(VALUES(callback_status))) IN ('scheduled','none','completed','customer disconnected','caller disconnected','disconnected - not connected')
               AND COALESCE(TRIM(attica_calls.callback_status), '') <> ''
               AND LOWER(TRIM(attica_calls.callback_status)) NOT IN ('scheduled','none','completed','customer disconnected','caller disconnected','disconnected - not connected')
               THEN attica_calls.callback_status
             ELSE VALUES(callback_status)
           END,
           follow_up_flag=COALESCE(VALUES(follow_up_flag), attica_calls.follow_up_flag),
           quick_note=COALESCE(NULLIF(VALUES(quick_note), ''), attica_calls.quick_note),
           notes=COALESCE(VALUES(notes), attica_calls.notes),
           sms_sent=COALESCE(VALUES(sms_sent), attica_calls.sms_sent),
           branch=COALESCE(VALUES(branch), attica_calls.branch),
           place=COALESCE(VALUES(place), attica_calls.place),
           purpose=COALESCE(VALUES(purpose), attica_calls.purpose),
           language=COALESCE(VALUES(language), attica_calls.language),
           intake_token=CASE
             WHEN COALESCE(attica_calls.intake_token, '') <> '' THEN attica_calls.intake_token
             ELSE VALUES(intake_token)
           END`,
        [
          persistedCall.id,
          persistedCall.callUuid || persistedCall.id,
          persistedCall.intakeToken || null,
          persistedCall.normalizedCustomerNumber || null,
          persistedCustomerUid || null,
          persistedCall.callerId,
          persistedCall.callerName,
          persistedCall.customerName,
          persistedCall.mob2 || '',
          persistedCall.age || '',
          persistedCall.gender || '',
          persistedCall.district || '',
          persistedCall.businessType || '',
          persistedCall.metalType || '',
          persistedCall.grams || '',
          persistedCall.releaseGrossAmount || '',
          persistedCall.releasingAmount || '',
          persistedCall.pledgePlace || '',
          persistedCall.otherPledgePlace || '',
          persistedCall.differenceAmount || '',
          persistedCall.bankName || '',
          persistedCall.onlinePrice || '',
          persistedCall.pricePerGram || '',
          persistedCall.advertisement || '',
          persistedCall.lead || '',
          persistedCall.formStatus || '',
          persistedCall.statusFollowUpAt,
          persistedCall.ringStartedAt,
          persistedCall.answeredAt,
          persistedCall.endedAt,
          persistedCall.talkDurationSeconds,
          persistedCall.agentId,
          persistedCall.agentName,
          persistedCall.direction,
          persistedCall.status,
          persistedCall.duration,
          persistedCall.time,
          persistedCall.date,
          persistedCall.language,
          persistedCall.hasRecording ? 1 : 0,
          persistedCall.branch || '',
          persistedCall.place || '',
          persistedCall.purpose || '',
          persistedCall.callbackStatus || '',
          persistedCall.followUpFlag ? 1 : 0,
          persistedCall.quickNote || '',
          persistedCall.notes || '',
          persistedCall.smsSent ? 1 : 0,
        ]
      );

      saveStage = 'call-duration-normalize';
      await connection.query(
        `UPDATE attica_calls
         SET ended_at=CASE
               WHEN LOWER(COALESCE(status,'')) IN ('completed','failed','missed','transferred')
                 AND ended_at IS NULL
               THEN COALESCE(
                 CASE
                   WHEN answered_at IS NOT NULL AND COALESCE(talk_duration_seconds,0) > 0
                   THEN DATE_ADD(answered_at, INTERVAL talk_duration_seconds SECOND)
                   ELSE NULL
                 END,
                 NOW()
               )
               ELSE ended_at
             END,
             duration=CASE
               WHEN COALESCE(talk_duration_seconds,0) > 0
               THEN TIME_FORMAT(SEC_TO_TIME(talk_duration_seconds), '%H:%i:%s')
               WHEN COALESCE(duration, '') IN ('', '0', '00', '00:00')
               THEN '00:00:00'
               ELSE duration
             END
         WHERE id=?`,
        [persistedCall.id]
      );

      saveStage = 'customer-profile-upsert';
      await upsertCustomerRecord(connection, {
        ...persistedCall,
        customerUid: persistedCustomerUid,
      });

      saveStage = 'intake-form-upsert';
      await upsertIntakeFormRecord(connection, persistedCall);
      if (c.pbxSipCallId) await intakeWorkflows.enroll(connection, persistedCall, c.pbxSipCallId);
      const [[currentWorkflow]] = await connection.query('SELECT * FROM attica_intake_workflows WHERE call_id=?', [persistedCall.id]);
      intakeWorkflow = currentWorkflow || null;
      if (currentWorkflow && (Number(currentWorkflow.draft_revision) > 0 || currentWorkflow.finalized_at)) {
        await intakeWorkflows.writeIntake(connection, currentWorkflow, Boolean(currentWorkflow.finalized_at));
      }

      if (normalizeCallDirection(persistedCall.direction) === 'incoming' && hasCustomerConnection(persistedCall)) {
        await closeNearbyIncomingForkMisses(connection, persistedCall);
        await closeNearbyShortIncomingForks(connection, persistedCall);
      }

      if (!shouldSkipCallSlotSync && persistedCall.agentId && isTerminalCallStatus(persistedCall.status)) {
        saveStage = 'call-slot-release';
        await releaseAgentCallSlot(connection, {
          agentId: persistedCall.agentId,
          callId: persistedCall.callUuid || persistedCall.id,
          nextStatus: c.nextAgentStatus || '',
        }).catch(() => null);
        releasedAgentCallSlot = true;
      }
      return true;
    }, {
      attempts: 3,
      baseDelayMs: 75,
      label: `save call ${persistedCall.id || normalizedIntakeToken || 'unknown'}`,
      connection: lockConnection,
    }));
    if (intakeWorkflow && !intakeWorkflow.finalized_at) {
      invalidateLiveAgentSnapshotCache();
      void syncAsteriskQueuePauseStates([intakeWorkflow.agent_id]).catch((error) => {
        console.warn('[intake-deadline] queue hold refresh failed:', error.message);
      });
    }
    void runCallSavePostCommitTasks({
      persistedCall,
      isDraftSave: isDraftSave || Boolean(intakeWorkflow && !intakeWorkflow.finalized_at),
      hasFormStatusField: Object.prototype.hasOwnProperty.call(c, 'formStatus'),
      shouldClearAgentWrapUp: shouldClearAgentWrapUp && !Boolean(intakeWorkflow && !intakeWorkflow.finalized_at),
      clearedAgentWrapUp,
      releasedAgentCallSlot,
    }).catch((error) => {
      console.error('Call save post-commit tasks failed:', error?.message || error);
    });
    res.json({
      success: true,
      draftSave: isDraftSave,
      autoFollowUp: null,
      outboundRnrFollowUp: null,
      statusFollowUpQueue: null,
      postCommitQueued: true,
    });
  } catch (e) {
    const statusCode = Number(e?.statusCode) || (isRetryableMysqlTransactionError(e) ? 503 : 500);
    const errorStage = cleanJustDialString(e?.errorStage || '', 60) || 'call-save';
    const errorCode = cleanJustDialString(e?.code || e?.errorCode || '', 80);

    if (errorCode === 'CALL_SAVE_LOCK_TIMEOUT') {
      try {
        const existingCall = await findPersistedCallForSaveRequest(req.body || {}, 6);
        if (existingCall?.id) {
          res.json({
            success: true,
            duplicateSave: true,
            lockTimeoutRecovered: true,
            call: serializeCallRow(existingCall),
          });
          return;
        }
      } catch (fallbackError) {
        console.warn('Call save lock-timeout fallback lookup failed:', fallbackError?.message || fallbackError);
      }
    }

    console.error('Call save failed:', {
      statusCode,
      stage: errorStage,
      code: errorCode,
      message: e?.message || e,
      callId: cleanCanonicalCallId(req.body?.id, 50),
      intakeToken: cleanCanonicalIntakeToken(req.body?.intakeToken),
      agentId: cleanJustDialString(req.body?.agentId, 20),
      direction: cleanJustDialString(req.body?.direction, 20),
      draftSave: Boolean(req.body?.draftSave),
    });

    res.status(statusCode).json({
      success: false,
      error: e?.message || 'Unable to save the call',
      stage: errorStage,
      code: errorCode || undefined,
      status: statusCode,
    });
  }
});

// ==================== FOLLOW-UPS ====================
app.get('/api/followups', async (req, res) => {
  try {
    await expireOldFollowUps();
    const requestedLimit = parseInt(req.query.limit, 10);
    const limit = Number.isFinite(requestedLimit)
      ? Math.min(MAX_DASHBOARD_FETCH_LIMIT, Math.max(1, requestedLimit))
      : DEFAULT_LIST_API_LIMIT;
    const [rows] = await pool.query(
      `SELECT *
       FROM attica_followups
       WHERE IFNULL(is_active,1)=1
         AND status IN ('Pending','Rescheduled')
         AND ${FOLLOWUP_NOT_DUPLICATE_REMOVED_SQL}
         AND (followup_expires_at IS NULL OR followup_expires_at >= ${MYSQL_QUEUE_NOW_SQL})
       ORDER BY created_at DESC
       LIMIT ?`,
      [limit]
    );
    res.json(rows.map((r) => {
      const sourceMeta = deriveFollowUpSourceMetadata(r);
      return {
        id: r.id,
        customerName: r.customer_name,
        phone: r.phone,
        branch: r.branch,
        followUpAt: r.follow_up_at ? r.follow_up_at.toISOString() : '',
        status: r.status,
        agentId: r.agent_id,
        agentName: r.agent_name,
        notes: r.notes,
        outcome: r.outcome || '',
        updatedAt: r.updated_at ? r.updated_at.toISOString() : (r.created_at ? r.created_at.toISOString() : ''),
        sourceCallId: sourceMeta.sourceCallId,
        sourceStatus: sourceMeta.sourceStatus,
      };
    }));
  } catch (e) { res.status(500).json({ error: e.message }); }
});

app.post('/api/followups/load-rnr-disconnected', async (req, res) => {
  try {
    const remoteAddress = String(req.socket?.remoteAddress || '').replace(/^::ffff:/, '');
    if (!['127.0.0.1', '::1', 'localhost'].includes(remoteAddress)) {
      return res.status(403).json({ success: false, error: 'Local maintenance endpoint only' });
    }

    const requestedDays = parsePositiveInteger(req.query.days ?? req.body?.days, 7);
    const lookbackDays = Math.max(1, Math.min(30, requestedDays));
    const result = await runWithDbLockRetry(
      `loadRnrDisconnectedCallsToFollowUpQueue:manual:${lookbackDays}`,
      () => loadRnrDisconnectedCallsToFollowUpQueue({ force: true, lookbackDays,
        rnrOnly:req.body?.reason === 'rnr',
        rnrDisconnectedOnly:req.body?.reason === 'rnr-disconnected',
        includePreviouslyProcessed:req.body?.includePreviouslyProcessed === true,
        dryRun:req.body?.dryRun === true }),
      5
    );
    res.json({ success: true, lookbackDays, ...result });
  } catch (e) {
    console.error('[followups/load-rnr-disconnected] failed:', e?.message || e);
    res.status(500).json({ success: false, error: e?.message || 'Unable to load follow-up calls' });
  }
});

async function syncAgentFollowUpToAutoDial(f = {}) {
  const followUpId = String(f.id || '').trim();
  const phone = normalizeAutoDialPhone(f.phone);
  if (!followUpId || !phone) return null;

  const leadId = followUpId;
  const nextStatus = String(f.status || 'Pending').trim() || 'Pending';
  const isOpenFollowUp = ['Pending', 'Rescheduled'].includes(nextStatus);

  if (!isOpenFollowUp) {
    await pool.query(
      `UPDATE attica_auto_dial_leads
       SET status='completed',
           is_active=0,
           retry_allowed=0,
           open_dedupe_number=NULL,
           queue_exit_reason=?,
           updated_at=NOW()
       WHERE id=?`,
      [`Follow-up marked ${nextStatus}`, leadId]
    );
    return null;
  }

  if (await isPhoneBlocked(phone)) return null;

  const scheduledFor = getScheduledFollowUpDate(f.followUpAt) || new Date();
  const followUpExpiry = getFollowUpExpiryValues(f.outcome || f.sourceStatus || 'Follow-Up');
  const customerName = cleanJustDialString(f.customerName || 'Follow-Up Customer', 120);
  const branch = cleanJustDialString(f.branch || '', 150);
  const agentId = normalizeAgentId(f.agentId);
  const agentName = cleanJustDialString(f.agentName, 100);
  const notes = cleanJustDialString(f.notes, 255);

  await collapseOpenAutoDialLeadsByPhone(pool, phone, {
    preferredLeadId: leadId,
    cleanupNote: 'Closed because agent scheduled the canonical follow-up queue lead for this customer',
  });

  await pool.query(
    `INSERT INTO attica_auto_dial_leads
      (id,customer_name,mobile_number,normalized_number,open_dedupe_number,area,source_state,preferred_language,gold_weight,lead_type,source_file,status,shuffle_no,assigned_agent_id,assigned_agent_name,scheduled_agent_id,scheduled_agent_name,assigned_at,dial_started_at,completed_at,call_id,last_error,scheduled_for,followup_created_at,followup_expires_at,followup_reason,is_active)
     VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,1)
     ON DUPLICATE KEY UPDATE
       customer_name=VALUES(customer_name),
       mobile_number=VALUES(mobile_number),
       normalized_number=VALUES(normalized_number),
       open_dedupe_number=VALUES(open_dedupe_number),
       area=VALUES(area),
       lead_type=VALUES(lead_type),
       source_file=VALUES(source_file),
       is_active=1,
       followup_created_at=COALESCE(attica_auto_dial_leads.followup_created_at, VALUES(followup_created_at)),
       followup_expires_at=COALESCE(attica_auto_dial_leads.followup_expires_at, VALUES(followup_expires_at)),
       followup_reason=COALESCE(NULLIF(attica_auto_dial_leads.followup_reason, ''), VALUES(followup_reason)),
       status=CASE
         WHEN attica_auto_dial_leads.status='dialing' THEN attica_auto_dial_leads.status
         ELSE 'pending'
       END,
       assigned_agent_id=CASE
         WHEN attica_auto_dial_leads.status='dialing' THEN attica_auto_dial_leads.assigned_agent_id
         ELSE NULL
       END,
       assigned_agent_name=CASE
         WHEN attica_auto_dial_leads.status='dialing' THEN attica_auto_dial_leads.assigned_agent_name
         ELSE NULL
       END,
       scheduled_agent_id=VALUES(scheduled_agent_id),
       scheduled_agent_name=VALUES(scheduled_agent_name),
       assigned_at=CASE
         WHEN attica_auto_dial_leads.status='dialing' THEN attica_auto_dial_leads.assigned_at
         ELSE NULL
       END,
       dial_started_at=CASE
         WHEN attica_auto_dial_leads.status='dialing' THEN attica_auto_dial_leads.dial_started_at
         ELSE NULL
       END,
       completed_at=NULL,
       queue_exit_reason=NULL,
       retry_allowed=1,
       shuffle_no=COALESCE(attica_auto_dial_leads.shuffle_no, VALUES(shuffle_no)),
       call_id=VALUES(call_id),
       last_error='',
       scheduled_for=VALUES(scheduled_for),
       updated_at=NOW()`,
    [
      leadId,
      customerName,
      phone,
      phone,
      getOpenAutoDialDedupeNumber(phone, 'pending', 1),
      branch,
      '',
      '',
      '',
      cleanJustDialString(f.sourceStatus || 'Scheduled Follow-Up', 80),
      'Agent Follow-Up',
      'pending',
      generateAutoDialShuffleNo(),
      null,
      null,
      agentId || null,
      agentName || null,
      null,
      null,
      null,
      f.sourceCallId || f.callId || '',
      notes,
      scheduledFor,
      followUpExpiry.createdAt,
      followUpExpiry.expiresAt,
      followUpExpiry.reason,
    ]
  );

  return { leadId, phone, scheduledFor };
}

async function saveAgentFollowUp(f) {
    const followUpExpiry = getFollowUpExpiryValues(f.outcome || f.status || 'Follow-Up');
    await pool.query(
      `INSERT INTO attica_followups (id,customer_name,phone,branch,follow_up_at,status,agent_id,agent_name,notes,outcome,followup_created_at,followup_expires_at,followup_reason,is_active,updated_at)
       VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
       ON DUPLICATE KEY UPDATE
         status=VALUES(status),
         is_active=CASE WHEN VALUES(status) IN ('Pending','Rescheduled') THEN 1 ELSE 0 END,
         notes=VALUES(notes),
         outcome=VALUES(outcome),
         followup_created_at=COALESCE(attica_followups.followup_created_at, VALUES(followup_created_at)),
         followup_expires_at=COALESCE(attica_followups.followup_expires_at, VALUES(followup_expires_at)),
         followup_reason=COALESCE(NULLIF(attica_followups.followup_reason, ''), VALUES(followup_reason)),
         follow_up_at=VALUES(follow_up_at),
         updated_at=VALUES(updated_at)`,
      [
        f.id,
        f.customerName,
        f.phone,
        f.branch,
        f.followUpAt,
        f.status,
        f.agentId,
        f.agentName,
        f.notes || '',
        f.outcome || '',
        followUpExpiry.createdAt,
        followUpExpiry.expiresAt,
        followUpExpiry.reason,
        ['Pending', 'Rescheduled'].includes(String(f.status || '')) ? 1 : 0,
        f.updatedAt || new Date(),
      ]
    );
    await syncAgentFollowUpToAutoDial(f);
    void triggerAutoDialAssignment('followup-save');
}

