async function updateAgentFollowUp(followUpId, body) {
    const nextStatus = String(body.status || '').trim();
    const fields = ['status=?', "is_active=CASE WHEN ? IN ('Pending','Rescheduled') THEN 1 ELSE 0 END", 'updated_at=NOW()'];
    const values = [nextStatus, nextStatus];
    if (body.outcome !== undefined) {
      fields.push('outcome=?');
      values.push(body.outcome || '');
    }
    if (body.followUpAt !== undefined) {
      fields.push('follow_up_at=?');
      values.push(body.followUpAt || null);
    }
    values.push(followUpId);
    await pool.query(`UPDATE attica_followups SET ${fields.join(', ')} WHERE id=?`, values);

    const [statusQueueRows] = await pool.query(
      'SELECT * FROM attica_status_followup_queue WHERE follow_up_id=? LIMIT 1',
      [followUpId]
    );
    const linkedQueue = statusQueueRows[0];

    if (linkedQueue) {
      const phone10 = normalizeAutoDialPhone(linkedQueue.phone);
      if (nextStatus === 'Called') {
        await closeStatusFollowUp(phone10, body.outcome || 'Marked called from follow-up');
      } else if (nextStatus === 'Pending' || nextStatus === 'Rescheduled') {
        const scheduledFor = getScheduledFollowUpDate(body.followUpAt) || getScheduledFollowUpDate(linkedQueue.updated_at) || new Date();
        await pool.query(
          `UPDATE attica_auto_dial_leads
          SET status='pending',
              is_active=1,
              assigned_agent_id=NULL,
              assigned_agent_name=NULL,
              assigned_at=NULL,
              dial_started_at=NULL,
              completed_at=NULL,
              queue_exit_reason=NULL,
              retry_allowed=1,
              scheduled_for=?,
              open_dedupe_number=normalized_number,
              updated_at=NOW(),
              last_error=''
           WHERE id=?`,
          [scheduledFor, linkedQueue.auto_dial_lead_id]
        );
        await pool.query(
          `UPDATE attica_status_followup_queue
           SET is_active=1,
               updated_at=NOW()
           WHERE id=?`,
          [linkedQueue.id]
        );
        await pool.query(
          `UPDATE attica_calls c
           JOIN attica_status_followup_queue s ON s.source_call_id=c.id
           SET c.callback_status='Pending',
               c.follow_up_flag=1
           WHERE s.id=?`,
          [linkedQueue.id]
        );
        void triggerAutoDialAssignment('event');
      }
    }

    const [updatedFollowUpRows] = await pool.query(
      'SELECT * FROM attica_followups WHERE id=? LIMIT 1',
      [followUpId]
    );
    if (updatedFollowUpRows[0] && !linkedQueue) {
      await syncAgentFollowUpToAutoDial({
        id: updatedFollowUpRows[0].id,
        customerName: updatedFollowUpRows[0].customer_name,
        phone: updatedFollowUpRows[0].phone,
        branch: updatedFollowUpRows[0].branch,
        followUpAt: updatedFollowUpRows[0].follow_up_at,
        status: updatedFollowUpRows[0].status,
        agentId: updatedFollowUpRows[0].agent_id,
        agentName: updatedFollowUpRows[0].agent_name,
        notes: updatedFollowUpRows[0].notes,
        outcome: updatedFollowUpRows[0].outcome,
      });
      void triggerAutoDialAssignment('followup-update');
    }
}

