app.get('/api/breaks', async (req, res) => {
  try {
    const requestedAgentId = normalizeAgentId(req.query.agentId);
    const requestedDate = normalizeQueryDate(req.query.date);
    const limit = Math.max(1, Math.min(MAX_DASHBOARD_FETCH_LIMIT, Number(req.query.limit) || MAX_DASHBOARD_FETCH_LIMIT));
    const filters = [];
    const params = [];

    if (requestedAgentId) {
      filters.push('agent_id=?');
      params.push(requestedAgentId);
    }

    if (requestedDate) {
      filters.push(`(
        break_date=?
        OR DATE(COALESCE(started_at, created_at))=?
      )`);
      params.push(requestedDate, requestedDate);
    }

    const whereClause = filters.length ? `WHERE ${filters.join(' AND ')}` : '';
    const [rows] = await pool.query(
      `SELECT *
       FROM attica_break_logs
       ${whereClause}
       ORDER BY COALESCE(started_at, created_at) DESC
       LIMIT ?`,
      [...params, limit]
    );
    const dedupedRows = [];
    const indexByBreakKey = new Map();

    for (const row of rows) {
      const dedupeKey = buildBreakDedupKey(row);
      const existingIndex = indexByBreakKey.get(dedupeKey);

      if (existingIndex === undefined) {
        indexByBreakKey.set(dedupeKey, dedupedRows.length);
        dedupedRows.push(row);
        continue;
      }

      if (shouldReplaceBreakRow(dedupedRows[existingIndex], row)) {
        dedupedRows[existingIndex] = row;
      }
    }

    res.json(dedupedRows.map((r) => {
      const createdAt = r.created_at ? new Date(r.created_at) : null;
      return {
        id: normalizeBreakLogId(r.id, r.id),
        agentId: r.agent_id,
        agentName: r.agent_name,
        breakType: normalizeAgentBreakStatus(r.break_type, 'on-break'),
        breakDate: formatDateInZone(r.break_date),
        startedAt: toApiIsoString(r.started_at) || toApiIsoString(r.created_at),
        endedAt: toApiIsoString(r.ended_at),
        startTime: r.start_time,
        endTime: r.end_time,
        duration: formatDurationSeconds(getBreakDurationSeconds(r)),
        createdAt: createdAt ? createdAt.toISOString() : '',
      };
    }));
  } catch (e) { res.status(500).json({ error: e.message }); }
});

app.post('/api/breaks', async (req, res) => {
  try {
    const b = req.body || {};
    const agentId = String(b.agentId || '').trim();
    if (!agentId) {
      return res.status(400).json({ error: 'Agent ID is required' });
    }

    const breakId = normalizeBreakLogId(b.id || b.breakId) || `BRK-${Date.now()}-${agentId}`;
    const breakType = normalizeAgentBreakStatus(b.breakType || b.status, 'on-break');
    const startedAtSource = b.startedAt || b.breakStartedAt || b.createdAt || new Date().toISOString();
    const startedAt = toDatabaseDateTime(startedAtSource) || toDatabaseDateTime(new Date().toISOString());
    const startedAtDate = startedAt ? new Date(`${startedAt.replace(' ', 'T')}Z`) : new Date();
    const breakDate = String(b.breakDate || '').trim() || formatDateInZone(startedAtDate);
    const startTime = String(b.startTime || b.breakStartTime || '').trim() || formatBreakTimeInZone(startedAtDate);
    const endedAtSource = b.endedAt || b.breakEndedAt || '';
    const endedAt = toDatabaseDateTime(endedAtSource);
    const endedAtDate = endedAt ? new Date(`${endedAt.replace(' ', 'T')}Z`) : null;
    const endTime = String(b.endTime || b.breakEndTime || '').trim() || (endedAtDate ? formatBreakTimeInZone(endedAtDate) : '');
    const duration = normalizeDurationValue(
      b.duration
        || b.breakDuration
        || (startedAtDate && endedAtDate ? formatDurationSeconds(Math.max(0, Math.floor((endedAtDate.getTime() - startedAtDate.getTime()) / 1000))) : ''),
      '',
    );

    if (!endTime && !endedAt) {
      const ensuredId = await ensureOpenBreakForAgent(agentId, {
        breakId,
        agentName: b.agentName,
        breakType,
        breakDate,
        startTime,
        startedAt: startedAtSource,
      });
      const releasedLeadCount = await releaseAssignedAutoDialLeadsForAgentBreak(agentId);
      await syncAsteriskQueuePauseStates([agentId]);
      invalidateLiveAgentSnapshotCache();
      invalidateAgentsEndpointCache();
      if (releasedLeadCount > 0) {
        void triggerAutoDialAssignment('event');
      }
      return res.json({ success: true, id: ensuredId, releasedLeadCount });
    }

    const [existingByIdRows] = await pool.query(
      'SELECT id, end_time FROM attica_break_logs WHERE id=? LIMIT 1',
      [breakId],
    );
    const matchingBreakRow = existingByIdRows[0] || null;
    const closedCount = await closeOpenBreaksForAgent(agentId, {
      breakId,
      endTime,
      endedAt: endedAtSource || new Date().toISOString(),
      duration,
    });

    if (!matchingBreakRow || matchingBreakRow.end_time) {
      await pool.query(
        `INSERT INTO attica_break_logs (id,agent_id,agent_name,break_type,break_date,start_time,started_at,end_time,ended_at,duration)
         VALUES (?,?,?,?,?,?,?,?,?,?)
         ON DUPLICATE KEY UPDATE
           agent_name=VALUES(agent_name),
           break_type=VALUES(break_type),
           break_date=VALUES(break_date),
           start_time=VALUES(start_time),
           started_at=VALUES(started_at),
           end_time=VALUES(end_time),
           ended_at=VALUES(ended_at),
           duration=VALUES(duration)`,
        [
          breakId,
          agentId,
          b.agentName || '',
          breakType,
          breakDate,
          startTime,
          startedAt,
          endTime || null,
          endedAt,
          duration || null,
        ],
      );
    }

    if (closedCount > 0) {
      void retryPendingMissedCallAssignments();
      void triggerAutoDialAssignment('event');
    }
    await syncAsteriskQueuePauseStates([agentId]);
    invalidateLiveAgentSnapshotCache();
    invalidateAgentsEndpointCache();
    res.json({ success: true, id: breakId });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

