      lastRouteEpoch: 0,
      secondsSinceLastRoute: 0,
      rateLimitRemainingSeconds: 0,
      cycleSize: 5,
      allowedPerCycle: 2,
      rejectedPerCycle: 3,
      nextPosition: 0,
      nextAction: 'route',
