app.post('/api/admin/incoming-2of5-gate/control', async (req, res) => {
  try {
    const role = String(req.body?.role || req.query.role || req.get('x-user-role') || '').trim().toLowerCase();
    if (role !== 'superadmin') {
      return res.status(403).json({ success: false, error: 'Forbidden' });
    }

    let status = getIncomingTwoOfFiveGateStatus();
    if (Object.prototype.hasOwnProperty.call(req.body || {}, 'enabled')) {
      const enabledValue = req.body?.enabled;
      const enabled = enabledValue === true
        || enabledValue === 1
        || ['1', 'true', 'yes', 'active', 'enable', 'enabled'].includes(String(enabledValue || '').trim().toLowerCase());
      status = setIncomingTwoOfFiveGateEnabled(enabled);
    }
    if (Object.prototype.hasOwnProperty.call(req.body || {}, 'stopLimit')) {
      status = setIncomingTwoOfFiveGateStopLimit(req.body?.stopLimit, req.body?.resetStopCount !== false);
    }
    if (Object.prototype.hasOwnProperty.call(req.body || {}, 'rateLimitSeconds')) {
      status = setIncomingTwoOfFiveGateRateLimit(req.body?.rateLimitSeconds, req.body?.resetRateTimer !== false);
    }
    res.json({ success: true, ...status });
  } catch (e) {
    console.error('[incoming-2of5-gate/control] failed:', e?.message || e);
    res.status(500).json({ success: false, error: 'Unable to update incoming gate status' });
  }
});

