app.get('/api/customerdata', async (req, res) => {
  try {
    const contact = normalizeAutoDialPhone(req.query.contact);
    const strict = ['1', 'true', 'yes'].includes(String(req.query.strict || '').trim().toLowerCase());
    if (!contact) return res.json([]);

    await syncRemoteCustomerDataCacheIfStale(CUSTOMER_DATA_REMOTE_REPORT_SYNC_MS);
    const cachedRemoteRows = await fetchCachedRemoteCustomerDataRowsByPhone(contact, 100);

    if (strict) {
      if (cachedRemoteRows.length > 0) {
        return res.json(cachedRemoteRows);
      }
    } else {
      const localRows = await fetchLocalCustomerDataRowsByPhone(contact, 100);
      if (cachedRemoteRows.length > 0 || localRows.length > 0) {
        return res.json([...cachedRemoteRows, ...localRows]);
      }
    }

    let timeout = null;
    try {
      const controller = new AbortController();
      timeout = setTimeout(() => controller.abort(), 2500);
      const response = await fetch(`https://atticagold.biz/FlutterProject/customerdata.php?contact=${encodeURIComponent(contact)}`, {
        headers: { Accept: 'application/json' },
        signal: controller.signal,
      });

      if (response.ok) {
        const payload = await response.json();
        if (hasCustomerDataPayloadRows(payload)) {
          return res.json(payload);
        }

        if (strict) {
          return res.json([]);
        }
      }
    } catch (_error) {
      if (strict) {
        return res.json([]);
      }
    } finally {
      if (timeout) clearTimeout(timeout);
    }

    const fallbackRows = await fetchLocalCustomerDataRowsByPhone(contact, 100);
    return res.json(fallbackRows);
  } catch (e) {
    res.status(500).json([]);
  }
});

