app.get('/api/recordings/:name', async (req, res) => {
  try {
    const requestedName = decodeURIComponent(String(req.params.name || ''));
    const safeName = basename(requestedName);

    if (!safeName || safeName !== requestedName) {
      return res.status(400).json({ error: 'Invalid recording name' });
    }

    const absolutePath = resolveRecordingAbsolutePath(safeName);
    if (!absolutePath) {
      return res.status(404).json({ error: 'Recording not found' });
    }

    const stats = statSync(absolutePath);
    if (!stats.isFile()) {
      return res.status(404).json({ error: 'Recording not found' });
    }

    res.set({
      'Content-Type': 'audio/wav',
      'Content-Length': String(stats.size),
      'Content-Disposition': `inline; filename="${safeName}"`,
    });
    return res.sendFile(absolutePath);
  } catch (e) {
    return res.status(404).json({ error: 'Recording not found' });
  }
});

