function normalizeAsteriskQueueStrategyConfig(content) {
  return String(content || '').replace(
    /^strategy\s*=\s*.+$/gmi,
    `strategy=${ASTERISK_REQUIRED_QUEUE_STRATEGY}`,
  );
}

function enforceAsteriskQueueStrategyConfig() {
  try {
    const currentContent = readFileSync(ASTERISK_QUEUE_CONFIG_PATH, 'utf8');
    const normalizedContent = normalizeAsteriskQueueStrategyConfig(currentContent);
    if (normalizedContent !== currentContent) {
      writeFileSync(ASTERISK_QUEUE_CONFIG_PATH, normalizedContent);
      console.warn(`Asterisk queue strategy drift corrected to ${ASTERISK_REQUIRED_QUEUE_STRATEGY}`);
      return true;
    }
  } catch (error) {
    console.warn('Unable to enforce Asterisk queue strategy config:', error?.message || error);
  }
  return false;
}

function verifyLiveAsteriskQueueStrategy() {
  try {
    const output = execSync('asterisk -rx "queue show"', { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'], timeout: 5000 });
    const mismatchedQueues = ASTERISK_INBOUND_QUEUE_NAMES.filter((queueName) => {
      const escapedQueueName = queueName.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      const queuePattern = new RegExp(`^${escapedQueueName}\\s+has\\s+\\d+\\s+calls?.+in\\s+'([^']+)'\\s+strategy`, 'im');
      const match = output.match(queuePattern);
      return !match || String(match[1] || '').trim().toLowerCase() !== ASTERISK_REQUIRED_QUEUE_STRATEGY;
    });
    return mismatchedQueues;
  } catch (error) {
    console.warn('Unable to verify live Asterisk queue strategy:', error?.message || error);
    return [];
  }
}

function enforceLiveAsteriskQueueStrategy() {
  const configChanged = enforceAsteriskQueueStrategyConfig();
  const mismatchedQueues = verifyLiveAsteriskQueueStrategy();
  if (configChanged || mismatchedQueues.length > 0) {
    try {
      execSync('asterisk -rx "queue reload all"', { stdio: ['ignore', 'pipe', 'pipe'], timeout: 10000 });
      console.warn(`Asterisk queue module reloaded to enforce ${ASTERISK_REQUIRED_QUEUE_STRATEGY} strategy`, {
        mismatchedQueues,
      });
    } catch (error) {
      console.warn('Unable to reload Asterisk queues for strategy enforcement:', error?.message || error);
    }
  }
}

async function updateAsteriskQueues() {
  try {
    await closeStaleOpenBreakLogs();
    const [rows] = await pool.query(
      `SELECT l.agent_id, l.language, a.extension
       FROM attica_agent_languages l
       JOIN attica_agents a ON a.id=l.agent_id
       LEFT JOIN attica_break_logs b ON b.agent_id=a.id AND b.end_time IS NULL AND b.ended_at IS NULL
       WHERE a.role='agent'
         AND a.status='active'
         AND a.incoming_access <> 0
         AND a.is_logged_in=1
         AND b.agent_id IS NULL`
    );
    const endpointAvailabilityByExtension = readPjsipEndpointAvailabilitySnapshot();
    const langMap = { Kannada: [], Tamil: [], Telugu: [], Hindi: [], English: [] };
    rows.forEach(r => {
      if (langMap[r.language]) {
        const extension = normalizeSipExtension(r.extension);
        const endpointAvailability = endpointAvailabilityByExtension.get(extension);
        if (endpointAvailability && endpointAvailability.available === false) return;
        if (extension) {
          langMap[r.language].push(extension);
        }
      }
    });
    Object.keys(langMap).forEach((language) => {
      langMap[language] = Array.from(new Set(langMap[language])).sort((left, right) => Number(left) - Number(right));
    });
    const lines = ['[general]','persistentmembers=no','autofill=yes','monitor-type=MixMonitor',''];
    for (const [lang, agents] of Object.entries(langMap)) {
      lines.push('[attica-' + lang.toLowerCase() + ']');
      lines.push(
        'musicclass=default',
        `strategy=${ASTERISK_REQUIRED_QUEUE_STRATEGY}`,
        `timeout=${ASTERISK_INBOUND_QUEUE_TIMEOUT_SECONDS}`,
        'retry=0',
        'wrapuptime=1',
        'maxlen=0',
        'joinempty=yes',
        'leavewhenempty=no',
        'ringinuse=no',
        'autopause=no',
        'autopausedelay=0',
      );
      // Queue members must stay dynamic. Static members cannot be removed at
      // runtime when an agent moves to break/outbound/follow-up, which causes
      // incoming calls to ring ineligible agents and then miss/drop.
      lines.push('');
    }
    writeFileSync(ASTERISK_QUEUE_CONFIG_PATH, normalizeAsteriskQueueStrategyConfig(lines.join('\n')));
    try {
      execSync('asterisk -rx "queue reload all"', { stdio: ['ignore', 'pipe', 'pipe'], timeout: 10000 });
    } catch (reloadError) {
      console.warn('Asterisk queue reload failed, falling back to app_queue module reload:', reloadError?.message || reloadError);
      execSync('asterisk -rx "module reload app_queue.so"', { stdio: ['ignore', 'pipe', 'pipe'], timeout: 10000 });
    }
    await syncAsteriskQueuePauseStates();
    invalidateLiveAgentSnapshotCache();
    console.log('Asterisk queues updated');
  } catch (e) { console.error('Queue update error:', e); }
}

