app.post('/api/live-call-monitor', async (req, res) => {
  try {
    const requestedById = normalizeAgentIdentifier(req.body.requestedById);
    const targetAgentId = normalizeAgentIdentifier(req.body.targetAgentId);
    const mode = String(req.body.mode || '').trim().toLowerCase();
    const monitorMode = LIVE_CALL_MONITOR_MODES[mode];

    if (!requestedById || !targetAgentId || !monitorMode) {
      return res.status(400).json({ error: 'Requester, target agent, and monitor mode are required' });
    }

    if (requestedById === targetAgentId) {
      return res.status(400).json({ error: 'Choose a different agent to monitor' });
    }

    const [rows] = await pool.query(
      'SELECT id, name, role, extension FROM attica_agents WHERE id IN (?, ?) LIMIT 2',
      [requestedById, targetAgentId]
    );
    const agentsById = new Map(rows.map((row) => [row.id, row]));
    const requester = agentsById.get(requestedById);
    const targetAgent = agentsById.get(targetAgentId);

    if (!requester?.id || !['admin', 'superadmin'].includes(String(requester.role || '').toLowerCase())) {
      return res.status(403).json({ error: 'Only admin users can start live listening or barging' });
    }

    if (!targetAgent?.id || targetAgent.role !== 'agent') {
      return res.status(404).json({ error: 'Target agent was not found' });
    }

    const requesterExtension = normalizeSipExtension(requester.extension);
    const targetExtension = normalizeSipExtension(targetAgent.extension);

    if (!requesterExtension) {
      return res.status(400).json({ error: 'Admin extension is not configured' });
    }

    if (!targetExtension) {
      return res.status(400).json({ error: 'Target agent extension is not configured' });
    }

    const liveAgents = await getLiveAgentSnapshot({ useCache: false });
    const pjsipOutput = readSipEndpointOutput();
    const sipPeerOutput = readSipPeerOutput();
    const requesterEndpoint = resolveLiveMonitorEndpoint(requesterExtension, {
      preferredDrivers: ['PJSIP', 'SIP'],
      pjsipOutput,
      sipPeerOutput,
    });
    if (!requesterEndpoint) {
      return res.status(409).json({
        error: `Admin web phone extension ${requesterExtension} is not registered in Asterisk right now. Wait for SIP Online, then try live listening again.`,
      });
    }

    const targetLiveAgent = liveAgents.find((agent) => agent.agentId === targetAgentId);
    if (!targetLiveAgent || targetLiveAgent.status !== 'on-call' || !(Number(targetLiveAgent.activeCalls) > 0)) {
      return res.status(409).json({ error: 'The selected agent is not on a live call right now' });
    }

    const targetEndpoint = resolveLiveMonitorEndpoint(targetExtension, {
      preferredDrivers: ['PJSIP', 'SIP'],
      requireActiveCall: true,
      pjsipOutput,
      sipPeerOutput,
    });
    if (!targetEndpoint) {
      return res.status(409).json({ error: 'The selected agent endpoint is not on an active SIP call right now' });
    }

    const targetSpyChannel = resolveLiveMonitorSpyChannel(targetExtension, targetEndpoint.channel);
    const chanSpyOptions = `${monitorMode.chanSpyOptions}${targetSpyChannel.includes('-') ? 'u' : ''}`;
    const originateCommand = `channel originate ${requesterEndpoint.channel} application ChanSpy ${targetSpyChannel},${chanSpyOptions}`;
    runAsteriskCli(originateCommand, { timeout: 5000 });

    res.json({
      success: true,
      mode,
      requestedById,
      requestedByName: requester.name || requestedById,
      requesterExtension,
      requesterChannel: requesterEndpoint.channel,
      targetAgentId,
      targetAgentName: targetAgent.name || targetAgentId,
      targetExtension,
      targetChannel: targetSpyChannel,
    });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

app.post('/api/calls/conference', async (req, res) => {
  try {
    const requestedById = normalizeAgentIdentifier(req.body?.requestedById);
    const dialExtension = getConferenceDialExtension(req.body?.targetPhone);

    if (!requestedById || !dialExtension) {
      return res.status(400).json({ error: 'Agent and a valid 10-digit conference number are required' });
    }

    const [[agent]] = await pool.query(
      'SELECT id, name, role, extension FROM attica_agents WHERE id=? LIMIT 1',
      [requestedById]
    );

    if (!agent?.id || agent.role !== 'agent') {
      return res.status(403).json({ error: 'Only agent users can start conference calls' });
    }

    const requesterExtension = normalizeSipExtension(agent.extension);
    if (!requesterExtension) {
      return res.status(400).json({ error: 'Agent extension is not configured' });
    }

    const conferenceChannels = findAgentConferenceChannels(requesterExtension);
    if (!conferenceChannels?.agentChannel) {
      return res.status(409).json({ error: 'No active agent call was found for conference merge' });
    }
    if (conferenceChannels.relatedChannels.length === 0) {
      return res.status(409).json({ error: 'No active customer call leg was found for conference merge' });
    }

    const conferenceId = buildConferenceId(requestedById, requesterExtension);
    const redirectedChannels = [];
    const redirectTarget = `${CONFERENCE_BRIDGE_CONTEXT},${conferenceId},1`;

    for (const channel of [...conferenceChannels.relatedChannels, conferenceChannels.agentChannel]) {
      runAsteriskCli(`channel redirect ${channel.channel} ${redirectTarget}`, { timeout: 5000 });
      redirectedChannels.push(channel.channel);
    }

    const dialChannel = `Local/${dialExtension}@${CONFERENCE_OUTBOUND_CONTEXT}`;
    runAsteriskCli(`channel originate ${dialChannel} application ConfBridge ${conferenceId}`, { timeout: 5000 });
    invalidateLiveAgentSnapshotCache();

    res.json({
      success: true,
      conferenceId,
      requesterId: requestedById,
      requesterExtension,
      targetPhone: dialExtension,
      redirectedChannels,
      dialChannel,
    });
  } catch (e) {
    console.error('Conference call request failed:', e);
    res.status(500).json({ error: e.message || 'Failed to start conference call' });
  }
});

app.post('/api/calls/transfer', async (req, res) => {
  try {
    const requestedById = normalizeAgentIdentifier(req.body?.requestedById);
    const sourceExtension = normalizeSipExtension(req.body?.sourceExtension);
    const sourceCallId = cleanJustDialString(req.body?.sourceCallId, 80);
    const targetExtension = normalizeSipExtension(req.body?.targetExtension);

    if (!requestedById && !sourceExtension) {
      return res.status(400).json({ error: 'Source agent is required' });
    }
    if (!targetExtension) {
      return res.status(400).json({ error: 'Target extension is required' });
    }

    const [sourceRows] = await pool.query(
      `SELECT id, name, role, extension, status
         FROM attica_agents
        WHERE ${requestedById ? 'id=?' : 'extension=?'}
        LIMIT 1`,
      [requestedById || sourceExtension]
    );
    const sourceAgent = sourceRows[0];
    if (!sourceAgent?.id) {
      return res.status(404).json({ error: 'Source agent was not found' });
    }

    const normalizedSourceExtension = normalizeSipExtension(sourceAgent.extension);
    if (!normalizedSourceExtension) {
      return res.status(400).json({ error: 'Source extension is not configured' });
    }
    if (normalizedSourceExtension === targetExtension) {
      return res.status(400).json({ error: 'Choose a different agent extension for transfer' });
    }

    const [[targetAgent]] = await pool.query(
      `SELECT id, name, role, extension, status, is_logged_in
         FROM attica_agents
        WHERE extension=? AND role='agent'
        LIMIT 1`,
      [targetExtension]
    );
    if (!targetAgent?.id) {
      return res.status(404).json({ error: 'Target agent was not found' });
    }

    const liveAgents = await getLiveAgentSnapshot({ useCache: false });
    const sourceLiveAgent = liveAgents.find((agent) => agent.agentId === sourceAgent.id)
      || { workMode: sourceAgent.status || '', status: sourceAgent.status || '' };
    const targetLiveAgent = liveAgents.find((agent) => agent.agentId === targetAgent.id)
      || { workMode: targetAgent.status || '', status: targetAgent.status || '', activeCalls: 0, isLoggedIn: targetAgent.is_logged_in === 1 };
    let sourceWorkMode = sourceLiveAgent.workMode || sourceAgent.status || '';
    let sourceLanguage = '';
    const targetStatus = targetLiveAgent.status || targetAgent.status || '';
    const targetWorkMode = targetLiveAgent.workMode || targetAgent.status || '';

    if (sourceCallId) {
      const [sourceLeadRows] = await pool.query(
        `SELECT *
         FROM attica_auto_dial_leads
         WHERE call_id=?
         ORDER BY updated_at DESC
         LIMIT 1`,
        [sourceCallId]
      );
      if (sourceLeadRows[0]) {
        sourceWorkMode = getAutoDialWorkModeForLead(sourceLeadRows[0]);
        sourceLanguage = cleanJustDialString(sourceLeadRows[0].preferred_language, 30);
      } else {
        const [sourceCallRows] = await pool.query(
          `SELECT direction, language
           FROM attica_calls
           WHERE id=?
           LIMIT 1`,
          [sourceCallId]
        );
        const sourceDirection = String(sourceCallRows[0]?.direction || '').trim().toLowerCase();
        sourceLanguage = cleanJustDialString(sourceCallRows[0]?.language, 30);
        if (sourceDirection === 'incoming') {
          sourceWorkMode = 'active';
        } else if (
          sourceDirection === 'outgoing'
          && sourceWorkMode !== 'outbound-auto'
          && sourceWorkMode !== 'follow-up'
        ) {
          sourceWorkMode = 'outbound-auto';
        }
      }
    }

    if (!targetLiveAgent.isLoggedIn && targetAgent.is_logged_in !== 1) {
      console.warn('[transfer] rejected target not logged in', {
        requestedById,
        sourceExtension,
        sourceAgentId: sourceAgent.id,
        targetAgentId: targetAgent.id,
        targetExtension,
      });
      return res.status(409).json({ error: 'Target agent is not logged in' });
    }

    const [[targetAutoDialWork]] = await pool.query(
      `SELECT id, status, mobile_number, assigned_at, dial_started_at
       FROM attica_auto_dial_leads
       WHERE assigned_agent_id=?
         AND status IN ('assigned','dialing')
         AND (
           status='dialing'
           OR assigned_at >= DATE_SUB(NOW(), INTERVAL ? SECOND)
         )
       ORDER BY COALESCE(dial_started_at, assigned_at) DESC
       LIMIT 1`,
      [targetAgent.id, AUTO_DIAL_STALE_ASSIGNMENT_SECONDS]
    );
    if (targetAutoDialWork?.id) {
      console.warn('[transfer] rejected target has auto-dial work', {
        requestedById,
        sourceExtension: normalizedSourceExtension,
        sourceCallId,
        sourceAgentId: sourceAgent.id,
        sourceWorkMode,
        targetAgentId: targetAgent.id,
        targetExtension,
        autoDialLeadId: targetAutoDialWork.id,
        autoDialStatus: targetAutoDialWork.status,
        autoDialPhone: targetAutoDialWork.mobile_number,
      });
      return res.status(409).json({ error: 'Target agent already has an assigned auto-dial call. Choose another available agent.' });
    }

    if (!canReceiveTransferredCall({
      status: targetStatus,
      workMode: targetWorkMode,
      sourceStatus: sourceWorkMode,
      activeCalls: targetLiveAgent.activeCalls,
      sipStatus: targetLiveAgent.sipStatus,
      isLoggedIn: targetLiveAgent.isLoggedIn ?? targetAgent.is_logged_in === 1,
      queuePaused: targetLiveAgent.queuePaused,
      onBreak: targetLiveAgent.onBreak,
      languages: targetLiveAgent.languages,
      sourceLanguage,
    })) {
      console.warn('[transfer] rejected target not eligible', {
        requestedById,
        sourceExtension: normalizedSourceExtension,
        sourceCallId,
        sourceAgentId: sourceAgent.id,
        sourceWorkMode,
        sourceLanguage,
        targetAgentId: targetAgent.id,
        targetExtension,
        targetStatus,
        targetWorkMode,
        targetLiveStatus: targetLiveAgent.status,
        targetActiveCalls: targetLiveAgent.activeCalls,
        targetSipStatus: targetLiveAgent.sipStatus,
        targetQueuePaused: targetLiveAgent.queuePaused,
        targetOnBreak: targetLiveAgent.onBreak,
        targetLanguages: targetLiveAgent.languages,
      });
      return res.status(409).json({ error: 'Transfer is allowed only to an available agent in the same work mode' });
    }

    const transferChannels = findAgentConferenceChannels(normalizedSourceExtension, {
      phone: req.body?.phone,
      sourceCallId,
    });
    if (!transferChannels?.agentChannel) {
      console.warn('[transfer] rejected no source agent channel', {
        requestedById,
        sourceExtension: normalizedSourceExtension,
        sourceCallId,
        targetExtension,
      });
      return res.status(409).json({ error: 'No active source agent call was found for transfer' });
    }
    if (!Array.isArray(transferChannels.relatedChannels) || transferChannels.relatedChannels.length === 0) {
      console.warn('[transfer] rejected no customer leg', {
        requestedById,
        sourceExtension: normalizedSourceExtension,
        sourceCallId,
        targetExtension,
        agentChannel: transferChannels.agentChannel,
        matchedHint: transferChannels.matchedHint,
      });
      return res.status(409).json({ error: 'No active customer call leg was found for transfer' });
    }

    const conferenceId = buildConferenceId(sourceAgent.id, normalizedSourceExtension);
    const transferReservationId = `TRANSFER-${conferenceId}`;
    const [reservationResult] = await pool.query(
      `UPDATE attica_agents
       SET wrap_up_started_at=NOW(),
           wrap_up_until=DATE_ADD(NOW(), INTERVAL 45 SECOND),
           wrap_up_call_id=?
       WHERE id=?
         AND is_logged_in=1
         AND active_call_id IS NULL
         AND (wrap_up_until IS NULL OR wrap_up_until <= NOW())
         AND NOT ${pendingIntakeSql('attica_agents.id')}`,
      [transferReservationId, targetAgent.id]
    );
    if (reservationResult.affectedRows === 0) {
      console.warn('[transfer] rejected target reservation failed', {
        requestedById,
        sourceExtension: normalizedSourceExtension,
        sourceCallId,
        sourceAgentId: sourceAgent.id,
        sourceWorkMode,
        targetAgentId: targetAgent.id,
        targetExtension,
      });
      return res.status(409).json({ error: 'Target agent became busy. Choose another available agent.' });
    }
    invalidateLiveAgentSnapshotCache();

    const redirectTarget = `${DIRECT_AGENT_TRANSFER_CONTEXT},${targetExtension},1`;
    const redirectedChannels = [];
    const targetDialChannel = `PJSIP/${targetExtension}`;
    try {
      for (const channel of transferChannels.relatedChannels) {
        runAsteriskCli(`channel redirect ${channel.channel} ${redirectTarget}`, { timeout: 5000 });
        redirectedChannels.push(channel.channel);
      }

      scheduleTransferredSourceHangup({
        sourceChannel: transferChannels.agentChannel.channel,
        targetExtension,
        transferId: conferenceId,
        delayMs: 1500,
      });
      console.log('[transfer] direct customer-leg transfer started', {
        conferenceId,
        targetAgentId: targetAgent.id,
        targetExtension,
        targetDialChannel,
        redirectedChannels,
      });
      scheduleTransferTargetReservationRelease({
        targetAgentId: targetAgent.id,
        conferenceId,
        delayMs: 45000,
      });
      invalidateLiveAgentSnapshotCache();
    } catch (error) {
      await releaseTransferTargetReservation(targetAgent.id, conferenceId);
      throw error;
    }
    console.log('[transfer] safe bridge transfer started', {
      requesterId: sourceAgent.id,
      requesterExtension: normalizedSourceExtension,
      targetAgentId: targetAgent.id,
      targetExtension,
      sourceWorkMode,
      conferenceId,
      redirectedChannels,
      targetDialChannel,
      sourceReleaseDelayMs: 1500,
    });

    res.json({
      success: true,
      conferenceId,
      requesterId: sourceAgent.id,
      requesterExtension: normalizedSourceExtension,
      targetAgentId: targetAgent.id,
      targetAgentName: targetAgent.name || targetAgent.id,
      targetExtension,
      sourceWorkMode,
      transferMode: 'direct-redirect',
      redirectedChannels,
      targetDialChannel,
      sourceReleaseDelayMs: 1500,
    });
  } catch (e) {
    console.error('Call transfer request failed:', e);
    res.status(500).json({ error: e.message || 'Failed to transfer call' });
  }
});

function readLeadReceiverApiKey(req) {
  const authorization = cleanJustDialString(req.headers?.authorization || '', 500);
  const bearerMatch = authorization.match(/^Bearer\s+(.+)$/i);
  return cleanJustDialString(
    req.headers?.['x-api-key']
      || req.headers?.['x_api_key']
      || (bearerMatch ? bearerMatch[1] : '')
      || req.query?.['x-api-key']
      || req.query?.x_api_key
      || req.query?.api_key
      || req.query?.apikey
      || req.query?.token
      || req.query?.key
      || req.body?.['x-api-key']
      || req.body?.x_api_key
      || req.body?.api_key
      || req.body?.apikey
      || req.body?.token
      || req.body?.key
      || '',
    255
  );
}

// ==================== JUSTDIAL LEADS ====================
app.all([
  '/api/justdial/lead-receiver',
  '/api/justdial/lead_receiver',
  '/api/justdial-leads/lead-receiver',
  '/api/justdial-leads/lead_receiver',
], async (req, res) => {
  if (!['GET', 'POST'].includes(req.method)) {
    return justDialBad(res, 405, 'BAD_REQUEST');
  }

  const clientKey = readLeadReceiverApiKey(req);
  if (clientKey !== JUSTDIAL_API_KEY) {
    return justDialBad(res, 401, 'UNAUTHORIZED');
  }

  const sourceData = req.method === 'POST' ? (req.body || {}) : (req.query || {});
  const keys = Object.keys(sourceData);
  const ignoredFields = keys.filter((key) => (
    !JUSTDIAL_ALLOWED_FIELDS.includes(key)
    && !['x-api-key', 'x_api_key', 'api_key', 'apikey', 'key'].includes(String(key || '').toLowerCase())
  ));
  if (ignoredFields.length) {
    console.warn('[justdial] Ignoring extra fields:', ignoredFields.join(','));
  }

  const payload = {};
  for (const field of JUSTDIAL_ALLOWED_FIELDS) {
    payload[field] = sourceData[field] ?? '';
  }

  const leadid = cleanJustDialString(payload.leadid, 255);
  if (!leadid) return justDialBad(res, 400, 'MISSING_LEADID');

  const leadDateInput = cleanJustDialString(payload.date || payload.lead_date, 10);
  const leadTimeInput = cleanJustDialString(payload.time || payload.lead_time, 8);
  const leadDate = leadDateInput ? validateJustDialDate(leadDateInput) : null;
  const leadTime = leadTimeInput ? validateJustDialTime(leadTimeInput) : null;
  if (leadDateInput && leadDate === null) return justDialBad(res, 400, 'INVALID_DATE');
  if (leadTimeInput && leadTime === null) return justDialBad(res, 400, 'INVALID_TIME');

  const dncMobile = cleanJustDialBinaryFlag(payload.dncmobile);
  const dncPhone = cleanJustDialBinaryFlag(payload.dncphone);
  if (dncMobile === null || dncPhone === null) return justDialBad(res, 400, 'INVALID_DNC');

  const normalizedLeadPhone = normalizeAutoDialPhone(payload.mobile || payload.phone);
  if (!normalizedLeadPhone) return justDialBad(res, 400, 'MISSING_PHONE');
  const blockedContentReason = getBlockedLeadContentReason({
    name: payload.name,
    leadtype: payload.leadtype,
    category: payload.category,
    city: payload.city,
    area: payload.area,
    brancharea: payload.brancharea,
    company: payload.company,
    state: payload.state,
  });
  if (blockedContentReason) {
    console.warn('[justdial] blocked spam lead content:', blockedContentReason);
    return justDialBad(res, 400, 'BLOCKED_SPAM_CONTENT');
  }
  const rawPayload = JSON.stringify(payload);

  try {
    const duplicateLead = await findExistingJustDialLeadDuplicate({
      leadid,
      phone10: normalizedLeadPhone,
      leadDate,
    });
    if (duplicateLead) {
      queueSourceLeadForAutoDial('justdial', duplicateLead.leadid);
      enqueueAisensyLeadCampaign('justdial', duplicateLead);
      return res.status(200).type('text/plain; charset=utf-8').send('SUCCESS');
    }

    await pool.query(
      `INSERT INTO attica_justdial_leads
      (leadid,leadtype,prefix,name,mobile,phone,email,lead_date,category,city,area,brancharea,dncmobile,dncphone,company,pincode,lead_time,branchpin,parentid,state,raw_payload)
      VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
      ON DUPLICATE KEY UPDATE
        leadtype=VALUES(leadtype),
        prefix=VALUES(prefix),
        name=VALUES(name),
        mobile=VALUES(mobile),
        phone=VALUES(phone),
        email=VALUES(email),
        lead_date=VALUES(lead_date),
        category=VALUES(category),
        city=VALUES(city),
        area=VALUES(area),
        brancharea=VALUES(brancharea),
        dncmobile=VALUES(dncmobile),
        dncphone=VALUES(dncphone),
        company=VALUES(company),
        pincode=VALUES(pincode),
        lead_time=VALUES(lead_time),
        branchpin=VALUES(branchpin),
        parentid=VALUES(parentid),
        state=VALUES(state),
        raw_payload=VALUES(raw_payload),
        received_at=NOW()`,
      [
        leadid,
        cleanJustDialString(payload.leadtype, 255),
        cleanJustDialString(payload.prefix, 10),
        cleanJustDialString(payload.name, 255),
        cleanJustDialString(payload.mobile, 50),
        cleanJustDialString(payload.phone, 50),
        cleanJustDialString(payload.email, 255),
        leadDate,
        cleanJustDialString(payload.category, 255),
        cleanJustDialString(payload.city, 255),
        cleanJustDialString(payload.area, 255),
        cleanJustDialString(payload.brancharea, 255),
        dncMobile,
        dncPhone,
        cleanJustDialString(payload.company, 255),
        cleanJustDialString(payload.pincode, 50),
        leadTime,
        cleanJustDialString(payload.branchpin, 50),
        cleanJustDialString(payload.parentid, 255),
        cleanJustDialString(payload.state, 255),
        rawPayload,
      ]
    );
    queueSourceLeadForAutoDial('justdial', leadid);
    enqueueAisensyLeadCampaign('justdial', {
      ...payload,
      leadid,
      mobile: normalizedLeadPhone,
      lead_date: leadDate,
      lead_time: leadTime,
    });
    return res.status(200).type('text/plain; charset=utf-8').send('SUCCESS');
  } catch (error) {
    return justDialBad(res, 500, 'ERROR');
  }
});

app.get('/api/justdial/leads', async (req, res) => {
  try {
    const { startDate, endDate, limit } = getSourceLeadQueryWindow(req.query);
    const [rows] = await pool.query(
      `SELECT j.*, a.status AS auto_dial_status_current
       FROM attica_justdial_leads j
       LEFT JOIN attica_auto_dial_leads a ON a.id=j.auto_dial_lead_id
       WHERE LOWER(IFNULL(j.auto_dial_status, '')) <> 'blocked'
         AND COALESCE(j.lead_date, DATE(j.received_at)) BETWEEN ? AND ?
       ORDER BY j.received_at DESC, j.id DESC
       LIMIT ?`,
      [startDate, endDate, limit]
    );
    const visibleRows = dedupeLeadRowsByMobileAndDay(
      rows,
      (row) => row.mobile || row.phone,
      (row) => getLeadDayKey(row.lead_date, row.received_at)
    );
    res.json(visibleRows.map(serializeJustDialLeadRow));
  } catch (e) { res.status(500).json({ error: e.message }); }
});

app.get('/api/lead-source-counts/today', async (req, res) => {
  try {
    if (req.query?.sync === '1') {
      await Promise.all([
        syncWebsiteLeadsFromSheet({ force: true }),
        syncWebsiteLeadsFromFormApi({ force: true }),
        syncBlogLeadsFromSheet({ force: true }),
      ]);
    }
    const today = getBusinessDateString();
    const todayRange = getQueryDateTimeRange(today);
    const websiteTodayWhere = todayRange
      ? '(lead_date=? OR (lead_date IS NULL AND received_at>=? AND received_at<?))'
      : 'lead_date=?';
    const websiteTodayParams = todayRange
      ? [today, todayRange.start, todayRange.end]
      : [today];
    const [websiteRows, googleRows, blogRows, justDialRows, metaRows] = await Promise.all([
      pool.query(
        `SELECT contact_number, lead_date, received_at
         FROM attica_website_leads
         WHERE ${websiteTodayWhere}
           AND COALESCE(lead_from, '') <> '${BLOG_LEADS_SOURCE_LABEL}'
           AND NOT ${getGoogleWebsiteLeadWhereSql('attica_website_leads')}
           AND LOWER(IFNULL(auto_dial_status, '')) <> 'blocked'`,
        websiteTodayParams
      ).then(([rows]) => rows),
      pool.query(
        `SELECT contact_number, lead_date, received_at
         FROM attica_website_leads
         WHERE ${websiteTodayWhere}
           AND ${getGoogleWebsiteLeadWhereSql('attica_website_leads')}
           AND LOWER(IFNULL(auto_dial_status, '')) <> 'blocked'`,
        websiteTodayParams
      ).then(([rows]) => rows),
      pool.query(
        `SELECT contact_number, lead_date, received_at
         FROM attica_website_leads
         WHERE ${websiteTodayWhere}
           AND lead_from=?
           AND LOWER(IFNULL(auto_dial_status, '')) <> 'blocked'`,
        [...websiteTodayParams, BLOG_LEADS_SOURCE_LABEL]
      ).then(([rows]) => rows),
      pool.query(
        `SELECT mobile, phone, lead_date, received_at
         FROM attica_justdial_leads
         WHERE COALESCE(lead_date, DATE(received_at)) = ?
           AND LOWER(IFNULL(auto_dial_status, '')) <> 'blocked'`,
        [today]
      ).then(([rows]) => rows),
      pool.query(
        `SELECT phone_number, lead_created_at, received_at
         FROM attica_meta_leads
         WHERE DATE(COALESCE(lead_created_at, received_at)) = ?
           AND LOWER(IFNULL(auto_dial_status, '')) <> 'blocked'`,
        [today]
      ).then(([rows]) => rows),
    ]);
    const visibleWebsiteRows = dedupeLeadRowsByMobileAndDay(
      websiteRows,
      (row) => row.contact_number,
      (row) => getLeadDayKey(row.lead_date, row.received_at)
    );
    const visibleGoogleRows = dedupeLeadRowsByMobileAndDay(
      googleRows,
      (row) => row.contact_number,
      (row) => getLeadDayKey(row.lead_date, row.received_at)
    );
    const visibleJustDialRows = dedupeLeadRowsByMobileAndDay(
      justDialRows,
      (row) => row.mobile || row.phone,
      (row) => getLeadDayKey(row.lead_date, row.received_at)
    );
    const visibleBlogRows = dedupeLeadRowsByMobileAndDay(
      blogRows,
      (row) => row.contact_number,
      (row) => getLeadDayKey(row.lead_date, row.received_at)
    );
    const visibleMetaRows = dedupeLeadRowsByMobileAndDay(
      metaRows,
      (row) => row.phone_number,
      (row) => getLeadDayKey(row.lead_created_at, row.received_at)
    );

    res.json({
      date: today,
      website: visibleWebsiteRows.length,
      google: visibleGoogleRows.length,
      blogs: visibleBlogRows.length,
      justdial: visibleJustDialRows.length,
      meta: visibleMetaRows.length,
    });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

