app.post('/api/justdial/leads/export-followups', async (req, res) => {
  try {
    const leadIds = normalizeLeadIdList(req.body?.leadIds);
    const params = [];
    const whereClause = leadIds.length > 0
      ? "WHERE j.leadid IN (?) AND LOWER(IFNULL(j.auto_dial_status, '')) <> 'blocked'"
      : "WHERE LOWER(IFNULL(j.auto_dial_status, '')) <> 'blocked'";
    if (leadIds.length > 0) params.push(leadIds);

    const [rows] = await pool.query(
      `SELECT j.*, a.status AS auto_dial_status_current
       FROM attica_justdial_leads j
       LEFT JOIN attica_auto_dial_leads a ON a.id=j.auto_dial_lead_id
       ${whereClause}
       ORDER BY j.received_at DESC
       LIMIT 500`,
      params
    );
    const result = await createFollowUpsFromJustDialLeadRows(rows);
    return res.json({
      success: true,
      source: 'justdial',
      requested: leadIds.length || rows.length,
      processed: result.processed,
      skipped: result.skipped,
    });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

app.post('/api/justdial/leads/:leadId/queue-autodial', async (req, res) => {
  try {
    const priorityQueue = parseSystemSettingBoolean(req.body?.priority ?? req.query?.priority, false);
    const [rows] = await pool.query(
      `SELECT j.*,
              a.status AS auto_dial_status_current,
              a.is_active AS auto_dial_is_active_current,
              a.retry_allowed AS auto_dial_retry_allowed_current,
              a.queue_exit_reason AS auto_dial_queue_exit_reason_current
       FROM attica_justdial_leads j
       LEFT JOIN attica_auto_dial_leads a ON a.id=j.auto_dial_lead_id
       WHERE j.leadid=?
       LIMIT 1`,
      [req.params.leadId]
    );
    if (!rows.length) return res.status(404).json({ error: 'Lead not found' });

    const lead = rows[0];
    const blockedContentReason = getBlockedLeadContentReason({
      name: lead.name,
      leadtype: lead.leadtype,
      category: lead.category,
      state: lead.state,
      city: lead.city,
      area: lead.area,
      brancharea: lead.brancharea,
      company: lead.company,
    });
    if (blockedContentReason) {
      if (lead.auto_dial_lead_id) {
        await pool.query(
          `UPDATE attica_auto_dial_leads
           SET status='completed',
               is_active=0,
               retry_allowed=0,
               open_dedupe_number=NULL,
               queue_exit_reason='Spam Lead',
               last_error=?,
               completed_at=COALESCE(completed_at, NOW()),
               updated_at=NOW()
           WHERE id=?`,
          [blockedContentReason, lead.auto_dial_lead_id]
        );
      }
      await pool.query(
        `UPDATE attica_justdial_leads
         SET auto_dial_status='blocked',
             remarks=CONCAT_WS(' | ', NULLIF(remarks,''), ?),
             updated_at=NOW()
         WHERE leadid=?`,
        [blockedContentReason, lead.leadid]
      );
      return res.status(400).json({ error: 'Blocked spam lead content' });
    }
    const currentStatus = String(lead.auto_dial_status_current || lead.auto_dial_status || '').toLowerCase();
    const currentQueueIsActive = Number(lead.auto_dial_is_active_current ?? 1) > 0;
    const currentRetryAllowed = Number(lead.auto_dial_retry_allowed_current ?? 1) > 0;
    const currentQueueExitReason = resolveAutoDialTerminalQueueExitReason({
      queueExitReason: lead.auto_dial_queue_exit_reason_current,
    });
    if (lead.auto_dial_lead_id && currentQueueIsActive && ['pending', 'assigned', 'dialing'].includes(currentStatus)) {
      if (priorityQueue && currentStatus === 'pending') {
        await pool.query(
          `UPDATE attica_auto_dial_leads
           SET scheduled_for=NOW(),
               updated_at=NOW()
           WHERE id=?
             AND status='pending'`,
          [lead.auto_dial_lead_id]
        );
        autoDialLeadsResponseCache.clear();
        void triggerAutoDialAssignment('event');
      }
      return res.json({ success: true, alreadyQueued: true, autoDialLeadId: lead.auto_dial_lead_id });
    }
    if (lead.auto_dial_lead_id && currentStatus === 'completed') {
      await pool.query(
        `UPDATE attica_justdial_leads
         SET last_dial_requested_at=NOW()
         WHERE leadid=?`,
        [lead.leadid]
      );
      return res.status(409).json({
        error: 'This lead was already completed in auto follow-up.',
        autoDialLeadId: lead.auto_dial_lead_id,
      });
    }
    const mobileNumber = normalizeAutoDialPhone(lead.mobile || lead.phone);
    if (!mobileNumber) return res.status(400).json({ error: 'Lead does not have a valid phone number' });

    if (lead.auto_dial_lead_id && currentStatus === 'failed') {
      const reopenResult = await reopenFailedSourceAutoDialLead(pool, {
        leadId: lead.auto_dial_lead_id,
        phoneNumber: mobileNumber,
        sourceLabel: 'JustDial',
      });
      if (reopenResult.success) {
        await pool.query(
          `UPDATE attica_justdial_leads
           SET auto_dial_lead_id=?,
               auto_dial_status='queued',
               last_dial_requested_at=NOW()
           WHERE leadid=?`,
          [reopenResult.autoDialLeadId, lead.leadid]
        );
        if (priorityQueue) {
          await pool.query(
            `UPDATE attica_auto_dial_leads
             SET scheduled_for=NOW(),
                 updated_at=NOW()
             WHERE id=?`,
            [reopenResult.autoDialLeadId]
          );
        }
        autoDialLeadsResponseCache.clear();
        void triggerAutoDialAssignment('event');
        return res.json({
          success: true,
          autoDialLeadId: reopenResult.autoDialLeadId,
          requeued: Boolean(reopenResult.requeued),
          alreadyQueued: Boolean(reopenResult.alreadyQueued),
          deduped: Boolean(reopenResult.deduped),
        });
      }
      if (!currentRetryAllowed || currentQueueExitReason) {
        await pool.query(
          `UPDATE attica_justdial_leads
           SET auto_dial_status='failed',
               last_dial_requested_at=NOW()
           WHERE leadid=?`,
          [lead.leadid]
        );
        return res.status(409).json({
          error: reopenResult.error || buildAutoDialQueueBlockMessage(currentQueueExitReason || 'Rejected by Agent'),
          autoDialLeadId: lead.auto_dial_lead_id,
        });
      }
    }

    const queueBlock = await getAutoDialQueueBlockByPhone(pool, mobileNumber);
    if (queueBlock.error) {
      await pool.query(
        `UPDATE attica_justdial_leads
         SET auto_dial_lead_id=COALESCE(?, auto_dial_lead_id),
             auto_dial_status=?,
             last_dial_requested_at=NOW()
         WHERE leadid=?`,
        [queueBlock.autoDialLeadId || null, queueBlock.sourceStatus || 'failed', lead.leadid]
      );
      return res.status(409).json({
        error: queueBlock.error,
        autoDialLeadId: queueBlock.autoDialLeadId || '',
      });
    }

    const sourceState = cleanJustDialString(
      extractAutoDialSourceState({
        state: lead.state,
        area: lead.area || lead.brancharea || lead.city || lead.state || '',
      }),
      120
    );
    const preferredLanguage = resolveAutoDialPreferredLanguage({
      state: sourceState || lead.state,
      area: lead.area || lead.brancharea || lead.city || lead.state || '',
    });
    const existingLead = await findExistingOpenAutoDialLeadByPhone(pool, mobileNumber);
    if (existingLead?.id) {
      await pool.query(
        `UPDATE attica_auto_dial_leads
         SET customer_name=COALESCE(NULLIF(?, ''), customer_name),
             area=COALESCE(NULLIF(?, ''), area),
             source_state=COALESCE(NULLIF(?, ''), source_state),
             preferred_language=COALESCE(NULLIF(?, ''), preferred_language),
             lead_type=COALESCE(NULLIF(?, ''), lead_type),
             source_file=COALESCE(NULLIF(?, ''), source_file),
             scheduled_for=CASE WHEN ? THEN NOW() ELSE scheduled_for END,
             updated_at=NOW()
         WHERE id=?`,
        [
          lead.name || 'JustDial Lead',
          lead.area || lead.brancharea || lead.city || lead.state || '',
          sourceState,
          preferredLanguage,
          lead.leadtype || lead.category || 'JustDial',
          'JustDial Lead',
          priorityQueue ? 1 : 0,
          existingLead.id,
        ]
      );
      await pool.query(
        `UPDATE attica_justdial_leads
         SET auto_dial_lead_id=?,
             auto_dial_status='queued',
             last_dial_requested_at=NOW()
         WHERE leadid=?`,
        [existingLead.id, lead.leadid]
      );
      autoDialLeadsResponseCache.clear();
      if (priorityQueue) void triggerAutoDialAssignment('event');
      return res.json({ success: true, alreadyQueued: true, autoDialLeadId: existingLead.id, deduped: true });
    }
    const autoDialLeadId = `JDL-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    try {
      await pool.query(
        'INSERT INTO attica_auto_dial_leads (id,customer_name,mobile_number,normalized_number,open_dedupe_number,area,source_state,preferred_language,gold_weight,lead_type,source_file,status,shuffle_no,scheduled_for) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)',
        [
          autoDialLeadId,
          lead.name || 'JustDial Lead',
          mobileNumber,
          mobileNumber,
          getOpenAutoDialDedupeNumber(mobileNumber, 'pending', 1),
          lead.area || lead.brancharea || lead.city || lead.state || '',
          sourceState,
          preferredLanguage,
          '',
          lead.leadtype || lead.category || 'JustDial',
          'JustDial Lead',
          'pending',
          generateAutoDialShuffleNo(),
          priorityQueue ? new Date() : null,
        ]
      );
    } catch (insertError) {
      const duplicateLead = await findOpenAutoDialLeadAfterDuplicateError(pool, insertError, mobileNumber);
      if (!duplicateLead?.id) throw insertError;
      await pool.query(
        `UPDATE attica_justdial_leads
         SET auto_dial_lead_id=?,
             auto_dial_status='queued',
             last_dial_requested_at=NOW()
         WHERE leadid=?`,
        [duplicateLead.id, lead.leadid]
      );
      if (priorityQueue) {
        await pool.query(
          `UPDATE attica_auto_dial_leads
           SET scheduled_for=NOW(),
               updated_at=NOW()
           WHERE id=?`,
          [duplicateLead.id]
        );
      }
      autoDialLeadsResponseCache.clear();
      if (priorityQueue) void triggerAutoDialAssignment('event');
      return res.json({ success: true, alreadyQueued: true, autoDialLeadId: duplicateLead.id, deduped: true });
    }

    await pool.query(
      `UPDATE attica_justdial_leads
       SET auto_dial_lead_id=?,
           auto_dial_status='queued',
           last_dial_requested_at=NOW()
       WHERE leadid=?`,
      [autoDialLeadId, req.params.leadId]
    );

    autoDialLeadsResponseCache.clear();
    void triggerAutoDialAssignment('event');
    return res.json({ success: true, autoDialLeadId });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

