app.all([
  '/api/website-leads/form-receiver',
  '/api/website-leads/form_receiver',
  '/api/website-leads/form-push',
], async (req, res) => {
  if (!['GET', 'POST'].includes(req.method)) {
    return res.status(405).json({ success: false, error: 'BAD_REQUEST' });
  }

  const clientKey = readLeadReceiverApiKey(req);
  if (clientKey !== WEBSITE_FORM_LEADS_API_TOKEN) {
    return res.status(401).json({ success: false, error: 'UNAUTHORIZED' });
  }

  const sourceData = req.method === 'POST' ? (req.body || {}) : (req.query || {});
  const lead = buildWebsiteLeadFromFormApiRow(sourceData, 0);
  if (!lead.contactNumber) {
    return res.status(400).json({ success: false, error: 'MISSING_CONTACT_NUMBER' });
  }

  try {
    const result = await persistWebsiteFormLead(lead, { immediateQueue: true });
    if (result?.error === 'BLOCKED_SPAM_CONTENT') {
      return res.status(400).json({ success: false, error: result.error, reason: result.reason || '' });
    }
    if (!result?.success) {
      return res.status(400).json({ success: false, error: result?.error || 'INVALID_LEAD' });
    }

    autoDialLeadsResponseCache.clear();
    void triggerAutoDialAssignment('event');
    return res.json({
      success: true,
      source: 'website-form',
      leadid: result.leadid,
      duplicate: Boolean(result.duplicate),
      queued: Boolean(result.queued),
      alreadyQueued: Boolean(result.alreadyQueued),
      autoDialLeadId: result.autoDialLeadId || '',
    });
  } catch (error) {
    console.error('[website-form-leads] push failed:', error?.message || error);
    return res.status(500).json({ success: false, error: 'ERROR' });
  }
});

app.all('/api/website-leads/lead-receiver', async (req, res) => {
  if (!['GET', 'POST'].includes(req.method)) {
    return justDialBad(res, 405, 'BAD_REQUEST');
  }

  const clientKey = req.headers['x-api-key'] || '';
  if (clientKey !== WEBSITE_LEAD_API_KEY) {
    return justDialBad(res, 401, 'UNAUTHORIZED');
  }

  const sourceData = req.method === 'POST' ? (req.body || {}) : (req.query || {});
  const keys = Object.keys(sourceData);
  const ignoredFields = keys.filter((key) => !WEBSITE_LEAD_ALLOWED_FIELDS.includes(key));
  if (ignoredFields.length) {
    console.warn('[website-leads] Ignoring extra fields:', ignoredFields.join(','));
  }

  const customerName = cleanJustDialString(pickWebsiteLeadValue(sourceData, ['customer_name', 'customerName', 'customer', 'name', 'Name', 'Customer Name']), 255);
  const contactNumber = normalizeAutoDialPhone(pickWebsiteLeadValue(sourceData, ['contact_number', 'contactNumber', 'contact', 'mobile', 'phone', 'Contact number']));
  const goldWeight = cleanJustDialString(pickWebsiteLeadValue(sourceData, ['gold_weight', 'goldWeight', 'gold_weight_g', 'Gold Weight (g)']), 50);
  const language = cleanJustDialString(pickWebsiteLeadValue(sourceData, ['language', 'Language', 'preferred_language', 'preferredLanguage']), 30);
  const type = cleanJustDialString(pickWebsiteLeadValue(sourceData, ['type', 'Type']), 120);
  const state = cleanJustDialString(pickWebsiteLeadValue(sourceData, ['state', 'State']), 120);
  const city = cleanJustDialString(pickWebsiteLeadValue(sourceData, ['city', 'City']), 120);
  const area = cleanJustDialString(pickWebsiteLeadValue(sourceData, ['area', 'Area']), 150);
  const leadFrom = cleanJustDialString(pickWebsiteLeadValue(sourceData, ['lead_from', 'leadFrom', 'Lead From']), 120);
  const dateInput = cleanJustDialString(pickWebsiteLeadValue(sourceData, ['date', 'Date']), 10);
  const time = cleanJustDialString(pickWebsiteLeadValue(sourceData, ['time', 'Time']), 20);
  const device = cleanJustDialString(pickWebsiteLeadValue(sourceData, ['device', 'deviceType', 'Device']), 30);
  const utmSource = cleanJustDialString(pickWebsiteLeadValue(sourceData, ['utm_source', 'utmSource', 'UTM Source']), 255);
  const utmCampaignName = cleanJustDialString(pickWebsiteLeadValue(sourceData, ['utm_campaign_name', 'utm_campaign', 'utmCampaignName', 'utmCampaign', 'UTM Campaign', 'UTM Campaign Name']), 255);
  const keyword = cleanJustDialString(pickWebsiteLeadValue(sourceData, ['keyword', 'Keyword']), 255);
  const adgroupid = cleanJustDialString(pickWebsiteLeadValue(sourceData, ['adgroupid', 'adgroupId', 'adgroup_id', 'AdGroupId', 'Ad Group ID']), 100);
  const gclid = cleanJustDialString(pickWebsiteLeadValue(sourceData, ['gclid', 'GCLID', 'GCL Id', 'GCL ID']), 255);
  const remarks = cleanJustDialString(pickWebsiteLeadValue(sourceData, ['remarks', 'Remarks']), 1000);
  const comments = cleanJustDialString(pickWebsiteLeadValue(sourceData, ['comments', 'Comments']), 2000);
  const followupDateInput = cleanJustDialString(pickWebsiteLeadValue(sourceData, ['followup_date', 'followupDate', 'Followup Date']), 10);

  const leadDate = normalizeWebsiteLeadDate(dateInput) || new Date().toISOString().slice(0, 10);
  const followupDate = normalizeWebsiteLeadDate(followupDateInput);
  if (!contactNumber) return justDialBad(res, 400, 'MISSING_CONTACT_NUMBER');
  const blockedContentReason = getBlockedLeadContentReason({
    customer_name: customerName,
    name: customerName,
    type,
    state,
    city,
    area,
    lead_from: leadFrom,
    remarks,
    comments,
  });
  if (blockedContentReason) {
    console.warn('[website-leads] blocked spam lead content:', blockedContentReason);
    return justDialBad(res, 400, 'BLOCKED_SPAM_CONTENT');
  }

  const leadidInput = cleanJustDialString(sourceData.leadid, 255);
  const leadid = leadidInput || `WL-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
  const rawPayload = JSON.stringify({
    ...sourceData,
    language,
  });

  try {
    const duplicateLead = await findExistingWebsiteLeadDuplicate({
      leadid,
      phone10: contactNumber,
      leadDate,
    });
    if (duplicateLead) {
      await updateWebsiteLeadMarketingFields(duplicateLead.leadid, {
        utmSource,
        utmCampaignName,
        keyword,
        adgroupid,
        gclid,
        rawPayload,
      });
      queueSourceLeadForAutoDial('website', duplicateLead.leadid);
      enqueueAisensyLeadCampaign('website', duplicateLead);
      return res.status(200).type('text/plain; charset=utf-8').send('SUCCESS');
    }

    await pool.query(
      `INSERT INTO attica_website_leads
      (leadid,customer_name,contact_number,gold_weight,language,lead_type,state,city,area,lead_from,lead_date,lead_time,device,utm_source,utm_campaign_name,keyword,adgroupid,gclid,remarks,comments,followup_date,raw_payload)
      VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
      ON DUPLICATE KEY UPDATE
        customer_name=VALUES(customer_name),
        contact_number=VALUES(contact_number),
        gold_weight=VALUES(gold_weight),
        language=VALUES(language),
        lead_type=VALUES(lead_type),
        state=VALUES(state),
        city=VALUES(city),
        area=VALUES(area),
        lead_from=VALUES(lead_from),
        lead_date=VALUES(lead_date),
        lead_time=VALUES(lead_time),
        device=VALUES(device),
        utm_source=VALUES(utm_source),
        utm_campaign_name=VALUES(utm_campaign_name),
        keyword=VALUES(keyword),
        adgroupid=VALUES(adgroupid),
        gclid=VALUES(gclid),
        remarks=VALUES(remarks),
        comments=VALUES(comments),
        followup_date=VALUES(followup_date),
        raw_payload=VALUES(raw_payload),
        received_at=NOW()`,
      [
        leadid,
        customerName,
        contactNumber,
        goldWeight,
        language,
        type,
        state,
        city,
        area,
        leadFrom,
        leadDate,
        time,
        device,
        utmSource,
        utmCampaignName,
        keyword,
        adgroupid,
        gclid,
        remarks,
        comments,
        followupDate,
        rawPayload,
      ]
    );
    queueSourceLeadForAutoDial('website', leadid);
    enqueueAisensyLeadCampaign('website', {
      leadid,
      customerName,
      contactNumber,
      goldWeight,
      language,
      type,
      state,
      city,
      area,
      leadFrom,
    });
    return res.status(200).type('text/plain; charset=utf-8').send('SUCCESS');
  } catch (error) {
    return justDialBad(res, 500, 'ERROR');
  }
});

const SEO_MARKETING_LEAD_DEFAULT_LIMIT = 50;
const SEO_MARKETING_LEAD_MAX_LIMIT = 100;
const SEO_MARKETING_SUMMARY_ROW_LIMIT = 10000;
const SEO_MARKETING_LINKED_BILL_CACHE_MS = 2 * 60 * 1000;
const seoMarketingLinkedBillCache = new Map();
const SEO_MARKETING_LINKED_BILL_CACHE_DIR = process.env.ATTICA_SEO_MARKETING_LINKED_BILL_CACHE_DIR || '/tmp/attica-seo-marketing-linked-bills';
const seoMarketingRemoteSyncInFlight = new Set();
const SEO_MARKETING_RESPONSE_CACHE_MS = 60 * 1000;
const SEO_MARKETING_RESPONSE_CACHE_DIR = process.env.ATTICA_SEO_MARKETING_RESPONSE_CACHE_DIR || '/tmp/attica-seo-marketing-cache';

function normalizeSeoMarketingFilter(value, maxLength = 180) {
  return cleanJustDialString(value, maxLength);
}

function shouldForceSeoMarketingRemoteSync(query = {}) {
  return ['1', 'true', 'yes', 'force'].includes(
    String(query.sync || query.forceSync || '').trim().toLowerCase()
  );
}

async function runSeoMarketingRemoteSync(range) {
  await syncRemoteCustomerDataCacheIfStale(CUSTOMER_DATA_REMOTE_REPORT_SYNC_MS);
  const transactionSyncDates = enumerateSqlDatesInclusive(range.startDate, range.endDate, 7);
  for (const transactionSyncDate of transactionSyncDates) {
    await syncRemoteCustomerTransactionsForDate(transactionSyncDate);
  }
}

function queueSeoMarketingRemoteSync(range) {
  if (!range?.startDate || !range?.endDate) return;
  const key = `${range.startDate}:${range.endDate}`;
  if (seoMarketingRemoteSyncInFlight.has(key)) return;
  seoMarketingRemoteSyncInFlight.add(key);
  void runSeoMarketingRemoteSync(range)
    .catch((error) => {
      console.warn('[seo-marketing] background remote sync failed:', error?.message || error);
    })
    .finally(() => {
      setTimeout(() => seoMarketingRemoteSyncInFlight.delete(key), 60000).unref?.();
    });
}

function getSeoMarketingResponseCacheFile(key) {
  const digest = createHash('sha1').update(key).digest('hex');
  return join(SEO_MARKETING_RESPONSE_CACHE_DIR, `${digest}.json`);
}

function getSeoMarketingResponseCacheKey(query = {}) {
  const normalized = {};
  for (const key of Object.keys(query).sort()) {
    if (['sync', 'forceSync', '_', 't'].includes(key)) continue;
    normalized[key] = String(query[key] ?? '');
  }
  return JSON.stringify(normalized);
}

function readSeoMarketingResponseCache(key) {
  try {
    const parsed = JSON.parse(readFileSync(getSeoMarketingResponseCacheFile(key), 'utf8'));
    if (!parsed || Number(parsed.expiresAt) <= Date.now() || !parsed.payload) return null;
    return parsed.payload;
  } catch {
    return null;
  }
}

function writeSeoMarketingResponseCache(key, payload) {
  try {
    mkdirSync(SEO_MARKETING_RESPONSE_CACHE_DIR, { recursive: true, mode: 0o700 });
    writeFileSync(
      getSeoMarketingResponseCacheFile(key),
      JSON.stringify({ expiresAt: Date.now() + SEO_MARKETING_RESPONSE_CACHE_MS, payload }),
      { mode: 0o600 }
    );
  } catch (error) {
    console.warn('[seo-marketing] response cache write failed:', error?.message || error);
  }
}

function getSeoMarketingLinkedBillCacheFile(key) {
  const digest = createHash('sha1').update(key).digest('hex');
  return join(SEO_MARKETING_LINKED_BILL_CACHE_DIR, `${digest}.json`);
}

function readSharedSeoMarketingLinkedBillCache(key) {
  try {
    const parsed = JSON.parse(readFileSync(getSeoMarketingLinkedBillCacheFile(key), 'utf8'));
    if (!parsed || Number(parsed.expiresAt) <= Date.now() || !Array.isArray(parsed.rows)) return null;
    return parsed.rows;
  } catch {
    return null;
  }
}

function writeSharedSeoMarketingLinkedBillCache(key, rows) {
  try {
    mkdirSync(SEO_MARKETING_LINKED_BILL_CACHE_DIR, { recursive: true, mode: 0o700 });
    writeFileSync(
      getSeoMarketingLinkedBillCacheFile(key),
      JSON.stringify({ expiresAt: Date.now() + SEO_MARKETING_LINKED_BILL_CACHE_MS, rows }),
      { mode: 0o600 }
    );
  } catch (error) {
    console.warn('[seo-marketing] linked bill cache write failed:', error?.message || error);
  }
}

function getSeoMarketingDateRange(query = {}) {
  const endDate = normalizeQueryDate(query.endDate || query.to || query.dateTo) || getBusinessDateString();
  const startDate = normalizeQueryDate(query.startDate || query.from || query.dateFrom) || endDate;
  return {
    startDate,
    endDate,
    startDateTime: `${startDate} 00:00:00`,
    endDateTime: `${getNextQueryDate(endDate)} 00:00:00`,
  };
}

function getJsonStringSql(alias, ...paths) {
  const fields = paths.map((path) => `NULLIF(JSON_UNQUOTE(JSON_EXTRACT(${alias}.raw_payload, '$.${path}')), 'null')`);
  return `COALESCE(${fields.join(', ')}, '')`;
}

function getSeoMarketingLeadUnionSql() {
  const websiteLeadAt = `COALESCE(
    STR_TO_DATE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(w.raw_payload, '$.createdAt')), ''), '%Y-%m-%d %H:%i:%s'),
    STR_TO_DATE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(w.raw_payload, '$.Timestamp')), ''), '%Y-%m-%d %H:%i:%s'),
    STR_TO_DATE(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(w.raw_payload, '$.timestamp')), ''), '%Y-%m-%d %H:%i:%s'),
    CASE
      WHEN CONCAT(SUBSTRING(w.leadid, 4, 8), SUBSTRING(w.leadid, 12, 6)) REGEXP '^[0-9]{14}$'
      THEN STR_TO_DATE(CONCAT(SUBSTRING(w.leadid, 4, 8), SUBSTRING(w.leadid, 12, 6)), '%Y%m%d%H%i%s')
      ELSE NULL
    END,
    TIMESTAMP(COALESCE(w.lead_date, DATE(w.received_at)), COALESCE(NULLIF(w.lead_time, ''), TIME(w.received_at))),
    w.received_at
  )`;
  const justDialLeadAt = `TIMESTAMP(COALESCE(j.lead_date, DATE(j.received_at)), COALESCE(j.lead_time, TIME(j.received_at)))`;
  const metaLeadAt = `COALESCE(m.lead_created_at, m.received_at)`;
  const whatsappAdsLeadAt = `COALESCE(wa.first_seen_at, wa.last_seen_at)`;

  return `
    SELECT * FROM (
      SELECT
        'website' AS source_key,
        w.leadid AS lead_id,
        w.customer_name AS customer_name,
        RIGHT(REGEXP_REPLACE(COALESCE(w.contact_number, ''), '[^0-9]', ''), 10) AS phone,
        w.state AS state,
        COALESCE(NULLIF(w.city, ''), NULLIF(w.area, '')) AS city,
        w.language AS language,
        w.gold_weight AS gold_weight,
        w.lead_type AS lead_type,
        CASE
          WHEN w.lead_from = '${BLOG_LEADS_SOURCE_LABEL}' THEN 'Blog'
          WHEN w.lead_from = '${GOOGLE_LP_LEADS_SOURCE_LABEL}' THEN '${GOOGLE_LP_LEADS_SOURCE_LABEL}'
          WHEN LOWER(COALESCE(w.utm_source, '')) IN ('google organic', 'organic', 'seo') THEN 'Google Organic'
          WHEN COALESCE(w.gclid, '') <> ''
            OR LOWER(COALESCE(w.utm_source, '')) LIKE '%google%'
          THEN 'Google Ads'
          ELSE 'Website Direct'
        END AS source,
        CASE
          WHEN w.lead_from = '${BLOG_LEADS_SOURCE_LABEL}' THEN 'Website'
          WHEN w.lead_from = '${GOOGLE_LP_LEADS_SOURCE_LABEL}'
            OR COALESCE(w.gclid, '') <> ''
            OR LOWER(COALESCE(w.utm_source, '')) IN ('google organic', 'organic', 'seo')
            OR LOWER(COALESCE(w.utm_source, '')) LIKE '%google%'
          THEN 'Google'
          ELSE 'Website'
        END AS platform,
        COALESCE(NULLIF(${getJsonStringSql('w', 'utm_medium', 'utmMedium', 'medium')}, ''), '') AS medium,
        ${getJsonStringSql('w', 'utm_id', 'utmId', 'campaign_id', 'campaignId')} AS campaign_id,
        COALESCE(NULLIF(w.utm_campaign_name, ''), NULLIF(${getJsonStringSql('w', 'utm_campaign', 'utmCampaign', 'campaign')}, ''), 'N/A') AS campaign_name,
        w.adgroupid AS adset_or_adgroup_id,
        ${getJsonStringSql('w', 'adgroup_name', 'adGroupName', 'adgroupName')} AS adset_or_adgroup_name,
        ${getJsonStringSql('w', 'ad_id', 'adId')} AS ad_id,
        ${getJsonStringSql('w', 'ad_name', 'adName')} AS ad_name,
        ${getJsonStringSql('w', 'creative_id', 'creativeId')} AS creative_id,
        ${getJsonStringSql('w', 'creative_name', 'creativeName')} AS creative_name,
        ${getJsonStringSql('w', 'form_id', 'formId')} AS form_id,
        ${getJsonStringSql('w', 'form', 'form_name', 'formName')} AS form_name,
        COALESCE(NULLIF(w.keyword, ''), 'N/A') AS keyword,
        COALESCE(NULLIF(${getJsonStringSql('w', 'search_term', 'searchTerm')}, ''), 'N/A') AS search_term,
        ${getJsonStringSql('w', 'landing_page_url', 'landingPageUrl', 'landing_page', 'page_url', 'pageUrl', 'url', 'blog_post_url', 'blogPostUrl')} AS landing_page,
        ${getJsonStringSql('w', 'page_title', 'pageTitle', 'blog_post_title', 'blogPostTitle')} AS blog_title,
        COALESCE(NULLIF(w.lead_from, ''), 'Website Lead') AS import_file_name,
        ${websiteLeadAt} AS lead_created_at,
        w.auto_dial_lead_id,
        COALESCE(a.status, w.auto_dial_status, 'idle') AS auto_dial_status,
        a.assigned_agent_id,
        a.assigned_agent_name,
        a.assigned_at,
        a.dial_started_at,
        a.completed_at,
        a.last_error
      FROM attica_website_leads w
      LEFT JOIN attica_auto_dial_leads a ON a.id = w.auto_dial_lead_id
      WHERE LOWER(IFNULL(w.auto_dial_status, '')) <> 'blocked'
        AND ${websiteLeadAt} >= ?
        AND ${websiteLeadAt} < ?

      UNION ALL

      SELECT
        'meta' AS source_key,
        m.leadid AS lead_id,
        m.full_name AS customer_name,
        RIGHT(REGEXP_REPLACE(COALESCE(m.phone_number, ''), '[^0-9]', ''), 10) AS phone,
        m.state AS state,
        m.city AS city,
        '' AS language,
        m.grams AS gold_weight,
        m.lead_type AS lead_type,
        'Meta Ads' AS source,
        'Meta' AS platform,
        'paid_social' AS medium,
        ${getJsonStringSql('m', 'campaign_id', 'meta_campaign_id')} AS campaign_id,
        COALESCE(NULLIF(${getJsonStringSql('m', 'campaign_name', 'meta_campaign_name')}, ''), 'N/A') AS campaign_name,
        ${getJsonStringSql('m', 'adset_id', 'adgroup_id', 'meta_adset_id')} AS adset_or_adgroup_id,
        ${getJsonStringSql('m', 'adset_name', 'adgroup_name', 'meta_adset_name')} AS adset_or_adgroup_name,
        ${getJsonStringSql('m', 'ad_id', 'meta_ad_id')} AS ad_id,
        ${getJsonStringSql('m', 'ad_name', 'meta_ad_name')} AS ad_name,
        ${getJsonStringSql('m', 'creative_id', 'meta_creative_id')} AS creative_id,
        ${getJsonStringSql('m', 'creative_name', 'meta_creative_name')} AS creative_name,
        ${getJsonStringSql('m', 'form_id', 'meta_form_id')} AS form_id,
        COALESCE(NULLIF(${getJsonStringSql('m', 'form_name', 'lead_form', 'platform')}, ''), 'N/A') AS form_name,
        'N/A' AS keyword,
        'N/A' AS search_term,
        '' AS landing_page,
        '' AS blog_title,
        'Meta Lead Ads' AS import_file_name,
        ${metaLeadAt} AS lead_created_at,
        m.auto_dial_lead_id,
        COALESCE(a.status, m.auto_dial_status, 'idle') AS auto_dial_status,
        a.assigned_agent_id,
        a.assigned_agent_name,
        a.assigned_at,
        a.dial_started_at,
        a.completed_at,
        a.last_error
      FROM attica_meta_leads m
      LEFT JOIN attica_auto_dial_leads a ON a.id = m.auto_dial_lead_id
      WHERE LOWER(IFNULL(m.auto_dial_status, '')) <> 'blocked'
        AND ${metaLeadAt} >= ?
        AND ${metaLeadAt} < ?

      UNION ALL

      SELECT
        'justdial' AS source_key,
        j.leadid AS lead_id,
        j.name AS customer_name,
        RIGHT(REGEXP_REPLACE(COALESCE(NULLIF(j.mobile, ''), j.phone, ''), '[^0-9]', ''), 10) AS phone,
        j.state AS state,
        j.city AS city,
        '' AS language,
        '' AS gold_weight,
        j.leadtype AS lead_type,
        'Justdial' AS source,
        'Justdial' AS platform,
        '' AS medium,
        '' AS campaign_id,
        COALESCE(NULLIF(j.category, ''), NULLIF(j.leadtype, ''), 'N/A') AS campaign_name,
        '' AS adset_or_adgroup_id,
        '' AS adset_or_adgroup_name,
        '' AS ad_id,
        '' AS ad_name,
        '' AS creative_id,
        '' AS creative_name,
        '' AS form_id,
        'Justdial Lead' AS form_name,
        'N/A' AS keyword,
        'N/A' AS search_term,
        '' AS landing_page,
        '' AS blog_title,
        COALESCE(NULLIF(j.leadtype, ''), 'Justdial') AS import_file_name,
        ${justDialLeadAt} AS lead_created_at,
        j.auto_dial_lead_id,
        COALESCE(a.status, j.auto_dial_status, j.status, 'idle') AS auto_dial_status,
        a.assigned_agent_id,
        a.assigned_agent_name,
        a.assigned_at,
        a.dial_started_at,
        a.completed_at,
        a.last_error
      FROM attica_justdial_leads j
      LEFT JOIN attica_auto_dial_leads a ON a.id = j.auto_dial_lead_id
      WHERE LOWER(IFNULL(j.auto_dial_status, '')) <> 'blocked'
        AND ${justDialLeadAt} >= ?
        AND ${justDialLeadAt} < ?

      UNION ALL

      SELECT
        'whatsapp_ads' AS source_key,
        CONCAT('WAADS-', wa.id) AS lead_id,
        COALESCE(NULLIF(${getJsonStringSql('wa', 'name', 'fullName', 'full_name', 'contact.name', 'contact.fullName', 'contact.full_name')}, ''), 'N/A') AS customer_name,
        RIGHT(REGEXP_REPLACE(COALESCE(wa.customer_number, ''), '[^0-9]', ''), 10) AS phone,
        '' AS state,
        '' AS city,
        '' AS language,
        '' AS gold_weight,
        'WhatsApp Ads' AS lead_type,
        'WhatsApp Ads' AS source,
        'WhatsApp' AS platform,
        'paid_social' AS medium,
        '' AS campaign_id,
        wa.tag_name AS campaign_name,
        '' AS adset_or_adgroup_id,
        '' AS adset_or_adgroup_name,
        '' AS ad_id,
        '' AS ad_name,
        '' AS creative_id,
        '' AS creative_name,
        '' AS form_id,
        'AiSensy Contact Tag' AS form_name,
        'N/A' AS keyword,
        'N/A' AS search_term,
        '' AS landing_page,
        '' AS blog_title,
        'AiSensy contact.tag.updated' AS import_file_name,
        ${whatsappAdsLeadAt} AS lead_created_at,
        NULL AS auto_dial_lead_id,
        'idle' AS auto_dial_status,
        NULL AS assigned_agent_id,
        NULL AS assigned_agent_name,
        NULL AS assigned_at,
        NULL AS dial_started_at,
        NULL AS completed_at,
        NULL AS last_error
      FROM aisensy_tagged_contacts wa
      WHERE LOWER(wa.tag_name) IN ('whatsapp_campagin', 'whatsapp_campaign')
        AND ${whatsappAdsLeadAt} >= ?
        AND ${whatsappAdsLeadAt} < ?
    ) source_leads
    WHERE phone <> ''
  `;
}

function buildSeoMarketingFilterSql(query = {}) {
  const filters = [];
  const params = [];
  const addLikeFilter = (column, value) => {
    const normalized = normalizeSeoMarketingFilter(value);
    if (!normalized || normalized.toLowerCase() === 'all') return;
    filters.push(`LOWER(${column}) LIKE ?`);
    params.push(`%${normalized.toLowerCase()}%`);
  };

  addLikeFilter('source', query.source);
  addLikeFilter('platform', query.platform);
  addLikeFilter('campaign_name', query.campaign);
  addLikeFilter('adset_or_adgroup_name', query.adGroup || query.adset);
  addLikeFilter('ad_name', query.ad);
  addLikeFilter('form_name', query.form);
  addLikeFilter('keyword', query.keyword);
  addLikeFilter('search_term', query.searchTerm);
  addLikeFilter('landing_page', query.landingPage);
  addLikeFilter('state', query.state);
  addLikeFilter('language', query.language);

  const search = normalizeSeoMarketingFilter(query.search, 120).toLowerCase();
  if (search) {
    filters.push(`(
      LOWER(lead_id) LIKE ?
      OR LOWER(customer_name) LIKE ?
      OR phone LIKE ?
      OR LOWER(source) LIKE ?
      OR LOWER(platform) LIKE ?
      OR LOWER(campaign_name) LIKE ?
      OR LOWER(keyword) LIKE ?
      OR LOWER(search_term) LIKE ?
      OR LOWER(landing_page) LIKE ?
      OR LOWER(assigned_agent_name) LIKE ?
    )`);
    const searchParam = `%${search}%`;
    params.push(searchParam, searchParam, searchParam, searchParam, searchParam, searchParam, searchParam, searchParam, searchParam, searchParam);
  }

  return {
    sql: filters.length ? ` AND ${filters.join(' AND ')}` : '',
    params,
  };
}

function getSeoMarketingQueryParts(query = {}) {
  const range = getSeoMarketingDateRange(query);
  const baseParams = [
    range.startDateTime,
    range.endDateTime,
    range.startDateTime,
    range.endDateTime,
    range.startDateTime,
    range.endDateTime,
    range.startDateTime,
    range.endDateTime,
  ];
  const filters = buildSeoMarketingFilterSql(query);
  const baseSql = `${getSeoMarketingLeadUnionSql()}${filters.sql}`;
  return {
    range,
    baseSql,
    params: [...baseParams, ...filters.params],
  };
}

function chunkArray(values, size = 500) {
  const chunks = [];
  for (let index = 0; index < values.length; index += size) {
    chunks.push(values.slice(index, index + size));
  }
  return chunks;
}

async function fetchSeoMarketingCallStats(phones, options = {}) {
  const phoneList = [...new Set((phones || []).map(normalizeAutoDialPhone).filter(Boolean))];
  const stats = new Map();
  const range = options?.range || null;
  for (const chunk of chunkArray(phoneList, 500)) {
    const params = [chunk];
    let dateSql = '';
    if (range?.startDateTime && range?.endDateTime) {
      dateSql = ' AND created_at >= ? AND created_at < ?';
      params.push(range.startDateTime, range.endDateTime);
    }
    const [rows] = await pool.query(
      `SELECT
         normalized_customer_number AS phone,
         COUNT(*) AS call_attempts,
         SUM(CASE WHEN talk_duration_seconds > 0 OR answered_at IS NOT NULL THEN 1 ELSE 0 END) AS connected_calls,
         SUM(GREATEST(IFNULL(talk_duration_seconds, 0), 0)) AS total_talk_seconds,
         MAX(created_at) AS latest_call_at,
         SUBSTRING_INDEX(GROUP_CONCAT(COALESCE(NULLIF(agent_name, ''), agent_id, '') ORDER BY created_at DESC SEPARATOR '\u001f'), '\u001f', 1) AS latest_agent,
         SUBSTRING_INDEX(GROUP_CONCAT(COALESCE(NULLIF(agent_id, ''), '') ORDER BY created_at DESC SEPARATOR '\u001f'), '\u001f', 1) AS latest_agent_id,
         SUBSTRING_INDEX(GROUP_CONCAT(COALESCE(NULLIF(form_status, ''), NULLIF(purpose, ''), NULLIF(callback_status, ''), NULLIF(status, ''), '') ORDER BY created_at DESC SEPARATOR '\u001f'), '\u001f', 1) AS latest_disposition,
         SUBSTRING_INDEX(GROUP_CONCAT(COALESCE(NULLIF(status, ''), '') ORDER BY created_at DESC SEPARATOR '\u001f'), '\u001f', 1) AS latest_status,
         SUBSTRING_INDEX(GROUP_CONCAT(COALESCE(NULLIF(direction, ''), '') ORDER BY created_at DESC SEPARATOR '\u001f'), '\u001f', 1) AS latest_direction,
         SUBSTRING_INDEX(GROUP_CONCAT(COALESCE(talk_duration_seconds, 0) ORDER BY created_at DESC SEPARATOR '\u001f'), '\u001f', 1) AS latest_duration
       FROM attica_calls
       WHERE normalized_customer_number IN (?)
         ${dateSql}
       GROUP BY normalized_customer_number`,
      params
    );
    for (const row of rows) {
      const phone = normalizeAutoDialPhone(row.phone);
      if (!phone) continue;
      stats.set(phone, {
        callAttempts: Math.max(0, Number(row.call_attempts) || 0),
        connectedCalls: Math.max(0, Number(row.connected_calls) || 0),
        totalTalkSeconds: Math.max(0, Number(row.total_talk_seconds) || 0),
        latestCallAt: row.latest_call_at ? row.latest_call_at.toISOString() : '',
        latestAgent: cleanJustDialString(row.latest_agent, 120),
        latestAgentId: normalizeAgentId(row.latest_agent_id),
        latestDisposition: cleanJustDialString(row.latest_disposition, 150),
        latestStatus: cleanJustDialString(row.latest_status, 60),
        latestDirection: cleanJustDialString(row.latest_direction, 30),
        latestDuration: Math.max(0, Number(row.latest_duration) || 0),
      });
    }
  }
  return stats;
}

async function fetchSeoMarketingBillStats(phones, options = {}) {
  const phoneList = [...new Set((phones || []).map(normalizeAutoDialPhone).filter(Boolean))];
  const stats = new Map();
  const range = options?.range || null;
  for (const chunk of chunkArray(phoneList, 500)) {
    const params = [chunk];
    let dateSql = '';
    if (range?.startDate && range?.endDate) {
      dateSql = ' AND record_date BETWEEN ? AND ?';
      params.push(range.startDate, range.endDate);
    }
    const [rows] = await pool.query(
      `SELECT
         contact AS phone,
         COUNT(DISTINCT COALESCE(NULLIF(bill_id, ''), remote_id)) AS bill_count,
         MIN(record_date) AS first_bill_date,
         MAX(record_date) AS latest_bill_date,
         GROUP_CONCAT(DISTINCT COALESCE(NULLIF(bill_id, ''), remote_id) ORDER BY record_date DESC SEPARATOR ', ') AS bill_ids,
         SUM(COALESCE(CAST(NULLIF(REGEXP_REPLACE(gross_w, '[^0-9.]', ''), '') AS DECIMAL(12,2)), 0)) AS gross_weight,
         SUM(COALESCE(billing_amount, 0)) AS bill_amount,
         SUBSTRING_INDEX(GROUP_CONCAT(COALESCE(NULLIF(attributed_agent_name, ''), NULLIF(remote_agent, ''), '') ORDER BY record_date DESC SEPARATOR '\u001f'), '\u001f', 1) AS credited_agent
       FROM attica_remote_customer_data
       WHERE contact IN (?)
         AND LOWER(TRIM(status)) IN ('billed', 'release')
         ${dateSql}
       GROUP BY contact`,
      params
    );
    for (const row of rows) {
      const phone = normalizeAutoDialPhone(row.phone);
      if (!phone) continue;
      stats.set(phone, {
        billCount: Math.max(0, Number(row.bill_count) || 0),
        firstBillDate: row.first_bill_date ? row.first_bill_date.toISOString().slice(0, 10) : '',
        latestBillDate: row.latest_bill_date ? row.latest_bill_date.toISOString().slice(0, 10) : '',
        billIds: cleanJustDialString(row.bill_ids, 500),
        grossWeight: Math.max(0, Number(row.gross_weight) || 0),
        billAmount: Math.max(0, Number(row.bill_amount) || 0),
        creditedAgent: cleanJustDialString(row.credited_agent, 120),
      });
    }
  }
  return stats;
}

async function fetchSeoMarketingLinkedBillRowsByBillDate(range, query = {}, options = {}) {
  if (!range?.endDateTime || !range?.startDate || !range?.endDate) return [];
  const limit = Math.max(1, Math.min(50000, Number(options.limit) || 500));
  const cacheFilter = {
    startDate: range.startDate,
    endDate: range.endDate,
    limit,
    source: normalizeSeoMarketingFilter(query.source),
    platform: normalizeSeoMarketingFilter(query.platform),
    campaign: normalizeSeoMarketingFilter(query.campaign),
    adGroup: normalizeSeoMarketingFilter(query.adGroup || query.adset),
    ad: normalizeSeoMarketingFilter(query.ad),
    form: normalizeSeoMarketingFilter(query.form),
    keyword: normalizeSeoMarketingFilter(query.keyword),
    searchTerm: normalizeSeoMarketingFilter(query.searchTerm),
    landingPage: normalizeSeoMarketingFilter(query.landingPage),
    state: normalizeSeoMarketingFilter(query.state),
    language: normalizeSeoMarketingFilter(query.language),
    search: normalizeSeoMarketingFilter(query.search, 120),
  };
  const cacheKey = JSON.stringify(cacheFilter);
  const cached = seoMarketingLinkedBillCache.get(cacheKey);
  if (cached && cached.expiresAt > Date.now()) return cached.rows;
  const sharedCached = readSharedSeoMarketingLinkedBillCache(cacheKey);
  if (sharedCached) {
    seoMarketingLinkedBillCache.set(cacheKey, { rows: sharedCached, expiresAt: Date.now() + SEO_MARKETING_LINKED_BILL_CACHE_MS });
    return sharedCached;
  }

  const [billRows] = await pool.query(
    `SELECT
       COALESCE(NULLIF(bill_id, ''), remote_id) AS bill_key,
       SUBSTRING_INDEX(GROUP_CONCAT(customer_name ORDER BY synced_at DESC SEPARATOR '\u001f'), '\u001f', 1) AS customer_name,
       SUBSTRING_INDEX(GROUP_CONCAT(contact ORDER BY synced_at DESC SEPARATOR '\u001f'), '\u001f', 1) AS phone,
       MAX(record_date) AS bill_record_date,
       GROUP_CONCAT(DISTINCT COALESCE(NULLIF(bill_id, ''), remote_id) ORDER BY record_date DESC SEPARATOR ', ') AS bill_ids,
       1 AS bill_count,
       MAX(COALESCE(billing_amount, 0)) AS bill_amount,
       MAX(COALESCE(CAST(NULLIF(REGEXP_REPLACE(gross_w, '[^0-9.]', ''), '') AS DECIMAL(12,2)), 0)) AS gross_weight,
       SUBSTRING_INDEX(GROUP_CONCAT(COALESCE(NULLIF(attributed_agent_name, ''), NULLIF(remote_agent, ''), '') ORDER BY record_date DESC SEPARATOR '\u001f'), '\u001f', 1) AS credited_agent
     FROM attica_remote_customer_data
     WHERE record_date BETWEEN ? AND ?
       AND LOWER(TRIM(status)) IN ('billed', 'release')
       AND COALESCE(NULLIF(contact, ''), '') <> ''
     GROUP BY COALESCE(NULLIF(bill_id, ''), remote_id)
     ORDER BY MAX(record_date) DESC, COALESCE(NULLIF(MAX(bill_id), ''), MAX(remote_id)) DESC
     LIMIT ?`,
    [range.startDate, range.endDate, limit]
  );

  const phones = [...new Set(billRows.map((row) => normalizeAutoDialPhone(row.phone)).filter(Boolean))];
  if (!phones.length) {
    seoMarketingLinkedBillCache.set(cacheKey, { rows: [], expiresAt: Date.now() + SEO_MARKETING_LINKED_BILL_CACHE_MS });
    writeSharedSeoMarketingLinkedBillCache(cacheKey, []);
    return [];
  }

  const leadStartDateTime = '2000-01-01 00:00:00';
  const leadEndDateTime = range.endDateTime;
  const leadParams = [
    leadStartDateTime,
    leadEndDateTime,
    leadStartDateTime,
    leadEndDateTime,
    leadStartDateTime,
    leadEndDateTime,
    leadStartDateTime,
    leadEndDateTime,
  ];
  const filters = buildSeoMarketingFilterSql(query);
  const leadSql = `${getSeoMarketingLeadUnionSql()}${filters.sql} AND phone IN (?)`;
  const [leadRows] = await pool.query(
    `SELECT * FROM (${leadSql}) filtered ORDER BY lead_created_at ASC, lead_id ASC`,
    [...leadParams, ...filters.params, phones]
  );

  const leadsByPhone = new Map();
  for (const row of leadRows) {
    const phone = normalizeAutoDialPhone(row.phone);
    if (!phone) continue;
    const list = leadsByPhone.get(phone) || [];
    list.push(row);
    leadsByPhone.set(phone, list);
  }

  const matchedRows = [];
  for (const billRow of billRows) {
    const phone = normalizeAutoDialPhone(billRow.phone);
    if (!phone) continue;
    const billDateString = billRow.bill_record_date instanceof Date
      ? billRow.bill_record_date.toISOString().slice(0, 10)
      : String(billRow.bill_record_date || '').slice(0, 10);
    const billCutoff = new Date(`${billDateString}T23:59:59+05:30`);
    const matchingLead = (leadsByPhone.get(phone) || []).find((leadRow) => {
      const leadDate = leadRow.lead_created_at instanceof Date
        ? leadRow.lead_created_at
        : leadRow.lead_created_at ? new Date(leadRow.lead_created_at) : null;
      return leadDate && leadDate <= billCutoff;
    });
    if (!matchingLead) continue;
    matchedRows.push({ ...matchingLead, ...billRow, phone });
  }

  const callStatsByPhone = await fetchSeoMarketingCallStats(phones, { range });
  const serializedRows = matchedRows.map((row) => {
    const phone = normalizeAutoDialPhone(row.phone);
    const callStats = callStatsByPhone.get(phone) || {
      callAttempts: 0,
      connectedCalls: 0,
      totalTalkSeconds: 0,
      latestCallAt: '',
      latestAgent: '',
      latestAgentId: '',
      latestDisposition: '',
      latestStatus: '',
      latestDirection: '',
      latestDuration: 0,
    };
    const billAmount = Math.max(0, Number(row.bill_amount) || 0);
    const grossWeight = Math.max(0, Number(row.gross_weight) || 0);
    const billCount = Math.max(0, Number(row.bill_count) || 0);
    const leadCreatedAt = row.lead_created_at instanceof Date ? row.lead_created_at : row.lead_created_at ? new Date(row.lead_created_at) : null;
    const billDate = row.bill_record_date instanceof Date ? row.bill_record_date.toISOString().slice(0, 10) : String(row.bill_record_date || '').slice(0, 10);
    const baseRow = {
      leadDate: leadCreatedAt ? formatDateInZone(leadCreatedAt) : '',
      leadTime: leadCreatedAt ? formatTimeInZone(leadCreatedAt) : '',
      leadCreatedAt: leadCreatedAt ? leadCreatedAt.toISOString() : '',
      leadId: cleanJustDialString(row.lead_id, 120),
      customerName: cleanJustDialString(row.customer_name, 180) || 'N/A',
      customerNumber: phone,
      source: cleanJustDialString(row.source, 80) || 'Other',
      platform: cleanJustDialString(row.platform, 80) || 'Other',
      medium: cleanJustDialString(row.medium, 80),
      campaignId: cleanJustDialString(row.campaign_id, 120),
      campaignName: cleanJustDialString(row.campaign_name, 180) || 'N/A',
      adSetOrAdGroupId: cleanJustDialString(row.adset_or_adgroup_id, 120),
      adSetOrAdGroupName: cleanJustDialString(row.adset_or_adgroup_name, 180),
      adId: cleanJustDialString(row.ad_id, 120),
      adName: cleanJustDialString(row.ad_name, 180),
      creativeId: cleanJustDialString(row.creative_id, 120),
      creativeName: cleanJustDialString(row.creative_name, 180),
      formId: cleanJustDialString(row.form_id, 120),
      formName: cleanJustDialString(row.form_name, 180),
      keyword: cleanJustDialString(row.keyword, 180) || 'N/A',
      searchTerm: cleanJustDialString(row.search_term, 180) || 'N/A',
      landingPage: cleanJustDialString(row.landing_page, 500),
      blogTitle: cleanJustDialString(row.blog_title, 250),
      state: cleanJustDialString(row.state, 120),
      city: cleanJustDialString(row.city, 120),
      language: cleanJustDialString(row.language, 40),
      goldWeight: cleanJustDialString(row.gold_weight, 80),
      leadType: cleanJustDialString(row.lead_type, 120),
      importFileName: cleanJustDialString(row.import_file_name, 180),
      autoDialLeadId: '',
      queueStatus: 'completed',
      assignedAgentId: normalizeAgentId(callStats.latestAgentId),
      assignedAgentName: cleanJustDialString(row.assigned_agent_name || callStats.latestAgent, 120),
      assignedAt: '',
      dialStartedAt: '',
      completedAt: '',
      latestError: '',
      callAttempts: callStats.callAttempts,
      connectedCalls: callStats.connectedCalls,
      totalTalkSeconds: callStats.totalTalkSeconds,
      totalTalkTime: formatDurationSeconds(callStats.totalTalkSeconds),
      latestCallAt: callStats.latestCallAt,
      disposition: callStats.latestDisposition,
      billStatus: 'Billed',
      billCount,
      billDate,
      billAmount,
      billIds: cleanJustDialString(row.bill_ids, 500),
      billingGrossWeight: grossWeight,
      creditedAgent: cleanJustDialString(row.credited_agent, 120),
      currentStage: 'Completed',
      businessStage: 'Billed',
    };
    return {
      ...baseRow,
      timeline: buildSeoLeadTimeline(baseRow, callStats, {
        billCount,
        latestBillDate: billDate,
        billAmount,
        grossWeight,
        billIds: baseRow.billIds,
        creditedAgent: baseRow.creditedAgent,
      }),
    };
  });
  seoMarketingLinkedBillCache.set(cacheKey, { rows: serializedRows, expiresAt: Date.now() + SEO_MARKETING_LINKED_BILL_CACHE_MS });
  writeSharedSeoMarketingLinkedBillCache(cacheKey, serializedRows);
  return serializedRows;
}

async function fetchSeoMarketingLinkedBillRowsForLeadRows(rows = [], options = {}) {
  const selectedLeadRows = Array.isArray(rows) ? rows : [];
  const limit = Math.max(1, Math.min(50000, Number(options.limit) || 500));
  const leadsByPhone = new Map();
  for (const row of selectedLeadRows) {
    const phone = normalizeAutoDialPhone(row?.customerNumber || row?.phone);
    if (!phone) continue;
    const leadCreatedAt = row.leadCreatedAt ? new Date(row.leadCreatedAt) : null;
    if (!leadCreatedAt || Number.isNaN(leadCreatedAt.getTime())) continue;
    const list = leadsByPhone.get(phone) || [];
    list.push({ ...row, leadCreatedAtDate: leadCreatedAt });
    leadsByPhone.set(phone, list);
  }
  for (const list of leadsByPhone.values()) {
    list.sort((left, right) =>
      left.leadCreatedAtDate.getTime() - right.leadCreatedAtDate.getTime()
      || String(left.leadId || '').localeCompare(String(right.leadId || ''))
    );
  }

  const phones = [...leadsByPhone.keys()];
  if (!phones.length) return [];

  const billRows = [];
  for (const chunk of chunkArray(phones, 500)) {
    const [rowsForChunk] = await pool.query(
      `SELECT
         COALESCE(NULLIF(bill_id, ''), remote_id) AS bill_key,
         SUBSTRING_INDEX(GROUP_CONCAT(customer_name ORDER BY synced_at DESC SEPARATOR '\u001f'), '\u001f', 1) AS customer_name,
         SUBSTRING_INDEX(GROUP_CONCAT(contact ORDER BY synced_at DESC SEPARATOR '\u001f'), '\u001f', 1) AS phone,
         MAX(record_date) AS bill_record_date,
         GROUP_CONCAT(DISTINCT COALESCE(NULLIF(bill_id, ''), remote_id) ORDER BY record_date DESC SEPARATOR ', ') AS bill_ids,
         1 AS bill_count,
         MAX(COALESCE(billing_amount, 0)) AS bill_amount,
         MAX(COALESCE(CAST(NULLIF(REGEXP_REPLACE(gross_w, '[^0-9.]', ''), '') AS DECIMAL(12,2)), 0)) AS gross_weight,
         SUBSTRING_INDEX(GROUP_CONCAT(COALESCE(NULLIF(attributed_agent_name, ''), NULLIF(remote_agent, ''), '') ORDER BY record_date DESC SEPARATOR '\u001f'), '\u001f', 1) AS credited_agent
       FROM attica_remote_customer_data
       WHERE contact IN (?)
         AND LOWER(TRIM(status)) IN ('billed', 'release')
         AND COALESCE(NULLIF(contact, ''), '') <> ''
       GROUP BY COALESCE(NULLIF(bill_id, ''), remote_id)
       ORDER BY MAX(record_date) DESC, COALESCE(NULLIF(MAX(bill_id), ''), MAX(remote_id)) DESC
       LIMIT ?`,
      [chunk, limit]
    );
    billRows.push(...rowsForChunk);
  }

  const seenBills = new Set();
  const matchedRows = [];
  for (const billRow of billRows) {
    const billKey = cleanJustDialString(billRow.bill_key, 160);
    if (!billKey || seenBills.has(billKey)) continue;
    const phone = normalizeAutoDialPhone(billRow.phone);
    if (!phone) continue;
    const billDateString = billRow.bill_record_date instanceof Date
      ? billRow.bill_record_date.toISOString().slice(0, 10)
      : String(billRow.bill_record_date || '').slice(0, 10);
    const billCutoff = new Date(`${billDateString}T23:59:59+05:30`);
    const matchingLead = (leadsByPhone.get(phone) || []).find((leadRow) => leadRow.leadCreatedAtDate <= billCutoff);
    if (!matchingLead) continue;
    seenBills.add(billKey);

    const billAmount = Math.max(0, Number(billRow.bill_amount) || 0);
    const grossWeight = Math.max(0, Number(billRow.gross_weight) || 0);
    const billCount = Math.max(0, Number(billRow.bill_count) || 0);
    const callStats = {
      callAttempts: Math.max(0, Number(matchingLead.callAttempts) || 0),
      connectedCalls: Math.max(0, Number(matchingLead.connectedCalls) || 0),
      totalTalkSeconds: Math.max(0, Number(matchingLead.totalTalkSeconds) || 0),
      latestCallAt: matchingLead.latestCallAt || '',
      latestAgent: matchingLead.assignedAgentName || '',
      latestAgentId: matchingLead.assignedAgentId || '',
      latestDisposition: matchingLead.disposition || '',
      latestStatus: '',
      latestDirection: '',
      latestDuration: 0,
    };
    const baseRow = {
      ...matchingLead,
      customerName: cleanJustDialString(billRow.customer_name, 180) || matchingLead.customerName || 'N/A',
      customerNumber: phone,
      billStatus: 'Billed',
      billCount,
      billDate: billDateString,
      billAmount,
      billIds: cleanJustDialString(billRow.bill_ids, 500),
      billingGrossWeight: grossWeight,
      creditedAgent: cleanJustDialString(billRow.credited_agent, 120),
      currentStage: 'Completed',
      businessStage: 'Billed',
    };
    matchedRows.push({
      ...baseRow,
      timeline: buildSeoLeadTimeline(baseRow, callStats, {
        billCount,
        latestBillDate: billDateString,
        billAmount,
        grossWeight,
        billIds: baseRow.billIds,
        creditedAgent: baseRow.creditedAgent,
      }),
    });
  }

  return matchedRows
    .sort((left, right) =>
      String(right.billDate || '').localeCompare(String(left.billDate || ''))
      || String(right.leadCreatedAt || '').localeCompare(String(left.leadCreatedAt || ''))
    )
    .slice(0, limit);
}

function getSeoLeadCallStatus(row, callStats, billStats) {
  if (billStats?.billCount > 0) return 'Completed';
  const status = String(row.queueStatus || row.auto_dial_status || '').trim().toLowerCase();
  if (callStats?.connectedCalls > 0) return 'Connected';
  if (status === 'dialing') return 'Dialing';
  if (status === 'assigned') return 'Assigned';
  if (status === 'pending' || status === 'queued') return 'Queued';
  if (status === 'completed') return 'Completed';
  if (status === 'failed') return 'Failed';
  if (status) return status.charAt(0).toUpperCase() + status.slice(1);
  return 'New';
}

function seoMarketingStageText(value) {
  return cleanJustDialString(value, 180).toLowerCase();
}

function isSeoMarketingQualifiedStage(value) {
  const text = seoMarketingStageText(value);
  const category = getDispositionCategory(value);
  return category === 'QL'
    || text === 'ql'
    || text.includes('planning to visit')
    || text.includes('tentative visit')
    || text.includes('coming to branch')
    || text.includes('coming to office')
    || text.includes('nearest branch')
    || text.includes('branch timing')
    || (text.includes('interested') && !text.includes('not interested'))
    || text.includes('margin reduce')
    || text.includes('increase quotation')
    || text.includes('speed up validation')
    || text.includes('door-step')
    || text.includes('door step');
}

function isSeoMarketingLostStage(value) {
  const text = seoMarketingStageText(value);
  const category = getDispositionCategory(value);
  return category === 'Lost'
    || category === 'L2 Lost & Complaints'
    || text === 'lost'
    || text.includes('l2 lost')
    || text.includes('abuse')
    || text.includes('not interested')
    || text.includes('wrong call')
    || text.includes('wrong number')
    || text.includes('job related')
    || text.includes('advertisement')
    || text.includes('general enquiry - other')
    || text.includes('disconnected - language barrier')
    || text.includes('spam')
    || text.includes('not feasible')
    || text.includes("can't send executive")
    || text.includes('cant send executive')
    || text.includes('quotation mismatch')
    || text.includes('bm behaviour')
    || text.includes('branch closed')
    || text.includes('without purity')
    || text.includes('service delay')
    || text.includes('staff behaviour')
    || text.includes('not serviceable')
    || text.includes('sold outside');
}

function isSeoMarketingBilledStage(value) {
  const text = seoMarketingStageText(value);
  const category = getDispositionCategory(value);
  return category === 'Billed'
    || text.includes('service enquiry - sell gold')
    || text.includes('service enquiry - buy gold')
    || text.includes('service enquiry - release gold')
    || text.includes('sale done')
    || text.includes('sold out')
    || text.includes('visited sold out')
    || text.includes('billed')
    || text.includes('final sale');
}

function isSeoMarketingFollowUpStage(disposition, status, direction, duration) {
  const text = seoMarketingStageText(disposition);
  const normalizedStatus = seoMarketingStageText(status);
  const normalizedDirection = normalizeCallDirection(direction);
  const latestDuration = Math.max(0, Number(duration) || 0);
  return text.includes('follow')
    || text.includes('pending')
    || text.includes('call back')
    || text.includes('callback')
    || text.includes('discuss and come')
    || (
      normalizedDirection === 'incoming'
      && latestDuration > 0
      && ['completed', 'answered', 'transferred'].includes(normalizedStatus)
      && (['rnr', 'na'].includes(text) || text.includes('ring no reply') || text.includes('no answer'))
    )
    || (
      normalizedStatus === 'completed'
      && (
        text.includes('customer disconnected')
        || text.includes('call disconnected')
        || text === 'disconnected'
        || text.includes('pending calls')
        || text === 'pending'
      )
    );
}

function getSeoLeadBusinessStage(row, callStats, billStats) {
  if (billStats?.billCount > 0) return 'Billed';
  const disposition = callStats?.latestDisposition || '';
  const status = callStats?.latestStatus || row.queueStatus || row.auto_dial_status || '';
  const direction = callStats?.latestDirection || '';
  const duration = callStats?.latestDuration || 0;
  if (disposition) {
    if (isSeoMarketingFollowUpStage(disposition, status, direction, duration)) return 'Follow Up / Call Back';
    if (!isSeoMarketingLostStage(disposition) && !isSeoMarketingBilledStage(disposition) && isSeoMarketingQualifiedStage(disposition)) return 'QL';
    if (isSeoMarketingLostStage(disposition)) return 'Lost';
    if (isSeoMarketingBilledStage(disposition)) return 'Billed';
    return getCallCategory({ form_status: disposition, callback_status: disposition, status, direction, talk_duration_seconds: duration }) || 'Enquiry';
  }
  return 'Enquiry';
}

function buildSeoLeadTimeline(row, callStats, billStats) {
  const timeline = [];
  if (row.leadCreatedAt) {
    timeline.push({ time: row.leadCreatedAt, event: `${row.source} lead received` });
  }
  if (row.autoDialLeadId) {
    timeline.push({ time: row.leadCreatedAt, event: 'Entered outbound dialer queue' });
  }
  if (row.assignedAgentName || row.assignedAgentId) {
    timeline.push({ time: row.assignedAt || row.leadCreatedAt, event: `Assigned to ${row.assignedAgentName || row.assignedAgentId}` });
  }
  if (row.dialStartedAt) {
    timeline.push({ time: row.dialStartedAt, event: 'Call attempted' });
  }
  if (callStats?.connectedCalls > 0) {
    timeline.push({ time: callStats.latestCallAt, event: `Customer connected with ${callStats.latestAgent || 'agent'}` });
  } else if (callStats?.callAttempts > 0) {
    timeline.push({ time: callStats.latestCallAt, event: callStats.latestDisposition || 'Call attempted' });
  }
  if (callStats?.latestDisposition) {
    timeline.push({ time: callStats.latestCallAt, event: `Disposition: ${callStats.latestDisposition}` });
  }
  if (billStats?.billCount > 0) {
    timeline.push({ time: billStats.latestBillDate, event: `Bill created${billStats.creditedAgent ? `, credited to ${billStats.creditedAgent}` : ''}` });
  }
  return timeline.filter((item) => item.time || item.event);
}

function normalizeSeoMarketingMetric(value) {
  const metric = cleanJustDialString(value, 80).toLowerCase().replace(/[^a-z0-9]+/g, '');
  const aliases = {
    leads: 'leads',
    leadstoday: 'leads',
    unique: 'unique',
    uniqueleads: 'unique',
    uniqueleadstoday: 'unique',
    contacted: 'contacted',
    contactedtoday: 'contacted',
    connected: 'connected',
    connectedtoday: 'connected',
    followups: 'followups',
    followup: 'followups',
    followupstoday: 'followups',
    ql: 'ql',
    qualified: 'ql',
    qualifiedleads: 'ql',
    qualifiedleadstoday: 'ql',
    lost: 'lost',
    lostleads: 'lost',
    lostleadstoday: 'lost',
    bills: 'bills',
    billstoday: 'bills',
    billing: 'bills',
    billingamount: 'bills',
    leadtobill: 'leadToBillRate',
    leadtobillrate: 'leadToBillRate',
    conversionrate: 'leadToBillRate',
    campaignspend: 'campaignSpend',
    spend: 'campaignSpend',
    costperbill: 'costPerBill',
  };
  return aliases[metric] || '';
}

function normalizeSeoMarketingLeadToBillView(value) {
  const normalized = cleanJustDialString(value, 40).toLowerCase();
  return normalized === 'unique-leads' || normalized === 'unique' ? 'unique-leads' : 'billed';
}

function getSeoMarketingUniqueLeadKey(row) {
  const phone = normalizeAutoDialPhone(row?.customerNumber || row?.phone);
  if (phone) return `phone:${phone}`;
  const leadId = cleanJustDialString(row?.leadId || row?.lead_id || row?.id, 160);
  return leadId ? `lead:${leadId}` : '';
}

function dedupeSeoMarketingRowsByUniqueLead(rows) {
  const seen = new Set();
  return rows.filter((row) => {
    const key = getSeoMarketingUniqueLeadKey(row);
    if (!key || seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function filterSeoMarketingLeadToBillRows(rows, viewValue) {
  const uniqueRows = dedupeSeoMarketingRowsByUniqueLead(rows);
  if (normalizeSeoMarketingLeadToBillView(viewValue) === 'unique-leads') return uniqueRows;
  return uniqueRows.filter((row) => Math.max(0, Number(row.billCount) || 0) > 0);
}

function filterSeoMarketingRowsByMetric(rows, metricValue, options = {}) {
  const metric = normalizeSeoMarketingMetric(metricValue);
  if (!metric || metric === 'leads') return { metric: metric || '', rows };

  if (metric === 'unique') {
    return { metric, rows: dedupeSeoMarketingRowsByUniqueLead(rows) };
  }

  if (metric === 'leadToBillRate') {
    return { metric, rows: filterSeoMarketingLeadToBillRows(rows, options.view) };
  }

  if (metric === 'contacted') {
    return { metric, rows: rows.filter((row) => Math.max(0, Number(row.callAttempts) || 0) > 0) };
  }
  if (metric === 'connected') {
    return {
      metric,
      rows: rows.filter((row) =>
        Math.max(0, Number(row.connectedCalls) || 0) > 0
        && Math.max(0, Number(row.totalTalkSeconds) || 0) > 0
      ),
    };
  }
  if (metric === 'followups') {
    return { metric, rows: rows.filter((row) => String(row.businessStage || '').toLowerCase().includes('follow')) };
  }
  if (metric === 'ql') {
    return { metric, rows: rows.filter((row) => String(row.businessStage || '').toLowerCase() === 'ql') };
  }
  if (metric === 'lost') {
    return { metric, rows: rows.filter((row) => String(row.businessStage || '').toLowerCase().includes('lost')) };
  }
  if (metric === 'bills') {
    return { metric, rows: rows.filter((row) => Math.max(0, Number(row.billCount) || 0) > 0) };
  }
  if (metric === 'campaignSpend' || metric === 'costPerBill') {
    return { metric, rows: [] };
  }
  return { metric: '', rows };
}

function serializeSeoMarketingLeadRow(row, callStatsByPhone, billStatsByPhone) {
  const phone = normalizeAutoDialPhone(row.phone);
  const callStats = callStatsByPhone.get(phone) || {
    callAttempts: 0,
    connectedCalls: 0,
    totalTalkSeconds: 0,
    latestCallAt: '',
    latestAgent: '',
    latestAgentId: '',
    latestDisposition: '',
    latestStatus: '',
    latestDirection: '',
    latestDuration: 0,
  };
  const billStats = billStatsByPhone.get(phone) || {
    billCount: 0,
    firstBillDate: '',
    latestBillDate: '',
    billIds: '',
    grossWeight: 0,
    billAmount: 0,
    creditedAgent: '',
  };
  const baseRow = {
    leadDate: row.lead_created_at ? formatDateInZone(row.lead_created_at) : '',
    leadTime: row.lead_created_at ? formatTimeInZone(row.lead_created_at) : '',
    leadCreatedAt: row.lead_created_at ? row.lead_created_at.toISOString() : '',
    leadId: cleanJustDialString(row.lead_id, 120),
    customerName: cleanJustDialString(row.customer_name, 180) || 'N/A',
    customerNumber: phone,
    source: cleanJustDialString(row.source, 80) || 'Other',
    platform: cleanJustDialString(row.platform, 80) || 'Other',
    medium: cleanJustDialString(row.medium, 80),
    campaignId: cleanJustDialString(row.campaign_id, 120),
    campaignName: cleanJustDialString(row.campaign_name, 180) || 'N/A',
    adSetOrAdGroupId: cleanJustDialString(row.adset_or_adgroup_id, 120),
    adSetOrAdGroupName: cleanJustDialString(row.adset_or_adgroup_name, 180),
    adId: cleanJustDialString(row.ad_id, 120),
    adName: cleanJustDialString(row.ad_name, 180),
    creativeId: cleanJustDialString(row.creative_id, 120),
    creativeName: cleanJustDialString(row.creative_name, 180),
    formId: cleanJustDialString(row.form_id, 120),
    formName: cleanJustDialString(row.form_name, 180),
    keyword: cleanJustDialString(row.keyword, 180) || 'N/A',
    searchTerm: cleanJustDialString(row.search_term, 180) || 'N/A',
    landingPage: cleanJustDialString(row.landing_page, 500),
    blogTitle: cleanJustDialString(row.blog_title, 250),
    state: cleanJustDialString(row.state, 120),
    city: cleanJustDialString(row.city, 120),
    language: cleanJustDialString(row.language, 40),
    goldWeight: cleanJustDialString(row.gold_weight, 80),
    leadType: cleanJustDialString(row.lead_type, 120),
    importFileName: cleanJustDialString(row.import_file_name, 180),
    autoDialLeadId: cleanJustDialString(row.auto_dial_lead_id, 100),
    queueStatus: cleanJustDialString(row.auto_dial_status, 40) || 'idle',
    assignedAgentId: normalizeAgentId(row.assigned_agent_id || callStats.latestAgentId),
    assignedAgentName: cleanJustDialString(row.assigned_agent_name || callStats.latestAgent, 120),
    assignedAt: row.assigned_at ? row.assigned_at.toISOString() : '',
    dialStartedAt: row.dial_started_at ? row.dial_started_at.toISOString() : '',
    completedAt: row.completed_at ? row.completed_at.toISOString() : '',
    latestError: cleanJustDialString(row.last_error, 200),
    callAttempts: callStats.callAttempts,
    connectedCalls: callStats.connectedCalls,
    totalTalkSeconds: callStats.totalTalkSeconds,
    totalTalkTime: formatDurationSeconds(callStats.totalTalkSeconds),
    latestCallAt: callStats.latestCallAt,
    disposition: callStats.latestDisposition,
    billStatus: billStats.billCount > 0 ? 'Billed' : 'Not Billed',
    billCount: billStats.billCount,
    billDate: billStats.latestBillDate,
    billAmount: billStats.billAmount,
    billIds: billStats.billIds,
    billingGrossWeight: billStats.grossWeight,
    creditedAgent: billStats.creditedAgent,
  };
  return {
    ...baseRow,
    currentStage: getSeoLeadCallStatus(baseRow, callStats, billStats),
    businessStage: getSeoLeadBusinessStage(baseRow, callStats, billStats),
    timeline: buildSeoLeadTimeline(baseRow, callStats, billStats),
  };
}

function addSeoAggregate(map, key, row) {
  const aggregateKey = cleanJustDialString(key, 250) || 'N/A';
  const existing = map.get(aggregateKey) || {
    key: aggregateKey,
    platform: row.platform || '',
    source: row.source || '',
    campaignId: row.campaignId || '',
    campaignName: row.campaignName || '',
    adSetOrAdGroup: row.adSetOrAdGroupName || row.adSetOrAdGroupId || '',
    adOrCreative: row.adName || row.creativeName || row.adId || row.creativeId || '',
    form: row.formName || row.formId || '',
    keyword: row.keyword || '',
    searchTerm: row.searchTerm || '',
    landingPage: row.landingPage || '',
    blogTitle: row.blogTitle || '',
    leads: 0,
    contacted: 0,
    connected: 0,
    followUp: 0,
    ql: 0,
    lost: 0,
    bills: 0,
    spend: 0,
    clicks: 0,
    impressions: 0,
    billingAmount: 0,
    billingGrossWeight: 0,
  };
  existing.leads += 1;
  if (row.callAttempts > 0) existing.contacted += 1;
  if (row.connectedCalls > 0) existing.connected += 1;
  if (String(row.businessStage || '').toLowerCase().includes('follow')) existing.followUp += 1;
  if (String(row.businessStage || '').toLowerCase() === 'ql') existing.ql += 1;
  if (String(row.businessStage || '').toLowerCase().includes('lost')) existing.lost += 1;
  map.set(aggregateKey, existing);
}

function addSeoBillAggregate(map, key, row) {
  const aggregateKey = cleanJustDialString(key, 250) || 'N/A';
  const existing = map.get(aggregateKey) || {
    key: aggregateKey,
    platform: row.platform || '',
    source: row.source || '',
    campaignId: row.campaignId || '',
    campaignName: row.campaignName || '',
    adSetOrAdGroup: row.adSetOrAdGroupName || row.adSetOrAdGroupId || '',
    adOrCreative: row.adName || row.creativeName || row.adId || row.creativeId || '',
    form: row.formName || row.formId || '',
    keyword: row.keyword || '',
    searchTerm: row.searchTerm || '',
    landingPage: row.landingPage || '',
    blogTitle: row.blogTitle || '',
    leads: 0,
    contacted: 0,
    connected: 0,
    followUp: 0,
    ql: 0,
    lost: 0,
    bills: 0,
    spend: 0,
    clicks: 0,
    impressions: 0,
    billingAmount: 0,
    billingGrossWeight: 0,
  };
  existing.platform ||= row.platform || '';
  existing.source ||= row.source || '';
  existing.campaignId ||= row.campaignId || '';
  existing.campaignName ||= row.campaignName || '';
  existing.adSetOrAdGroup ||= row.adSetOrAdGroupName || row.adSetOrAdGroupId || '';
  existing.adOrCreative ||= row.adName || row.creativeName || row.adId || row.creativeId || '';
  existing.form ||= row.formName || row.formId || '';
  existing.keyword ||= row.keyword || '';
  existing.searchTerm ||= row.searchTerm || '';
  existing.landingPage ||= row.landingPage || '';
  existing.blogTitle ||= row.blogTitle || '';
  existing.bills += Math.max(0, Number(row.billCount) || 0);
  existing.billingAmount += Math.max(0, Number(row.billAmount) || 0);
  existing.billingGrossWeight += Math.max(0, Number(row.billingGrossWeight) || 0);
  map.set(aggregateKey, existing);
}

function applyGoogleAdsMetricToAggregate(row, metrics) {
  if (!metrics || String(row.platform || '').toLowerCase() !== 'google') return row;
  const campaignName = cleanJustDialString(row.campaignName, 180);
  const keyword = cleanJustDialString(row.keyword, 180);
  const campaignMetric = metrics.campaignMetrics?.get(campaignName.toLowerCase());
  const keywordMetric = metrics.keywordMetrics?.get(`${campaignName}|${keyword}`.toLowerCase())
    || metrics.keywordMetrics?.get(keyword.toLowerCase());
  const selectedMetric = keywordMetric || campaignMetric;
  if (!selectedMetric) return row;

  return {
    ...row,
    spend: Math.max(0, Number(row.spend) || 0) + Math.max(0, Number(selectedMetric.spend) || 0),
    clicks: Math.max(0, Number(row.clicks) || 0) + Math.max(0, Number(selectedMetric.clicks) || 0),
    impressions: Math.max(0, Number(row.impressions) || 0) + Math.max(0, Number(selectedMetric.impressions) || 0),
    googleConversions: Math.max(0, Number(row.googleConversions) || 0) + Math.max(0, Number(selectedMetric.googleConversions) || 0),
    googleConversionValue: Math.max(0, Number(row.googleConversionValue) || 0) + Math.max(0, Number(selectedMetric.googleConversionValue) || 0),
  };
}

function finalizeSeoAggregate(row) {
  const leads = Math.max(0, Number(row.leads) || 0);
  const bills = Math.max(0, Number(row.bills) || 0);
  const spend = Math.max(0, Number(row.spend) || 0);
  return {
    ...row,
    conversionRate: leads > 0 ? Number(((bills / leads) * 100).toFixed(2)) : 0,
    costPerLead: leads > 0 ? Number((spend / leads).toFixed(2)) : 0,
    costPerBill: bills > 0 ? Number((spend / bills).toFixed(2)) : 0,
    roas: spend > 0 ? Number(((Number(row.billingAmount) || 0) / spend).toFixed(2)) : 0,
  };
}

async function buildSeoMarketingReportPayload(rows, options = {}) {
  let googleAdsMetrics = null;
  try {
    googleAdsMetrics = await fetchGoogleAdsMetricsForDateRange(options.range);
  } catch (error) {
    console.warn('[seo-marketing/google-ads] metrics sync failed:', error?.message || error);
  }
  const linkedBillRows = Array.isArray(options.linkedBillRows) ? options.linkedBillRows : [];
  const billMetricRows = rows.filter((row) => Math.max(0, Number(row.billCount) || 0) > 0);
  const billRowsForSummary = linkedBillRows.length ? linkedBillRows : billMetricRows;
  const billHistoryRows = billRowsForSummary;
  const uniqueLeadKeys = new Set(rows.map((row) => getSeoMarketingUniqueLeadKey(row)).filter(Boolean));
  const uniqueBilledLeadIds = new Set(
    billRowsForSummary
      .map((row) => getSeoMarketingUniqueLeadKey(row))
      .filter(Boolean)
  );
  const billConversionHistory = [...billHistoryRows]
    .sort((left, right) => {
      const rightDate = String(right.billDate || right.leadDate || '');
      const leftDate = String(left.billDate || left.leadDate || '');
      return rightDate.localeCompare(leftDate)
        || String(right.leadCreatedAt || '').localeCompare(String(left.leadCreatedAt || ''));
    })
    .slice(0, options.billLimit || 500);
  const summary = {
    leadsToday: rows.length,
    uniqueLeadsToday: uniqueLeadKeys.size,
    contactedToday: rows.filter((row) => row.callAttempts > 0).length,
    connectedToday: rows.filter((row) => row.connectedCalls > 0).length,
    followUpsToday: rows.filter((row) => String(row.businessStage || '').toLowerCase().includes('follow')).length,
    qualifiedLeadsToday: rows.filter((row) => String(row.businessStage || '').toLowerCase() === 'ql').length,
    lostLeadsToday: rows.filter((row) => String(row.businessStage || '').toLowerCase().includes('lost')).length,
    billsToday: billRowsForSummary.reduce((sum, row) => sum + Math.max(0, Number(row.billCount) || 0), 0),
    billedLeadsToday: uniqueBilledLeadIds.size,
    totalBillingAmountToday: billRowsForSummary.reduce((sum, row) => sum + Math.max(0, Number(row.billAmount) || 0), 0),
    totalBillingGrossWeightToday: Number(billRowsForSummary.reduce((sum, row) => sum + Math.max(0, Number(row.billingGrossWeight) || 0), 0).toFixed(2)),
    campaignSpendToday: Number((googleAdsMetrics?.totalSpend || 0).toFixed(2)),
  };
  summary.leadToBillConversionRate = summary.uniqueLeadsToday > 0
    ? Number(((summary.billedLeadsToday / summary.uniqueLeadsToday) * 100).toFixed(2))
    : 0;
  summary.costPerLead = summary.uniqueLeadsToday > 0 && summary.campaignSpendToday > 0
    ? Number((summary.campaignSpendToday / summary.uniqueLeadsToday).toFixed(2))
    : 0;
  summary.costPerBill = summary.billsToday > 0 && summary.campaignSpendToday > 0
    ? Number((summary.campaignSpendToday / summary.billsToday).toFixed(2))
    : 0;

  const sourceMap = new Map();
  const campaignMap = new Map();
  const keywordMap = new Map();
  const landingMap = new Map();
  for (const row of rows) {
    addSeoAggregate(sourceMap, row.source, row);
    addSeoAggregate(campaignMap, `${row.platform}|${row.campaignId || row.campaignName}|${row.adSetOrAdGroupName || row.adSetOrAdGroupId}|${row.adName || row.creativeName}`, row);
    addSeoAggregate(keywordMap, `${row.platform}|${row.keyword || 'N/A'}|${row.searchTerm || 'N/A'}|${row.campaignName}`, row);
    addSeoAggregate(landingMap, row.landingPage || row.blogTitle || row.source, row);
  }
  for (const row of billRowsForSummary) {
    addSeoBillAggregate(sourceMap, row.source, row);
    addSeoBillAggregate(campaignMap, `${row.platform}|${row.campaignId || row.campaignName}|${row.adSetOrAdGroupName || row.adSetOrAdGroupId}|${row.adName || row.creativeName}`, row);
    addSeoBillAggregate(keywordMap, `${row.platform}|${row.keyword || 'N/A'}|${row.searchTerm || 'N/A'}|${row.campaignName}`, row);
    addSeoBillAggregate(landingMap, row.landingPage || row.blogTitle || row.source, row);
  }

  const sortAggregateRows = (values) => [...values]
    .map((row) => applyGoogleAdsMetricToAggregate(row, googleAdsMetrics))
    .map(finalizeSeoAggregate)
    .sort((left, right) => right.leads - left.leads || right.bills - left.bills)
    .slice(0, options.limit || 50);

  return {
    summary,
    sourceFunnel: sortAggregateRows(sourceMap.values()),
    campaignPerformance: sortAggregateRows(campaignMap.values()),
    keywordPerformance: sortAggregateRows(keywordMap.values()),
    landingPagePerformance: sortAggregateRows(landingMap.values()),
    billConversionHistory,
  };
}

async function fetchSeoMarketingLeadRows(query = {}, options = {}) {
  const { range, baseSql, params } = getSeoMarketingQueryParts(query);
  if (shouldForceSeoMarketingRemoteSync(query)) {
    await runSeoMarketingRemoteSync(range);
  } else {
    queueSeoMarketingRemoteSync(range);
  }

  const requestedPage = Number.parseInt(String(query.page || '1'), 10);
  const page = Math.max(1, Number.isFinite(requestedPage) ? requestedPage : 1);
  const requestedLimit = Number.parseInt(String(query.limit || SEO_MARKETING_LEAD_DEFAULT_LIMIT), 10);
  const limit = Math.min(SEO_MARKETING_LEAD_MAX_LIMIT, Math.max(1, Number.isFinite(requestedLimit) ? requestedLimit : SEO_MARKETING_LEAD_DEFAULT_LIMIT));
  const offset = (page - 1) * limit;
  const summaryLimit = Math.max(limit, Math.min(SEO_MARKETING_SUMMARY_ROW_LIMIT, Number(options.summaryLimit) || SEO_MARKETING_SUMMARY_ROW_LIMIT));
  const metric = normalizeSeoMarketingMetric(query.metric);

  const [summarySourceRows] = await pool.query(
    `SELECT * FROM (${baseSql}) filtered ORDER BY lead_created_at DESC, lead_id DESC LIMIT ?`,
    [...params, summaryLimit]
  );
  const summaryPhones = summarySourceRows.map((row) => row.phone).filter(Boolean);
  const [summaryCallStats, summaryBillStats] = await Promise.all([
    fetchSeoMarketingCallStats(summaryPhones, { range }),
    fetchSeoMarketingBillStats(summaryPhones, { range }),
  ]);

  const unfilteredSummaryRows = summarySourceRows.map((row) => serializeSeoMarketingLeadRow(row, summaryCallStats, summaryBillStats));
  const leadToBillView = normalizeSeoMarketingLeadToBillView(query.view);
  const metricResult = filterSeoMarketingRowsByMetric(unfilteredSummaryRows, metric, { view: leadToBillView });
  const summaryRows = metric ? metricResult.rows : unfilteredSummaryRows;
  const rows = summaryRows.slice(offset, offset + limit);
  const total = summaryRows.length;
  return {
    range,
    metric: metricResult.metric || metric,
    view: metric === 'leadToBillRate' ? leadToBillView : '',
    rows,
    unfilteredSummaryRows,
    summaryRows,
    page,
    limit,
    total,
    totalPages: Math.max(1, Math.ceil(total / limit)),
    partialSummary: summarySourceRows.length >= summaryLimit,
  };
}

function buildSeoMarketingCsv(rows) {
  const headers = [
    'Lead Date',
    'Lead Time',
    'Lead ID',
    'Customer Name',
    'Customer Number',
    'Source',
    'Platform',
    'Medium',
    'Campaign ID',
    'Campaign Name',
    'Ad Set / Ad Group',
    'Ad / Creative',
    'Form',
    'Keyword',
    'Search Term',
    'Landing Page / Blog',
    'Current Stage',
    'Business Stage',
    'Disposition',
    'Assigned Agent',
    'Call Attempts',
    'Connected Calls',
    'Total Talk Time',
    'Bill Status',
    'Bill Date',
    'Bill Count',
    'Bill IDs',
    'Bill Amount',
    'Billed Weight',
    'Import File Name',
  ];
  const csvRows = [
    headers,
    ...rows.map((row) => [
      row.leadDate,
      row.leadTime,
      row.leadId,
      row.customerName,
      row.customerNumber,
      row.source,
      row.platform,
      row.medium,
      row.campaignId,
      row.campaignName,
      row.adSetOrAdGroupName || row.adSetOrAdGroupId,
      row.adName || row.creativeName || row.adId || row.creativeId,
      row.formName || row.formId,
      row.keyword,
      row.searchTerm,
      row.landingPage || row.blogTitle,
      row.currentStage,
      row.businessStage,
      row.disposition,
      row.assignedAgentName || row.assignedAgentId,
      row.callAttempts,
      row.connectedCalls,
      row.totalTalkTime,
      row.billStatus,
      row.billDate,
      row.billCount,
      row.billIds,
      row.billAmount,
      row.billingGrossWeight,
      row.importFileName,
    ]),
  ];
  return `\uFEFF${csvRows.map((row) => row.map(escapeCsvCell).join(',')).join('\r\n')}`;
}

function getSeoMarketingSpendDateLabel(range = {}) {
  const startDate = normalizeQueryDate(range.startDate);
  const endDate = normalizeQueryDate(range.endDate);
  return startDate && endDate && startDate !== endDate ? `${startDate} to ${endDate}` : startDate || endDate || '';
}

function shouldIncludeGoogleAdsSpendForSeoQuery(query = {}) {
  const source = cleanJustDialString(query.source, 120).toLowerCase();
  const platform = cleanJustDialString(query.platform, 80).toLowerCase();
  if (platform && platform !== 'all' && platform !== 'google' && platform !== 'google ads') return false;
  if (!source || source === 'all') return true;
  return source.includes('google');
}

function buildSeoMarketingSpendCsv(rows) {
  const headers = [
    'Date',
    'Platform',
    'Ad Account',
    'Campaign ID',
    'Campaign Name',
    'Ad Set / Ad Group',
    'Ad / Creative',
    'Impressions',
    'Clicks',
    'Spend',
    'Leads',
    'Unique Leads',
    'Qualified Leads',
    'Billed Leads',
    'Bill Records',
    'Billing Amount',
    'CPL',
    'Cost per Qualified Lead',
    'Cost per Bill',
    'ROAS',
    'Last Synced At',
    'Sync Status',
  ];
  const csvRows = [
    headers,
    ...rows.map((row) => [
      row.date,
      row.platform,
      row.adAccount,
      row.campaignId,
      row.campaignName,
      row.adSetOrAdGroup,
      row.adOrCreative,
      row.impressions,
      row.clicks,
      row.spend,
      row.leads,
      row.uniqueLeads,
      row.qualifiedLeads,
      row.billedLeads,
      row.billRecords,
      row.billingAmount,
      row.cpl,
      row.costPerQualifiedLead,
      row.costPerBill,
      row.roas,
      row.lastSyncedAt,
      row.syncStatus,
    ]),
  ];
  return `\uFEFF${csvRows.map((row) => row.map(escapeCsvCell).join(',')).join('\r\n')}`;
}

async function fetchSeoMarketingSpendRows(query = {}) {
  const range = getSeoMarketingDateRange(query);
  const requestedPage = Number.parseInt(String(query.page || '1'), 10);
  const page = Math.max(1, Number.isFinite(requestedPage) ? requestedPage : 1);
  const requestedLimit = Number.parseInt(String(query.limit || 50), 10);
  const limit = Math.min(100, Math.max(1, Number.isFinite(requestedLimit) ? requestedLimit : 50));
  const offset = (page - 1) * limit;

  if (!shouldIncludeGoogleAdsSpendForSeoQuery(query)) {
    return {
      metric: 'spend',
      totalSpend: 0,
      page,
      limit,
      totalRows: 0,
      totalPages: 1,
      rows: [],
    };
  }

  const leadQuery = { ...query, metric: '', page: 1, limit: SEO_MARKETING_LEAD_MAX_LIMIT };
  const [leadResult, googleAdsMetrics] = await Promise.all([
    fetchSeoMarketingLeadRows(leadQuery, { summaryLimit: Math.min(50000, SEO_MARKETING_SUMMARY_ROW_LIMIT) }),
    fetchGoogleAdsMetricsForDateRange(range),
  ]);
  const linkedBillRows = await fetchSeoMarketingLinkedBillRowsForLeadRows(leadResult.unfilteredSummaryRows, {
    limit: SEO_MARKETING_SUMMARY_ROW_LIMIT,
  });
  const aggregates = await buildSeoMarketingReportPayload(leadResult.summaryRows, {
    range,
    linkedBillRows,
  });

  const aggregateByCampaign = new Map();
  for (const row of aggregates.campaignPerformance || []) {
    const campaignName = cleanJustDialString(row.campaignName, 180);
    if (!campaignName || campaignName === 'N/A') continue;
    const key = campaignName.toLowerCase();
    const existing = aggregateByCampaign.get(key) || {
      leads: 0,
      uniqueLeads: 0,
      qualifiedLeads: 0,
      billedLeads: 0,
      billRecords: 0,
      billingAmount: 0,
    };
    existing.leads += Math.max(0, Number(row.leads) || 0);
    existing.uniqueLeads += Math.max(0, Number(row.leads) || 0);
    existing.qualifiedLeads += Math.max(0, Number(row.ql) || 0);
    existing.billedLeads += Math.max(0, Number(row.bills) || 0);
    existing.billRecords += Math.max(0, Number(row.bills) || 0);
    existing.billingAmount += Math.max(0, Number(row.billingAmount) || 0);
    aggregateByCampaign.set(key, existing);
  }

  const campaignFilter = cleanJustDialString(query.campaign, 180).toLowerCase();
  const dateLabel = getSeoMarketingSpendDateLabel(range);
  const adAccount = normalizeGoogleAdsCustomerId(GOOGLE_MARKETING_ADS_CUSTOMER_ID);
  const lastSyncedAt = new Date().toISOString();
  const sourceRows = [...(googleAdsMetrics?.campaignMetrics || new Map()).entries()]
    .map(([key, metric]) => {
      const campaignName = cleanJustDialString(metric?.key || key, 180) || key;
      const leadAggregate = aggregateByCampaign.get(campaignName.toLowerCase()) || {};
      const spend = Number((Math.max(0, Number(metric?.spend) || 0)).toFixed(2));
      const leads = Math.max(0, Number(leadAggregate.leads) || 0);
      const qualifiedLeads = Math.max(0, Number(leadAggregate.qualifiedLeads) || 0);
      const billRecords = Math.max(0, Number(leadAggregate.billRecords) || 0);
      const billingAmount = Number((Math.max(0, Number(leadAggregate.billingAmount) || 0)).toFixed(2));
      return {
        date: dateLabel,
        platform: 'Google Ads',
        adAccount,
        campaignId: '',
        campaignName,
        adSetOrAdGroup: '',
        adOrCreative: '',
        impressions: Math.max(0, Number(metric?.impressions) || 0),
        clicks: Math.max(0, Number(metric?.clicks) || 0),
        spend,
        leads,
        uniqueLeads: Math.max(0, Number(leadAggregate.uniqueLeads) || leads),
        qualifiedLeads,
        billedLeads: Math.max(0, Number(leadAggregate.billedLeads) || billRecords),
        billRecords,
        billingAmount,
        cpl: leads > 0 ? Number((spend / leads).toFixed(2)) : 0,
        costPerQualifiedLead: qualifiedLeads > 0 ? Number((spend / qualifiedLeads).toFixed(2)) : 0,
        costPerBill: billRecords > 0 ? Number((spend / billRecords).toFixed(2)) : 0,
        roas: spend > 0 ? Number((billingAmount / spend).toFixed(2)) : 0,
        lastSyncedAt,
        syncStatus: googleAdsMetrics?.configured ? 'Synced' : 'Sync Pending',
      };
    })
    .filter((row) => row.spend > 0)
    .filter((row) => !campaignFilter || row.campaignName.toLowerCase().includes(campaignFilter))
    .sort((left, right) => right.spend - left.spend || right.leads - left.leads || left.campaignName.localeCompare(right.campaignName));

  const pagedRows = sourceRows.slice(offset, offset + limit);
  const totalSpend = Number(sourceRows.reduce((sum, row) => sum + Math.max(0, Number(row.spend) || 0), 0).toFixed(2));
  return {
    metric: 'spend',
    totalSpend,
    page,
    limit,
    totalRows: sourceRows.length,
    totalPages: Math.max(1, Math.ceil(sourceRows.length / limit)),
    rows: pagedRows,
  };
}

function getSeoMarketingRequestRole(req) {
  return String(req.query.role || req.get('x-user-role') || '').trim().toLowerCase();
}

function canAccessSeoMarketingDashboard(req) {
  const role = getSeoMarketingRequestRole(req);
  return role === 'superadmin' || role === 'seo';
}

app.get('/api/seo-marketing/leads', async (req, res) => {
  try {
    if (!canAccessSeoMarketingDashboard(req)) {
      return res.status(403).json({ error: 'Forbidden', rows: [] });
    }
    const cacheKey = getSeoMarketingResponseCacheKey(req.query);
    if (!shouldForceSeoMarketingRemoteSync(req.query)) {
      const cachedPayload = readSeoMarketingResponseCache(cacheKey);
      if (cachedPayload) return res.json(cachedPayload);
    }

    const result = await fetchSeoMarketingLeadRows(req.query);
    const linkedBillRows = await fetchSeoMarketingLinkedBillRowsForLeadRows(result.unfilteredSummaryRows, {
      limit: SEO_MARKETING_SUMMARY_ROW_LIMIT,
    });
    const aggregates = await buildSeoMarketingReportPayload(result.unfilteredSummaryRows, {
      range: result.range,
      linkedBillRows,
    });
    const metric = normalizeSeoMarketingMetric(req.query.metric);
    const responseRows = metric === 'bills'
      ? linkedBillRows.slice((result.page - 1) * result.limit, result.page * result.limit)
      : result.rows;
    const responseTotal = metric === 'bills' ? linkedBillRows.length : result.total;
    const payload = {
      range: result.range,
      metric: metric || result.metric,
      view: result.view,
      page: result.page,
      limit: result.limit,
      total: responseTotal,
      totalPages: Math.max(1, Math.ceil(responseTotal / result.limit)),
      partialSummary: result.partialSummary,
      rows: responseRows,
      ...aggregates,
    };
    if (!shouldForceSeoMarketingRemoteSync(req.query)) {
      writeSeoMarketingResponseCache(cacheKey, payload);
    }
    res.json(payload);
  } catch (e) {
    console.error('[seo-marketing/leads] failed:', e);
    res.status(500).json({ error: e.message, rows: [] });
  }
});

