app.post('/api/internal/meta-leads/ingest', async (req, res) => {
  try {
    if (!META_REALTIME_INGEST_SECRET) {
      return res.status(503).json({ error: 'Meta real-time ingest is not configured' });
    }
    const provided = Buffer.from(String(req.get('x-attica-meta-secret') || ''));
    const expected = Buffer.from(META_REALTIME_INGEST_SECRET);
    if (provided.length !== expected.length || !timingSafeEqual(provided, expected)) {
      return res.status(401).json({ error: 'Invalid Meta ingest credential' });
    }

    const leadId = cleanJustDialString(req.body?.metaLeadId || req.body?.leadid, 255);
    const phoneNumber = normalizeAutoDialPhone(req.body?.phoneNormalized || req.body?.phoneRaw || req.body?.phoneNumber);
    const fullName = cleanJustDialString(req.body?.customerName || req.body?.fullName, 255);
    const city = cleanJustDialString(req.body?.city, 120);
    const state = cleanJustDialString(req.body?.state, 120);
    const formName = cleanJustDialString(req.body?.formName, 120);
    const platform = cleanJustDialString(req.body?.platform, 120);
    if (!leadId || !phoneNumber) {
      return res.status(400).json({ error: 'metaLeadId and a valid phone number are required' });
    }
    const blockedContentReason = getBlockedLeadContentReason({ full_name: fullName, city, state, type: formName });
    if (blockedContentReason) {
      return res.status(400).json({ error: 'Blocked spam lead content' });
    }

    await pool.query(
      `INSERT INTO attica_meta_leads
        (leadid, full_name, phone_number, city, state, grams, lead_type, lead_created_at, raw_payload)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
       ON DUPLICATE KEY UPDATE
         full_name=COALESCE(NULLIF(VALUES(full_name),''),full_name),
         phone_number=COALESCE(NULLIF(VALUES(phone_number),''),phone_number),
         city=COALESCE(NULLIF(VALUES(city),''),city),
         state=COALESCE(NULLIF(VALUES(state),''),state),
         grams=COALESCE(NULLIF(VALUES(grams),''),grams),
         lead_type=COALESCE(NULLIF(VALUES(lead_type),''),lead_type),
         lead_created_at=COALESCE(VALUES(lead_created_at),lead_created_at),
         raw_payload=VALUES(raw_payload),
         updated_at=NOW()`,
      [
        leadId,
        fullName,
        phoneNumber,
        city,
        state,
        cleanJustDialString(req.body?.grams, 50),
        formName || platform || 'Meta Lead',
        toDatabaseDateTime(req.body?.createdTime) || new Date(),
        JSON.stringify(req.body || {}),
      ]
    );
    const queue = await queueSourceLeadForAutoDialNow('meta', leadId);
    return res.status(queue.ok ? 200 : (queue.status || 500)).json({
      success: Boolean(queue.ok),
      leadId,
      queue,
    });
  } catch (error) {
    return res.status(500).json({ error: error?.message || String(error) });
  }
});

app.get('/api/meta-leads', async (req, res) => {
  try {
    let syncResult = {
      cached: true,
      background: false,
      error: lastMetaLeadsSheetSyncError,
    };
    if (req.query?.sync === '1') {
      syncResult = await syncMetaLeadsFromSheet({ force: true });
    } else if (Date.now() - lastMetaLeadsSheetSyncAt >= META_LEADS_SYNC_CACHE_MS) {
      syncResult = {
        cached: false,
        background: true,
        error: lastMetaLeadsSheetSyncError,
      };
      if (!metaLeadsBackgroundSyncPromise) {
        metaLeadsBackgroundSyncPromise = syncMetaLeadsFromSheet()
          .catch((error) => {
            console.warn('[meta-leads] background sync failed:', error?.message || error);
            lastMetaLeadsSheetSyncError = error?.message || String(error);
          })
          .finally(() => {
            metaLeadsBackgroundSyncPromise = null;
          });
      }
    }
    const { startDate, endDate, limit } = getSourceLeadQueryWindow(req.query);
    const [rows] = await pool.query(
      `SELECT m.*,
              a.status AS auto_dial_status_current,
              a.retry_allowed AS auto_dial_retry_allowed_current,
              a.queue_exit_reason AS auto_dial_queue_exit_reason_current,
              a.last_error AS auto_dial_last_error_current
       FROM attica_meta_leads m
       LEFT JOIN attica_auto_dial_leads a ON a.id=m.auto_dial_lead_id
       WHERE LOWER(IFNULL(m.auto_dial_status, '')) <> 'blocked'
         AND DATE(COALESCE(m.lead_created_at, m.received_at)) BETWEEN ? AND ?
       ORDER BY COALESCE(m.lead_created_at, m.received_at) DESC, m.received_at DESC
       LIMIT ?`,
      [startDate, endDate, limit]
    );
    const visibleRows = dedupeLeadRowsByMobileAndDay(
      rows,
      (row) => row.phone_number,
      (row) => getLeadDayKey(row.lead_created_at, row.received_at)
    );
    res.json({
      rows: visibleRows.map(serializeMetaLeadRow),
      sync: syncResult,
    });
  } catch (e) { res.status(500).json({ error: e.message, rows: [] }); }
});

