// Kaleyra calls this URL for each delivery/status update.  It is intentionally
// idempotent: retries update the same row instead of creating another SMS.
app.all('/api/sms/dlr', async (req, res) => {
  const payload = parseSmsCallbackPayload(req);
  const expectedToken = readKaleyraDlrToken();
  const suppliedToken = firstSmsValue(payload, 'token');
  if (!expectedToken || suppliedToken !== expectedToken) return res.status(401).json({ error: 'Unauthorized' });

  try {
    const clientMessageId = firstSmsValue(payload, 'client_id', 'ref', 'custom', 'custom1').replace(/[?]+$/, '');
    const providerMessageId = firstSmsValue(payload, 'message_id', 'sid', 'id');
    const recipient = firstSmsValue(payload, 'recipient', 'mobile', 'to');
    const rawStatus = firstSmsValue(payload, 'status', 'status_trace');
    const deliveredAt = firstSmsValue(payload, 'delivered', 'delivered_at', 'delivat');
    const deliveryStatus = normalizeSmsDeliveryStatus(rawStatus, deliveredAt);
    const country = firstSmsValue(payload, 'country_name', 'country');
    const network = firstSmsValue(payload, 'network', 'operator');
    const cost = firstSmsValue(payload, 'price', 'credits', 'cost');
    const statusReason = firstSmsValue(payload, 'description', 'reason', 'status_trace');
    const statusTime = normalizeSmsDateTime(firstSmsValue(payload, 'status_time', 'delivered', 'delivered_at', 'delivat'));
    const sentTime = normalizeSmsDateTime(firstSmsValue(payload, 'sent_time', 'senttime', 'sentat'));
    const submitTime = normalizeSmsDateTime(firstSmsValue(payload, 'submittime', 'submit_time', 'submitat'));
    const normalizedDeliveredAt = normalizeSmsDateTime(deliveredAt);
    const payloadForStorage = { ...payload };
    delete payloadForStorage.token;
    if (payloadForStorage._query && typeof payloadForStorage._query === 'object') {
      payloadForStorage._query = { ...payloadForStorage._query };
      delete payloadForStorage._query.token;
    }
    const serializedPayload = JSON.stringify(payloadForStorage).slice(0, 200000);

    let rowId = null;
    if (clientMessageId) {
      const [rows] = await pool.query('SELECT id FROM attica_sms_log WHERE client_message_id=? ORDER BY id DESC LIMIT 1', [clientMessageId]);
      rowId = rows[0]?.id || null;
    }
    if (!rowId && providerMessageId) {
      const [rows] = await pool.query('SELECT id FROM attica_sms_log WHERE provider_message_id=? ORDER BY id DESC LIMIT 1', [providerMessageId]);
      rowId = rows[0]?.id || null;
    }
    if (!rowId && recipient) {
      const normalizedRecipient = normalizeSmsMobile(recipient);
      if (normalizedRecipient) {
        const [rows] = await pool.query(
          `SELECT id FROM attica_sms_log
           WHERE RIGHT(REPLACE(REPLACE(REPLACE(phone,'+',''),' ',''),'-',''),10)=?
             AND delivery_status IN ('queued','submitted')
           ORDER BY created_at DESC, id DESC LIMIT 1`,
          [normalizedRecipient.slice(-10)]
        );
        rowId = rows[0]?.id || null;
      }
    }
    if (!rowId) return res.status(200).json({ success: true, matched: false });

    const nextStatus = deliveryStatus === 'delivered' ? 'delivered' : deliveryStatus === 'failed' ? 'failed' : 'sent';
    await pool.query(
      `UPDATE attica_sms_log SET
         status=?, delivery_status=?, provider_message_id=COALESCE(NULLIF(?,''),provider_message_id),
         delivery_status_code=?, delivery_reason=COALESCE(NULLIF(?,''),delivery_reason),
         delivered_at=COALESCE(NULLIF(?,''),delivered_at), submitted_at=COALESCE(NULLIF(?,''),submitted_at),
         sent_at=COALESCE(NULLIF(?,''),sent_at), status_updated_at=COALESCE(NULLIF(?,''),NOW()),
         country=COALESCE(NULLIF(?,''),country), iso_code=COALESCE(NULLIF(?,''),iso_code),
         network=COALESCE(NULLIF(?,''),network), cost=COALESCE(NULLIF(?,''),cost),
         units=COALESCE(NULLIF(?,''),units), message_type=COALESCE(NULLIF(?,''),message_type),
         source=COALESCE(NULLIF(?,''),source), dlr_payload_json=?, updated_at=NOW()
       WHERE id=?`,
      [
        nextStatus, deliveryStatus, providerMessageId, rawStatus, statusReason,
        normalizedDeliveredAt, submitTime, sentTime, statusTime, country,
        firstSmsValue(payload, 'iso_code', 'iso'), network, cost,
        firstSmsValue(payload, 'units'), firstSmsValue(payload, 'type', 'category'),
        firstSmsValue(payload, 'source'), serializedPayload, rowId,
      ]
    );
    res.status(200).json({ success: true, matched: true });
  } catch (error) {
    console.error('[sms] delivery callback failed:', error?.message || error);
    // Provider callbacks should not be retried forever because of an internal
    // reporting error. The raw request is logged by the web server if needed.
    res.status(200).json({ success: false });
  }
});

