app.get('/api/admin-broadcast', async (req, res) => {
  try {
    const broadcastRow = await getActiveAdminBroadcast();
    const agentId = normalizeAgentId(req.query?.agentId);
    if (!agentId) {
      return res.json({
        active: Boolean(broadcastRow),
        message: broadcastRow?.message || '',
        broadcast: serializeAdminBroadcastRecord(broadcastRow),
      });
    }

    const [[agentRow]] = await pool.query(
      `SELECT id, role, status, is_logged_in, incoming_access, outgoing_access, follow_up_access, admin_message
         FROM attica_agents
        WHERE id=?
        LIMIT 1`,
      [agentId]
    );
    const applies = adminBroadcastAppliesToAgent(broadcastRow, agentRow);
    const privateMessage = String(agentRow?.admin_message || '').trim();
    const effectiveMessage = [
      applies ? String(broadcastRow?.message || '').trim() : '',
      privateMessage,
    ].filter(Boolean).filter((value, index, values) => values.indexOf(value) === index).join('  •  ');
    return res.json({
      active: applies,
      message: effectiveMessage,
      broadcast: applies ? serializeAdminBroadcastRecord(broadcastRow) : null,
    });
  } catch (error) {
    return res.status(500).json({ error: error?.message || 'Failed to load admin broadcast' });
  }
});

