app.post('/api/admin-broadcast', async (req, res) => {
  try {
    const message = String(req.body?.message || '').trim().slice(0, 500);
    const recipientScope = String(req.body?.recipientScope || 'all').trim().toLowerCase();
    const expiry = String(req.body?.expiry || 'until-cleared').trim().toLowerCase();
    if (!message) return res.status(400).json({ success: false, error: 'Broadcast message is required' });
    if (!ADMIN_BROADCAST_SCOPES.has(recipientScope)) return res.status(400).json({ success: false, error: 'Invalid recipient group' });
    if (!ADMIN_BROADCAST_EXPIRIES.has(expiry)) return res.status(400).json({ success: false, error: 'Invalid expiry option' });

    const sentById = String(req.body?.sentById || '').trim().slice(0, 80) || null;
    const sentByName = String(req.body?.sentByName || '').trim().slice(0, 160) || null;
    const expiresAt = getAdminBroadcastExpiryDate(expiry);
    const expiresAtDb = expiresAt ? toDatabaseDateTime(expiresAt.toISOString()) : null;

    await pool.query(
      `UPDATE attica_admin_broadcasts
          SET is_active=0, cleared_by_id=?, cleared_by_name=?, cleared_at=NOW()
        WHERE is_active=1`,
      [sentById, sentByName]
    );
    const [insertResult] = await pool.query(
      `INSERT INTO attica_admin_broadcasts
        (message, recipient_scope, expiry_code, expires_at, sent_by_id, sent_by_name, sent_at, is_active)
       VALUES (?, ?, ?, ?, ?, ?, NOW(), 1)`,
      [message, recipientScope, expiry, expiresAtDb, sentById, sentByName]
    );
    const [[row]] = await pool.query(
      `SELECT id, message, recipient_scope, expiry_code, expires_at,
              sent_by_id, sent_by_name, sent_at,
              cleared_by_id, cleared_by_name, cleared_at, is_active
         FROM attica_admin_broadcasts
        WHERE id=?
        LIMIT 1`,
      [insertResult.insertId]
    );
    uiRefreshState = {
      token: String(Date.now()),
      scope: 'agents',
      reason: 'admin-broadcast-sent',
      triggeredAt: new Date().toISOString(),
    };
    return res.json({ success: true, broadcast: serializeAdminBroadcastRecord(row), ...uiRefreshState });
  } catch (error) {
    return res.status(500).json({ success: false, error: error?.message || 'Failed to send admin broadcast' });
  }
});

