app.get('/api/agents/:id', async (req, res) => {
  try {
    const agentId = normalizeAgentId(req.params.id);
    if (!agentId) {
      return res.status(400).json({ error: 'Agent id required' });
    }
    const [[agentRow]] = await pool.query(
      `SELECT id, name, email, role, extension, shift, status, admin_message,
              is_logged_in, login_time, logout_time,
              last_login_at, last_logout_at, active_duration, break_time,
              follow_up_started_at, follow_up_duration,
              incoming_access, outgoing_access, follow_up_access,
              active_call_id, active_call_direction, active_call_started_at,
              call_state_updated_at, last_call_ended_at, last_login_ip,
              last_public_login_ip, last_workstation_ip, last_workstation_ip_seen_at,
              last_login_device_id,
              (
                SELECT sess.login_ip
                FROM attica_agent_sessions sess
                WHERE sess.agent_id=attica_agents.id
                  AND IFNULL(sess.login_ip, '') <> ''
                ORDER BY sess.login_at DESC, sess.id DESC
                LIMIT 1
              ) AS last_session_login_ip,
              (
                SELECT sess.public_login_ip
                FROM attica_agent_sessions sess
                WHERE sess.agent_id=attica_agents.id
                  AND IFNULL(sess.public_login_ip, '') <> ''
                ORDER BY sess.login_at DESC, sess.id DESC
                LIMIT 1
              ) AS last_session_public_login_ip,
              (
                SELECT sess.workstation_ip
                FROM attica_agent_sessions sess
                WHERE sess.agent_id=attica_agents.id
                  AND IFNULL(sess.workstation_ip, '') <> ''
                ORDER BY sess.workstation_ip_seen_at DESC, sess.login_at DESC, sess.id DESC
                LIMIT 1
              ) AS last_session_workstation_ip,
              (
                SELECT sess.workstation_ip_seen_at
                FROM attica_agent_sessions sess
                WHERE sess.agent_id=attica_agents.id
                  AND IFNULL(sess.workstation_ip, '') <> ''
                ORDER BY sess.workstation_ip_seen_at DESC, sess.login_at DESC, sess.id DESC
                LIMIT 1
              ) AS last_session_workstation_ip_seen_at,
              (
                SELECT sess.device_id
                FROM attica_agent_sessions sess
                WHERE sess.agent_id=attica_agents.id
                  AND IFNULL(sess.device_id, '') <> ''
                ORDER BY sess.login_at DESC, sess.id DESC
                LIMIT 1
              ) AS last_session_device_id
       FROM attica_agents
       WHERE id=?
       LIMIT 1`,
      [agentId]
    );
    if (!agentRow?.id) {
      return res.status(404).json({ error: 'Agent not found' });
    }
    const [breakRows] = await pool.query(
      `SELECT agent_id, break_type, started_at, created_at
       FROM attica_break_logs
       WHERE agent_id=?
         AND end_time IS NULL`,
      [agentId]
    );
    let liveChannels = [];
    try {
      liveChannels = readAsteriskConciseChannels();
    } catch (error) {
      console.warn('User management active-call channel snapshot skipped:', error?.message || error);
    }
    const pjsipContactIpByExtension = parsePjsipContactIpByExtension(readPjsipContactOutput());
    const [agent] = applyRuntimeAgentStatus([agentRow], breakRows, { liveChannels }).map((entry) => serializeAgentRecord({
      ...entry,
      sip_contact_ip: pjsipContactIpByExtension.get(normalizeSipExtension(entry.extension)) || '',
    }));
    return res.json(attachCurrentUiRefreshStateToAgents([agent])[0]);
  } catch (e) { return res.status(500).json({ error: e.message }); }
});

app.get('/api/agent-sessions', async (req, res) => {
  try {
    const limit = Math.max(1, Math.min(1000, parsePositiveInteger(req.query.limit, 300)));
    const rawDays = String(req.query.days || '').trim();
    const days = rawDays ? Math.max(0, Math.min(365, parsePositiveInteger(rawDays, 14))) : 0;
    const whereClauses = [];
    const params = [];

    if (days > 0) {
      whereClauses.push('COALESCE(login_at, logout_at, created_at, updated_at) >= DATE_SUB(NOW(), INTERVAL ? DAY)');
      params.push(days);
    }

    const [rows] = await pool.query(`
      SELECT id, agent_id, agent_name, role, extension,
             login_at, logout_at, login_time, logout_time,
             login_ip, public_login_ip, workstation_ip, workstation_ip_seen_at,
             device_id, active_duration, break_time, created_at, updated_at
      FROM attica_agent_sessions
      ${whereClauses.length ? `WHERE ${whereClauses.join(' AND ')}` : ''}
      ORDER BY login_at DESC, id DESC
      LIMIT ?
    `, [...params, limit]);
    res.json(rows.map((row) => serializeAgentSessionRecord(row)));
  } catch (e) { res.status(500).json({ error: e.message }); }
});

