app.put('/api/agents/:id', async (req, res) => {
  try {
    const b = req.body;
    const reportedComputerIp = getReportedComputerIp(
      b?.computerIp || b?.browserIp || b?.clientIp
    );
    const requestPublicLoginIp = (
      b?.isLoggedIn === true
      || b?.isLoggedIn === 1
      || b?.isLoggedIn === '1'
    ) ? getRequestClientIp(req) : '';
    const requestWorkstationIp = (
      b?.isLoggedIn === true
      || b?.isLoggedIn === 1
      || b?.isLoggedIn === '1'
    ) ? reportedComputerIp : '';
    const requestDeviceId = sanitizeLoginDeviceId(b?.deviceId);
    if (requestPublicLoginIp) {
      b.publicLoginIp = requestPublicLoginIp;
      b.loginIp = requestPublicLoginIp;
    }
    if (requestWorkstationIp) {
      b.workstationIp = requestWorkstationIp;
    }
    if (requestDeviceId) {
      b.deviceId = requestDeviceId;
    }
    if (isStaleAgentLoginUpdate(b)) {
      return res.status(409).json({
        success: false,
        error: 'Stale browser session ignored. Please login again for today.',
        staleSession: true,
      });
    }

    const fields = []; const vals = [];
    const queueAffectingAgentUpdate = [
      'status',
      'extension',
      'incomingAccess',
      'outgoingAccess',
      'followUpAccess',
    ].some((key) => b[key] !== undefined) || b.isLoggedIn === false;
    const agentListAffectingUpdate = [
      'name',
      'email',
      'role',
      'status',
      'extension',
      'shift',
      'logoutTime',
      'lastLogoutAt',
      'followUpStartedAt',
      'followUpDuration',
      'incomingAccess',
      'outgoingAccess',
      'followUpAccess',
      'adminMessage',
    ].some((key) => b[key] !== undefined) || b.isLoggedIn === false || Boolean(requestPublicLoginIp || requestWorkstationIp || requestDeviceId);
    const shouldSyncSessionHistory = [
      'isLoggedIn',
      'loginTime',
      'logoutTime',
      'lastLoginAt',
      'lastLogoutAt',
      'activeDuration',
      'breakTime',
    ].some((key) => b[key] !== undefined);
    if (b.status !== undefined && normalizeAgentAvailabilityStatus(b.status, '') === 'active') {
      const [[currentAgentForStatus]] = await pool.query(
        `SELECT status, incoming_access, outgoing_access, follow_up_access,
                (
                  SELECT COUNT(*)
                  FROM attica_break_logs bl
                  WHERE bl.agent_id=attica_agents.id
                    AND bl.end_time IS NULL
                ) AS open_break_count
         FROM attica_agents
         WHERE id=?
         LIMIT 1`,
        [req.params.id],
      );
      if (isAgentBreakStatusValue(currentAgentForStatus?.status) || Number(currentAgentForStatus?.open_break_count || 0) > 0) {
        b.status = resolveAgentWorkStatusFromAccessValues({
          incomingAccess: b.incomingAccess !== undefined
            ? normalizeAgentUpdateValue('incomingAccess', b.incomingAccess)
            : currentAgentForStatus?.incoming_access,
          outgoingAccess: b.outgoingAccess !== undefined
            ? normalizeAgentUpdateValue('outgoingAccess', b.outgoingAccess)
            : currentAgentForStatus?.outgoing_access,
          followUpAccess: b.followUpAccess !== undefined
            ? normalizeAgentUpdateValue('followUpAccess', b.followUpAccess)
            : currentAgentForStatus?.follow_up_access,
        });
      }
    }
    if (b.status !== undefined) {
      const requestedStatus = normalizeAgentAvailabilityStatus(b.status, '');
      if (requestedStatus === 'follow-up' || requestedStatus === 'outbound-auto' || requestedStatus === 'manual-outgoing') {
        const [[currentAgentForWorkMode]] = await pool.query(
          `SELECT incoming_access, outgoing_access, follow_up_access
           FROM attica_agents
           WHERE id=?
           LIMIT 1`,
          [req.params.id],
        );
        const incomingAccess = b.incomingAccess !== undefined
          ? normalizeAgentUpdateValue('incomingAccess', b.incomingAccess)
          : currentAgentForWorkMode?.incoming_access;
        const outgoingAccess = b.outgoingAccess !== undefined
          ? normalizeAgentUpdateValue('outgoingAccess', b.outgoingAccess)
          : currentAgentForWorkMode?.outgoing_access;
        const followUpAccess = b.followUpAccess !== undefined
          ? normalizeAgentUpdateValue('followUpAccess', b.followUpAccess)
          : currentAgentForWorkMode?.follow_up_access;
        const requestedModeAllowed = requestedStatus === 'follow-up'
          ? Number(followUpAccess) !== 0
          : Number(outgoingAccess) !== 0;
        if (!requestedModeAllowed) {
          b.status = resolveAgentWorkStatusFromAccessValues({
            incomingAccess,
            outgoingAccess,
            followUpAccess,
          });
        }
        if (b.status !== 'follow-up') {
          b.followUpStartedAt = '';
          b.followUpDuration = '';
        }
      }
    }
    const fieldMap = [
      ['name', 'name'],
      ['email', 'email'],
      ['role', 'role'],
      ['status', 'status'],
      ['extension', 'extension'],
      ['shift', 'shift'],
      ['isLoggedIn', 'is_logged_in'],
      ['loginTime', 'login_time'],
      ['logoutTime', 'logout_time'],
      ['lastLoginAt', 'last_login_at'],
      ['lastLogoutAt', 'last_logout_at'],
      ['activeDuration', 'active_duration'],
      ['breakTime', 'break_time'],
      ['followUpStartedAt', 'follow_up_started_at'],
      ['followUpDuration', 'follow_up_duration'],
      ['incomingAccess', 'incoming_access'],
      ['outgoingAccess', 'outgoing_access'],
      ['followUpAccess', 'follow_up_access'],
      ['adminMessage', 'admin_message'],
    ];
    for (const [requestKey, columnName] of fieldMap) {
      if (b[requestKey] !== undefined) {
        fields.push(columnName + '=?');
        vals.push(normalizeAgentUpdateValue(requestKey, b[requestKey]));
      }
    }
    if (requestPublicLoginIp) {
      fields.push('last_public_login_ip=?');
      vals.push(requestPublicLoginIp);
    }
    if (requestWorkstationIp) {
      fields.push('last_workstation_ip=?', 'last_workstation_ip_seen_at=NOW()', 'last_login_ip=?');
      vals.push(requestWorkstationIp, requestWorkstationIp);
    }
    if (requestDeviceId) {
      fields.push('last_login_device_id=?');
      vals.push(requestDeviceId);
    }
    if (b.isLoggedIn === false || b.isLoggedIn === 0 || b.isLoggedIn === '0') {
      fields.push(
        'active_call_id=NULL',
        'active_call_direction=NULL',
        'active_call_phone=NULL',
        'active_call_started_at=NULL',
        'wrap_up_started_at=NULL',
        'wrap_up_until=NULL',
        'wrap_up_call_id=NULL',
        'call_state_updated_at=NOW()',
      );
    }
    if (fields.length) {
      vals.push(req.params.id);
      await pool.query('UPDATE attica_agents SET ' + fields.join(',') + ' WHERE id=?', vals);
    } else if (!isAgentBreakStatusValue(b.status)) {
      return res.status(400).json({ error: 'No fields' });
    }
    if (b.status !== undefined) {
      if (isAgentBreakStatusValue(b.status)) {
        await ensureOpenBreakForAgent(req.params.id, {
          breakId: normalizeBreakLogId(b.breakId),
          breakDate: b.breakDate,
          startTime: b.breakStartTime,
          startedAt: b.breakStartedAt,
          agentName: b.agentName,
          breakType: b.breakType || b.status,
        });
      } else {
        const closedCount = await closeOpenBreaksForAgent(req.params.id, {
          breakId: normalizeBreakLogId(b.breakId),
          endTime: b.breakEndTime,
          endedAt: b.breakEndedAt,
          duration: b.breakDuration,
        });
        if (closedCount > 0 && ['active', 'outbound-auto', 'follow-up', 'manual-outgoing'].includes(b.status)) {
          void retryPendingMissedCallAssignments();
          void triggerAutoDialAssignment('event');
        }
      }
    }
    if (shouldSyncSessionHistory) {
      await syncAgentSessionHistory(req.params.id, b);
    }
    if (queueAffectingAgentUpdate) {
      await syncAsteriskQueuePauseStates([req.params.id]);
      invalidateLiveAgentSnapshotCache();
    }
    if (agentListAffectingUpdate) {
      invalidateAgentsEndpointCache();
    }
    res.json({ success: true });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

app.post('/api/agents/:id/call-slot/claim', async (req, res) => {
  try {
    const result = await runTransactionWithRetries(async (connection) => {
      const nextResult = await claimAgentCallSlot(connection, {
        agentId: req.params.id,
        callId: req.body?.callId,
        direction: req.body?.direction,
        fallbackAgentStatus: req.body?.fallbackAgentStatus || 'active',
        customerNumber: req.body?.customerNumber || req.body?.phone || '',
      });
      if (!nextResult.success) {
        const error = new Error(nextResult.error || 'Unable to reserve call slot');
        error.result = nextResult;
        error.statusCode = nextResult.statusCode || 409;
        error.skipTransactionRetry = true;
        throw error;
      }
      return nextResult;
    }, {
      attempts: 5,
      baseDelayMs: 150,
      label: `claim call slot for ${req.params.id}`,
    });
    res.json({ success: true });
  } catch (e) {
    if (e?.result && e?.skipTransactionRetry) {
      return res.status(e.statusCode || 409).json({ error: e.result.error || 'Unable to reserve call slot', success: false });
    }
    console.error('Call slot claim failed:', {
      agentId: cleanJustDialString(req.params.id, 20),
      callId: cleanCanonicalCallId(req.body?.callId, 120),
      direction: cleanJustDialString(req.body?.direction, 20),
      code: cleanJustDialString(e?.code || '', 40),
      message: e?.message || e,
    });
    res.status(isRetryableMysqlTransactionError(e) ? 503 : 500).json({ error: e.message, success: false });
  }
});

