app.put('/api/agents/:id/password', async (req, res) => {
  try {
    const { password } = req.body;
    if (!password || password.length < 6) return res.status(400).json({ error: 'Min 6 chars' });
    const [[agent]] = await pool.query('SELECT id, role, extension FROM attica_agents WHERE id=? LIMIT 1', [req.params.id]);
    if (!agent?.id) return res.status(404).json({ error: 'Agent not found' });

    await pool.query('UPDATE attica_agents SET password=? WHERE id=?', [password, req.params.id]);
    invalidateAgentsEndpointCache();

    let sipUpdated = false;
    if (agent.role === 'agent' && agent.extension) {
      sipUpdated = updateAgentSipPassword(agent.extension, password);
    }

    res.json({ success: true, sipUpdated });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// ==================== LOGIN ====================
app.post('/api/login', async (req, res) => {
  try {
    const { id, password } = req.body;
    const [rows] = await pool.query(`
      SELECT id, name, email, role, extension, shift, status,
             password AS sip_password,
             is_logged_in, login_time, logout_time,
             last_login_at, last_logout_at, active_duration, break_time,
             follow_up_started_at, follow_up_duration,
             incoming_access, outgoing_access, follow_up_access,
             last_login_ip, last_public_login_ip, last_workstation_ip,
             last_workstation_ip_seen_at, last_login_device_id
      FROM attica_agents
      WHERE id=? AND password=?
    `, [id, password]);
    if (rows.length === 0) return res.status(401).json({ error: 'Invalid credentials' });
    if (rows[0].status === 'inactive') return res.status(403).json({ error: 'Account inactive' });
    // Admin PBX credentials are separate from dashboard login passwords.
    if (rows[0].role !== 'agent') {
      rows[0].sip_password = getConfiguredSipPassword(rows[0].extension);
    }
    const reportedComputerIp = getReportedComputerIp(
      req.body?.computerIp || req.body?.browserIp || req.body?.clientIp
    );
    const publicLoginIp = getRequestClientIp(req);
    const workstationIp = reportedComputerIp;
    const deviceId = sanitizeLoginDeviceId(req.body?.deviceId);
    const loginAt = new Date();
    const loginAtDb = toDatabaseDateTime(loginAt.toISOString());
    const loginTime = formatTimeInZone(loginAt);
    await pool.query(
      `UPDATE attica_agents
          SET is_logged_in=1,
              login_time=?,
              last_login_at=?,
              logout_time=NULL,
              last_logout_at=NULL,
              last_public_login_ip=CASE WHEN ? <> '' THEN ? ELSE last_public_login_ip END,
              last_workstation_ip=CASE WHEN ? <> '' THEN ? ELSE last_workstation_ip END,
              last_workstation_ip_seen_at=CASE WHEN ? <> '' THEN NOW() ELSE last_workstation_ip_seen_at END,
              last_login_ip=CASE WHEN ? <> '' THEN ? ELSE last_login_ip END,
              last_login_device_id=CASE WHEN ? <> '' THEN ? ELSE last_login_device_id END
        WHERE id=?`,
      [
        loginTime,
        loginAtDb,
        publicLoginIp,
        publicLoginIp,
        workstationIp,
        workstationIp,
        workstationIp,
        workstationIp,
        workstationIp,
        deviceId,
        deviceId,
        id,
      ]
    );
    rows[0].is_logged_in = 1;
    rows[0].login_time = loginTime;
    rows[0].last_login_at = loginAtDb;
    rows[0].logout_time = null;
    rows[0].last_logout_at = null;
    if (publicLoginIp) rows[0].last_public_login_ip = publicLoginIp;
    if (workstationIp) {
      rows[0].last_workstation_ip = workstationIp;
      rows[0].last_workstation_ip_seen_at = new Date();
      rows[0].last_login_ip = workstationIp;
    }
    if (deviceId) rows[0].last_login_device_id = deviceId;
    await syncAgentSessionHistory(id, {
      isLoggedIn: true,
      loginTime,
      lastLoginAt: loginAtDb,
      publicLoginIp,
      workstationIp,
      deviceId,
      activeDuration: rows[0].active_duration || '',
      breakTime: rows[0].break_time || '',
    });
    invalidateAgentsEndpointCache();
    const [breaks] = await pool.query('SELECT agent_id, break_type, created_at FROM attica_break_logs WHERE end_time IS NULL AND agent_id=?', [id]);
    try {
      await Promise.race([
        syncAsteriskQueuePauseStates([id]),
        new Promise((_, reject) => setTimeout(() => reject(new Error('Queue sync timed out during login')), 6000)),
      ]);
    } catch (syncError) {
      console.warn('Login queue sync skipped:', {
        id,
        message: syncError?.message || String(syncError),
      });
    }
    const agent = applyRuntimeAgentStatus(rows, breaks)[0];
    res.json(serializeAgentRecord(agent));
  } catch (e) {
    console.error('Login request failed:', e);
    res.status(503).json({ error: 'Backend login unavailable' });
  }
});

