// ==================== SMART AUTOCOMPLETE ====================
app.get('/api/places/autocomplete', async (req, res) => {
  try {
    const query = String(req.query?.q || '').trim();
    if (!query || query.length < 2) return res.json([]);

    if (hasGooglePlacesApiKey()) {
      try {
        const googleSuggestions = await fetchGooglePlaceAutocompleteSuggestions(query);
        if (googleSuggestions.length > 0) {
          return res.json(googleSuggestions.slice(0, 15));
        }
      } catch (error) {
        console.error('Google Places autocomplete failed:', {
          query: cleanJustDialString(query, 120),
          message: error?.message || error,
        });
      }
    }

    try {
      const photonSuggestions = await fetchPhotonAutocompleteSuggestions(query);
      if (photonSuggestions.length > 0) {
        return res.json(photonSuggestions.slice(0, 15));
      }
    } catch (error) {
      console.error('Photon autocomplete failed:', {
        query: cleanJustDialString(query, 120),
        message: error?.message || error,
      });
    }

    const term = '%' + query + '%';
    
    // Search across all location fields
    const [rows] = await pool.query(
      `SELECT DISTINCT branchName as name, city, state, area, latitude, longitude FROM wp_branches_database 
       WHERE status=1 AND (
         branchName LIKE ? OR city LIKE ? OR area LIKE ? OR state LIKE ? OR 
         addressline LIKE ? OR pincode LIKE ?
       ) LIMIT 20`,
      [term, term, term, term, term, term]
    );
    
    // Build unique suggestions with context
    const seen = new Set();
    const suggestions = [];
    for (const r of rows) {
      // Add area suggestions
      if (r.area && r.area.toLowerCase().includes(query.toLowerCase()) && !seen.has(r.area)) {
        seen.add(r.area);
        suggestions.push({ description: r.area + ', ' + r.city + ', ' + r.state, lat: r.latitude, lng: r.longitude });
      }
      // Add city suggestions
      if (r.city && r.city.toLowerCase().includes(query.toLowerCase()) && !seen.has(r.city)) {
        seen.add(r.city);
        suggestions.push({ description: r.city + ', ' + r.state, lat: r.latitude, lng: r.longitude });
      }
      // Add branch name suggestions
      if (r.name && r.name.toLowerCase().includes(query.toLowerCase()) && !seen.has(r.name)) {
        seen.add(r.name);
        suggestions.push({ description: r.name + ' (' + r.city + ')', lat: r.latitude, lng: r.longitude });
      }
    }
    
    // Also add state-level if matched
    const [states] = await pool.query(
      "SELECT DISTINCT state, MIN(latitude) as lat, MIN(longitude) as lng FROM wp_branches_database WHERE status=1 AND state LIKE ? GROUP BY state LIMIT 5",
      [term]
    );
    for (const s of states) {
      if (!seen.has(s.state)) {
        seen.add(s.state);
        suggestions.push({ description: s.state, lat: s.lat, lng: s.lng });
      }
    }
    
    res.json(suggestions.slice(0, 15));
  } catch (e) { res.json([]); }
});

app.get('/api/places/geocode', async (req, res) => {
  try {
    const address = String(req.query?.address || '').trim();
    const placeId = String(req.query?.placeId || '').trim();
    if (!address && !placeId) return res.json({ error: 'No address' });

    if (hasGooglePlacesApiKey()) {
      try {
        const googleResult = await geocodeGooglePlace({ address, placeId });
        if (googleResult) {
          return res.json(googleResult);
        }
      } catch (error) {
        console.error('Google Places geocode failed:', {
          address: cleanJustDialString(address, 160),
          placeId: cleanJustDialString(placeId, 160),
          message: error?.message || error,
        });
      }
    }

    if (address) {
      try {
        const photonResult = await geocodePhotonPlace({ address });
        if (photonResult) {
          return res.json(photonResult);
        }
      } catch (error) {
        console.error('Photon geocode failed:', {
          address: cleanJustDialString(address, 160),
          message: error?.message || error,
        });
      }
    }

    if (!address) return res.json({ error: 'Not found' });

    const term = '%' + address.split(',')[0].trim() + '%';
    const [rows] = await pool.query(
      "SELECT latitude, longitude FROM wp_branches_database WHERE status=1 AND (branchName LIKE ? OR city LIKE ? OR area LIKE ? OR addressline LIKE ?) AND latitude != '' LIMIT 1",
      [term, term, term, term]
    );
    if (rows.length > 0) {
      res.json({ lat: parseFloat(rows[0].latitude), lng: parseFloat(rows[0].longitude) });
    } else {
      res.json({ error: 'Not found' });
    }
  } catch (e) { res.json({ error: e.message }); }
});

const CALL_IVR_MEMORY_CACHE_TTL_MS = 30 * 1000;
const CALL_IVR_SAVE_DEDUPE_TTL_MS = 15 * 1000;
const callIvrMemoryCache = new Map();
const callIvrSaveDedupe = new Map();

function getCallIvrMemoryCache(phone10) {
  const cached = callIvrMemoryCache.get(phone10);
  if (!cached || cached.expiresAt <= Date.now()) {
    callIvrMemoryCache.delete(phone10);
    return null;
  }
  return cached.value;
}

function setCallIvrMemoryCache(phone10, value) {
  if (!phone10) return;
  callIvrMemoryCache.set(phone10, {
    value,
    expiresAt: Date.now() + CALL_IVR_MEMORY_CACHE_TTL_MS,
  });
  if (callIvrMemoryCache.size > 2000) {
    const now = Date.now();
    for (const [key, entry] of callIvrMemoryCache.entries()) {
      if (entry.expiresAt <= now || callIvrMemoryCache.size > 1500) {
        callIvrMemoryCache.delete(key);
      }
    }
  }
}

function shouldSkipDuplicateCallIvrSave(phone10, language, businessType, purpose) {
  const signature = [phone10, language, businessType, purpose].join('|');
  const cached = callIvrSaveDedupe.get(phone10);
  const now = Date.now();
  if (cached && cached.signature === signature && cached.expiresAt > now) {
    return true;
  }
  callIvrSaveDedupe.set(phone10, {
    signature,
    expiresAt: now + CALL_IVR_SAVE_DEDUPE_TTL_MS,
  });
  if (callIvrSaveDedupe.size > 2000) {
    for (const [key, entry] of callIvrSaveDedupe.entries()) {
      if (entry.expiresAt <= now || callIvrSaveDedupe.size > 1500) {
        callIvrSaveDedupe.delete(key);
      }
    }
  }
  return false;
}

async function saveCallIvrCache({ phone, language = '', businessType = '', purpose = '' }) {
  const cleanPhone = String(phone || '').replace(/[^0-9]/g, '').slice(-10);
  const cleanLanguage = cleanJustDialString(language, 30);
  const cleanBusinessType = cleanJustDialString(businessType, 100);
  const cleanPurpose = cleanJustDialString(purpose, 100);
  if (!cleanPhone || isNonCustomerCallIvrPhone(cleanPhone)) return false;
  if (!cleanLanguage && !cleanBusinessType && !cleanPurpose) {
    const existing = await getCachedCallIvr(cleanPhone).catch(() => null);
    if (existing && (existing.language || existing.businessType || existing.purpose)) {
      const cachedValue = {
        language: existing.language || '',
        businessType: existing.businessType || '',
        purpose: existing.purpose || '',
        source: 'cache',
      };
      setCallIvrMemoryCache(cleanPhone, cachedValue);
      return {
        phone: cleanPhone,
        language: cachedValue.language,
        businessType: cachedValue.businessType,
        purpose: cachedValue.purpose,
        reusedCached: true,
      };
    }
    return false;
  }
  if (shouldSkipDuplicateCallIvrSave(cleanPhone, cleanLanguage, cleanBusinessType, cleanPurpose)) {
    const existing = await getCachedCallIvr(cleanPhone).catch(() => null);
    return {
      phone: cleanPhone,
      language: cleanLanguage || existing?.language || '',
      businessType: cleanBusinessType || existing?.businessType || '',
      purpose: cleanPurpose || existing?.purpose || '',
      duplicateSkipped: true,
    };
  }

  await runWithDbLockRetry('saveCallIvrCache', async () => {
    const [normalizedRows] = await pool.query(
      `SELECT id
       FROM attica_calls
       WHERE normalized_customer_number=?
       ORDER BY created_at DESC
       LIMIT 1`,
      [cleanPhone]
    );
    let targetCallId = normalizedRows[0]?.id || '';

    if (!targetCallId) {
      const [callerRows] = await pool.query(
        `SELECT id
         FROM attica_calls
         WHERE caller_id IN (?, ?, ?)
         ORDER BY created_at DESC
         LIMIT 1`,
        [cleanPhone, `91${cleanPhone}`, `+91${cleanPhone}`]
      );
      targetCallId = callerRows[0]?.id || '';
    }

    if (targetCallId) {
      await pool.query(
        `UPDATE attica_calls
         SET language=CASE WHEN ? <> '' THEN ? ELSE language END,
             business_type=CASE WHEN ? <> '' THEN ? ELSE business_type END,
             purpose=CASE WHEN ? <> '' THEN ? ELSE purpose END,
             normalized_customer_number=COALESCE(normalized_customer_number, ?)
         WHERE id=?`,
        [
          cleanLanguage, cleanLanguage,
          cleanBusinessType, cleanBusinessType,
          cleanPurpose, cleanPurpose,
          cleanPhone,
          targetCallId,
        ]
      );
    }
  });

  await pool.query(
    `INSERT INTO attica_call_language_cache (phone, language, business_type, purpose, created_at)
     VALUES (?, ?, ?, ?, NOW())
     ON DUPLICATE KEY UPDATE
       language=COALESCE(VALUES(language), attica_call_language_cache.language),
       business_type=COALESCE(VALUES(business_type), attica_call_language_cache.business_type),
       purpose=COALESCE(VALUES(purpose), attica_call_language_cache.purpose),
       created_at=NOW()`,
    [cleanPhone, cleanLanguage || null, cleanBusinessType || null, cleanPurpose || null]
  );

  const existing = await getCachedCallIvr(cleanPhone).catch(() => null);
  const effectiveLanguage = cleanLanguage || existing?.language || '';
  const effectiveBusinessType = cleanBusinessType || existing?.businessType || '';
  const effectivePurpose = cleanPurpose || existing?.purpose || '';
  setCallIvrMemoryCache(cleanPhone, {
    language: effectiveLanguage,
    businessType: effectiveBusinessType,
    purpose: effectivePurpose,
    source: 'memory-cache',
  });

  return {
    phone: cleanPhone,
    language: effectiveLanguage,
    businessType: effectiveBusinessType,
    purpose: effectivePurpose,
  };
}

async function getCachedCallIvr(phone10) {
  if (isNonCustomerCallIvrPhone(phone10)) return null;

  const [cached] = await pool.query(
    `SELECT language, business_type, purpose
     FROM attica_call_language_cache
     WHERE phone=? AND created_at > DATE_SUB(NOW(), INTERVAL 4 HOUR)
     LIMIT 1`,
    [phone10]
  );

  if (!cached.length) return null;
  return {
    language: cached[0].language || '',
    businessType: cached[0].business_type || '',
    purpose: cached[0].purpose || '',
  };
}

async function persistIvrAbandonedMissedCall({
  phone,
  language = '',
  businessType = '',
  purpose = '',
  selectedAt = new Date(),
  graceSeconds = IVR_ABANDONED_MISSED_GRACE_SECONDS,
  forcePersistLanguageSelection = false,
  source = '',
  queueUniqueId = '',
} = {}) {
  const phone10 = normalizeAutoDialPhone(phone);
  if (!phone10 || isNonCustomerCallIvrPhone(phone10)) {
    return { skipped: true, reason: 'invalid-phone' };
  }

  const selectedDate = selectedAt instanceof Date ? selectedAt : new Date(selectedAt);
  if (Number.isNaN(selectedDate.getTime())) {
    return { skipped: true, reason: 'invalid-selected-at' };
  }

  const selectedDateTime = toDatabaseDateTime(selectedDate);
  if (!selectedDateTime) {
    return { skipped: true, reason: 'invalid-selected-datetime' };
  }

  const cleanLanguage = cleanJustDialString(language, 30);
  const cleanBusinessType = cleanJustDialString(businessType, 100);
  const cleanPurpose = cleanJustDialString(purpose, 100) || 'Inbound Enquiry';
  const cleanQueueUniqueId = cleanJustDialString(queueUniqueId, 80);
  if (cleanLanguage && !forcePersistLanguageSelection) {
    return { skipped: true, reason: 'language-selected-queue-handled' };
  }
  if (forcePersistLanguageSelection && cleanQueueUniqueId) {
    const queueAbandoned = isQueueUniqueIdAbandoned(cleanQueueUniqueId);
    if (queueAbandoned === false) {
      return { skipped: true, reason: 'queue-call-was-answered' };
    }
    if (queueAbandoned === null) {
      setTimeout(() => {
        persistIvrAbandonedMissedCall({
          phone: phone10,
          language,
          businessType,
          purpose,
          selectedAt,
          graceSeconds: 0,
          forcePersistLanguageSelection: true,
          source,
          queueUniqueId: cleanQueueUniqueId,
        }).catch((error) => {
          console.error('IVR queue abandon retry failed:', error);
        });
      }, 1500);
      return { skipped: true, reason: 'queue-log-pending', retryInMs: 1500 };
    }
  }

  const normalizedGraceSeconds = Number.isFinite(Number(graceSeconds))
    ? Math.max(0, Number(graceSeconds))
    : IVR_ABANDONED_MISSED_GRACE_SECONDS;
  const graceMs = normalizedGraceSeconds * 1000;
  const elapsedMs = Date.now() - selectedDate.getTime();
  if (elapsedMs < graceMs) {
    const remainingMs = Math.max(1000, graceMs - elapsedMs);
    setTimeout(() => {
      persistIvrAbandonedMissedCall({
        phone: phone10,
        language,
        businessType,
        purpose,
        selectedAt,
      }).catch((error) => {
        console.error('IVR abandoned missed-call grace retry failed:', error);
      });
    }, remainingMs);
    return { skipped: true, reason: 'grace-period-active', retryInMs: remainingMs };
  }

  const lockName = `attica_ivr_abandon_${phone10}_${Math.floor(selectedDate.getTime() / 1000)}`;
  let lockAcquired = false;
  try {
    const [[lockRow]] = await pool.query('SELECT GET_LOCK(?, 0) AS lock_acquired', [lockName]);
    lockAcquired = Number(lockRow?.lock_acquired || 0) === 1;
    if (!lockAcquired) {
      return { skipped: true, reason: 'lock-busy' };
    }

    const [existingRows] = await pool.query(
      `SELECT id
       FROM attica_calls
       WHERE direction='incoming'
         AND RIGHT(REPLACE(REPLACE(REPLACE(COALESCE(NULLIF(normalized_customer_number,''),caller_id),'+',''),' ',''),'-',''),10)=?
         AND (
           created_at BETWEEN DATE_SUB(?, INTERVAL 15 SECOND) AND DATE_ADD(?, INTERVAL 5 MINUTE)
           OR (
             agent_id='IVR'
             AND status='missed'
             AND created_at BETWEEN DATE_SUB(?, INTERVAL 180 SECOND) AND DATE_ADD(?, INTERVAL 120 SECOND)
           )
         )
       ORDER BY created_at DESC
       LIMIT 1`,
      [phone10, selectedDateTime, selectedDateTime, selectedDateTime, selectedDateTime]
    );
    if (existingRows[0]?.id) {
      return { skipped: true, reason: 'incoming-call-already-recorded', callId: existingRows[0].id };
    }

    if (!forcePersistLanguageSelection && hasQueueLogEntryAfterIvrSelection(phone10, selectedDate)) {
      return { skipped: true, reason: 'caller-entered-language-queue' };
    }

    const [[profileRow]] = await pool.query(
      `SELECT customer_name, caller_name, branch, place
       FROM attica_calls
       WHERE RIGHT(REPLACE(REPLACE(REPLACE(COALESCE(NULLIF(normalized_customer_number,''),caller_id),'+',''),' ',''),'-',''),10)=?
       ORDER BY created_at DESC
       LIMIT 1`,
      [phone10]
    );

    const queueHangup = forcePersistLanguageSelection && cleanLanguage;
    const callIdPrefix = queueHangup ? 'IN-IVR-ABANDON' : 'IN-IVR-NOSEL';
    const callId = cleanCanonicalCallId(`${callIdPrefix}-${Math.floor(selectedDate.getTime() / 1000)}-${phone10}`, 120);
    const customerName = getDisplayCustomerNameFromValues(
      profileRow?.customer_name,
      profileRow?.caller_name
    );
    const callDate = selectedDateTime.slice(0, 10);
    const callTime = selectedDateTime.slice(11, 19);
    const missedCall = {
      id: callId,
      callUuid: callId,
      normalizedCustomerNumber: phone10,
      callerId: phone10,
      callerName: customerName || '',
      customerName: customerName || '',
      displayCustomerName: customerName || '',
      agentId: 'NONE',
      agentName: queueHangup ? 'IVR Abandoned' : 'IVR No Selection',
      direction: 'incoming',
      status: 'missed',
      duration: '00:00',
      time: callTime,
      date: callDate,
      language: cleanLanguage,
      branch: profileRow?.branch || '',
      place: profileRow?.place || '',
      purpose: cleanPurpose,
      businessType: cleanBusinessType,
      callbackStatus: queueHangup ? 'Pending' : 'Duplicate Removed',
      followUpFlag: queueHangup,
      notes: queueHangup
        ? `Caller disconnected after IVR selection before agent answer${source ? ` (${cleanJustDialString(source, 80)})` : ''}`
        : 'Caller disconnected before language selection in IVR',
      smsSent: false,
      ringStartedAt: selectedDateTime,
      answeredAt: null,
      endedAt: selectedDateTime,
      talkDurationSeconds: 0,
      hasRecording: false,
      createdAt: selectedDateTime,
    };
    const customerUid = await getOrCreateCustomerUidForPhone(pool, phone10, selectedDateTime);

    await pool.query(
      `INSERT INTO attica_calls
       (id,call_uuid,normalized_customer_number,customer_uid,caller_id,caller_name,customer_name,agent_id,agent_name,direction,status,duration,call_time,call_date,language,branch,place,purpose,business_type,callback_status,follow_up_flag,notes,ring_started_at,ended_at,talk_duration_seconds,created_at)
       VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
       ON DUPLICATE KEY UPDATE
         callback_status=VALUES(callback_status),
         follow_up_flag=VALUES(follow_up_flag),
         notes=VALUES(notes),
         language=COALESCE(NULLIF(VALUES(language),''), attica_calls.language),
         business_type=COALESCE(NULLIF(VALUES(business_type),''), attica_calls.business_type),
         purpose=COALESCE(NULLIF(VALUES(purpose),''), attica_calls.purpose)`,
      [
        missedCall.id,
        missedCall.callUuid,
        missedCall.normalizedCustomerNumber,
        customerUid,
        missedCall.callerId,
        missedCall.callerName,
        missedCall.customerName,
        missedCall.agentId,
        missedCall.agentName,
        missedCall.direction,
        missedCall.status,
        missedCall.duration,
        missedCall.time,
        missedCall.date,
        missedCall.language,
        missedCall.branch,
        missedCall.place,
        missedCall.purpose,
        missedCall.businessType,
        missedCall.callbackStatus,
        missedCall.followUpFlag ? 1 : 0,
        missedCall.notes,
        missedCall.ringStartedAt,
        missedCall.endedAt,
        missedCall.talkDurationSeconds,
        selectedDateTime,
      ]
    );

    if (cleanLanguage || forcePersistLanguageSelection) {
      await autoScheduleMissedCallFollowUp(missedCall).catch((error) => {
        console.error('IVR abandoned missed callback queue failed:', error);
      });
    } else if (ENABLE_VERBOSE_IVR_LOGS) {
      console.info('[IVR] no-selection auto-dial skipped', JSON.stringify({
        phone: phone10,
        callId,
      }));
    }
    enqueueWatiCallOutcome(missedCall);
    if (cleanLanguage || forcePersistLanguageSelection) {
      void triggerAutoDialAssignment('event');
    }

    if (ENABLE_VERBOSE_IVR_LOGS) {
        console.info('[IVR] no-selection missed call persisted', JSON.stringify({
        phone: phone10,
        callId,
        language: cleanLanguage,
      }));
    }

    return { skipped: false, callId };
  } finally {
    if (lockAcquired) {
      await pool.query('SELECT RELEASE_LOCK(?)', [lockName]).catch(() => null);
    }
  }
}

function scheduleIvrAbandonedMissedCallFallback(payload) {
  setTimeout(() => {
    persistIvrAbandonedMissedCall(payload).catch((error) => {
      console.error('IVR abandoned missed-call fallback failed:', error);
    });
  }, 70000);
}

function hasQueueLogEntryAfterIvrSelection(phone10, selectedDate) {
  const phone = normalizeAutoDialPhone(phone10);
  const selectedAt = selectedDate instanceof Date ? selectedDate : new Date(selectedDate);
  if (!phone || Number.isNaN(selectedAt.getTime())) return false;

  try {
    const output = execSync(`grep "${phone}" /var/log/asterisk/queue_log 2>/dev/null | tail -50`, {
      encoding: 'utf8',
      timeout: 3000,
    }).trim();
    if (!output) return false;

    const selectedSeconds = Math.floor(selectedAt.getTime() / 1000);
    return output.split('\n').some((line) => {
      const parts = String(line || '').split('|');
      const eventSeconds = Number(parts[0]);
      const eventName = String(parts[4] || '').trim().toUpperCase();
      if (!Number.isFinite(eventSeconds)) return false;
      if (!['ENTERQUEUE', 'CONNECT', 'COMPLETECALLER', 'COMPLETEAGENT', 'ABANDON', 'RINGNOANSWER'].includes(eventName)) return false;
      return eventSeconds >= selectedSeconds - 300 && eventSeconds <= selectedSeconds + 300;
    });
  } catch (error) {
    return false;
  }
}

function getQueueLogEventsForUniqueId(queueUniqueId) {
  const uniqueId = cleanJustDialString(queueUniqueId, 80);
  if (!uniqueId) return [];

  try {
    const output = execSync(`grep "${uniqueId}" /var/log/asterisk/queue_log 2>/dev/null | tail -50`, {
      encoding: 'utf8',
      timeout: 3000,
    }).trim();
    if (!output) return [];

    return output
      .split('\n')
      .map((line) => {
        const parts = String(line || '').split('|');
        return {
          line,
          eventSeconds: Number(parts[0]),
          queue: String(parts[2] || '').trim(),
          member: String(parts[3] || '').trim(),
          eventName: String(parts[4] || '').trim().toUpperCase(),
        };
      })
      .filter((entry) => Number.isFinite(entry.eventSeconds) && entry.eventName);
  } catch (error) {
    return [];
  }
}

function isQueueUniqueIdAbandoned(queueUniqueId) {
  const events = getQueueLogEventsForUniqueId(queueUniqueId);
  if (events.length === 0) return null;

  const hasAnswered = events.some((entry) => ['CONNECT', 'COMPLETECALLER', 'COMPLETEAGENT', 'TRANSFER'].includes(entry.eventName));
  if (hasAnswered) return false;
  return events.some((entry) => entry.eventName === 'ABANDON');
}

async function lookupCallIvr(phone10) {
  if (isNonCustomerCallIvrPhone(phone10)) {
    return { language: '', businessType: '', purpose: '', source: 'ignored-service-number' };
  }

  const memoryCached = getCallIvrMemoryCache(phone10);
  if (memoryCached) {
    return { ...memoryCached, source: memoryCached.source || 'memory-cache' };
  }

  const cached = await getCachedCallIvr(phone10);
  if (cached && (cached.language || cached.businessType || cached.purpose)) {
    const result = { ...cached, source: 'cache' };
    setCallIvrMemoryCache(phone10, result);
    return result;
  }

  try {
    const output = execSync('grep "' + phone10 + '" /var/log/asterisk/queue_log 2>/dev/null | tail -5', { encoding: 'utf8', timeout: 3000 }).trim();
    const qlines = output.split('\n').reverse();
    const langMap = {'attica-kannada':'Kannada','attica-tamil':'Tamil','attica-telugu':'Telugu','attica-hindi':'Hindi','attica-english':'English'};
    for (const ql of qlines) {
      if (ql.includes('ENTERQUEUE') || ql.includes('CONNECT')) {
        for (const [qname, lang] of Object.entries(langMap)) {
          if (ql.includes(qname)) {
            const result = { language: lang, businessType: '', purpose: '', source: 'queue-log' };
            setCallIvrMemoryCache(phone10, result);
            return result;
          }
        }
      }
    }
  } catch (error) {}

  const result = { language: '', businessType: '', purpose: '', source: 'none' };
  setCallIvrMemoryCache(phone10, result);
  return result;
}

