// ==================== SAVE CALL IVR (from Asterisk) ====================
app.get('/api/save-call-ivr', async (req, res) => {
  try {
    const { phone, language, businessType, purpose, agentId, agentName, source, uniqueId, queueUniqueId } = req.query;
    if (!phone) return res.json({ ok: false, success: false });
    const selectedAt = new Date();
    const normalizedSource = cleanJustDialString(source, 80).toLowerCase();
    const cleanLanguage = cleanJustDialString(language, 30);
    const cleanBusinessType = cleanJustDialString(businessType, 100);
    const cleanPurpose = cleanJustDialString(purpose, 100);
    const saved = await saveCallIvrCache({
      phone,
      language: cleanLanguage,
      businessType: cleanBusinessType,
      purpose: cleanPurpose,
    });
    const effectiveLanguage = cleanLanguage || saved?.language || '';
    const effectiveBusinessType = cleanBusinessType || saved?.businessType || '';
    const effectivePurpose = cleanPurpose || saved?.purpose || '';
    if (saved && !saved.duplicateSkipped && ENABLE_VERBOSE_IVR_LOGS) {
      console.info('[IVR] selection saved', JSON.stringify({
        source: normalizedSource || 'unknown',
        agentId: cleanJustDialString(agentId, 20),
        agentName: cleanJustDialString(agentName, 100),
        phone: saved.phone,
        selectedLanguage: effectiveLanguage,
        businessType: effectiveBusinessType,
        purpose: effectivePurpose,
      }));
    }
    if (['ivr-queue-hangup', 'language-queue-hangup', 'attica-language-queue-hangup'].includes(normalizedSource)) {
      const abandoned = await persistIvrAbandonedMissedCall({
        phone,
        language: effectiveLanguage,
        businessType: effectiveBusinessType,
        purpose: effectivePurpose,
        selectedAt,
        graceSeconds: 0,
        forcePersistLanguageSelection: true,
        source: normalizedSource,
        queueUniqueId: queueUniqueId || uniqueId || '',
      });
      return res.json({ ok: true, success: true, saved, abandoned });
    }
    if (['ivr-hangup', 'ivr-abandoned', 'attica-ivr-hangup'].includes(normalizedSource)) {
      if (effectiveLanguage) {
        return res.json({
          ok: true,
          success: true,
          saved,
          abandoned: { skipped: true, reason: 'language-selected-queue-handled' },
        });
      }
      const abandoned = await persistIvrAbandonedMissedCall({
        phone,
        language: effectiveLanguage,
        businessType: effectiveBusinessType,
        purpose: effectivePurpose,
        selectedAt,
        graceSeconds: 15,
      });
      return res.json({ ok: true, success: true, saved, abandoned });
    }
    if (saved && !saved.duplicateSkipped && !effectiveLanguage) {
      if (!normalizedSource || normalizedSource === 'unknown' || normalizedSource === 'inbound') {
        scheduleIvrAbandonedMissedCallFallback({
          phone: saved.phone,
          language: effectiveLanguage,
          businessType: effectiveBusinessType,
          purpose: effectivePurpose,
          selectedAt,
        });
      }
    }
    res.json({ ok: true, success: true, saved });
  } catch (e) { res.json({ ok: false, success: false, error: e.message }); }
});

