const intakeWorkflows = createIntakeWorkflowService({
  pool, withCallSaveLock, saveIntake:upsertIntakeFormRecord,
  onRoutingChanged: async (agentIds) => { invalidateLiveAgentSnapshotCache(); await syncAsteriskQueuePauseStates(agentIds); },
  onSubmitted: async (draft, workflow) => {
    const [[row]] = await pool.query('SELECT * FROM attica_calls WHERE id=?',[workflow.call_id]);
    if (!row) throw new Error('Final intake call is missing');
    if (JSON.parse(workflow.review_reasons || '[]').length === 0) {
      const followUpId = `INTAKE-FU-${createHash('sha256').update(workflow.intake_token).digest('hex').slice(0,32)}`;
      const phone = normalizeAutoDialPhone(workflow.normalized_phone);
      if (phone && ['schedule','call-done'].includes(draft.followUpAction)) {
        const [pending] = await pool.query(`SELECT id FROM attica_followups WHERE status IN ('Pending','Rescheduled')
          AND RIGHT(REGEXP_REPLACE(phone,'[^0-9]',''),10)=? AND id<>?
          AND DATE(CONVERT_TZ(follow_up_at,'+00:00','+05:30'))<=?
          AND COALESCE(followup_created_at,updated_at)<=?`,
          [phone,followUpId,getIstDateString(workflow.finalized_at),workflow.finalized_at]);
        for (const item of pending) await updateAgentFollowUp(item.id,{status:'Called',outcome:'Call done from intake form'});
      }
      await runCallSavePostCommitTasks({persistedCall:serializeCallRow(row),hasFormStatusField:true,shouldClearAgentWrapUp:true});
      if (phone && draft.followUpAction === 'schedule' && draft.statusFollowUpAt && !shouldQueueFormStatus(normalizeFormStatusLabel(draft.formStatus))) {
        await saveAgentFollowUp({id:followUpId,customerName:draft.customerName || draft.callerName,phone,
          branch:draft.branch,followUpAt:new Date(draft.statusFollowUpAt),status:'Pending',agentId:workflow.agent_id,
          agentName:workflow.agent_name,notes:draft.notes,callId:workflow.call_id,sourceCallId:workflow.call_id,sourceStatus:draft.formStatus});
        await pool.query('UPDATE attica_calls SET follow_up_flag=1 WHERE id=?',[workflow.call_id]);
      }
    }
  },
});

app.post('/api/intake-forms', async (req, res) => {
  try {
    const requestBody = req.body || {};
    const intakeForm = await withCallSaveLock(
      requestBody,
      (lockConnection) => runTransactionWithRetries(
        async (connection) => upsertIntakeFormRecord(connection, requestBody),
        {
          attempts: 3,
          baseDelayMs: 75,
          label: `save intake form ${cleanCanonicalCallId(requestBody?.id, 50) || cleanCanonicalIntakeToken(requestBody?.intakeToken) || 'unknown'}`,
          connection: lockConnection,
        }
      )
    );
    if (!intakeForm?.callId) {
      return res.status(400).json({ success: false, error: 'callId is required' });
    }

    void saveCallIvrCache({
      phone: intakeForm.normalizedPhone || req.body?.callerId,
      language: req.body?.language || intakeForm.language,
      businessType: req.body?.businessType || intakeForm.businessType,
      purpose: req.body?.purpose || intakeForm.purpose,
    }).catch((error) => {
      console.error('Failed to sync IVR cache after intake save:', error);
    });

    return res.json({
      success: true,
      customerId: intakeForm.customerUid || getCustomerUidForPhone(intakeForm.normalizedPhone),
      customerUid: intakeForm.customerUid || getCustomerUidForPhone(intakeForm.normalizedPhone),
      callId: intakeForm.callId,
      intakeToken: intakeForm.intakeToken || '',
      phone: intakeForm.normalizedPhone || '',
      savedAt: toApiIsoString(intakeForm.lastSavedAt || intakeForm.createdAt),
    });
  } catch (e) {
    const statusCode = isRetryableMysqlTransactionError(e) ? 503 : 500;
    const errorCode = cleanJustDialString(e?.code || e?.errorCode || '', 80);

    console.error('Intake form save failed:', {
      statusCode,
      stage: 'intake-form-upsert',
      code: errorCode,
      message: e?.message || e,
      callId: cleanCanonicalCallId(req.body?.id, 50),
      intakeToken: cleanCanonicalIntakeToken(req.body?.intakeToken),
      agentId: cleanJustDialString(req.body?.agentId, 20),
    });

    return res.status(statusCode).json({
      success: false,
      error: e?.message || 'Unable to save the intake form',
      stage: 'intake-form-upsert',
      code: errorCode || undefined,
      status: statusCode,
    });
  }
});

app.get('/api/intake-workflow/pending', async (req, res) => {
  res.set('Cache-Control','no-store');
  try {
    const agentId = normalizeAgentId(req.query.agentId);
    const workflow = await intakeWorkflows.readPending(agentId);
    if (!workflow) return res.json({success:true,workflow:null,call:null});
    const [[agent]] = await pool.query('SELECT extension FROM attica_agents WHERE id=?',[agentId]);
    const endpoint = agent && getAgentLiveEndpointState(agent.extension);
    // Never reopen an old form over a live or ringing PBX call.
    if (!isAgentEndpointExplicitlyIdle(endpoint)) return res.json({success:true,workflow:null,call:null});
    const [[call]] = await pool.query('SELECT * FROM attica_calls WHERE id=? AND agent_id=?',[workflow.callId,agentId]);
    return res.json({success:true,workflow:call ? workflow : null,call:call ? serializeCallRow(call) : null});
  } catch (error) { res.status(503).json({success:false,error:'Unable to restore pending intake'}); }
});

