app.get('/api/calls/export', async (req, res) => {
  const date = normalizeQueryDate(req.query.date);
  const fromDate = normalizeQueryDate(req.query.fromDate);
  const toDate = normalizeQueryDate(req.query.toDate);
  const agentId = normalizeAgentId(req.query.agent || req.query.agentId);
  const direction = normalizeQueryText(req.query.direction, 20);
  const status = normalizeQueryText(req.query.status, 40);
  const disposition = normalizeQueryText(req.query.disposition, 100);
  const dispositionCategory = normalizeQueryText(req.query.dispositionCategory || req.query.disposition_category, 100);
  const source = normalizeQueryText(req.query.source || req.query.callSource || req.query.leadSource, 120);
  const language = normalizeQueryText(req.query.language, 40);
  const branch = normalizeQueryText(req.query.branch, 150);
  const search = normalizeQueryText(req.query.search, 160);

  if (!date && !fromDate && !toDate) {
    return res.status(400).json({ error: 'date, fromDate, or toDate required' });
  }
  if (fromDate && toDate && fromDate > toDate) {
    return res.status(400).json({ error: 'fromDate must be before toDate' });
  }

  const filters = {
    date,
    fromDate,
    toDate,
    agentId,
    direction,
    status,
    disposition,
    dispositionCategory,
    language,
    branch,
    search,
  };
  const { where, params } = buildCallFilters(filters);
  const filteredWhere = `${where}
    AND ${CALL_ROW_VISIBILITY_SQL}
    AND ${NON_DUPLICATE_REMOVED_CALL_SQL}
    AND ${NON_REPORT_ARTIFACT_CALL_SQL}`;
  const fileStart = date || fromDate || getBusinessDateString();
  const fileEnd = date || toDate || fileStart;
  let exported = 0;
  try {
    const [[countRow]] = await pool.query(`SELECT COUNT(*) total FROM attica_calls WHERE ${filteredWhere}`, params);
    const unfilteredTotal = Number(countRow?.total || 0);
    res.set({
      'Content-Type': 'text/csv; charset=utf-8',
      'Content-Disposition': `attachment; filename="attica-report-${fileStart}-to-${fileEnd}.csv"`,
      'Cache-Control': 'private, no-store',
      'X-Report-Row-Count': String(source ? -1 : unfilteredTotal),
      'X-Report-Max-Rows': '0',
    });
    res.write(`\uFEFF${REPORT_EXPORT_HEADERS.map(escapeCsvCell).join(',')}\r\n`);
    res.flush?.();

    let cursorCreatedAt = '';
    let cursorId = '';
    while (!res.destroyed) {
      const cursorWhere = cursorCreatedAt
        ? ' AND (created_at<? OR (created_at=? AND id<?))'
        : '';
      const cursorParams = cursorCreatedAt ? [cursorCreatedAt, cursorCreatedAt, cursorId] : [];
      const [rows] = await pool.query(
        `SELECT ${CALL_REPORT_LIST_SELECT_SQL}
         FROM attica_calls
         WHERE ${filteredWhere}${cursorWhere}
         ORDER BY ${CALL_ROW_SORT_SQL}
         LIMIT 5000`,
        [...params, ...cursorParams],
      );
      if (!rows.length) break;
      const serializedRows = await serializeCallRowsWithDisplayNames(rows, {
        includeProfileNames: false,
        includeLeadSources: true,
        dedupe: false,
        agentId,
      });
      const sourceKey = normalizeReportSourceFilterValue(source);
      const exportRows = source
        ? serializedRows.filter((row) => normalizeReportSourceFilterValue(
          row?.leadSource || (row?.direction === 'incoming' ? 'Incoming' : 'Manual')
        ) === sourceKey)
        : serializedRows;
      if (exportRows.length) {
        const chunk = exportRows
          .map((call, index) => buildReportCsvRow(call, exported + index).map(escapeCsvCell).join(','))
          .join('\r\n');
        if (!res.write(`${chunk}\r\n`) && !res.destroyed) {
          await new Promise((resolve) => {
            const done = () => {
              res.off('drain', done);
              res.off('close', done);
              resolve();
            };
            res.once('drain', done);
            res.once('close', done);
          });
        }
        exported += exportRows.length;
        res.flush?.();
      }
      const last = rows.at(-1);
      cursorCreatedAt = last.created_at;
      cursorId = last.id;
      if (rows.length < 5000) break;
    }
    if (!res.destroyed) res.end();
    console.log('[calls-export]', JSON.stringify({ fileStart, fileEnd, source: source || null, unfilteredTotal, exported }));
    return undefined;
  } catch (e) {
    console.error('[calls-export] failed:', e?.message || e);
    if (res.headersSent) res.destroy(e);
    else res.status(500).json({ error: e.message });
    return undefined;
  }
});

const mdReporting = createMdReporting({
  pool: heavyPool,
  readerPool: primaryPool,
  readBatch: async (connection, filters, cursor, limit) => {
    const { where, params } = buildCallFilters(filters);
    const pageWhere = cursor ? ' AND (created_at<? OR (created_at=? AND id<?))' : '';
    const [rows] = await connection.query(`SELECT ${CALL_LIGHTWEIGHT_LIST_SELECT_SQL},
      HOUR(DATE_ADD(COALESCE(ring_started_at,created_at),INTERVAL 330 MINUTE)) report_hour,
      (answered_at IS NOT NULL OR IFNULL(talk_duration_seconds,0)>0 OR LOWER(IFNULL(status,'')) IN ('active','on-hold','answered','transferred')) report_answered,
      (direction='incoming' AND LOWER(IFNULL(status,''))='missed' AND ${OPEN_MISSED_CALLBACK_STATUS_SQL}) report_missed
      FROM attica_calls WHERE ${where} AND ${CALL_ROW_VISIBILITY_SQL}
      AND ${NON_DUPLICATE_REMOVED_CALL_SQL} AND ${NON_REPORT_ARTIFACT_CALL_SQL}${pageWhere}
      ORDER BY ${CALL_ROW_SORT_SQL} LIMIT ?`,
      [...params,...(cursor ? [cursor.createdAt,cursor.createdAt,cursor.id] : []),limit]);
    return rows;
  },
  normalizeRows: (rows, connection) => dbStorage.run(connection,
    () => serializeCallRowsBasic(rows,{includeLeadSources:true,dedupe:false})),
  readDetail: async (id) => {
    const [[row]] = await heavyPool.query('SELECT * FROM attica_calls WHERE id=? LIMIT 1',[id]);
    return row ? serializeCallRow(row) : null;
  },
});
mountMdReporting(app,mdReporting);

app.get('/api/calls/report-summary', async (req, res) => {
  try {
    const date = normalizeQueryDate(req.query.date);
    const fromDate = normalizeQueryDate(req.query.fromDate);
    const toDate = normalizeQueryDate(req.query.toDate);
    const agentId = normalizeAgentId(req.query.agent || req.query.agentId);
    const direction = normalizeQueryText(req.query.direction, 20);
    const status = normalizeQueryText(req.query.status, 40);
    const disposition = normalizeQueryText(req.query.disposition, 100);
    const dispositionCategory = normalizeQueryText(req.query.dispositionCategory || req.query.disposition_category, 100);
    const source = normalizeQueryText(req.query.source || req.query.callSource || req.query.leadSource, 120);
    const language = normalizeQueryText(req.query.language, 40);
    const branch = normalizeQueryText(req.query.branch, 150);
    const search = normalizeQueryText(req.query.search, 160);

    if (!date && !fromDate && !toDate) {
      return res.status(400).json({ error: 'date, fromDate, or toDate required' });
    }
    if (fromDate && toDate && fromDate > toDate) {
      return res.status(400).json({ error: 'fromDate must be before toDate' });
    }

    const summaryFilters = {
      date,
      fromDate,
      toDate,
      agentId,
      direction,
      status,
      disposition,
      dispositionCategory,
      language,
      branch,
      search,
      source,
    };
    const summaryCacheKey = buildReportSummaryCacheKey(summaryFilters);
    const cachedSummary = reportSummaryCache.get(summaryCacheKey);
    const now = Date.now();
    if (cachedSummary && cachedSummary.expiresAt > now) {
      return res.json(await cachedSummary.promise);
    }
    const sharedCachedSummary = readSharedReportSummaryCache(summaryCacheKey);
    if (sharedCachedSummary) {
      reportSummaryCache.set(summaryCacheKey, {
        expiresAt: now + REPORT_SUMMARY_CACHE_TTL_MS,
        promise: Promise.resolve(sharedCachedSummary),
      });
      return res.json(sharedCachedSummary);
    }

    const summaryPromise = (async () => {
      const dispositionKey = disposition
        ? cleanJustDialString(normalizeFormStatusLabel(disposition), 100).toLowerCase()
        : '';
      if (!source && !dispositionKey) {
        const [summary, hourly, breakdowns] = await Promise.all([
          summarizeFilteredCallsFromDatabase(summaryFilters),
          buildFilteredHourlyCallsFromDatabase(summaryFilters),
          buildFilteredReportBreakdownsFromDatabase(summaryFilters),
        ]);
        return {
          summary,
          hourly,
          ...breakdowns,
          rowCount: summary.total,
          maxRows: 0,
        };
      }

      const rows = await fetchSerializedCallsByFilters({
        date,
        fromDate,
        toDate,
        agentId,
        direction,
        status,
        disposition: '',
        dispositionCategory,
        language,
        branch,
        search,
      }, {
        includeDisplayNames: true,
        hydrateCustomerProfiles: false,
        includeLeadSources: true,
        includeIntakeOnly: false,
        dedupe: false,
        forExport: true,
        limit: MAX_REPORT_EXPORT_ROWS,
      });
      const dispositionFilteredRows = dispositionKey
        ? rows.filter((row) => (
          cleanJustDialString(normalizeFormStatusLabel(row?.callbackStatus || row?.callback_status || row?.formStatus || row?.form_status || row?.disposition || ''), 100).toLowerCase() === dispositionKey
        ))
        : rows;
      const filteredRows = source
        ? dispositionFilteredRows.filter((row) => normalizeReportSourceFilterValue(row?.leadSource || (row?.direction === 'incoming' ? 'Incoming' : 'Manual')) === normalizeReportSourceFilterValue(source))
        : dispositionFilteredRows;
      const databaseAnalytics = source
        || dispositionKey
        ? null
        : await Promise.all([
          summarizeFilteredCallsFromDatabase({
            date,
            fromDate,
            toDate,
            agentId,
            direction,
            status,
            disposition,
            dispositionCategory,
            language,
            branch,
            search,
          }),
          buildFilteredHourlyCallsFromDatabase({
            date,
            fromDate,
            toDate,
            agentId,
            direction,
            status,
            disposition,
            dispositionCategory,
            language,
            branch,
            search,
          }),
        ]);
      return buildReportAnalytics(
        filteredRows,
        databaseAnalytics ? { summary: databaseAnalytics[0], hourly: databaseAnalytics[1] } : {},
      );
    })();
    reportSummaryCache.set(summaryCacheKey, {
      expiresAt: now + REPORT_SUMMARY_CACHE_TTL_MS,
      promise: summaryPromise,
    });
    summaryPromise.then((payload) => writeSharedReportSummaryCache(summaryCacheKey, payload));
    if (reportSummaryCache.size > 40) {
      for (const [cacheKey, entry] of reportSummaryCache.entries()) {
        if (!entry || entry.expiresAt <= now || reportSummaryCache.size > 40) {
          reportSummaryCache.delete(cacheKey);
        }
      }
    }
    summaryPromise.catch(() => reportSummaryCache.delete(summaryCacheKey));
    return res.json(await summaryPromise);
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

// List all calls with phone numbers (paginated)
app.get('/api/calls/list', async (req, res) => {
  try {
    const page = Math.max(1, parseInt(req.query.page) || 1);
    const limit = Math.min(MAX_LIST_API_LIMIT, Math.max(10, parseInt(req.query.limit) || DEFAULT_LIST_API_LIMIT));
    const offset = (page - 1) * limit;
    const date = normalizeQueryDate(req.query.date);
    const fromDate = normalizeQueryDate(req.query.fromDate);
    const toDate = normalizeQueryDate(req.query.toDate);
    const agent = normalizeAgentId(req.query.agent || req.query.agentId);
    const direction = normalizeQueryText(req.query.direction, 20);
    const status = normalizeQueryText(req.query.status, 40);
    const disposition = normalizeQueryText(req.query.disposition, 100);
    const dispositionCategory = normalizeQueryText(req.query.dispositionCategory || req.query.disposition_category, 100);
    const source = normalizeQueryText(req.query.source || req.query.callSource || req.query.leadSource, 120);
    const language = normalizeQueryText(req.query.language, 40);
    const branch = normalizeQueryText(req.query.branch, 150);
    const search = normalizeQueryText(req.query.search, 160);
    const shouldDedupeRows = String(req.query.dedupe || '').trim().toLowerCase() !== 'false';
	    const filterArgs = {
	      date,
	      fromDate,
      toDate,
      agentId: agent,
      direction,
      status,
      disposition,
      dispositionCategory,
      language,
      branch,
	      search,
	    };
	    if (!source) {
      const { where, params } = buildCallFilters(filterArgs);
      const filteredWhere = `${where}
        AND ${CALL_ROW_VISIBILITY_SQL}
        AND ${NON_DUPLICATE_REMOVED_CALL_SQL}
        AND ${NON_REPORT_ARTIFACT_CALL_SQL}`;
      const phoneSql = `NULLIF(RIGHT(REPLACE(REPLACE(REPLACE(REPLACE(IFNULL(COALESCE(NULLIF(normalized_customer_number,''), caller_id),''), '+', ''), ' ', ''), '-', ''), ':', ''), 10), '')`;
      const connectedSql = `(
        answered_at IS NOT NULL
        OR IFNULL(talk_duration_seconds, 0) > 0
        OR LOWER(IFNULL(status,'')) IN ('active','on-hold','answered','transferred')
      )`;
      const countableIncomingSql = countableIncomingCallSql();
      const [countRows, summaryRows, rows] = await Promise.all([
        pool.query(`SELECT COUNT(*) AS total FROM attica_calls WHERE ${filteredWhere}`, params),
        pool.query(
          `SELECT
             COUNT(*) AS total,
             SUM(CASE WHEN direction='incoming' AND ${countableIncomingSql} THEN 1 ELSE 0 END) AS inbound,
             SUM(CASE WHEN direction='outgoing' THEN 1 ELSE 0 END) AS outbound,
             SUM(CASE WHEN ${connectedSql} THEN 1 ELSE 0 END) AS answered,
             COUNT(DISTINCT ${phoneSql}) AS uniqueCallers,
             SUM(CASE WHEN direction='incoming' AND ${countableIncomingSql} AND ${connectedSql} THEN 1 ELSE 0 END) AS incomingAnswered,
             COUNT(DISTINCT CASE
	               WHEN direction='incoming'
	                AND ${countableIncomingSql}
	                AND LOWER(IFNULL(status,''))='missed'
	                AND ${OPEN_MISSED_CALLBACK_STATUS_SQL}
	               THEN ${phoneSql}
	             END) AS incomingMissed,
             COUNT(DISTINCT CASE WHEN direction='incoming' AND ${countableIncomingSql} THEN ${phoneSql} END) AS incomingUnique
           FROM attica_calls
           WHERE ${filteredWhere}`,
          params
        ),
        pool.query(
          `SELECT ${CALL_LIGHTWEIGHT_LIST_SELECT_SQL}
           FROM attica_calls
           WHERE ${filteredWhere}
           ORDER BY ${CALL_ROW_SORT_SQL}
           LIMIT ? OFFSET ?`,
          [...params, limit, offset]
        ),
      ]);

      const total = Number(countRows?.[0]?.[0]?.total || 0);
      const summaryRow = summaryRows?.[0]?.[0] || {};
      const summary = {
        total: Number(summaryRow.total || 0),
        inbound: Number(summaryRow.inbound || 0),
        outbound: Number(summaryRow.outbound || 0),
        answered: Number(summaryRow.answered || 0),
        missed: Number(summaryRow.incomingMissed || 0),
        uniqueCallers: Number(summaryRow.uniqueCallers || 0),
        incomingTotal: Number(summaryRow.inbound || 0),
        incomingAnswered: Number(summaryRow.incomingAnswered || 0),
        incomingMissed: Number(summaryRow.incomingMissed || 0),
        incomingUnique: Number(summaryRow.incomingUnique || 0),
      };
      const pageRows = rows?.[0] || [];
      await backfillRecordingMetadataOnCallRows(pageRows, { persistMatches: true });
      const serializedRows = await serializeCallRowsBasic(pageRows, {
        includeLeadSources: true,
        dedupe: false,
      });
      res.json({
        page,
        limit,
        total,
        totalPages: total > 0 ? Math.ceil(total / limit) : 0,
        summary,
        results: compactCallListRows(serializedRows),
      });
      return;
    }
    if (source) {
      const allReportRows = await fetchSerializedCallsByFilters(filterArgs, {
        includeDisplayNames: true,
        hydrateCustomerProfiles: false,
        includeLeadSources: true,
        includeIntakeOnly: false,
        dedupe: false,
        forExport: true,
        limit: MAX_REPORT_EXPORT_ROWS,
      });
      const sourceKey = normalizeReportSourceFilterValue(source);
      const filteredRows = allReportRows.filter((row) => (
        normalizeReportSourceFilterValue(row?.leadSource || 'Manual') === sourceKey
      ));
      const summary = summarizeSerializedCalls(filteredRows);
      const total = filteredRows.length;
      const totalPages = total > 0 ? Math.ceil(total / limit) : 0;
      res.json({
        page,
        limit,
        total,
        totalPages,
        summary,
        results: compactCallListRows(filteredRows.slice(offset, offset + limit)),
      });
      return;
    }

    const allReportRows = shouldDedupeRows
      ? await fetchCachedDedupedReportRows(filterArgs)
      : await fetchSerializedCallsByFilters(filterArgs, {
        includeDisplayNames: true,
        hydrateCustomerProfiles: false,
        includeLeadSources: true,
        includeIntakeOnly: false,
        dedupe: false,
      });
    const summary = summarizeSerializedCalls(allReportRows);
    const total = allReportRows.length;
    const totalPages = total > 0 ? Math.ceil(total / limit) : 0;
    const pagedRows = allReportRows.slice(offset, offset + limit);
    
    res.json({
      page,
      limit,
      total,
      totalPages,
      summary,
      results: compactCallListRows(pagedRows),
    });
  } catch (e) { res.status(500).json({ error: e.message, results: [] }); }
});

async function ensureIndexExists(tableName, indexName, createSql) {
  const [rows] = await pool.query(`SHOW INDEX FROM ${tableName} WHERE Key_name=?`, [indexName]);
  if (Array.isArray(rows) && rows.length > 0) {
    return;
  }
  await pool.query(createSql);
}

function isRetryableDbLockError(error) {
  return ['ER_LOCK_DEADLOCK', 'ER_LOCK_WAIT_TIMEOUT'].includes(String(error?.code || '').trim());
}

async function runWithDbLockRetry(label, operation, attempts = 3) {
  let lastError = null;
  const normalizedAttempts = Math.max(1, Number(attempts) || 1);
  for (let attempt = 1; attempt <= normalizedAttempts; attempt += 1) {
    try {
      return await operation(attempt);
    } catch (error) {
      lastError = error;
      if (!isRetryableDbLockError(error) || attempt >= normalizedAttempts) {
        throw error;
      }
      const waitMs = 150 * attempt;
      console.warn(`[db-retry] ${label} failed with ${error.code}; retrying attempt ${attempt + 1}/${normalizedAttempts}`);
      await new Promise((resolve) => setTimeout(resolve, waitMs));
    }
  }
  throw lastError;
}

function buildCallSaveLockName(callLike = {}) {
  const lockIdentity = cleanCanonicalCallId(callLike.id || callLike.callId || callLike.callUuid || callLike.call_uuid, 80)
    || cleanCanonicalIntakeToken(callLike.intakeToken || callLike.intake_token)
    || normalizeAutoDialPhone(
      callLike.normalizedPhone
      || callLike.normalized_phone
      || callLike.normalizedCustomerNumber
      || callLike.normalized_customer_number
      || callLike.callerId
      || callLike.caller_id
    );
  if (!lockIdentity) return '';
  return `attica_call_save_${lockIdentity}`.slice(0, 64);
}

async function findPersistedCallForSaveRequest(callLike = {}, attempts = 1) {
  const ids = Array.from(new Set([
    cleanCanonicalCallId(callLike.id || callLike.callId, 120),
    cleanCanonicalCallId(callLike.callUuid || callLike.call_uuid, 120),
  ].filter(Boolean)));
  const intakeToken = cleanCanonicalIntakeToken(callLike.intakeToken || callLike.intake_token);
  if (ids.length === 0 && !intakeToken) return null;

  const normalizedAttempts = Math.max(1, Number(attempts) || 1);
  for (let attempt = 1; attempt <= normalizedAttempts; attempt += 1) {
    const whereParts = [];
    const params = [];
    if (ids.length > 0) {
      whereParts.push(`(id IN (${ids.map(() => '?').join(',')}) OR call_uuid IN (${ids.map(() => '?').join(',')}))`);
      params.push(...ids, ...ids);
    }
    if (intakeToken) {
      whereParts.push('intake_token=?');
      params.push(intakeToken);
    }
    const [rows] = await pool.query(
      `SELECT *
       FROM attica_calls
       WHERE ${whereParts.join(' OR ')}
       ORDER BY created_at DESC
       LIMIT 1`,
      params,
    );
    if (rows?.[0]) return rows[0];
    if (attempt < normalizedAttempts) {
      await new Promise((resolve) => setTimeout(resolve, 250));
    }
  }

  return null;
}

async function withCallSaveLock(callLike = {}, operation) {
  const lockName = buildCallSaveLockName(callLike);
  if (!lockName) {
    return operation();
  }

  const lockConnection = await pool.getConnection();
  let lockAcquired = false;
  let shouldDestroyLockConnection = false;
  let lockConnectionDestroyedByWatchdog = false;
  let lockHoldTimer = null;
  try {
    const [[lockRow]] = await lockConnection.query('SELECT GET_LOCK(?, ?) AS got_lock', [lockName, CALL_SAVE_LOCK_WAIT_SECONDS]);
    lockAcquired = Number(lockRow?.got_lock || 0) === 1;
    if (!lockAcquired) {
      const error = new Error('Call save is busy, please retry');
      error.statusCode = 503;
      error.code = 'CALL_SAVE_LOCK_TIMEOUT';
      throw error;
    }
    lockHoldTimer = setTimeout(() => {
      lockConnectionDestroyedByWatchdog = true;
      shouldDestroyLockConnection = true;
      console.warn('Destroyed long-held call save lock connection:', {
        lockName,
        maxHoldMs: CALL_SAVE_LOCK_MAX_HOLD_MS,
      });
      lockConnection.destroy();
    }, CALL_SAVE_LOCK_MAX_HOLD_MS);
    return await operation(lockConnection);
  } finally {
    if (lockHoldTimer) {
      clearTimeout(lockHoldTimer);
    }
    if (lockAcquired && !lockConnectionDestroyedByWatchdog) {
      try {
        await lockConnection.query('SELECT RELEASE_LOCK(?)', [lockName]);
      } catch (releaseError) {
        shouldDestroyLockConnection = true;
        console.warn('Failed to release call save lock:', releaseError?.message || releaseError);
      }
    }
    if (shouldDestroyLockConnection) {
      lockConnection.destroy();
    } else {
      lockConnection.release();
    }
  }
}

async function runCallSavePostCommitTasks({
  persistedCall,
  isDraftSave = false,
  hasFormStatusField = false,
  shouldClearAgentWrapUp = false,
  clearedAgentWrapUp = false,
  releasedAgentCallSlot = false,
} = {}) {
  if (!persistedCall) return;

  try {
    if (!isDraftSave && persistedCall.hasRecording && persistedCall.id) {
      if (persistedCall.recordingName) {
        await pool.query(
          `UPDATE attica_calls
           SET has_recording=1,
               recording_name=COALESCE(NULLIF(recording_name, ''), ?)
           WHERE id=?`,
          [persistedCall.recordingName, persistedCall.id]
        );
      } else {
        scheduleRecordingMetadataBackfill(persistedCall.id);
      }
    }
  } catch (error) {
    console.error('Post-save recording metadata update failed:', error?.message || error);
  }

  if (persistedCall.normalizedCustomerNumber || persistedCall.callerId) {
    try {
      await saveCallIvrCache({
        phone: persistedCall.normalizedCustomerNumber || persistedCall.callerId,
        language: persistedCall.language,
        businessType: persistedCall.businessType,
        purpose: persistedCall.purpose,
      });
    } catch (error) {
      console.error('Failed to sync IVR cache after call save:', error?.message || error);
    }
  }

  if (!isDraftSave) {
    try {
      await autoBlockCallDispositionNumber(persistedCall);
    } catch (error) {
      console.error('Post-save auto-block disposition failed:', error?.message || error);
    }

    try {
      await autoScheduleShortIncomingDisconnectedFollowUp(persistedCall);
    } catch (error) {
      console.error('Post-save short incoming disconnect follow-up scheduling failed:', error?.message || error);
    }

    try {
      await autoScheduleMissedCallFollowUp(persistedCall);
    } catch (error) {
      console.error('Post-save missed follow-up scheduling failed:', error?.message || error);
    }

    try {
      await autoScheduleOutboundRnrFollowUp(persistedCall);
    } catch (error) {
      console.error('Post-save outbound RNR follow-up scheduling failed:', error?.message || error);
    }

    if (hasFormStatusField) {
      try {
        await syncStatusFollowUpQueue(persistedCall);
      } catch (error) {
        console.error('Post-save status follow-up queue sync failed:', error?.message || error);
      }
    }

    enqueueWatiCallOutcome(persistedCall);
  }

  let postCommitClearedAgentWrapUp = Boolean(clearedAgentWrapUp);
  if (shouldClearAgentWrapUp && persistedCall.agentId) {
    try {
      const clearCallId = cleanCanonicalCallId(persistedCall.callUuid || persistedCall.id, 120);
      const [clearResult] = await pool.query(
        `UPDATE attica_agents
         SET wrap_up_started_at=NULL,
             wrap_up_until=NULL,
             wrap_up_call_id=NULL
         WHERE id=?
           AND (
             wrap_up_call_id IS NULL
             OR wrap_up_call_id=''
             OR wrap_up_call_id=?
             OR wrap_up_call_id=?
           )`,
        [
          persistedCall.agentId,
          clearCallId,
          cleanCanonicalCallId(persistedCall.id, 120),
        ]
      );
      postCommitClearedAgentWrapUp = postCommitClearedAgentWrapUp || Number(clearResult?.affectedRows || 0) > 0;
    } catch (error) {
      console.error('Post-save agent wrap-up clear failed:', error?.message || error);
    }
  }

  if ((postCommitClearedAgentWrapUp || releasedAgentCallSlot) && persistedCall.agentId) {
    try {
      await syncAsteriskQueuePauseStates([persistedCall.agentId]);
      invalidateLiveAgentSnapshotCache();
    } catch (error) {
      console.error('Failed to sync queue pause after disposition save:', error?.message || error);
    }
  }

  if (!isDraftSave && normalizeCallStatus(persistedCall.status) === 'completed') {
    void retryPendingMissedCallAssignments();
    void triggerAutoDialAssignment('event');
  }
}

