  await pool.query(`
    ALTER TABLE attica_auto_dial_leads
      ADD COLUMN IF NOT EXISTS queue_bucket varchar(24)
        GENERATED ALWAYS AS (
          CASE
            WHEN LOWER(IFNULL(source_file,'')) LIKE '%missed callback%'
              OR LOWER(IFNULL(lead_type,'')) = 'missed call'
              THEN 'missed-callback'
            WHEN LOWER(IFNULL(source_file,'')) LIKE '%follow%'
              OR LOWER(IFNULL(source_file,'')) LIKE '%auto follow-up%'
              OR LOWER(IFNULL(source_file,'')) LIKE '%status follow%'
              OR LOWER(IFNULL(source_file,'')) LIKE '%rnr%'
              OR UPPER(IFNULL(id,'')) LIKE 'SFL-%'
              OR UPPER(IFNULL(id,'')) LIKE 'AUTO-%'
              OR UPPER(IFNULL(id,'')) LIKE 'RNR-%'
              THEN 'follow-up'
            ELSE 'outbound'
          END
        ) PERSISTENT,
      ADD COLUMN IF NOT EXISTS queue_work_mode varchar(24)
        GENERATED ALWAYS AS (
          CASE
            WHEN (
              LOWER(IFNULL(source_file,'')) LIKE '%follow%'
              OR LOWER(IFNULL(source_file,'')) LIKE '%auto follow-up%'
              OR LOWER(IFNULL(source_file,'')) LIKE '%status follow%'
              OR LOWER(IFNULL(source_file,'')) LIKE '%rnr%'
              OR UPPER(IFNULL(id,'')) LIKE 'SFL-%'
              OR UPPER(IFNULL(id,'')) LIKE 'AUTO-%'
              OR UPPER(IFNULL(id,'')) LIKE 'RNR-%'
            )
            AND NOT (
              LOWER(IFNULL(source_file,'')) LIKE '%missed callback%'
              OR LOWER(IFNULL(lead_type,'')) = 'missed call'
            )
              THEN 'follow-up'
            ELSE 'outbound-auto'
          END
        ) PERSISTENT
  `);
  await pool.query(
    `UPDATE attica_auto_dial_leads
     SET followup_created_at=COALESCE(followup_created_at, created_at),
         followup_expires_at=COALESCE(followup_expires_at, DATE_ADD(COALESCE(followup_created_at, created_at, NOW()), INTERVAL ? DAY)),
         followup_reason=COALESCE(NULLIF(followup_reason, ''), NULLIF(lead_type, ''), NULLIF(source_file, ''), 'Follow-Up')
     WHERE ${FOLLOW_UP_AUTO_DIAL_PREDICATE_SQL}
       AND (followup_created_at IS NULL OR followup_expires_at IS NULL OR IFNULL(followup_reason, '')='')`,
    [FOLLOW_UP_RETENTION_DAYS]
  );
  await ensureIndexExists(
    'attica_auto_dial_leads',
    'idx_attica_auto_dial_followup_expiry',
    'ALTER TABLE attica_auto_dial_leads ADD KEY idx_attica_auto_dial_followup_expiry (is_active, followup_expires_at, status)'
  );
  await pool.query(`
    UPDATE attica_auto_dial_leads
    SET normalized_number=NULLIF(
          RIGHT(REPLACE(REPLACE(REPLACE(IFNULL(mobile_number,''),'+',''),' ',''),'-',''), 10),
          ''
        )
  `);
  const [preDedupeResult] = await pool.query(`
    UPDATE attica_auto_dial_leads a
    INNER JOIN (
      SELECT id
      FROM (
        SELECT
          id,
          ROW_NUMBER() OVER (
            PARTITION BY normalized_number
            ORDER BY
              CASE
                WHEN status='dialing' THEN 0
                WHEN status='assigned' THEN 1
                WHEN LOWER(IFNULL(source_file,''))='missed callback' THEN 2
                ELSE 3
              END,
              created_at ASC,
              id ASC
          ) AS duplicate_rank
        FROM attica_auto_dial_leads
        WHERE IFNULL(normalized_number,'') <> ''
          AND IFNULL(is_active,1)=1
          AND (
            status IN ('assigned','dialing')
            OR (status='pending' AND IFNULL(retry_allowed, 1) <> 0)
          )
      ) ranked_open_leads
      WHERE duplicate_rank > 1
      LIMIT 2000
    ) duplicate_open_leads ON duplicate_open_leads.id=a.id
    SET a.status='completed',
        a.is_active=0,
        a.retry_allowed=0,
        a.open_dedupe_number=NULL,
        a.completed_at=COALESCE(a.completed_at, NOW()),
        a.queue_exit_reason='Duplicate open auto-dial lead removed before dedupe rebuild',
        a.last_error=CASE
          WHEN IFNULL(a.last_error,'')='' THEN 'Duplicate open auto-dial lead removed before dedupe rebuild'
          WHEN IFNULL(a.last_error,'') LIKE '%Duplicate open auto-dial lead removed before dedupe rebuild%' THEN LEFT(a.last_error, 255)
          ELSE LEFT(CONCAT(LEFT(a.last_error, 160), ' | Duplicate open auto-dial lead removed before dedupe rebuild'), 255)
        END,
        a.updated_at=NOW()
  `);
  if (Number(preDedupeResult?.affectedRows || 0) > 0) {
    console.warn('[self-heal] Closed duplicate open auto-dial leads before dedupe rebuild', {
      retired: Number(preDedupeResult.affectedRows || 0),
    });
  }
  await pool.query(`
    UPDATE attica_auto_dial_leads
    SET open_dedupe_number=CASE
          WHEN IFNULL(normalized_number,'') = '' THEN NULL
          WHEN IFNULL(is_active,1)=1 AND status IN ('assigned','dialing') THEN normalized_number
          WHEN IFNULL(is_active,1)=1 AND status='pending' AND IFNULL(retry_allowed, 1) <> 0 THEN normalized_number
          ELSE NULL
        END
  `);
  await cleanupDuplicateOpenAutoDialLeads();
  await pool.query("UPDATE attica_auto_dial_leads SET shuffle_no = FLOOR((RAND() * 2147483646) + 1) WHERE shuffle_no IS NULL");
